local boxKeyChars = {
    [Enum.KeyCode.Space] = {' ', ' '},
    [Enum.KeyCode.Period] = {'.', '>'},
    [Enum.KeyCode.Slash] = {'/', '?'},
    [Enum.KeyCode.Comma] = {',', '<'},
    [Enum.KeyCode.Semicolon] = {';', ':'},
    [Enum.KeyCode.Quote] = {"'", '"'},
    [Enum.KeyCode.LeftBracket] = {'[', '{'},
    [Enum.KeyCode.RightBracket] = {']', '}'},
    [Enum.KeyCode.BackSlash] = {'\\', '|'},
    [Enum.KeyCode.Minus] = {'-', '_'},
    [Enum.KeyCode.Equals] = {'=', '+'},
    [Enum.KeyCode.Backquote] = {'`', '~'},
    [Enum.KeyCode.Zero] = {'0', ')'},
    [Enum.KeyCode.One] = {'1', '!'},
    [Enum.KeyCode.Two] = {'2', '@'},
    [Enum.KeyCode.Three] = {'3', '#'},
    [Enum.KeyCode.Four] = {'4', '$'},
