                Size = 13;
                ZIndex = z+55;
                Outline = true;
                Parent = objs.midBorder;
            })
            objs.titleSuffix = utility:Draw('Text', {
                Position = newUDim2(0,68,0,2);
                Color = fromrgb(255,255,255);
                ThemeColor = 'Primary Text';
                Text = '.xyz';
                Font = 2;
                Size = 13;
                ZIndex = z+55;
                Outline = true;
                Parent = objs.midBorder;
            })
            objs.titleRole = utility:Draw('Text', {
                Position = newUDim2(1,-70,0,3);
