            if typeof(bool) == 'boolean' then
                self.open = bool;
                self.objects.background.Visible = bool;
                if library.tweens then
                    for obj, props in next, library.tweens do
                        for _, tween in next, props do
                            pcall(function()
                                tween:Cancel()
                            end)
                        end
                    end
                    table.clear(library.tweens)
                end
            end
        end

