	local function colorToTable(c: Color3): { number }
		return { math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5) }
	end

	local function tableToColor(value: any, fallback: Color3): Color3
		if typeof(value) == "Color3" then
			return value
		end
		if type(value) == "table" and type(value[1]) == "number" then
			return Color3.fromRGB(value[1], value[2] or 0, value[3] or 0)
		end
		return fallback
	end

