	local function restoreUtilStyle(style: any, src: any)
		for _, key in UTIL_STYLE_BOOLS do
			if type(src[key]) == "boolean" then
				style[key] = src[key]
			end
		end
		if type(src.font) == "string" then style.font = src.font end
		if type(src.textSize) == "number" then style.textSize = math.clamp(src.textSize, 8, 24) end
		if type(src.imageSize) == "number" then style.imageSize = math.clamp(src.imageSize, 12, 48) end
		for _, key in UTIL_STYLE_COLORS do
			style[key] = tableToColor(src[key], style[key])
		end
	end

	restoreEsp = function(data: any)
		if type(data) ~= "table" then
			return
		end
		if type(data.master) == "boolean" then Esp.master = data.master end
		if type(data.box) == "boolean" then Esp.box = data.box end
		Esp.boxColor = tableToColor(data.boxColor, Esp.boxColor)
		if type(data.boxFill) == "boolean" then Esp.boxFill = data.boxFill end
		Esp.boxFillColor = tableToColor(data.boxFillColor, Esp.boxFillColor)
		if type(data.boxOutline) == "boolean" then Esp.boxOutline = data.boxOutline end
		if type(data.skeleton) == "boolean" then Esp.skeleton = data.skeleton end
		Esp.skeletonColor = tableToColor(data.skeletonColor, Esp.skeletonColor)
		if type(data.skeletonOutline) == "boolean" then Esp.skeletonOutline = data.skeletonOutline end
		if type(data.names) == "boolean" then Esp.names = data.names end
		Esp.namesColor = tableToColor(data.namesColor, Esp.namesColor)
		if type(data.namesY) == "number" then Esp.namesY = data.namesY end
		if type(data.namesSize) == "number" then Esp.namesSize = math.clamp(data.namesSize, 8, 32) end
		if type(data.health) == "boolean" then Esp.health = data.health end
		Esp.healthHigh = tableToColor(data.healthHigh, Esp.healthHigh)
		Esp.healthMid = tableToColor(data.healthMid, Esp.healthMid)
		Esp.healthLow = tableToColor(data.healthLow, Esp.healthLow)
		if type(data.healthThick) == "number" then Esp.healthThick = data.healthThick end
		if type(data.healthX) == "number" then Esp.healthX = data.healthX end
		if type(data.healthY) == "number" then Esp.healthY = data.healthY end
		if type(data.healthGradient) == "boolean" then Esp.healthGradient = data.healthGradient end
		if type(data.healthAnim) == "boolean" then Esp.healthAnim = data.healthAnim end
		if type(data.healthAnimSpeed) == "number" then Esp.healthAnimSpeed = math.clamp(data.healthAnimSpeed, 0.1, 8) end
		if type(data.distance) == "boolean" then Esp.distance = data.distance end
		Esp.distanceColor = tableToColor(data.distanceColor, Esp.distanceColor)
		if type(data.distanceY) == "number" then Esp.distanceY = data.distanceY end
		if type(data.weapon) == "boolean" then Esp.weapon = data.weapon end
		Esp.weaponColor = tableToColor(data.weaponColor, Esp.weaponColor)
		if type(data.weaponY) == "number" then Esp.weaponY = data.weaponY end
		if type(data.weaponSize) == "number" then Esp.weaponSize = math.clamp(data.weaponSize, 8, 32) end
		if type(data.flags) == "boolean" then Esp.flags = data.flags end
		if type(data.flagHealth) == "boolean" then Esp.flagHealth = data.flagHealth end
		if type(data.flagTeam) == "boolean" then Esp.flagTeam = data.flagTeam end
		if type(data.flagsY) == "number" then Esp.flagsY = data.flagsY end
		if type(data.font) == "string" then Esp.font = data.font end
		if type(data.fontWeight) == "string" then Esp.fontWeight = data.fontWeight end
		if type(data.nameText) == "string" then Esp.nameText = data.nameText end
		if type(data.gradName) == "boolean" then Esp.gradName = data.gradName end
		Esp.gradNameColor = tableToColor(data.gradNameColor, Esp.gradNameColor)
		Esp.gradNameColor2 = tableToColor(data.gradNameColor2, Esp.gradNameColor2)
		if type(data.gradDistance) == "boolean" then Esp.gradDistance = data.gradDistance end
		Esp.gradDistanceColor = tableToColor(data.gradDistanceColor, Esp.gradDistanceColor)
		Esp.gradDistanceColor2 = tableToColor(data.gradDistanceColor2, Esp.gradDistanceColor2)
		if type(data.gradWeapon) == "boolean" then Esp.gradWeapon = data.gradWeapon end
		Esp.gradWeaponColor = tableToColor(data.gradWeaponColor, Esp.gradWeaponColor)
		Esp.gradWeaponColor2 = tableToColor(data.gradWeaponColor2, Esp.gradWeaponColor2)
		if type(data.gradFlags) == "boolean" then Esp.gradFlags = data.gradFlags end
		Esp.gradFlagsColor = tableToColor(data.gradFlagsColor, Esp.gradFlagsColor)
		Esp.gradFlagsColor2 = tableToColor(data.gradFlagsColor2, Esp.gradFlagsColor2)
		if type(data.arrows) == "boolean" then Esp.arrows = data.arrows end
		Esp.arrowsColor = tableToColor(data.arrowsColor, Esp.arrowsColor)
		if type(data.arrowsRadius) == "number" then Esp.arrowsRadius = math.clamp(data.arrowsRadius, 20, 400) end
		if type(data.chams) == "boolean" then Esp.chams = data.chams end
		if type(data.chamsShowVisible) == "boolean" then Esp.chamsShowVisible = data.chamsShowVisible end
		if type(data.chamsShowOccluded) == "boolean" then Esp.chamsShowOccluded = data.chamsShowOccluded end
		Esp.chamsVisible = tableToColor(data.chamsVisible, Esp.chamsVisible)
		Esp.chamsVisible2 = tableToColor(data.chamsVisible2, Esp.chamsVisible)
		Esp.chamsOccluded = tableToColor(data.chamsOccluded, Esp.chamsOccluded)
		Esp.chamsOccluded2 = tableToColor(data.chamsOccluded2, Esp.chamsOccluded)
		if type(data.chamsTransparency) == "number" then Esp.chamsTransparency = math.clamp(data.chamsTransparency, 0, 0.95) end
		if type(data.onshot) == "boolean" then Esp.onshot = data.onshot end
		if type(data.onshotShowVisible) == "boolean" then Esp.onshotShowVisible = data.onshotShowVisible end
		if type(data.onshotShowOccluded) == "boolean" then Esp.onshotShowOccluded = data.onshotShowOccluded end
		Esp.onshotVisible = tableToColor(data.onshotVisible, Esp.onshotVisible)
		Esp.onshotVisible2 = tableToColor(data.onshotVisible2, Esp.onshotVisible2)
		Esp.onshotOccluded = tableToColor(data.onshotOccluded, Esp.onshotOccluded)
		Esp.onshotOccluded2 = tableToColor(data.onshotOccluded2, Esp.onshotOccluded2)
		if type(data.onshotTransparency) == "number" then Esp.onshotTransparency = math.clamp(data.onshotTransparency, 0, 0.95) end
		if type(data.onshotDuration) == "number" then Esp.onshotDuration = math.clamp(data.onshotDuration, 0.1, 5) end
		if type(data.hitFx) == "boolean" then HitFx.enabled = data.hitFx end
		if type(data.hitStyle) == "string" then HitFx.style = data.hitStyle end
		HitFx.color = tableToColor(data.hitColor, HitFx.color)
		if type(data.hitFade) == "number" then HitFx.fade = math.clamp(data.hitFade, 0.08, 2) end
		if type(data.hitAnchor) == "boolean" then HitFx.anchor = data.hitAnchor end
		local util = data.util
		if type(util) == "table" then
			if type(util.enabled) == "boolean" then
				UtilEsp.enabled = util.enabled
			end
			if type(util.types) == "table" then
				for _, item in UTIL_ITEMS do
					UtilEsp.types[item.id] = util.types[item.id] == true
				end
			end
			if type(util.maxDistance) == "number" then UtilEsp.maxDistance = math.clamp(util.maxDistance, 50, 3000) end
			local styles = if type(util.styles) == "table" then util.styles else nil
			for _, item in UTIL_ITEMS do
				local style = table.clone(UTIL_STYLE_DEFAULTS)
				local src = if styles then styles[item.id] else util
				if type(src) == "table" then
					restoreUtilStyle(style, src)
				end
				UtilEsp.styles[item.id] = style
			end
		end
		task.defer(function()
			for _, paint in EspPaintFns do
				pcall(paint, false)
			end
		end)
	end

	DrawingBridge.builders.esp = function(kit: any)
		local tab = kit.tab("visuals")
		pcall(function()
			tab:AddSubTabs({ "players", "utility", "extra bs" })
		end)
		local features = tab:AddSection("features", 1)
		features.subTab = "players"
		local style = tab:AddSection("style", 2)
		style.subTab = "players"
		style.enabled = true
		pcall(function()
			style.side = 2
		end)
		local state: any = Esp
		local refreshFeatures: () -> ()

		kit.flag(features, "Master", state, "master", nil, function()
			refreshFeatures()
		end)
		local box = kit.flag(features, "Box", state, "box", { { key = "boxColor" } }, function()
			refreshFeatures()
		end)
		local fill = kit.flag(features, "Fill", state, "boxFill", { { key = "boxFillColor" } })
		local outline = kit.flag(features, "Outline", state, "boxOutline")
		local skeleton = kit.flag(features, "Skeleton", state, "skeleton", { { key = "skeletonColor" } }, function()
			refreshFeatures()
		end)
		local skelOutline = kit.flag(features, "Skeleton outline", state, "skeletonOutline")
		local chams = kit.flag(features, "Chams", state, "chams", nil, function()
			refreshFeatures()
		end)
		local chamsVis = kit.flag(features, "Chams visible", state, "chamsShowVisible", {
			{ key = "chamsVisible" },
			{ key = "chamsVisible2" },
		})
		local chamsOcc = kit.flag(features, "Chams occluded", state, "chamsShowOccluded", {
			{ key = "chamsOccluded" },
			{ key = "chamsOccluded2" },
		})
		local chamsAlpha = kit.number(features, "Chams transparency", state, "chamsTransparency", 0, 0.95, 0.05)
		local onshot = kit.flag(features, "Onshot", state, "onshot", nil, function()
			refreshFeatures()
		end)
		local onshotVis = kit.flag(features, "Onshot visible", state, "onshotShowVisible", {
			{ key = "onshotVisible" },
			{ key = "onshotVisible2" },
		})
		local onshotOcc = kit.flag(features, "Onshot occluded", state, "onshotShowOccluded", {
			{ key = "onshotOccluded" },
			{ key = "onshotOccluded2" },
		})
		local onshotAlpha = kit.number(features, "Onshot transparency", state, "onshotTransparency", 0, 0.95, 0.05)
		local onshotTime = kit.number(features, "Onshot duration", state, "onshotDuration", 0.1, 5, 0.1, { suffix = "s" })
		local names = kit.flag(features, "Names", state, "names", { { key = "namesColor" } }, function()
			refreshFeatures()
		end)
		local namePos = kit.number(features, "Name Y", state, "namesY", -200, 200, 1)
		local nameSize = kit.number(features, "Name size", state, "namesSize", 8, 32, 1)
		local health = kit.flag(features, "Healthbar", state, "health", {
			{ key = "healthHigh" },
			{ key = "healthMid" },
			{ key = "healthLow" },
		}, function()
			refreshFeatures()
		end)
		local healthGrad = kit.flag(features, "Health gradient", state, "healthGradient", nil, function()
			refreshFeatures()
		end)
		local healthAnim = kit.flag(features, "animate gradient", state, "healthAnim", nil, function()
			refreshFeatures()
		end)
		local healthAnimSp = kit.number(features, "speed", state, "healthAnimSpeed", 0.1, 8, 0.1)
		local healthThick = kit.number(features, "Health thickness", state, "healthThick", 1, 8, 1)
		local healthX = kit.number(features, "Health X", state, "healthX", -200, 200, 1)
		local healthY = kit.number(features, "Health Y", state, "healthY", -200, 200, 1)
		local distance = kit.flag(features, "Distance", state, "distance", { { key = "distanceColor" } }, function()
			refreshFeatures()
		end)
		local distanceY = kit.number(features, "Distance Y", state, "distanceY", -200, 200, 1)
		local weapon = kit.flag(features, "Weapon", state, "weapon", { { key = "weaponColor" } }, function()
			refreshFeatures()
		end)
		local weaponY = kit.number(features, "Weapon Y", state, "weaponY", -200, 200, 1)
		local weaponSize = kit.number(features, "Weapon size", state, "weaponSize", 8, 32, 1)
		local flags = kit.flag(features, "Flags", state, "flags", nil, function()
			refreshFeatures()
		end)
		local flagHealth = kit.flag(features, "Health flag", state, "flagHealth")
		local flagTeam = kit.flag(features, "Team flag", state, "flagTeam")
		local flagsY = kit.number(features, "Flags Y", state, "flagsY", -200, 200, 1)

		refreshFeatures = function()
			local on = state.master == true
			local map = {
				{ box, on },
				{ fill, on and state.box },
				{ outline, on and state.box },
				{ skeleton, on },
				{ skelOutline, on and state.skeleton },
				{ chams, on },
				{ chamsVis, on and state.chams },
				{ chamsOcc, on and state.chams },
				{ chamsAlpha, on and state.chams },
				{ onshot, on },
				{ onshotVis, on and state.onshot },
				{ onshotOcc, on and state.onshot },
				{ onshotAlpha, on and state.onshot },
				{ onshotTime, on and state.onshot },
				{ names, on },
				{ namePos, on and state.names },
				{ nameSize, on and state.names },
				{ health, on },
				{ healthGrad, on and state.health },
				{ healthAnim, on and state.health },
				{ healthAnimSp, on and state.health },
				{ healthThick, on and state.health },
				{ healthX, on and state.health },
				{ healthY, on and state.health },
				{ distance, on },
				{ distanceY, on and state.distance },
				{ weapon, on },
				{ weaponY, on and state.weapon },
				{ weaponSize, on and state.weapon },
				{ flags, on },
				{ flagHealth, on and state.flags },
				{ flagTeam, on and state.flags },
				{ flagsY, on and state.flags },
			}
			for _, entry in map do
				entry[1].enabled = entry[2] == true
			end
			pcall(function()
				features:UpdateOptions()
			end)
			pcall(function()
				tab:UpdateSections()
			end)
		end
		table.insert(DrawingBridge.syncers, refreshFeatures)
		refreshFeatures()

		kit.box(style, "Name override", function()
			return state.nameText
		end, function(value: string)
			state.nameText = value
		end, true)
		local fontList = DrawingBridge.EspFontNames
		if type(fontList) ~= "table" or #fontList == 0 then
			fontList = { "Plex", "UI", "System", "Monospace" }
		end
		local function filteredFonts(): { string }
			local names = DrawingBridge.EspFontNames
			if type(names) ~= "table" then
				names = fontList
			end
			local q = string.lower(tostring(state.fontSearch or ""))
			if q == "" then
				return names
			end
			local out = {}
			for _, name in names do
				if string.find(string.lower(name), q, 1, true) then
					table.insert(out, name)
				end
			end
			return if #out > 0 then out else names
		end
		kit.box(style, "search", function()
			return state.fontSearch
		end, function(value: string)
			state.fontSearch = value
			if DrawingBridge.requestSync then
				DrawingBridge.requestSync()
			end
		end, false)
		local fontChoice = kit.choice(style, "font", filteredFonts(), function()
			return state.font
		end, function(value: string)
			state.font = value
		end)
		local weightList = DrawingBridge.EspFontWeights or { "Regular", "Medium", "SemiBold", "Bold" }
		kit.choice(style, "weight", weightList, function()
			return state.fontWeight
		end, function(value: string)
			state.fontWeight = value
		end)
		DrawingBridge.EspFontList = fontChoice
		local fontListStamp = ""
		table.insert(DrawingBridge.syncers, function()
			local names = filteredFonts()
			if type(names) ~= "table" or not fontChoice then
				return
			end
			local stamp = tostring(state.fontSearch) .. "#" .. #names .. "#" .. tostring(names[1]) .. "#" .. tostring(names[#names])
			pcall(function()
				if fontListStamp ~= stamp then
					fontListStamp = stamp
					if fontChoice.SetValues then
						fontChoice:SetValues(names)
					else
						fontChoice:ClearValues()
						for _, name in names do
							fontChoice:AddValue(name)
						end
					end
				end
				fontChoice:Select(tostring(state.font), true)
			end)
		end)
		kit.separator(style, "Gradients")
		kit.flag(style, "Name gradient", state, "gradName", {
			{ key = "gradNameColor" },
			{ key = "gradNameColor2" },
		})
		kit.flag(style, "Distance gradient", state, "gradDistance", {
			{ key = "gradDistanceColor" },
			{ key = "gradDistanceColor2" },
		})
		kit.flag(style, "Weapon gradient", state, "gradWeapon", {
			{ key = "gradWeaponColor" },
			{ key = "gradWeaponColor2" },
		})
		kit.flag(style, "Flags gradient", state, "gradFlags", {
			{ key = "gradFlagsColor" },
			{ key = "gradFlagsColor2" },
		})
		kit.flag(style, "arrows", state, "arrows", { { key = "arrowsColor" } })
		kit.number(style, "arrow radius", state, "arrowsRadius", 20, 400, 1)

		local utilMain = tab:AddSection("utilities", 1)
		utilMain.subTab = "utility"
		local utilStyle = tab:AddSection("utility style", 2)
		utilStyle.subTab = "utility"
		local function utilOn(): boolean
			return UtilEsp.enabled == true
		end
		kit.flag(utilMain, "enabled", UtilEsp, "enabled", nil, function()
			if DrawingBridge.requestSync then
				DrawingBridge.requestSync()
			end
		end)
		local utilTypes = kit.masks(utilMain, "utilities", UTIL_ITEMS, function()
			return UtilEsp.types
		end)
		local utilRange = kit.number(utilMain, "max distance", UtilEsp, "maxDistance", 50, 3000, 10, { suffix = "st" })
		kit.gate(utilMain, utilOn, { utilTypes, utilRange })

		local utilLabels = {}
		local utilIdByLabel = {}
		local utilLabelById = {}
		for _, item in UTIL_ITEMS do
			table.insert(utilLabels, item.label)
			utilIdByLabel[item.label] = item.id
			utilLabelById[item.id] = item.label
		end
		local utilEdit = kit.choice(utilStyle, "edit", utilLabels, function()
			return utilLabelById[UtilEsp.editing] or utilLabels[1]
		end, function(value: string)
			local id = utilIdByLabel[value]
			if id and id ~= UtilEsp.editing then
				UtilEsp.editing = id
				if DrawingBridge.requestSync then
					DrawingBridge.requestSync()
				end
			end
		end)
		local utilFont = kit.choice(utilStyle, "font", fontList, function()
			return UtilStyleView.font
		end, function(value: string)
			UtilStyleView.font = value
		end)
		local utilFontNames: any = nil
		table.insert(DrawingBridge.syncers, function()
			local names = DrawingBridge.EspFontNames
			if type(names) ~= "table" or not utilFont then
				return
			end
			pcall(function()
				local stamp = tostring(#names) .. "#" .. tostring(names[1]) .. "#" .. tostring(names[#names])
				if utilFontNames ~= stamp then
					utilFontNames = stamp
					if utilFont.SetValues then
						utilFont:SetValues(names)
					else
						utilFont:ClearValues()
						for _, name in names do
							utilFont:AddValue(name)
						end
					end
				end
				utilFont:Select(tostring(UtilStyleView.font), true)
			end)
		end)
		local utilSize = kit.number(utilStyle, "text size", UtilStyleView, "textSize", 8, 24, 1)
		local utilImage = kit.flag(utilStyle, "image", UtilStyleView, "image")
		local utilImageSize = kit.number(utilStyle, "image size", UtilStyleView, "imageSize", 12, 48, 1)
		local utilBox = kit.flag(utilStyle, "box", UtilStyleView, "box", { { key = "boxColor" } })
		local utilName = kit.flag(utilStyle, "name", UtilStyleView, "name", { { key = "nameColor" } })
		local utilDist = kit.flag(utilStyle, "distance", UtilStyleView, "distance", { { key = "distanceColor" } })
		kit.gate(utilStyle, utilOn, { utilEdit, utilFont, utilSize, utilImage, utilImageSize, utilBox, utilName, utilDist })

		local extra = tab:AddSection("hit effects", 2)
		extra.subTab = "extra bs"
		local hitRefresh: () -> ()
		kit.flag(extra, "enable", HitFx, "enabled", nil, function()
			hitRefresh()
		end)
		local hitStyle = kit.choice(extra, "effect", { "loser x" }, function()
			return HitFx.style
		end, function(value: string)
			HitFx.style = value
		end)
		local hitColor = kit.color(extra, "color", function()
			return HitFx.color
		end, function(c3: Color3)
			HitFx.color = c3
		end)
		local hitFade = kit.number(extra, "fade", HitFx, "fade", 0.08, 2, 0.01, { suffix = "s" })
		local hitAnchor = kit.flag(extra, "anchor to player", HitFx, "anchor")
		hitRefresh = function()
			local on = HitFx.enabled == true
			for _, opt in { hitStyle, hitColor, hitFade, hitAnchor } do
				opt.enabled = on
			end
			pcall(function()
				extra:UpdateOptions()
				tab:UpdateSections()
			end)
		end
		table.insert(DrawingBridge.syncers, hitRefresh)
		hitRefresh()

		table.insert(EspPaintFns, DrawingBridge.requestSync)
	end

	do
		local function installEspRuntime()
		local DrawingLib: any = nil
		pcall(function()
			DrawingLib = Drawing
		end)
		if not DrawingLib then
			pcall(function()
				local env = fsGetgenv and fsGetgenv()
				if type(env) == "table" then
					DrawingLib = env.Drawing
				end
			end)
		end

		local hitMarks: { any } = {}
		local function hitLine(): any?
			if not DrawingLib then
				return nil
			end
			local ok, line = pcall(function()
				return DrawingLib.new("Line")
			end)
			if not ok or not line then
				return nil
			end
			line.Visible = false
			line.Thickness = 1
			line.Transparency = 1
			line.ZIndex = 55
			return line
		end
		local function hideHit(mark: any)
			if mark.a then mark.a.Visible = false end
			if mark.b then mark.b.Visible = false end
		end
		DrawingBridge.spawnHitFx = function(pos: Vector3, player: Player?)
			if HitFx.enabled ~= true or typeof(pos) ~= "Vector3" or not DrawingLib then
				return
			end
			if #hitMarks >= 12 then
				local old = table.remove(hitMarks, 1)
				if old then
					hideHit(old)
				end
			end
			local a, b = hitLine(), hitLine()
			if not a or not b then
				return
			end
			table.insert(hitMarks, {
				pos = pos,
				player = player,
				born = os.clock(),
				off = Vector2.new((math.random() - 0.5) * 18, (math.random() - 0.5) * 18),
				a = a,
				b = b,
			})
		end
		table.insert(ears, RunService.RenderStepped:Connect(function()
			local count = #hitMarks
			if count == 0 then
				return
			end
			if DrawingBridge.library and DrawingBridge.library.uiDragging then
				return
			end
			local cam = Workspace.CurrentCamera
			local now = os.clock()
			local life = math.clamp(HitFx.fade, 0.08, 2)
			local tint = HitFx.color
			local size = 3.2
			for index = count, 1, -1 do
				local mark = hitMarks[index]
				local age = now - mark.born
				if age >= life or not cam then
					hideHit(mark)
					table.remove(hitMarks, index)
					continue
				end
				local u = age / life
				local alpha = if u < 0.18 then u / 0.18 else 1 - ((u - 0.18) / 0.82)
				local world = mark.pos
				if HitFx.anchor and mark.player and mark.player.Parent then
					local ch = mark.player.Character
					local root = ch and (ch:FindFirstChild("HumanoidRootPart") or ch:FindFirstChild("Head"))
					if root and root:IsA("BasePart") then
						world = root.Position
					end
				end
				local sp, onScreen = cam:WorldToViewportPoint(world)
				local show = HitFx.enabled == true and onScreen and sp.Z > 0
				local c = Vector2.new(sp.X, sp.Y) + mark.off
				local d = size * 0.7071
				mark.a.From = Vector2.new(c.X - d, c.Y - d)
				mark.a.To = Vector2.new(c.X + d, c.Y + d)
				mark.b.From = Vector2.new(c.X - d, c.Y + d)
				mark.b.To = Vector2.new(c.X + d, c.Y - d)
				mark.a.Color = tint
				mark.b.Color = tint
				mark.a.Transparency = alpha
				mark.b.Transparency = alpha
				mark.a.Visible = show
				mark.b.Visible = show
			end
		end))
		table.insert(ears, {
			Disconnect = function()
				for _, mark in hitMarks do
					hideHit(mark)
					pcall(function()
						if mark.a and mark.a.Remove then mark.a:Remove() end
						if mark.b and mark.b.Remove then mark.b:Remove() end
					end)
				end
				table.clear(hitMarks)
			end,
		} :: any)

		local FONT_DIR = CONFIG_FOLDER .. "/fonts"
		local EspFontFaces: { [string]: Font } = {}
		local EspFontOrder: { string } = {}
		local EspFontIsPixel: { [string]: boolean } = {
			System = true,
