			local seen: { [string]: boolean } = {}
			for _, name in EspFontOrder do
				seen[name] = true
			end
			for name in string.gmatch(FONT_CATALOG, "[^\r\n]+") do
				name = string.gsub(name, "^%s+", "")
				name = string.gsub(name, "%s+$", "")
				if name ~= "" and not seen[name] then
					seen[name] = true
					table.insert(EspFontOrder, name)
				end
			end
			DrawingBridge.EspFontNames = table.clone(EspFontOrder)
		end

		local function resolveEspFont(name: string): Font
			local key = tostring(name or "Plex")
			local wName = tostring(Esp.fontWeight or "Regular")
			local cacheKey = key .. "|" .. wName
			local cached = fontFaceCache[cacheKey]
			if cached then
				return cached
			end
			local w = FONT_WEIGHT_ENUM[wName]
			if typeof(w) ~= "EnumItem" then
				w = Enum.FontWeight.Regular
			end
			local function store(face: Font): Font
				fontFaceCache[cacheKey] = face
				return face
			end
			local base = EspFontFaces[key]
			if typeof(base) == "Font" then
				local ok, face = pcall(function()
					return Font.new(base.Family, w, Enum.FontStyle.Normal)
				end)
				if ok and typeof(face) == "Font" then
					return store(face)
				end
				return store(base)
			end
			local compact = string.gsub(key, "%s+", "")
			local okName, faceName = pcall(Font.fromName, compact, w)
			if okName and typeof(faceName) == "Font" then
				EspFontFaces[key] = faceName
				return store(faceName)
			end
			local okAsset, faceAsset = pcall(function()
				return Font.new("rbxasset://fonts/families/" .. compact .. ".json", w, Enum.FontStyle.Normal)
			end)
			if okAsset and typeof(faceAsset) == "Font" then
				EspFontFaces[key] = faceAsset
				return store(faceAsset)
			end
			local fallback = EspFontFaces.Plex or EspFontFaces.System or EspFontFaces.UI
			if typeof(fallback) == "Font" then
				local okF, faceF = pcall(function()
					return Font.new(fallback.Family, w, Enum.FontStyle.Normal)
				end)
				if okF and typeof(faceF) == "Font" then
					return store(faceF)
				end
				return store(fallback)
			end
			return Font.fromEnum(Enum.Font.Code)
		end

