		local function fontAsset(path: string): string?
			local fn = execApi("getcustomasset") or execApi("GetCustomAsset") or execApi("getsynasset") or execApi("GetSynAsset")
			if typeof(fn) ~= "function" then
				return nil
			end
			local ok, asset = pcall(fn :: (string) -> string, path)
			if ok and type(asset) == "string" and asset ~= "" then
				return asset
			end
			return nil
		end

		local function rememberFont(name: string, face: Font, pixel: boolean?, pixelStep: number?)
			EspFontFaces[name] = face
			if not table.find(EspFontOrder, name) then
				table.insert(EspFontOrder, name)
			end
			if pixel == true then
				EspFontIsPixel[name] = true
			end
			if type(pixelStep) == "number" and pixelStep > 0 then
				EspFontPixelStep[name] = pixelStep
			end
		end

		for _, entry in {
			{ name = "Teko Cloud", id = 12187376174, weight = Enum.FontWeight.Bold },
			{ name = "Bungee Cloud", id = 12187370000, weight = Enum.FontWeight.Regular },
			{ name = "Audiowide", id = 12187360881, weight = Enum.FontWeight.Regular },
			{ name = "Faster One", id = 12187370928, weight = Enum.FontWeight.Regular },
		} do
			local okFace, face = pcall(Font.fromId, entry.id, entry.weight, Enum.FontStyle.Normal)
			if okFace and typeof(face) == "Font" and EspFontFaces[entry.name] == nil then
				rememberFont(entry.name, face)
			end
		end
		DrawingBridge.EspFontNames = table.clone(EspFontOrder)

		local function isPixelFontKey(key: string): boolean
			if EspFontIsPixel[key] then
				return true
			end
			local lower = string.lower(key)
			return string.find(lower, "proggy", 1, true) ~= nil
				or string.find(lower, "pixel", 1, true) ~= nil
				or string.find(lower, "press start", 1, true) ~= nil
				or string.find(lower, "silkscreen", 1, true) ~= nil
				or string.find(lower, "vt323", 1, true) ~= nil
				or string.find(lower, "tiny5", 1, true) ~= nil
				or string.find(lower, "unscii", 1, true) ~= nil
				or string.find(lower, "minecraft", 1, true) ~= nil
		end

		local function snapPixelTextSize(key: string, size: number): number
			local n = math.clamp(math.floor(size + 0.5), 8, 32)
			local step = EspFontPixelStep[key]
			if type(step) == "number" and step > 1 then
				n = math.max(step, math.floor(n / step + 0.5) * step)
			end
			return n
		end

		local function fontWeightEnum(weight: number): EnumItem
			if weight >= 800 then
				return Enum.FontWeight.ExtraBold
			elseif weight >= 700 then
				return Enum.FontWeight.Bold
			elseif weight >= 600 then
				return Enum.FontWeight.SemiBold
			elseif weight >= 500 then
				return Enum.FontWeight.Medium
			elseif weight <= 300 then
				return Enum.FontWeight.Light
			end
			return Enum.FontWeight.Regular
		end

		local function registerFontFace(name: string, path: string, weight: number?, pixel: boolean?, pixelStep: number?): boolean
			local asset = fontAsset(path)
			if not asset then
				return false
			end
			local w = if type(weight) == "number" then weight else 400
			local faceLabel = if w >= 700 then "Bold" elseif w >= 600 then "SemiBold" elseif w <= 300 then "Light" else "Regular"
			local weightEnum = fontWeightEnum(w)
			local slug = string.lower((string.gsub(name, "[^%w]+", "_")))
			local familyPath = FONT_DIR .. "/" .. slug .. ".font.json"
			local familyJson = HttpService:JSONEncode({
				name = name,
				faces = {
					{
						name = faceLabel,
						weight = w,
						style = "normal",
						assetId = asset,
					},
				},
			})
			if hasFsApi("writefile") then
				pcall(fsWritefile, familyPath, familyJson)
			end
			local familyAsset = fontAsset(familyPath)
			if familyAsset then
				local okFamily, faceFamily = pcall(function()
					return Font.new(familyAsset, weightEnum, Enum.FontStyle.Normal)
				end)
				if okFamily and typeof(faceFamily) == "Font" then
					rememberFont(name, faceFamily)
					return true
				end
				local okPlain, facePlain = pcall(function()
					return Font.new(familyAsset)
				end)
				if okPlain and typeof(facePlain) == "Font" then
					rememberFont(name, facePlain)
					return true
				end
			end
			local okDirect, faceDirect = pcall(function()
				return Font.new(asset, weightEnum, Enum.FontStyle.Normal)
			end)
			if okDirect and typeof(faceDirect) == "Font" then
				rememberFont(name, faceDirect)
				return true
			end
			return false
		end

		local registerFontFaceRaw = registerFontFace
		registerFontFace = function(name: string, path: string, weight: number?, pixel: boolean?, pixelStep: number?): boolean
			local ok = registerFontFaceRaw(name, path, weight)
			if ok then
				if pixel == true or isPixelFontKey(name) then
					EspFontIsPixel[name] = true
				end
				if type(pixelStep) == "number" and pixelStep > 0 then
					EspFontPixelStep[name] = pixelStep
				end
			end
			return ok
		end

		local function publishFontNames()
			DrawingBridge.EspFontNames = table.clone(EspFontOrder)
			if DrawingBridge.requestSync then
				pcall(DrawingBridge.requestSync)
			end
		end

		local function ensureFontFolder()
			if hasFsApi("makefolder") and not fsIsfolder(CONFIG_FOLDER) then
				pcall(fsMakefolder, CONFIG_FOLDER)
			end
			if hasFsApi("makefolder") and not fsIsfolder(FONT_DIR) then
				pcall(fsMakefolder, FONT_DIR)
			end
		end

		local function fontFileReady(path: string): boolean
			if not hasFsApi("readfile") then
				return false
			end
			local okRead, data = pcall(fsReadfile, path)
			return okRead and type(data) == "string" and #data > 64
		end

		local function basenameNoExt(path: string): string
			local name = path
			local slash = string.match(path, "[/\\]([^/\\]+)$")
			if slash then
				name = slash
			end
			name = string.gsub(name, "%.%w+$", "")
			name = string.gsub(name, "[-_]+", " ")
			return name
		end

		local function registerDroppedFonts()
			local listFn = execApi("listfiles")
			if typeof(listFn) ~= "function" then
				return
			end
			local okList, files = pcall(listFn :: (string) -> { string }, FONT_DIR)
			if not okList or type(files) ~= "table" then
				return
			end
			for _, path in files do
				if type(path) ~= "string" then
					continue
				end
				local lower = string.lower(path)
				if not (string.find(lower, "%.ttf$") or string.find(lower, "%.otf$")) then
					continue
				end
				local name = basenameNoExt(path)
				if name == "" or EspFontFaces[name] then
					continue
				end
				local weight = if string.find(string.lower(name), "bold") then 700 else 400
				local pixel = isPixelFontKey(name)
				pcall(function()
					registerFontFace(name, path, weight, pixel)
				end)
			end
		end

		local function loadExistingEspFonts()
			ensureFontFolder()
			for _, entry in FONT_PACK do
				local path = FONT_DIR .. "/" .. entry.file
				if fontFileReady(path) then
					pcall(function()
						registerFontFace(entry.name, path, entry.weight, entry.pixel, entry.pixelStep)
					end)
				end
			end
			pcall(registerDroppedFonts)
			publishFontNames()
		end

		local function downloadEspFonts()
			ensureFontFolder()
			if not hasFsApi("writefile") then
				publishFontNames()
				return
			end
			for _, entry in FONT_PACK do
				local path = FONT_DIR .. "/" .. entry.file
				if not fontFileReady(path) then
					local okGet, body = pcall(function()
						return game:HttpGet(entry.url)
					end)
					if okGet and type(body) == "string" and #body > 64 then
						pcall(fsWritefile, path, body)
					end
				end
				if fontFileReady(path) then
					pcall(function()
						registerFontFace(entry.name, path, entry.weight, entry.pixel, entry.pixelStep)
					end)
				end
				task.wait()
			end
			pcall(registerDroppedFonts)
			publishFontNames()
		end

		pcall(loadExistingEspFonts)

		local espTextGui: ScreenGui? = nil
		local function ensureEspTextGui(): ScreenGui?
			if espTextGui and espTextGui.Parent then
				return espTextGui
			end
			local gui = Instance.new("ScreenGui")
			gui.Name = "sonata_esp_fonts"
			gui.ResetOnSpawn = false
			gui.IgnoreGuiInset = true
			gui.DisplayOrder = 999999
			gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
			pcall(function()
				(gui :: any).OnTopOfCoreBlur = true
			end)
			local parent: Instance? = fsGethui()
			if not parent then
				local lp = Players.LocalPlayer
				parent = lp and lp:FindFirstChildOfClass("PlayerGui")
			end
			if not parent then
				parent = game:GetService("CoreGui")
			end
			gui.Parent = parent
			espTextGui = gui
			table.insert(ears, {
				Disconnect = function()
					table.clear(fontFaceCache)
					table.clear(EspFontFaces)
					if espTextGui then
						pcall(function()
							espTextGui:Destroy()
						end)
						espTextGui = nil
					end
				end,
			} :: any)
			return gui
		end

		local function newsquare(z: number): any?
			if not DrawingLib then
				return nil
			end
			local ok, square = pcall(function()
				return DrawingLib.new("Square")
			end)
			if not ok or not square then
				return nil
			end
			square.Filled = false
			square.Thickness = 1
			square.Color = Color3.new(0, 0, 0)
			square.Visible = false
			square.Transparency = 1
			square.ZIndex = math.max(1, z)
			return square
		end

		local function newline(): any?
			if not DrawingLib then
				return nil
			end
			local ok, line = pcall(function()
				return DrawingLib.new("Line")
			end)
			if not ok or not line then
				return nil
			end
			line.Thickness = 1
			line.Color = Color3.new(1, 1, 1)
			line.Visible = false
			line.Transparency = 1
			line.ZIndex = 1
			return line
		end

		local PIXEL_OUTLINE_DIRS = {
			Vector2.new(-1, 0),
			Vector2.new(1, 0),
			Vector2.new(0, -1),
			Vector2.new(0, 1),
		}

		local function newtext(): any?
			local gui = ensureEspTextGui()
			if not gui then
				return nil
			end

			local function makeLabel(name: string, z: number): TextLabel
				local label = Instance.new("TextLabel")
				label.Name = name
				label.BackgroundTransparency = 1
				label.BorderSizePixel = 0
				label.AutomaticSize = Enum.AutomaticSize.XY
				label.TextScaled = false
				label.TextWrapped = false
				label.RichText = false
				label.Rotation = 0
				label.TextSize = 13
				label.TextColor3 = Color3.new(1, 1, 1)
				label.TextStrokeColor3 = Color3.new(0, 0, 0)
				label.TextStrokeTransparency = 1
				label.TextTransparency = 0
				label.TextXAlignment = Enum.TextXAlignment.Left
				label.TextYAlignment = Enum.TextYAlignment.Top
				label.AnchorPoint = Vector2.zero
				label.FontFace = EspFontFaces.Plex or Font.fromEnum(Enum.Font.Code)
				label.Visible = false
				label.ZIndex = z
				label.Text = ""
				label.Parent = gui
				local grad = Instance.new("UIGradient")
				grad.Enabled = false
				grad.Rotation = 0
				grad.Offset = Vector2.zero
				grad.Parent = label
				return label, grad
			end

			local label, fillGrad = makeLabel("esp_text", 12)
			local outlines: { TextLabel } = {}
			for i = 1, #PIXEL_OUTLINE_DIRS do
				local ol = makeLabel("esp_text_ol", 11)
				table.insert(outlines, ol)
			end

			local state = {
				Center = true,
				Position = Vector2.zero,
				Outline = true,
				OutlineColor = Color3.new(0, 0, 0),
				Transparency = 1,
				FontKey = "Plex",
				Pixel = false,
				Size = 13,
				GradA = nil :: Color3?,
				GradB = nil :: Color3?,
				GradU = 0,
			}

			local function sampleLoop(a: Color3, b: Color3, p: number): Color3
				local x = p % 1
				if x < 0.5 then
					return a:Lerp(b, x * 2)
				end
				return b:Lerp(a, (x - 0.5) * 2)
			end

			local function paintEspScroll(u: number)
				local a, b = state.GradA, state.GradB
				if not (a and b) then
					return
				end
				local t = u % 1
				state.GradU = t
				fillGrad.Enabled = true
				fillGrad.Rotation = 0
				fillGrad.Offset = Vector2.zero
				pcall(function()
					local c0 = sampleLoop(a, b, t)
					fillGrad.Color = ColorSequence.new({
						ColorSequenceKeypoint.new(0, c0),
						ColorSequenceKeypoint.new(1 / 6, sampleLoop(a, b, t + 1 / 6)),
						ColorSequenceKeypoint.new(2 / 6, sampleLoop(a, b, t + 2 / 6)),
						ColorSequenceKeypoint.new(3 / 6, sampleLoop(a, b, t + 3 / 6)),
						ColorSequenceKeypoint.new(4 / 6, sampleLoop(a, b, t + 4 / 6)),
						ColorSequenceKeypoint.new(5 / 6, sampleLoop(a, b, t + 5 / 6)),
						ColorSequenceKeypoint.new(1, c0),
					})
				end)
			end

			local function syncOutlineStyle()
				local fillT = math.clamp(1 - state.Transparency, 0, 1)
				local useHard = state.Pixel == true
				label.TextStrokeTransparency = if (state.Outline and not useHard) then fillT else 1
				for _, ol in outlines do
					ol.TextColor3 = state.OutlineColor
					ol.TextStrokeTransparency = 1
					ol.TextTransparency = if (state.Outline and useHard) then fillT else 1
					ol.Visible = label.Visible and state.Outline and useHard and label.Text ~= ""
				end
			end

			local function applyLayout()
				local ax = math.floor(state.Position.X + 0.5)
				local ay = math.floor(state.Position.Y + 0.5)
				local x, y = ax, ay
				if state.Center then
					local b = label.TextBounds
					x = math.floor(ax - b.X * 0.5 + 0.5)
					y = math.floor(ay - b.Y * 0.5 + 0.5)
				end
				label.AnchorPoint = Vector2.zero
				label.Position = UDim2.fromOffset(x, y)
				label.TextXAlignment = Enum.TextXAlignment.Left
				label.TextYAlignment = Enum.TextYAlignment.Top
				for i, ol in outlines do
					local d = PIXEL_OUTLINE_DIRS[i]
					ol.AnchorPoint = Vector2.zero
					ol.Position = UDim2.fromOffset(x + d.X, y + d.Y)
					ol.TextXAlignment = Enum.TextXAlignment.Left
					ol.TextYAlignment = Enum.TextYAlignment.Top
				end
				syncOutlineStyle()
			end

			local function applyTextSize(size: number)
				local n = math.floor(size + 0.5)
				if state.Pixel then
					n = snapPixelTextSize(state.FontKey, n)
				end
				state.Size = n
				label.TextSize = n
				for _, ol in outlines do
					ol.TextSize = n
				end
			end

			local function applyFontValue(value: any)
				local name = if type(value) == "string" then value else tostring(Esp.font or state.FontKey or "Plex")
				if typeof(value) == "Font" then
					local key = tostring(Esp.font or state.FontKey or "")
					if key ~= "" then
						name = key
					end
				end
				state.FontKey = name
				state.Pixel = isPixelFontKey(name)
				local face = resolveEspFont(name)
				if typeof(face) == "Font" then
					label.FontFace = face
					for _, ol in outlines do
						ol.FontFace = face
					end
				end
				pcall(function()
					label.Font = Enum.Font.Unknown
				end)
				applyTextSize(state.Size)
				applyLayout()
			end

			applyLayout()

			local proxy: any = {}
			setmetatable(proxy, {
				__index = function(_, key: string): any
					if key == "Text" then
						return label.Text
					elseif key == "Visible" then
						return label.Visible
					elseif key == "Color" then
						return label.TextColor3
					elseif key == "Size" then
						return state.Size
					elseif key == "Position" then
						return state.Position
					elseif key == "Center" then
						return state.Center
					elseif key == "Font" then
						return state.FontKey
					elseif key == "TextBounds" then
						return label.TextBounds
					elseif key == "Transparency" then
						return state.Transparency
					elseif key == "Outline" then
						return state.Outline
					elseif key == "OutlineColor" then
						return state.OutlineColor
					elseif key == "Remove" or key == "Destroy" then
						return function()
							pcall(function()
								label:Destroy()
							end)
							for _, ol in outlines do
								pcall(function()
									ol:Destroy()
								end)
							end
						end
					end
					return nil
				end,
				__newindex = function(_, key: string, value: any)
					if key == "Text" then
						local text = tostring(value or "")
						if label.Text ~= text then
							label.Text = text
							for _, ol in outlines do
								ol.Text = text
							end
							applyLayout()
						end
					elseif key == "Visible" then
						local v = value == true
						if label.Visible ~= v then
							label.Visible = v
							syncOutlineStyle()
						end
					elseif key == "Color" and typeof(value) == "Color3" then
						if label.TextColor3 ~= value then
							label.TextColor3 = value
						end
					elseif key == "Gradient" then
						if type(value) == "table" and typeof(value[1]) == "Color3" and typeof(value[2]) == "Color3" then
							state.GradA = value[1]
							state.GradB = value[2]
							label.TextColor3 = Color3.new(1, 1, 1)
							paintEspScroll(state.GradU)
						else
							state.GradA = nil
							state.GradB = nil
							fillGrad.Enabled = false
							fillGrad.Offset = Vector2.zero
						end
					elseif key == "GradientOffset" and type(value) == "number" then
						if state.GradA and state.GradB then
							paintEspScroll(value)
						end
					elseif key == "Size" and type(value) == "number" then
						if state.Size ~= value then
							applyTextSize(value)
							applyLayout()
						end
					elseif key == "Position" and typeof(value) == "Vector2" then
						local px = math.floor(value.X + 0.5)
						local py = math.floor(value.Y + 0.5)
						if state.Position.X ~= px or state.Position.Y ~= py then
							state.Position = Vector2.new(px, py)
							applyLayout()
						end
					elseif key == "Center" then
						local c = value == true
						if state.Center ~= c then
							state.Center = c
							applyLayout()
						end
					elseif key == "Font" then
						applyFontValue(value)
					elseif key == "Transparency" and type(value) == "number" then
						if state.Transparency ~= value then
							state.Transparency = value
							label.TextTransparency = math.clamp(1 - value, 0, 1)
							syncOutlineStyle()
						end
					elseif key == "Outline" then
						local o = value == true
						if state.Outline ~= o then
							state.Outline = o
							syncOutlineStyle()
						end
					elseif key == "OutlineColor" and typeof(value) == "Color3" then
						if state.OutlineColor ~= value then
							state.OutlineColor = value
							label.TextStrokeColor3 = value
							syncOutlineStyle()
						end
					end
				end,
			})
			return proxy
		end
		DrawingBridge.newEspText = newtext

		local function _resolvefont(name: string): Font?
			return resolveEspFont(tostring(name or "System"))
		end

		local function gradientColor(t: number, low: Color3, mid: Color3, high: Color3): Color3
			if t <= 0.5 then
				return low:Lerp(mid, t * 2)
			end
			return mid:Lerp(high, (t - 0.5) * 2)
		end

		local lastWaveTime = -1
		local lastWaveVal = 0
		local function currentWave(): number
			local now = os.clock()
			if now ~= lastWaveTime then
				lastWaveTime = now
				lastWaveVal = (math.sin(now * 1.6) + 1) * 0.5
			end
			return lastWaveVal
		end

		local function waveColor(base: Color3, accent: Color3): Color3
			local u = (os.clock() * 0.55) % 1
			if u < 0.5 then
				return base
			end
			return accent
		end
		local function scrollGrad(): number
			return os.clock() * 0.42
		end

		local function isLivePlayer(player: any): boolean
			return typeof(player) == "Instance"
				and player:IsA("Player")
				and player.Parent ~= nil
				and player:IsDescendantOf(Players)
		end

		local function setDrawAlpha(obj: any, alpha: number)
			if obj.Transparency ~= alpha then
				obj.Transparency = alpha
			end
		end

		local function place(square: any, x: number, y: number, w: number, h: number, paint: Color3, alpha: number, visible: boolean)
			local show = visible and w >= 1 and h >= 1
			if square._vis ~= show then
				square._vis = show
				square.Visible = show
			end
			if not show then
				return
			end
			local px = math.floor(x)
			local py = math.floor(y)
			local pw = math.floor(w)
			local ph = math.floor(h)
			if square._px ~= px or square._py ~= py then
				square._px = px
				square._py = py
				square.Position = Vector2.new(px, py)
			end
			if square._pw ~= pw or square._ph ~= ph then
				square._pw = pw
				square._ph = ph
				square.Size = Vector2.new(pw, ph)
			end
			if square._color ~= paint then
				square._color = paint
				square.Color = paint
			end
			if square._alpha ~= alpha then
				square._alpha = alpha
				square.Transparency = alpha
			end
		end

		local entries: { [Player]: any } = {}
		local roster: { Player } = {}
		local fighters: any = nil
		local duels: any = nil
		local seenDuel: any = nil
		local duelerOf: { [Player]: any } = {}
		local teamOf: { [Player]: any } = {}

		local function destroyDrawing(obj: any)
			if obj == nil then
				return
			end
			pcall(function()
				obj.Visible = false
			end)
			pcall(function()
				if type(obj.Remove) == "function" then
					obj:Remove()
				elseif type(obj.Destroy) == "function" then
					obj:Destroy()
				end
			end)
		end

		local function destroyEntry(player: Player)
			local entry = entries[player]
			if not entry then
				return
			end
			entries[player] = nil
			duelerOf[player] = nil
			teamOf[player] = nil
			for key, obj in entry do
				if key == "on" then
					continue
				end
				if key == "bones" and type(obj) == "table" then
					for _, bone in obj do
						if type(bone) == "table" then
							destroyDrawing(bone.line)
							destroyDrawing(bone.outline)
						end
					end
					continue
				end
				if key == "healthSegs" and type(obj) == "table" then
					for _, seg in obj do
						destroyDrawing(seg)
					end
					continue
				end
				if typeof(obj) == "Instance" then
					pcall(function()
						obj:Destroy()
					end)
				elseif type(obj) == "userdata" or type(obj) == "table" then
					destroyDrawing(obj)
				end
			end
		end

		local function hideBones(entry: any)
			if not entry or not entry.bones then
				return
			end
			for _, bone in entry.bones do
				pcall(function()
					bone.line.Visible = false
					bone.outline.Visible = false
				end)
			end
		end

		local function hideHealthSegs(entry: any)
			if not entry or type(entry.healthSegs) ~= "table" then
				return
			end
			for _, seg in entry.healthSegs do
				pcall(function()
					seg.Visible = false
				end)
			end
		end

		local function hideEntry(entry: any)
			if not entry then
				return
			end
			entry.on = false
			pcall(function()
				entry.outline.Visible = false
				entry.box.Visible = false
				entry.inline.Visible = false
				entry.fill.Visible = false
				entry.healthbg.Visible = false
				entry.health.Visible = false
				entry.name.Visible = false
				entry.distance.Visible = false
				entry.weapon.Visible = false
				entry.flag.Visible = false
			end)
				hideHealthSegs(entry)
			if entry.healthUi then
				entry.healthUi.bg.Visible = false
			end
			if entry.arrow then
				pcall(function()
					entry.arrow.Visible = false
					if entry.arrowL then entry.arrowL.Visible = false end
					if entry.arrowR then entry.arrowR.Visible = false end
				end)
			end
			hideBones(entry)
		end

		local function refreshRoster()
			if type(roster) ~= "table" then
				roster = {}
			else
				table.clear(roster)
			end
			local list: any = nil
			pcall(function()
				list = Players:GetPlayers()
			end)
			if type(list) ~= "table" then
				return
			end
			local localPlayer = Players.LocalPlayer
			for _, player in list do
				if typeof(player) == "Instance" and player:IsA("Player") and player ~= localPlayer then
					table.insert(roster, player)
				end
			end
		end
		refreshRoster()
		table.insert(ears, Players.PlayerAdded:Connect(function()
			refreshRoster()
		end))
		table.insert(ears, Players.PlayerRemoving:Connect(function(player: Player)
			destroyEntry(player)
			refreshRoster()
		end))

		local charCleaners: { [Player]: RBXScriptConnection } = {}
		local function watchCharacter(player: Player)
			local old = charCleaners[player]
			if old then
				pcall(function()
					old:Disconnect()
				end)
				charCleaners[player] = nil
			end
			local function onCharacter(character: Model?)
				if not character then
					hideEntry(entries[player])
					return
				end
				local humanoid = character:FindFirstChildOfClass("Humanoid")
				if humanoid then
					table.insert(ears, humanoid.Died:Connect(function()
						hideEntry(entries[player])
					end))
				end
				table.insert(ears, character.AncestryChanged:Connect(function(_, parent)
					if parent == nil then
						hideEntry(entries[player])
					end
				end))
			end
			if player.Character then
				onCharacter(player.Character)
			end
			charCleaners[player] = player.CharacterAdded:Connect(function(character)
				hideEntry(entries[player])
				onCharacter(character)
			end)
			table.insert(ears, player.CharacterRemoving:Connect(function()
				hideEntry(entries[player])
			end))
		end
		for _, player in Players:GetPlayers() do
			if player ~= Players.LocalPlayer then
				watchCharacter(player)
			end
		end
		table.insert(ears, Players.PlayerAdded:Connect(function(player: Player)
			watchCharacter(player)
		end))
		table.insert(ears, Players.PlayerRemoving:Connect(function(player: Player)
			local cleaner = charCleaners[player]
			if cleaner then
				pcall(function()
					cleaner:Disconnect()
				end)
				charCleaners[player] = nil
			end
		end))

		local function bindControllers(): boolean
			local client = Players.LocalPlayer
			if not client then
				return false
			end
			local scripts = client:FindFirstChild("PlayerScripts")
			if not scripts then
				return false
			end
			local controllers = scripts:FindFirstChild("Controllers")
			if not controllers then
				return false
			end
			local fighterMod = controllers:FindFirstChild("FighterController")
			local duelMod = controllers:FindFirstChild("DuelController") or controllers:FindFirstChild("DuelsController")
			if not fighterMod or not duelMod then
				fighters = nil
				duels = nil
				return false
			end
			local okF, f = pcall(require, fighterMod)
			local okD, d = pcall(require, duelMod)
			if okF and type(f) == "table" then
				fighters = f
			else
				fighters = nil
			end
			if okD and type(d) == "table" then
				duels = d
			else
				duels = nil
			end
			return fighters ~= nil and duels ~= nil
		end

		local cachedDuel: any = nil
		local cachedTeam: any = nil
		local lastMatchEnemiesAt = -1
		local function matchEnemies(): (any, any)
			local now = os.clock()
			if lastMatchEnemiesAt >= 0 and (now - lastMatchEnemiesAt) < 0.45 then
				return cachedDuel, cachedTeam
			end
			local inMatchProbe = DrawingBridge.isInGameMatch
			if type(inMatchProbe) == "function" then
				local okMatch, inMatch = pcall(inMatchProbe)
				if okMatch and inMatch ~= true then
					cachedDuel, cachedTeam = nil, nil
					lastMatchEnemiesAt = now
					return nil, nil
				end
			end
			if not fighters or not duels then
				if not bindControllers() then
					cachedDuel, cachedTeam = nil, nil
					lastMatchEnemiesAt = now
					return nil, nil
				end
			end
			local mine = fighters.LocalFighter
			if not mine then
				cachedDuel, cachedTeam = nil, nil
				lastMatchEnemiesAt = now
				return nil, nil
			end
			local current, team
			pcall(function()
				current = duels:GetDuel(Players.LocalPlayer)
				if current then
					local me = current:GetDueler(Players.LocalPlayer)
					if me then
						team = me:Get("TeamID")
					end
				end
			end)
			cachedDuel = current
			cachedTeam = team
			lastMatchEnemiesAt = now
			return current, team
		end

		local function livingCharacter(player: Player): (Model?, Humanoid?)
			if not isLivePlayer(player) or player == Players.LocalPlayer then
				return nil, nil
			end
			local character = player.Character
			if not character or character.Parent == nil then
				return nil, nil
			end
			local humanoid = character:FindFirstChildOfClass("Humanoid")
			if not humanoid or humanoid.Health <= 0 then
				return nil, nil
			end
			return character, humanoid
		end

		local function livingEnemy(player: Player, duel: any, team: any): (Model?, Humanoid?)
			if not isLivePlayer(player) then
				return nil, nil
			end
			if not duel then
				return livingCharacter(player)
			end
			if seenDuel ~= duel then
				seenDuel = duel
				table.clear(duelerOf)
				table.clear(teamOf)
			end
			local dueler = duelerOf[player]
			if dueler == nil then
				local foundOk, found = pcall(function()
					return duel:GetDueler(player)
				end)
				dueler = if foundOk then found else false
				duelerOf[player] = dueler
			end
			if not dueler or dueler == false then
				return livingCharacter(player)
			end
			if dueler._is_ally == true then
				return nil, nil
			end
			local theirTeam = teamOf[player]
			if theirTeam == nil then
				local teamOk, foundTeam = pcall(function()
					return dueler:Get("TeamID")
				end)
				theirTeam = if teamOk then foundTeam else false
				teamOf[player] = theirTeam
			end
			if theirTeam ~= false and team ~= nil and theirTeam == team then
				return nil, nil
			end
			local fighter = dueler.ClientFighter
			local entity = fighter and fighter.Entity
			local character = entity and entity.RootPart and entity.RootPart.Parent
			if typeof(character) ~= "Instance" or not character:IsA("Model") then
				character = player.Character
			end
			if character and character.Parent == nil then
				character = player.Character
			end
			if not character or character.Parent == nil then
				return livingCharacter(player)
			end
			local humanoid = entity and entity.Humanoid
			if typeof(humanoid) ~= "Instance" or humanoid.Parent == nil then
				humanoid = character:FindFirstChildOfClass("Humanoid")
			end
			if not humanoid or humanoid.Health <= 0 then
				return nil, nil
			end
			return character :: Model, humanoid :: Humanoid
		end

		local BODY_PART_SET = {
			Head = true, HitboxHead = true, HumanoidRootPart = true,
			UpperTorso = true, LowerTorso = true, Torso = true,
			LeftUpperArm = true, RightUpperArm = true, LeftLowerArm = true, RightLowerArm = true,
			LeftUpperLeg = true, RightUpperLeg = true, LeftLowerLeg = true, RightLowerLeg = true,
		}

		local function bounds(character: Model, camera: Camera, head: Instance?): (number?, number?, number?, number?)
			local root = character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso")
			if root and root:IsA("BasePart") then
				local screen = camera:WorldToViewportPoint(root.Position)
				if screen.Z <= 0 then
					return nil, nil, nil, nil
				end
			end
			local min3D_X, min3D_Y, min3D_Z = math.huge, math.huge, math.huge
			local max3D_X, max3D_Y, max3D_Z = -math.huge, -math.huge, -math.huge
			local foundAny = false

			local function expandPart(part: BasePart?)
				if not part then return end
				local cf = part.CFrame
				local half = part.Size * 0.5
				local right = cf.RightVector * half.X
				local up = cf.UpVector * half.Y
				local look = cf.LookVector * half.Z
				local c = cf.Position
				local pX = math.abs(right.X) + math.abs(up.X) + math.abs(look.X)
				local pY = math.abs(right.Y) + math.abs(up.Y) + math.abs(look.Y)
				local pZ = math.abs(right.Z) + math.abs(up.Z) + math.abs(look.Z)
				if c.X - pX < min3D_X then min3D_X = c.X - pX end
				if c.X + pX > max3D_X then max3D_X = c.X + pX end
				if c.Y - pY < min3D_Y then min3D_Y = c.Y - pY end
				if c.Y + pY > max3D_Y then max3D_Y = c.Y + pY end
				if c.Z - pZ < min3D_Z then min3D_Z = c.Z - pZ end
				if c.Z + pZ > max3D_Z then max3D_Z = c.Z + pZ end
				foundAny = true
			end

			for _, child in character:GetChildren() do
				if child:IsA("BasePart") and BODY_PART_SET[child.Name] then
					expandPart(child :: BasePart)
				end
			end

			if not foundAny and head and head:IsA("BasePart") then
				expandPart(head :: BasePart)
			end

			if not foundAny then
				if root and root:IsA("BasePart") then
					local screen = camera:WorldToViewportPoint(root.Position)
					if screen.Z > 0 then
						local scale = math.clamp(220 / math.max(screen.Z, 1), 8, 90)
						local width = scale * 0.7
						local height = scale * 1.5
						return screen.X - width * 0.5, screen.Y - height * 0.55, width, height
					end
				end
				return nil, nil, nil, nil
			end

			local midZ_test = camera:WorldToViewportPoint(Vector3.new((min3D_X + max3D_X) * 0.5, (min3D_Y + max3D_Y) * 0.5, (min3D_Z + max3D_Z) * 0.5))
			if midZ_test.Z <= 0 then
				return nil, nil, nil, nil
			end

			local minX, minY = math.huge, math.huge
			local maxX, maxY = -math.huge, -math.huge
			local any = false
			local function mark(x: number, y: number, z: number)
				local screen, onScreen = camera:WorldToViewportPoint(Vector3.new(x, y, z))
				if screen.Z > 0 and onScreen then
					any = true
					if screen.X < minX then minX = screen.X end
					if screen.Y < minY then minY = screen.Y end
					if screen.X > maxX then maxX = screen.X end
					if screen.Y > maxY then maxY = screen.Y end
				end
			end

			mark(min3D_X, min3D_Y, min3D_Z)
			mark(min3D_X, min3D_Y, max3D_Z)
			mark(min3D_X, max3D_Y, min3D_Z)
			mark(min3D_X, max3D_Y, max3D_Z)
			mark(max3D_X, min3D_Y, min3D_Z)
			mark(max3D_X, min3D_Y, max3D_Z)
			mark(max3D_X, max3D_Y, min3D_Z)
			mark(max3D_X, max3D_Y, max3D_Z)

			if not any then
				if root and root:IsA("BasePart") then
					local screen, _on = camera:WorldToViewportPoint(root.Position)
					if screen.Z > 0 then
						local scale = math.clamp(220 / math.max(screen.Z, 1), 8, 90)
						local width = scale * 0.7
						local height = scale * 1.5
						return screen.X - width * 0.5, screen.Y - height * 0.55, width, height
					end
				end
				return nil, nil, nil, nil
			end

			local width = math.max(maxX - minX, 4)
			local height = math.max(maxY - minY, 4)
			local pad = height * 0.1
			return minX, minY - pad * 0.25, width, height + pad * 0.65
		end

		local function entryFor(player: Player): any?
			local entry = entries[player]
			if entry then
				return entry
			end
			local outline = newsquare(2)
			local box = newsquare(3)
			local inline = newsquare(4)
			local fill = newsquare(1)
			local healthbg = newsquare(2)
			local health = newsquare(3)
			local name = newtext()
			local distance = newtext()
			local weapon = newtext()
			local flag = newtext()
			local arrow = newline()
			local arrowL = newline()
			local arrowR = newline()
			if not (outline and box and inline and fill and healthbg and health and name and distance and weapon and flag and arrow and arrowL and arrowR) then
				return nil
			end
			fill.Filled = true
			healthbg.Filled = true
			health.Filled = true
			healthbg.ZIndex = 2
			health.ZIndex = 4
			if flag then
				flag.Center = false
			end
			local bones = {}
			for _ = 1, 14 do
				local line = newline()
				local outlineLine = newline()
				if line and outlineLine then
					table.insert(bones, { line = line, outline = outlineLine })
				end
			end
			local healthSegs = {}
			local healthUi = nil
			do
				local gui = ensureEspTextGui()
				if gui then
					local bg = Instance.new("Frame")
					bg.Name = "hp"
					bg.BorderSizePixel = 0
					bg.BackgroundColor3 = Color3.new(0, 0, 0)
					bg.Visible = false
					bg.ZIndex = 8
					bg.Parent = gui
					local fillFr = Instance.new("Frame")
					fillFr.Name = "fill"
					fillFr.BorderSizePixel = 0
					fillFr.BackgroundColor3 = Color3.new(1, 1, 1)
					fillFr.Position = UDim2.fromOffset(1, 1)
					fillFr.ZIndex = 9
					fillFr.Parent = bg
					local grad = Instance.new("UIGradient")
					grad.Rotation = 90
					grad.Offset = Vector2.zero
					grad.Parent = fillFr
					healthUi = { bg = bg, fill = fillFr, grad = grad }
				end
			end
			entry = {
				on = false,
				outline = outline,
				box = box,
				inline = inline,
				fill = fill,
				healthbg = healthbg,
				health = health,
				healthSegs = healthSegs,
				healthUi = healthUi,
				name = name,
				distance = distance,
				weapon = weapon,
				flag = flag,
				arrow = arrow,
				arrowL = arrowL,
				arrowR = arrowR,
				bones = bones,
			}
			entries[player] = entry
			return entry
		end

		local function _snapPixel(v: Vector2): Vector2
			return Vector2.new(math.floor(v.X + 0.5), math.floor(v.Y + 0.5))
		end

		local lastBonePaint: Color3? = nil
		local lastBoneOutlineColor: Color3? = nil
		local function getBoneOutlineColor(paint: Color3): Color3
			if lastBonePaint == paint and lastBoneOutlineColor then
				return lastBoneOutlineColor
			end
			lastBonePaint = paint
			lastBoneOutlineColor = Color3.new(
				math.clamp(paint.R * 0.22 + 0.04, 0, 1),
				math.clamp(paint.G * 0.22 + 0.04, 0, 1),
				math.clamp(paint.B * 0.22 + 0.04, 0, 1)
			)
			return lastBoneOutlineColor :: Color3
		end

		local function drawBone(bone: any, a: Vector2, b: Vector2, paint: Color3, showOutline: boolean)
			local ax = math.floor(a.X + 0.5)
			local ay = math.floor(a.Y + 0.5)
			local bx = math.floor(b.X + 0.5)
			local by = math.floor(b.Y + 0.5)
			if bone._ax ~= ax or bone._ay ~= ay or bone._bx ~= bx or bone._by ~= by then
				bone._ax = ax
				bone._ay = ay
				bone._bx = bx
				bone._by = by
				local a2 = Vector2.new(ax, ay)
				local b2 = Vector2.new(bx, by)
				bone.line.From = a2
				bone.line.To = b2
				if bone.outline then
					bone.outline.From = a2
					bone.outline.To = b2
				end
			end
			if showOutline then
				local outlineColor = getBoneOutlineColor(paint)
				if bone.outline and bone.outline.Color ~= outlineColor then
					bone.outline.Color = outlineColor
				end
				if bone.outline and not bone.outline.Visible then
					bone.outline.Visible = true
				end
			elseif bone.outline and bone.outline.Visible then
				bone.outline.Visible = false
			end
			if bone.line.Color ~= paint then
				bone.line.Color = paint
			end
			if not bone.line.Visible then
				bone.line.Visible = true
			end
		end

		local SKELETON_R15 = {
			{ "Head", "UpperTorso" },
			{ "UpperTorso", "LowerTorso" },
			{ "UpperTorso", "LeftUpperArm" },
			{ "UpperTorso", "RightUpperArm" },
			{ "LeftUpperArm", "LeftLowerArm" },
			{ "RightUpperArm", "RightLowerArm" },
			{ "LeftLowerArm", "LeftHand" },
			{ "RightLowerArm", "RightHand" },
			{ "LowerTorso", "LeftUpperLeg" },
			{ "LowerTorso", "RightUpperLeg" },
			{ "LeftUpperLeg", "LeftLowerLeg" },
			{ "RightUpperLeg", "RightLowerLeg" },
			{ "LeftLowerLeg", "LeftFoot" },
			{ "RightLowerLeg", "RightFoot" },
		}
		local SKELETON_R6 = {
			{ "Head", "Torso" },
			{ "Torso", "Left Arm" },
			{ "Torso", "Right Arm" },
			{ "Torso", "Left Leg" },
			{ "Torso", "Right Leg" },
		}

		local function paintArrow(entry: any, camera: Camera, worldPos: Vector3)
			if not (Esp.arrows and entry and entry.arrow and entry.arrowL and entry.arrowR) then
				if entry then
					if entry.arrow then entry.arrow.Visible = false end
					if entry.arrowL then entry.arrowL.Visible = false end
					if entry.arrowR then entry.arrowR.Visible = false end
				end
				return
			end
			local vp = camera.ViewportSize
			local cx = vp.X * 0.5
			local cy = vp.Y * 0.5
			local screen = camera:WorldToViewportPoint(worldPos)
			local dx = screen.X - cx
			local dy = screen.Y - cy
			if screen.Z <= 0 then
				dx = -dx
				dy = -dy
			end
			local mag = math.sqrt(dx * dx + dy * dy)
			if mag < 1 then
				dx, dy, mag = 0, -1, 1
			end
			dx /= mag
			dy /= mag
			local r = math.clamp(Esp.arrowsRadius, 20, 400)
			local tipX = math.floor(cx + dx * r + 0.5)
			local tipY = math.floor(cy + dy * r + 0.5)
			local backX = tipX - dx * 14
			local backY = tipY - dy * 14
			local px, py = -dy, dx
			local leftX = math.floor(backX + px * 7 + 0.5)
			local leftY = math.floor(backY + py * 7 + 0.5)
			local rightX = math.floor(backX - px * 7 + 0.5)
			local rightY = math.floor(backY - py * 7 + 0.5)
			local pulse = 0.2 + 0.8 * (0.5 + 0.5 * math.sin(os.clock() * 5))
			local paint = Esp.arrowsColor

			if entry._arrowTipX ~= tipX or entry._arrowTipY ~= tipY or entry._arrowLeftX ~= leftX or entry._arrowLeftY ~= leftY or entry._arrowRightX ~= rightX or entry._arrowRightY ~= rightY then
				entry._arrowTipX = tipX
				entry._arrowTipY = tipY
				entry._arrowLeftX = leftX
				entry._arrowLeftY = leftY
				entry._arrowRightX = rightX
				entry._arrowRightY = rightY
				local tip = Vector2.new(tipX, tipY)
				local left = Vector2.new(leftX, leftY)
				local right = Vector2.new(rightX, rightY)
				entry.arrow.From = left
				entry.arrow.To = tip
				entry.arrowL.From = right
				entry.arrowL.To = tip
				entry.arrowR.From = left
				entry.arrowR.To = right
			end
			if entry.arrow.Color ~= paint then
				entry.arrow.Color = paint
				entry.arrowL.Color = paint
				entry.arrowR.Color = paint
			end
			if not entry.arrow.Visible then
				entry.arrow.Visible = true
				entry.arrowL.Visible = true
				entry.arrowR.Visible = true
			end
			setDrawAlpha(entry.arrow, pulse)
			setDrawAlpha(entry.arrowL, pulse)
			setDrawAlpha(entry.arrowR, pulse)
		end

		local function projectPart(camera: Camera, part: BasePart?): Vector2?
			if not part then
				return nil
			end
			local screen = camera:WorldToViewportPoint(part.Position)
			if screen.Z <= 0 then
				return nil
			end
			return Vector2.new(screen.X, screen.Y)
		end

		local skeletonProjCache: { [string]: any } = {}
		local function paintSkeleton(entry: any, character: Model, camera: Camera)
			if not entry.bones then
				return
			end
			local index = 1
			local links = if character:FindFirstChild("UpperTorso") then SKELETON_R15 else SKELETON_R6
			table.clear(skeletonProjCache)
			local function getJointProj(name: string): Vector2?
				local cached = skeletonProjCache[name]
				if cached ~= nil then
					return if cached == false then nil else cached
				end
				local part = character:FindFirstChild(name) :: BasePart?
				if part and part:IsA("BasePart") then
					local res = projectPart(camera, part)
					skeletonProjCache[name] = res or false
					return res
				end
				skeletonProjCache[name] = false
				return nil
			end

			for _, link in links do
				if index > #entry.bones then
					break
				end
				local a = getJointProj(link[1])
				local b = getJointProj(link[2])
				if a and b then
					drawBone(entry.bones[index], a, b, Esp.skeletonColor, Esp.skeletonOutline)
					index += 1
				end
			end
			for i = index, #entry.bones do
				if entry.bones[i].line.Visible then entry.bones[i].line.Visible = false end
				if entry.bones[i].outline.Visible then entry.bones[i].outline.Visible = false end
			end
		end

		type ChamsEntry = {
			character: Model,
			scannedAt: number,
			occluded: boolean?,
			boxes: { [BasePart]: BoxHandleAdornment },
			weights: { [BasePart]: number },
			probe: BasePart?,
			paintDirty: boolean,
		}
		type OnshotSnap = {
			cframes: { CFrame },
			sizes: { Vector3 },
			weights: { number },
			probe: Vector3,
		}
		type OnshotEntry = {
			boxes: { BoxHandleAdornment },
			weights: { number },
			probe: Vector3,
			born: number,
			occluded: boolean?,
			shown: boolean?,
			rayAt: number,
			paintDirty: boolean,
		}
		type HpTrack = {
			character: Model,
			humanoid: Humanoid,
			hp: number,
			shotAt: number,
		}
		local chamsOf: { [Player]: ChamsEntry } = {}
		local onshots: { OnshotEntry } = {}
		local hpTrack: { [Player]: HpTrack } = {}
		local pendingDrops: { [Player]: { snap: OnshotSnap, at: number } } = {}
		local lastDealtAt = -math.huge
		local lastSpawnAt = -math.huge
		local localShotAt = -math.huge
		local dealtFallback: { snap: OnshotSnap, at: number }? = nil
		local chamsFolder: Folder? = nil
		local chamsRay = RaycastParams.new()
		chamsRay.FilterType = Enum.RaycastFilterType.Exclude
		chamsRay.IgnoreWater = true
		local chamsFilter: { Instance } = {}
		local chamsFilterAt = -1
		local CHAMS_RESCAN = 2.5
		local CHAMS_FILTER_TTL = 0.75
		local CHAMS_TICK = 1 / 30
		local ONSHOT_MAX = 24
		local ONSHOT_WINDOW = 0.4
		local ONSHOT_RAY_TICK = 1 / 20
		local CHAMS_STYLE_KEYS = {
			"chamsVisible",
			"chamsVisible2",
			"chamsOccluded",
			"chamsOccluded2",
			"chamsTransparency",
			"chamsShowVisible",
			"chamsShowOccluded",
		}
		local ONSHOT_STYLE_KEYS = {
			"onshotVisible",
			"onshotVisible2",
			"onshotOccluded",
			"onshotOccluded2",
		}
		local chamsLastTick = 0
		local chamsLast: { [string]: any } = {}
		local onshotLast: { [string]: any } = {}

		local function styleChanged(keys: { string }, last: { [string]: any }): boolean
			local changed = false
			local source: any = Esp
			for _, key in keys do
				local value = source[key]
				if last[key] ~= value then
					last[key] = value
					changed = true
				end
			end
			return changed
		end

		local function chamsContainer(): Folder?
			if chamsFolder and chamsFolder.Parent then
				return chamsFolder
			end
			local folder = Instance.new("Folder")
			pcall(function()
				folder.Parent = fsGethui() or game:GetService("CoreGui")
			end)
			if not folder.Parent then
				folder:Destroy()
				return nil
			end
			chamsFolder = folder
			return folder
		end

		local function isChamsPart(part: Instance): boolean
			if not part:IsA("BasePart") or part.Name == "HumanoidRootPart" then
				return false
			end
			local name = part.Name
			if string.find(name, "Hitbox", 1, true) or string.find(name, "Physical", 1, true) then
				return false
			end
			return (part :: BasePart).Transparency < 0.95
		end

		local function gradientWeights(character: Model, parts: { BasePart }): { [BasePart]: number }
			local root = character:FindFirstChild("HumanoidRootPart")
			local origin = Vector3.zero
			local up = Vector3.yAxis
			if root and root:IsA("BasePart") then
				origin = root.Position
				up = root.CFrame.UpVector
			end
			local heights: { [BasePart]: number } = {}
			local top, bottom = -math.huge, math.huge
			for _, part in parts do
				local h = (part.Position - origin):Dot(up)
				heights[part] = h
				local half = part.Size.Y * 0.5
				if h + half > top then
					top = h + half
				end
				if h - half < bottom then
					bottom = h - half
				end
			end
			local span = math.max(top - bottom, 0.01)
			local out: { [BasePart]: number } = {}
			for part, h in heights do
				out[part] = math.clamp((top - h) / span, 0, 1)
			end
			return out
		end

		local function destroyChams(player: Player)
			local entry = chamsOf[player]
			if not entry then
				return
			end
			chamsOf[player] = nil
			for _, box in entry.boxes do
				pcall(box.Destroy, box)
			end
		end

		local function clearChams()
			for player in chamsOf do
				destroyChams(player)
			end
		end

		local function pickProbe(character: Model): BasePart?
			local torso = character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso")
			if torso and torso:IsA("BasePart") then
				return torso
			end
			local head = character:FindFirstChild("Head")
			if head and head:IsA("BasePart") then
				return head
			end
			local root = character:FindFirstChild("HumanoidRootPart")
			if root and root:IsA("BasePart") then
				return root
			end
			return nil
		end

		local function scanChams(entry: ChamsEntry, folder: Folder, now: number)
			entry.scannedAt = now
			entry.probe = pickProbe(entry.character)
			local changed = false
			for part, box in entry.boxes do
				if part.Parent ~= entry.character then
					pcall(box.Destroy, box)
					entry.boxes[part] = nil
					entry.weights[part] = nil
					changed = true
				end
			end
			local parts: { BasePart } = {}
			for _, child in entry.character:GetChildren() do
				if isChamsPart(child) then
					local part = child :: BasePart
					parts[#parts + 1] = part
					local box = entry.boxes[part]
					if not box then
						box = Instance.new("BoxHandleAdornment")
						box.AlwaysOnTop = true
						box.ZIndex = 5
						box.Visible = false
						box.Adornee = part
						box.Parent = folder
						entry.boxes[part] = box
						changed = true
					end
					box.Size = part.Size
				end
			end
			if changed then
				entry.weights = gradientWeights(entry.character, parts)
				entry.paintDirty = true
			end
		end

		local function paintChams(entry: ChamsEntry, isOcc: boolean)
			local show = (if isOcc then Esp.chamsShowOccluded else Esp.chamsShowVisible) == true
			local top = if isOcc then Esp.chamsOccluded else Esp.chamsVisible
			local bottom = if isOcc then Esp.chamsOccluded2 else Esp.chamsVisible2
			local alpha = math.clamp(Esp.chamsTransparency, 0, 0.95)
			for part, box in entry.boxes do
				if show then
					box.Color3 = top:Lerp(bottom, entry.weights[part] or 0.5)
					box.Transparency = alpha
				end
				box.Visible = show
			end
			entry.paintDirty = false
		end

		local function refreshChamsFilter(camera: Camera, now: number)
			if now - chamsFilterAt < CHAMS_FILTER_TTL and #chamsFilter > 0 then
				return
			end
			chamsFilterAt = now
			table.clear(chamsFilter)
			chamsFilter[1] = camera
			local viewModels = Workspace:FindFirstChild("ViewModels")
			if viewModels then
				chamsFilter[#chamsFilter + 1] = viewModels
			end
			local lp = Players.LocalPlayer
			if lp and lp.Character then
				chamsFilter[#chamsFilter + 1] = lp.Character
			end
			for _, player in roster do
				local character = player.Character
				if character then
					chamsFilter[#chamsFilter + 1] = character
				end
			end
			chamsRay.FilterDescendantsInstances = chamsFilter
		end

		local function destroyOnshot(index: number)
			local shot = table.remove(onshots, index)
			if shot then
				for _, box in shot.boxes do
					pcall(box.Destroy, box)
				end
			end
		end

		local function clearOnshots()
			for index = #onshots, 1, -1 do
				destroyOnshot(index)
			end
		end

		local function onshotLive(): boolean
			return Esp.master == true and Esp.onshot == true
		end

		local function snapshotCharacter(character: Model): OnshotSnap?
			local parts: { BasePart } = {}
			for _, child in character:GetChildren() do
				if isChamsPart(child) then
					parts[#parts + 1] = child :: BasePart
				end
			end
			if #parts == 0 then
				return nil
			end
			local weightOf = gradientWeights(character, parts)
			local snap: OnshotSnap = {
				cframes = table.create(#parts),
				sizes = table.create(#parts),
				weights = table.create(#parts),
				probe = parts[1].Position,
			}
			for index, part in parts do
				snap.cframes[index] = part.CFrame
				snap.sizes[index] = part.Size
				snap.weights[index] = weightOf[part] or 0.5
			end
			local probe = pickProbe(character)
			if probe then
				snap.probe = probe.Position
			end
			return snap
		end

		local onshotAnchorPart: BasePart? = nil
		local function onshotAnchor(): BasePart?
			local cam = Workspace.CurrentCamera
			if not cam then
				return nil
			end
			local part = onshotAnchorPart
			if part and part.Parent == cam then
				return part
			end
			if part then
				pcall(part.Destroy, part)
			end
			local created = Instance.new("Part")
			created.Anchored = true
			created.CanCollide = false
			created.CanQuery = false
			created.CanTouch = false
			created.CastShadow = false
			created.Transparency = 1
			created.Size = Vector3.new(0.05, 0.05, 0.05)
			created.CFrame = CFrame.identity
			created.Parent = cam
			onshotAnchorPart = created
			return created
		end

		local function spawnOnshot(snap: OnshotSnap, now: number)
			local folder = chamsContainer()
			if not folder then
				return
			end
			while #onshots >= ONSHOT_MAX do
				destroyOnshot(1)
			end
			local anchor = onshotAnchor()
			if not anchor then
				return
			end
			local anchorCf = anchor.CFrame
			local alpha = math.clamp(Esp.onshotTransparency, 0, 0.95)
			local boxes: { BoxHandleAdornment } = table.create(#snap.cframes)
			for index, cf in snap.cframes do
				local box = Instance.new("BoxHandleAdornment")
				box.AlwaysOnTop = true
				box.ZIndex = 6
				box.Size = snap.sizes[index]
				box.CFrame = anchorCf:ToObjectSpace(cf)
				box.Transparency = alpha
				box.Visible = false
				box.Adornee = anchor
				box.Parent = folder
				boxes[index] = box
			end
			table.insert(onshots, {
				boxes = boxes,
				weights = snap.weights,
				probe = snap.probe,
				born = now,
				occluded = nil,
				shown = nil,
				rayAt = -1,
				paintDirty = true,
			})
		end

		local function rageTargetPlayer(): Player?
			local rage = DrawingBridge.Rage
			local live = DrawingBridge.RageLive
			if type(rage) ~= "table" or rage.enabled ~= true or type(live) ~= "table" then
				return nil
			end
			local target = live.targetPlayer
			if typeof(target) == "Instance" and target:IsA("Player") then
				return target
			end
			return nil
		end

		local function crosshairVictim(duel: any, team: any): Model?
			local cam = Workspace.CurrentCamera
			if not cam then
				return nil
			end
			local ragePlayer = rageTargetPlayer()
			if ragePlayer then
				local character = livingEnemy(ragePlayer, duel, team)
				if character then
					return character
				end
			end
			local mouse = UserInputService:GetMouseLocation()
			local best: Model? = nil
			local bestDist = 220
			for _, player in roster do
				local character = livingEnemy(player, duel, team)
				local probe = character and pickProbe(character)
				if probe then
					local sp, onScreen = cam:WorldToViewportPoint(probe.Position)
					if onScreen and sp.Z > 0 then
						local dist = (Vector2.new(sp.X, sp.Y) - mouse).Magnitude
						if dist < bestDist then
							bestDist = dist
							best = character
						end
					end
				end
			end
			return best
		end

		local function onDamageDealt()
			if not onshotLive() then
				return
			end
			local now = os.clock()
			if now - lastDealtAt < 0.02 then
				return
			end
			lastDealtAt = now
			local matched = false
			for player, drop in pendingDrops do
				if now - drop.at <= ONSHOT_WINDOW then
					spawnOnshot(drop.snap, now)
					lastSpawnAt = now
					matched = true
				end
				pendingDrops[player] = nil
			end
			if matched or now - lastSpawnAt <= ONSHOT_WINDOW then
				dealtFallback = nil
				return
			end
			local duel, team = matchEnemies()
			local victim = duel and crosshairVictim(duel, team)
			local snap = victim and snapshotCharacter(victim)
			dealtFallback = if snap then { snap = snap, at = now } else nil
		end

		do
			local dispatch = function()
				pcall(onDamageDealt)
			end
			DrawingBridge.onshotDealt = dispatch
			local genv = fsGetgenv()
			if type(genv) == "table" then
				genv.__sonataOnshotDealt = dispatch
			end
			table.insert(ears, {
				Disconnect = function()
					local env = fsGetgenv()
					if type(env) == "table" and env.__sonataOnshotDealt == dispatch then
						env.__sonataOnshotDealt = nil
					end
					if DrawingBridge.onshotDealt == dispatch then
						DrawingBridge.onshotDealt = nil
					end
				end,
			} :: any)
		end

		local chamsActive = false
		local chamsSeen: { [Player]: boolean } = {}
		table.insert(ears, RunService.Heartbeat:Connect(function()
			local now = os.clock()
			if now - chamsLastTick < CHAMS_TICK then
				return
			end
			chamsLastTick = now

			if not (Esp.master and Esp.chams) then
				if chamsActive then
					clearChams()
					chamsActive = false
					chamsFilterAt = -1
				end
				return
			end

			local camera = Workspace.CurrentCamera
			if not camera then
				return
			end
			local duel, team = matchEnemies()
			if not duel then
				if chamsActive then
					clearChams()
					chamsActive = false
					chamsFilterAt = -1
				end
				return
			end
			local folder = chamsContainer()
			if not folder then
				return
			end
			chamsActive = true

			local styleDirty = styleChanged(CHAMS_STYLE_KEYS, chamsLast)
			refreshChamsFilter(camera, now)
			local camPos = camera.CFrame.Position
			table.clear(chamsSeen)

			for _, player in roster do
				local character = livingEnemy(player, duel, team)
				if character then
					chamsSeen[player] = true
					local entry = chamsOf[player]
					if entry and entry.character ~= character then
						destroyChams(player)
						entry = nil
					end
					if not entry then
						entry = {
							character = character,
							scannedAt = 0,
							occluded = nil,
							boxes = {},
							weights = {},
							probe = nil,
							paintDirty = true,
						}
						chamsOf[player] = entry
					end
					local chamsEntry = entry :: ChamsEntry
					if now - chamsEntry.scannedAt >= CHAMS_RESCAN then
						scanChams(chamsEntry, folder, now)
					end
					local probe = chamsEntry.probe
					if not probe or probe.Parent ~= character then
						probe = pickProbe(character)
						chamsEntry.probe = probe
					end
					local isOcc = chamsEntry.occluded == true
					if probe then
						local delta = probe.Position - camPos
						if delta.Magnitude > 0.05 then
							isOcc = Workspace:Raycast(camPos, delta, chamsRay) ~= nil
						else
							isOcc = false
						end
					end
					local stateDirty = chamsEntry.occluded ~= isOcc
					chamsEntry.occluded = isOcc
					if stateDirty or styleDirty or chamsEntry.paintDirty then
						paintChams(chamsEntry, isOcc)
					end
				end
			end
			for player in chamsOf do
				if not chamsSeen[player] then
					destroyChams(player)
				end
			end
		end))

		table.insert(ears, UserInputService.InputBegan:Connect(function(input: InputObject)
			if input.UserInputType == Enum.UserInputType.MouseButton1 then
				localShotAt = os.clock()
			end
		end))
		table.insert(ears, UserInputService.InputEnded:Connect(function(input: InputObject)
			if input.UserInputType == Enum.UserInputType.MouseButton1 then
				localShotAt = os.clock()
			end
		end))

		table.insert(ears, RunService.Heartbeat:Connect(function()
			if not onshotLive() then
				if next(hpTrack) ~= nil or next(pendingDrops) ~= nil then
					table.clear(hpTrack)
					table.clear(pendingDrops)
				end
				dealtFallback = nil
				return
			end
			local duel, team = matchEnemies()
			if not duel then
				if next(hpTrack) ~= nil or next(pendingDrops) ~= nil then
					table.clear(hpTrack)
					table.clear(pendingDrops)
				end
				return
			end
			local now = os.clock()
			local firing = now - localShotAt <= ONSHOT_WINDOW
				or UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
			local ragePlayer = rageTargetPlayer()
			for player, track in hpTrack do
				local hp = track.humanoid.Health
				if hp < track.hp - 0.05 and now - track.shotAt > 0.05 and track.character.Parent then
					track.shotAt = now
					local snap = snapshotCharacter(track.character)
					if snap then
						if now - lastDealtAt <= ONSHOT_WINDOW or firing or ragePlayer == player then
							pendingDrops[player] = nil
							dealtFallback = nil
							lastSpawnAt = now
							spawnOnshot(snap, now)
						else
							pendingDrops[player] = { snap = snap, at = now }
						end
					end
				end
				track.hp = hp
			end
			local fallback = dealtFallback
			if fallback and now - fallback.at > ONSHOT_WINDOW then
				dealtFallback = nil
				if lastSpawnAt < fallback.at then
					lastSpawnAt = now
					spawnOnshot(fallback.snap, now)
				end
			end
			for _, player in roster do
				local character, humanoid = livingEnemy(player, duel, team)
				local track = hpTrack[player]
				if character and humanoid then
					if not track or track.humanoid ~= humanoid then
						hpTrack[player] = {
							character = character,
							humanoid = humanoid,
							hp = humanoid.Health,
							shotAt = 0,
						}
					end
				elseif track then
					hpTrack[player] = nil
				end
			end
			for player in hpTrack do
				if player.Parent == nil then
					hpTrack[player] = nil
				end
			end
			for player, drop in pendingDrops do
				if now - drop.at > ONSHOT_WINDOW then
					pendingDrops[player] = nil
				end
			end
		end))

		table.insert(ears, RunService.RenderStepped:Connect(function()
			local count = #onshots
			if count == 0 then
				return
			end
			if not onshotLive() then
				clearOnshots()
				return
			end
			if DrawingBridge.library and DrawingBridge.library.uiDragging then
				return
			end
			local camera = Workspace.CurrentCamera
			if not camera then
				return
			end
			local now = os.clock()
			local duration = math.max(Esp.onshotDuration, 0.1)
			local alpha = math.clamp(Esp.onshotTransparency, 0, 0.95)
			local camPos = camera.CFrame.Position
			local styleDirty = styleChanged(ONSHOT_STYLE_KEYS, onshotLast)
			refreshChamsFilter(camera, now)
			for index = count, 1, -1 do
				local shot = onshots[index]
				local progress = (now - shot.born) / duration
				if progress >= 1 then
					destroyOnshot(index)
				else
					if now - shot.rayAt >= ONSHOT_RAY_TICK then
						shot.rayAt = now
						local delta = shot.probe - camPos
						local isOcc = delta.Magnitude > 0.05 and Workspace:Raycast(camPos, delta, chamsRay) ~= nil
						if isOcc ~= shot.occluded then
							shot.occluded = isOcc
							shot.paintDirty = true
						end
					end
					local isOcc = shot.occluded == true
					local show = (if isOcc then Esp.onshotShowOccluded else Esp.onshotShowVisible) == true
					if shot.paintDirty or styleDirty then
						local top = if isOcc then Esp.onshotOccluded else Esp.onshotVisible
						local bottom = if isOcc then Esp.onshotOccluded2 else Esp.onshotVisible2
						for boxIndex, box in shot.boxes do
							box.Color3 = top:Lerp(bottom, shot.weights[boxIndex] or 0.5)
						end
						shot.paintDirty = false
					end
					local fade = alpha + (1 - alpha) * progress * progress
					local toggleShown = shot.shown ~= show
					shot.shown = show
					for _, box in shot.boxes do
						if show then
							box.Transparency = fade
						end
						if toggleShown then
							box.Visible = show
						end
					end
				end
			end
		end))

		table.insert(ears, {
			Disconnect = function()
				clearChams()
				clearOnshots()
				table.clear(hpTrack)
				table.clear(pendingDrops)
				dealtFallback = nil
				if onshotAnchorPart then
					pcall(onshotAnchorPart.Destroy, onshotAnchorPart)
					onshotAnchorPart = nil
				end
				if chamsFolder then
					pcall(chamsFolder.Destroy, chamsFolder)
					chamsFolder = nil
				end
			end,
		} :: any)

		local lastEspSweep = 0
		local espHiddenIdle = false
		local espActive: { [Player]: boolean } = {}
		table.insert(ears, RunService.RenderStepped:Connect(function()
			if not DrawingLib then
				return
			end
			if DrawingBridge.library and DrawingBridge.library.uiDragging then
				return
			end
			local master = Esp.master
			local showbox = master and Esp.box
			local showfill = showbox and Esp.boxFill
			local showOutline = showbox and Esp.boxOutline
			local showSkeleton = master and Esp.skeleton
			local shownames = master and Esp.names
			local showhealth = master and Esp.health
			local showdistance = master and Esp.distance
			local showweapon = master and Esp.weapon
			local showflags = master and Esp.flags
			local showArrows = master and Esp.arrows
			local visuals = showbox or shownames or showhealth or showdistance or showweapon or showflags or showSkeleton or showArrows
			if not visuals then
				if not espHiddenIdle then
					for _, entry in entries do
						hideEntry(entry)
					end
					espHiddenIdle = true
				end
				return
			end
			espHiddenIdle = false
			local now = os.clock()
			if now - lastEspSweep > 0.5 then
				lastEspSweep = now
				local stale: { Player } = {}
				for player in entries do
					if not isLivePlayer(player) or player == Players.LocalPlayer then
						table.insert(stale, player)
					end
				end
				for _, player in stale do
					destroyEntry(player)
				end
			end
			local camera = Workspace.CurrentCamera
			local duel, team = matchEnemies()
			if not camera then
				for _, entry in entries do
					hideEntry(entry)
				end
				return
			end

			local barThick = math.clamp(Esp.healthThick, 1, 8)
			local nameY = Esp.namesY or 0
			local healthX = Esp.healthX or 0
			local healthY = Esp.healthY or 0
			local distanceY = Esp.distanceY or 0
			local weaponY = Esp.weaponY or 0
			local flagsY = Esp.flagsY or 0
			local fontKey = tostring(Esp.font or "System")
			table.clear(espActive)

			for _, player in roster do
				if not isLivePlayer(player) then
					destroyEntry(player)
				else
				local character, humanoid = livingEnemy(player, duel, team)
				if not character or not humanoid then
					hideEntry(entries[player])
				else
				local head = character:FindFirstChild("Head") or character:FindFirstChild("HitboxHead")
				local x, y, w, h = bounds(character, camera, head)
				if not x or not y or not w or not h then
					if showArrows then
						local entry = entryFor(player)
						if entry then
							espActive[player] = true
							local root = character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("Head")
							if root and root:IsA("BasePart") then
								paintArrow(entry, camera, root.Position)
							end
							entry.outline.Visible = false
							entry.box.Visible = false
							entry.inline.Visible = false
							entry.fill.Visible = false
							entry.healthbg.Visible = false
							entry.health.Visible = false
							entry.name.Visible = false
							entry.distance.Visible = false
							entry.weapon.Visible = false
							entry.flag.Visible = false
							hideHealthSegs(entry)
							hideBones(entry)
						end
					else
						hideEntry(entries[player])
					end
				else
				local entry = entryFor(player)
				if entry then
				espActive[player] = true
				entry.on = true
				place(entry.outline, x - 1, y - 1, w + 2, h + 2, Color3.new(0, 0, 0), 1, showOutline)
				place(entry.box, x, y, w, h, Esp.boxColor, 1, showbox)
				place(entry.inline, x + 1, y + 1, w - 2, h - 2, Color3.new(0, 0, 0), 1, showOutline)
				place(entry.fill, x + 2, y + 2, w - 4, h - 4, Esp.boxFillColor, 0.35, showfill)
				if showSkeleton then
					paintSkeleton(entry, character, camera)
				else
					hideBones(entry)
				end

				if showhealth then
					local ratio = math.clamp(humanoid.Health / math.max(humanoid.MaxHealth, 1), 0, 1)
					local innerH = math.max(math.floor(h), 1)
					local fillH = math.clamp(math.floor(innerH * ratio), 0, innerH)
					local barX = x - barThick - 4 + healthX
					local barY = y + healthY
					local barColor = gradientColor(ratio, Esp.healthLow, Esp.healthMid, Esp.healthHigh)
					hideHealthSegs(entry)
					if entry.healthUi then
						place(entry.healthbg, barX - 1, barY - 1, barThick + 2, innerH + 2, Color3.new(0, 0, 0), 1, false)
						place(entry.health, barX, barY + (innerH - fillH), barThick, fillH, barColor, 1, false)
						local ui = entry.healthUi
						ui.bg.Position = UDim2.fromOffset(barX - 1, barY - 1)
						ui.bg.Size = UDim2.fromOffset(barThick + 2, innerH + 2)
						ui.bg.BackgroundColor3 = Color3.new(0, 0, 0)
						ui.bg.BackgroundTransparency = 0
						ui.bg.Visible = true
						ui.fill.Visible = fillH >= 1
						ui.fill.BackgroundColor3 = Color3.new(1, 1, 1)
						ui.fill.Position = UDim2.fromOffset(1, 1 + (innerH - fillH))
						ui.fill.Size = UDim2.fromOffset(barThick, fillH)
						pcall(function()
							ui.grad.Enabled = true
							ui.grad.Rotation = 90
							ui.grad.Offset = Vector2.zero
							if Esp.healthGradient then
								local high, mid, low = Esp.healthHigh, Esp.healthMid, Esp.healthLow
								local function orbit(p: number): Color3
									local x = p % 1
									if x < 0.25 then
										return high:Lerp(mid, x / 0.25)
									elseif x < 0.5 then
										return mid:Lerp(low, (x - 0.25) / 0.25)
									elseif x < 0.75 then
										return low:Lerp(mid, (x - 0.5) / 0.25)
									end
									return mid:Lerp(high, (x - 0.75) / 0.25)
								end
								local t = if Esp.healthAnim then (os.clock() * math.clamp(Esp.healthAnimSpeed or 1.2, 0.1, 8)) else 0
								local c0 = orbit(t)
								ui.grad.Color = ColorSequence.new({
									ColorSequenceKeypoint.new(0, c0),
									ColorSequenceKeypoint.new(1 / 6, orbit(t + 1 / 6)),
									ColorSequenceKeypoint.new(2 / 6, orbit(t + 2 / 6)),
									ColorSequenceKeypoint.new(0.5, orbit(t + 0.5)),
									ColorSequenceKeypoint.new(4 / 6, orbit(t + 4 / 6)),
									ColorSequenceKeypoint.new(5 / 6, orbit(t + 5 / 6)),
									ColorSequenceKeypoint.new(1, c0),
								})
							else
								ui.grad.Color = ColorSequence.new(barColor)
							end
						end)
					else
						place(entry.healthbg, barX - 1, barY - 1, barThick + 2, innerH + 2, Color3.new(0, 0, 0), 1, true)
						place(entry.health, barX, barY + (innerH - fillH), barThick, fillH, barColor, 1, fillH >= 1)
					end
				else
					entry.healthbg.Visible = false
					entry.health.Visible = false
					hideHealthSegs(entry)
					if entry.healthUi then
						entry.healthUi.bg.Visible = false
					end
				end

				local weightKey = tostring(Esp.fontWeight or "Regular")
				if entry.fontKey ~= fontKey or entry.fontWeight ~= weightKey then
					entry.fontKey = fontKey
					entry.fontWeight = weightKey
					entry.name.Font = fontKey
					entry.distance.Font = fontKey
					entry.weapon.Font = fontKey
					entry.flag.Font = fontKey
				end

				local alias = Esp.nameText
				local nameText = if type(alias) == "string" and alias ~= "" then alias else player.Name
				entry.name.Visible = shownames
				if shownames then
					if entry.lastName ~= nameText then
						entry.lastName = nameText
						entry.name.Text = nameText
					end
					local nSize = math.clamp(Esp.namesSize or 13, 8, 32)
					if entry._nSize ~= nSize then
						entry._nSize = nSize
						entry.name.Size = nSize
					end
					if Esp.gradName then
						entry.name.Gradient = { Esp.gradNameColor, Esp.gradNameColor2 }
						entry.name.GradientOffset = scrollGrad()
					else
						entry.name.Gradient = nil
						local nCol = Esp.namesColor
						if entry._nCol ~= nCol then
							entry._nCol = nCol
							entry.name.Color = nCol
						end
					end
					local nx = math.floor(x + w * 0.5)
					local ny = math.floor(y - 8 - nameY)
					if entry._nx ~= nx or entry._ny ~= ny then
						entry._nx = nx
						entry._ny = ny
						entry.name.Position = Vector2.new(nx, ny)
					end
					setDrawAlpha(entry.name, 1)
				end

				entry.distance.Visible = showdistance
				if showdistance then
					local root = character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso")
					local studs = 0
					if root and root:IsA("BasePart") then
						studs = math.floor((camera.CFrame.Position - root.Position).Magnitude + 0.5)
					end
					if entry.lastStuds ~= studs then
						entry.lastStuds = studs
						entry.distance.Text = studs .. "st"
					end
					local dSize = math.clamp(Esp.namesSize or 13, 8, 32)
					if entry._dSize ~= dSize then
						entry._dSize = dSize
						entry.distance.Size = dSize
					end
					if Esp.gradDistance then
						entry.distance.Gradient = { Esp.gradDistanceColor, Esp.gradDistanceColor2 }
						entry.distance.GradientOffset = scrollGrad()
					else
						entry.distance.Gradient = nil
						local dCol = Esp.distanceColor
						if entry._dCol ~= dCol then
							entry._dCol = dCol
							entry.distance.Color = dCol
						end
					end
					local dx = math.floor(x + w * 0.5)
					local dy = math.floor(y + h + 2 + distanceY)
					if entry._dx ~= dx or entry._dy ~= dy then
						entry._dx = dx
						entry._dy = dy
						entry.distance.Position = Vector2.new(dx, dy)
					end
				end

				local weaponName: string? = nil
				if showweapon then
					local dueler = duelerOf[player]
					local fighter = dueler and dueler ~= false and dueler.ClientFighter
					if fighter then
						pcall(function()
							local item = fighter.Get and fighter:Get("EquippedItem") or fighter.EquippedItem
							if type(item) == "string" then
								weaponName = item
							elseif type(item) == "table" then
								weaponName = item.Name
							end
						end)
					end
					if not weaponName then
						local tool = character:FindFirstChildOfClass("Tool")
						weaponName = tool and tool.Name
					end
				end
				entry.weapon.Visible = showweapon and weaponName ~= nil
				if showweapon and weaponName then
					if entry.lastWeapon ~= weaponName then
						entry.lastWeapon = weaponName
						entry.weapon.Text = weaponName
					end
					local wSize = math.clamp(Esp.weaponSize or 13, 8, 32)
					if entry._wSize ~= wSize then
						entry._wSize = wSize
						entry.weapon.Size = wSize
					end
					if Esp.gradWeapon then
						entry.weapon.Gradient = { Esp.gradWeaponColor, Esp.gradWeaponColor2 }
						entry.weapon.GradientOffset = scrollGrad()
					else
						entry.weapon.Gradient = nil
						local wCol = Esp.weaponColor
						if entry._wCol ~= wCol then
							entry._wCol = wCol
							entry.weapon.Color = wCol
						end
					end
					local weaponBase = if showdistance then (y + h + 14) else (y + h + 2)
					local wx = math.floor(x + w * 0.5)
					local wy = math.floor(weaponBase + weaponY)
					if entry._wx ~= wx or entry._wy ~= wy then
						entry._wx = wx
						entry._wy = wy
						entry.weapon.Position = Vector2.new(wx, wy)
					end
				end

				local flagText = ""
				if showflags then
					if Esp.flagHealth then
						flagText = tostring(math.floor(humanoid.Health + 0.5))
					end
					if Esp.flagTeam then
						flagText = if flagText ~= "" then flagText .. "\nenemy" else "enemy"
					end
				end
				local hasFlag = flagText ~= ""
				entry.flag.Visible = hasFlag
				if hasFlag then
					if entry.lastFlag ~= flagText then
						entry.lastFlag = flagText
						entry.flag.Text = flagText
					end
					local fSize = math.clamp(Esp.namesSize or 13, 8, 32)
					if entry._fSize ~= fSize then
						entry._fSize = fSize
						entry.flag.Size = fSize
					end
					if Esp.gradFlags then
						entry.flag.Gradient = { Esp.gradFlagsColor, Esp.gradFlagsColor2 }
						entry.flag.GradientOffset = scrollGrad()
					else
						entry.flag.Gradient = nil
						local fCol = Color3.new(1, 1, 1)
						if entry._fCol ~= fCol then
							entry._fCol = fCol
							entry.flag.Color = fCol
						end
					end
					local fx = math.floor(x + w + 4)
					local fy = math.floor(y + flagsY)
					if entry._fx ~= fx or entry._fy ~= fy then
						entry._fx = fx
						entry._fy = fy
						entry.flag.Position = Vector2.new(fx, fy)
					end
				end
				local rootArrow = character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("Head")
				if showArrows and rootArrow and rootArrow:IsA("BasePart") then
					paintArrow(entry, camera, rootArrow.Position)
				elseif entry.arrow then
					entry.arrow.Visible = false
					if entry.arrowL then entry.arrowL.Visible = false end
					if entry.arrowR then entry.arrowR.Visible = false end
				end
				end
				end
				end
				end
			end

			for player, entry in entries do
				if not espActive[player] then
					hideEntry(entry)
				end
			end
		end))

		do
			local CollectionService = getService("CollectionService")
			local UTIL_TAGS: { [string]: string } = {
				SubspaceTripmine = "Subspace Tripmine",
				JumpPadHitbox = "Jump Pad",
				SmokeCloud = "Smoke Grenade",
				FireHitbox = "Molotov",
			}
			local UTIL_FADE_SPEED = 7
			local utilImages: { [string]: string } = {}
			pcall(function()
				local lib = require(ReplicatedStorage.Modules.ItemLibrary)
				for name, info in lib.Items do
					if type(info) == "table" and info.Class == "Utility" and type(info.Image) == "string" then
						utilImages[name] = info.Image
					end
				end
			end)

			local utilEntries: { [Instance]: any } = {}

			local function utilKind(name: string): string
				if string.find(name, "Warpstone", 1, true) then
					return "Warpstone"
				end
				return name
			end

			local function trackUtility(inst: Instance, name: string)
				if typeof(inst) ~= "Instance" or utilEntries[inst] then
					return
				end
				utilEntries[inst] = {
					inst = inst,
					kind = utilKind(name),
					alpha = 0,
					alive = true,
					pos = nil,
					cf = nil,
					size = nil,
				}
			end

			local genv = fsGetgenv()
			if type(genv) == "table" then
				genv.__sonataUtilTrack = trackUtility
			end
			DrawingBridge.trackUtility = trackUtility

			pcall(function()
				if type(genv) == "table" and genv.__sonataUtilThrowHook then
					return
				end
				local lp = Players.LocalPlayer
				local throwable = require(lp.PlayerScripts.Modules.ItemTypes.Throwable)
				if type(throwable) ~= "table" or type(throwable.ReplicateFromServer) ~= "function" then
					return
				end
				local old = hookGameMethod(throwable.ReplicateFromServer, function(oldFn, self: any, kind: any, ...: any): any
					if kind == "ThrowEffect" then
						local part = ...
						local okRender, rendered = pcall(function()
							return self:IsRendered()
						end)
						if typeof(part) == "Instance" and part:IsA("BasePart") and not (okRender and rendered == false) then
							local env = fsGetgenv()
							local track = if type(env) == "table" then env.__sonataUtilTrack else nil
							if type(track) == "function" then
								pcall(track, part, tostring(type(self) == "table" and self.Name or "Utility"))
							end
						end
					end
					return oldFn(self, kind, ...)
				end)
				if old and type(genv) == "table" then
					genv.__sonataUtilThrowHook = true
				end
			end)

			for tag, kind in UTIL_TAGS do
				pcall(function()
					for _, inst in CollectionService:GetTagged(tag) do
						trackUtility(inst, kind)
					end
					table.insert(ears, CollectionService:GetInstanceAddedSignal(tag):Connect(function(inst: Instance)
						trackUtility(inst, kind)
					end))
				end)
			end

			local function utilAdornee(inst: Instance): Instance?
				if inst:IsA("Model") then
					local hitbox = inst:FindFirstChild("Hitbox")
					if hitbox and hitbox:IsA("BasePart") then
						return hitbox
					end
					return inst
				end
				if inst:IsA("BasePart") then
					return inst
				end
				return nil
			end

			local UTIL_BOX_EDGES = {
				{ 1, 2 }, { 3, 4 }, { 5, 6 }, { 7, 8 },
				{ 1, 3 }, { 2, 4 }, { 5, 7 }, { 6, 8 },
				{ 1, 5 }, { 2, 6 }, { 3, 7 }, { 4, 8 },
			}

			local function utilBounds(inst: Instance): (CFrame?, Vector3?)
				local target = utilAdornee(inst)
				if not target then
					if inst:IsA("Attachment") then
						return CFrame.new(inst.WorldPosition), Vector3.new(1, 1, 1)
					end
					return nil, nil
				end
				if target:IsA("BasePart") then
					return target.CFrame, target.Size
				end
				local ok, cf, size = pcall(function()
					return (target :: Model):GetBoundingBox()
				end)
				if ok and typeof(cf) == "CFrame" then
					return cf, size
				end
				return nil, nil
			end

			local function buildUtilVisuals(entry: any)
				if entry.visuals then
					return entry.visuals
				end
				local gui = ensureEspTextGui()
				if not gui then
					return nil
				end
				local v: any = {}
				v.name = newtext()
				v.distance = newtext()
				local image = Instance.new("ImageLabel")
				image.Name = "util_image"
				image.BackgroundTransparency = 1
				image.BorderSizePixel = 0
				image.AnchorPoint = Vector2.new(0.5, 0.5)
				image.ScaleType = Enum.ScaleType.Fit
				image.Image = utilImages[entry.kind] or ""
				image.ImageTransparency = 1
				image.Visible = false
				image.ZIndex = 10
				image.Parent = gui
				v.image = image
				v.lines = {}
				for i = 1, #UTIL_BOX_EDGES do
					local line = newline()
					if line then
						line.Thickness = 1
					end
					v.lines[i] = line
				end
				v.circle = nil
				if DrawingLib then
					pcall(function()
						local c = DrawingLib.new("Circle")
						c.Filled = false
						c.NumSides = 32
						c.Thickness = 1
						c.Visible = false
						c.ZIndex = 2
						v.circle = c
					end)
				end
				v.fontKey = nil
				for _, text in { v.name, v.distance } do
					if text then
						text.Center = true
						text.Outline = true
						text.Visible = false
					end
				end
				entry.visuals = v
				return v
			end

			local function hideUtilBox(v: any)
				for _, line in v.lines do
					if line then
						line.Visible = false
					end
				end
				if v.circle then
					v.circle.Visible = false
				end
			end

			local function hideUtilVisuals(v: any)
				if not v then
					return
				end
				if v.name then
					v.name.Visible = false
				end
				if v.distance then
					v.distance.Visible = false
				end
				v.image.Visible = false
				hideUtilBox(v)
			end

			local utilCorners: { Vector2 } = table.create(8)
			local function paintUtilBox(v: any, camera: Camera, cf: CFrame, size: Vector3, alpha: number, color: Color3, kind: string?)
				if v.circle then
					v.circle.Visible = false
				end
				local hx, hy, hz
				local thick = 1
				if kind == "Molotov" then
					local span = math.max(size.X, size.Z)
					if span < 4 then
						hideUtilBox(v)
						return
					end
					hx, hy, hz = span * 0.5, 0.12, span * 0.5
					thick = 1.5
				else
					hx, hy, hz = size.X * 0.28, size.Y * 0.42, size.Z * 0.28
				end
				for i = 1, 8 do
					local ix = (i - 1) % 2
					local iy = math.floor((i - 1) / 2) % 2
					local iz = math.floor((i - 1) / 4)
					local world = cf * Vector3.new(if ix == 1 then hx else -hx, if iy == 1 then hy else -hy, if iz == 1 then hz else -hz)
					local sp = camera:WorldToViewportPoint(world)
					if sp.Z <= 0 then
						hideUtilBox(v)
						return
					end
					utilCorners[i] = Vector2.new(sp.X, sp.Y)
				end
				for i, edge in UTIL_BOX_EDGES do
					local line = v.lines[i]
					if line then
						line.From = utilCorners[edge[1]]
						line.To = utilCorners[edge[2]]
						line.Color = color
						line.Transparency = alpha
						line.Thickness = thick
						line.Visible = true
					end
				end
			end

			local function destroyUtilVisuals(entry: any)
				local v = entry.visuals
				if not v then
					return
				end
				entry.visuals = nil
				pcall(function()
					v.name:Remove()
				end)
				pcall(function()
					v.distance:Remove()
				end)
				pcall(function()
					v.image:Destroy()
				end)
				if v.circle then
					pcall(function()
						v.circle:Remove()
					end)
				end
				for _, line in v.lines do
					pcall(function()
						line:Remove()
					end)
				end
			end

			table.insert(ears, {
				Disconnect = function()
					for inst, entry in utilEntries do
						destroyUtilVisuals(entry)
						utilEntries[inst] = nil
					end
				end,
			} :: any)

			local utilEspHidden = false
			table.insert(ears, RunService.RenderStepped:Connect(function(dt: number)
				if DrawingBridge.library and DrawingBridge.library.uiDragging then
					return
				end
				local enabled = UtilEsp.enabled == true
				if not enabled then
					if not utilEspHidden then
						for _, entry in utilEntries do
							if entry.visuals then
								hideUtilVisuals(entry.visuals)
							end
							entry.alpha = 0
						end
						utilEspHidden = true
					end
					return
				end
				utilEspHidden = false
				if next(utilEntries) == nil then
					return
				end
				local camera = Workspace.CurrentCamera
				if not camera then
					return
				end
				local camPos = camera.CFrame.Position
				local maxDist = tonumber(UtilEsp.maxDistance) or 600
				local step = math.clamp(dt * UTIL_FADE_SPEED, 0, 1)

				for inst, entry in utilEntries do
					if entry.alive and not inst:IsDescendantOf(Workspace) then
						entry.alive = false
					end
					if entry.alive then
						local cf, size = utilBounds(inst)
						if cf and size then
							entry.cf = cf
							entry.size = size
							entry.pos = cf.Position
						end
					end
					local pos = entry.pos
					local dist = if pos then (pos - camPos).Magnitude else math.huge
					local want = enabled
						and entry.alive
						and pos ~= nil
						and UtilEsp.types[entry.kind] == true
						and dist <= maxDist
					entry.alpha += ((if want then 1 else 0) - entry.alpha) * step
					if not want and entry.alpha < 0.02 then
						entry.alpha = 0
						if entry.alive then
							hideUtilVisuals(entry.visuals)
						else
							destroyUtilVisuals(entry)
							utilEntries[inst] = nil
						end
						continue
					end
					if not pos then
						continue
					end
					local screen, onScreen = camera:WorldToViewportPoint(pos)
					local v = buildUtilVisuals(entry)
					if not v then
						continue
					end
					local alpha = entry.alpha
					local style = UtilEsp.styles[entry.kind] or UTIL_STYLE_DEFAULTS
					if style.box == true and entry.cf and entry.size then
						paintUtilBox(v, camera, entry.cf, entry.size, alpha, style.boxColor, entry.kind)
					else
						hideUtilBox(v)
					end
					if not onScreen or screen.Z <= 0 then
						v.image.Visible = false
						if v.name then
							v.name.Visible = false
						end
						if v.distance then
							v.distance.Visible = false
						end
						continue
					end
					local cx = math.floor(screen.X + 0.5)
					local cy = math.floor(screen.Y + 0.5)

					local textSize = math.clamp(math.floor(tonumber(style.textSize) or 13), 8, 24)
					local imageSize = math.clamp(math.floor(tonumber(style.imageSize) or 22), 12, 48)
					local fontKey = tostring(style.font or "Plex")
					local showImage = style.image == true and v.image.Image ~= ""
					v.image.Visible = showImage
					local half = 0
					if showImage then
						half = math.floor(imageSize * 0.5)
						v.image.Size = UDim2.fromOffset(imageSize, imageSize)
						v.image.Position = UDim2.fromOffset(cx, cy)
						v.image.ImageTransparency = 1 - alpha
					end
					local topY, botY = cy, cy
					if entry.cf and entry.size then
						local hx, hy, hz = entry.size.X * 0.5, entry.size.Y * 0.5, entry.size.Z * 0.5
						local minY, maxY = math.huge, -math.huge
						local cf = entry.cf
						for i = 1, 8 do
							local ix = (i - 1) % 2
							local iy = math.floor((i - 1) / 2) % 2
							local iz = math.floor((i - 1) / 4)
							local world = cf * Vector3.new(if ix == 1 then hx else -hx, if iy == 1 then hy else -hy, if iz == 1 then hz else -hz)
							local sp = camera:WorldToViewportPoint(world)
							if sp.Z > 0 then
								minY = math.min(minY, sp.Y)
								maxY = math.max(maxY, sp.Y)
							end
						end
						if minY < math.huge then
							topY, botY = minY, maxY
						end
					end
					if half > 0 then
						topY = math.min(topY, cy - half)
						botY = math.max(botY, cy + half)
					end

					if v.fontKey ~= fontKey then
						v.fontKey = fontKey
						if v.name then
							v.name.Font = fontKey
						end
						if v.distance then
							v.distance.Font = fontKey
						end
					end

					if v.name then
						local showName = style.name == true
						v.name.Visible = showName
						if showName then
							v.name.Text = string.lower(entry.kind)
							v.name.Size = textSize
							v.name.Color = style.nameColor
							v.name.Transparency = alpha
							v.name.Position = Vector2.new(cx, math.floor(topY - textSize * 0.5 - 3))
						end
					end
					if v.distance then
						local showDist = style.distance == true
						v.distance.Visible = showDist
						if showDist then
							v.distance.Text = math.floor(dist + 0.5) .. "st"
							v.distance.Size = textSize
							v.distance.Color = style.distanceColor
							v.distance.Transparency = alpha
							v.distance.Position = Vector2.new(cx, math.floor(botY + textSize * 0.5 + 3))
						end
					end
				end
			end))
		end

		end
		installEspRuntime()
	end
	end

