		g.__sonata_aim = Aim
		g.__sonata_silent = Silent
		g.__sonata_esp = DrawingBridge.Esp
		g.__sonata_movement = Movement
		g.__sonata_exploits = Exploits
	end)

	local RAGE_SLOT_NUMBERS = {
		Primary = 1,
		Secondary = 2,
		Melee = 3,
		Knife = 3,
	}

	local AIM_CONDITION_ITEMS = {
		{ id = "flashed", label = "skip if flashed" },
		{ id = "katana", label = "skip katana ability" },
		{ id = "riot", label = "skip riot shield" },
	}

	local CONDITION_ITEMS = {
		{ id = "visible", label = "skip if not visible" },
		{ id = "flashed", label = "skip if flashed" },
		{ id = "katana", label = "skip katana ability" },
		{ id = "riot", label = "skip riot shield" },
	}

	local HITBOX_ITEMS = {
		{ id = "Head", label = "Head" },
		{ id = "HumanoidRootPart", label = "HumanoidRootPart" },
		{ id = "UpperTorso", label = "UpperTorso" },
		{ id = "LowerTorso", label = "LowerTorso" },
		{ id = "Torso", label = "Torso" },
	}

	local function restoreHitboxes(target: { [string]: boolean }, data: any, legacyHitPart: any)
		if type(data) == "table" then
			for _, item in HITBOX_ITEMS do
				local v = data[item.id]
				target[item.id] = v == true
			end
			local anyOn = false
			for _, item in HITBOX_ITEMS do
				if target[item.id] then
					anyOn = true
					break
				end
			end
			if not anyOn and type(legacyHitPart) == "string" then
				target[legacyHitPart] = true
			elseif not anyOn then
				target.Head = true
			end
		elseif type(legacyHitPart) == "string" then
			for _, item in HITBOX_ITEMS do
				target[item.id] = item.id == legacyHitPart
			end
		end
	end

	local function deepClone(value: any): any
		if type(value) ~= "table" then
			return value
		end
		local copy = {}
		for key, child in value do
			copy[key] = deepClone(child)
		end
		return copy
	end

