	exportCombat = exportCombatInner

	local function restoreCombatInner(data: any)
		if type(data) ~= "table" then
			return
		end
		if type(data.aim) == "table" then
			local a = data.aim
			if type(a.enabled) == "boolean" then Aim.enabled = a.enabled end
			if type(a.keyName) == "string" then Aim.keyName = a.keyName end
			if type(a.drawFov) == "boolean" then Aim.drawFov = a.drawFov end
			if type(a.dynamicFov) == "boolean" then Aim.dynamicFov = a.dynamicFov end
			if type(a.fov) == "number" then Aim.fov = a.fov end
			if type(a.fovOrigin) == "string" then
				local o = string.lower(a.fovOrigin)
				Aim.fovOrigin = if o == "muzzle" then "Muzzle" elseif o == "target" then "Target" else "Center"
			end
			if type(a.smooth) == "number" then Aim.smooth = math.clamp(a.smooth, 0, 40) end
			Aim.sticky = true
			if type(a.deadzone) == "number" then Aim.deadzone = math.clamp(a.deadzone, 0, 100) end
			if type(a.humanize) == "number" then Aim.humanize = math.clamp(a.humanize, 0, 100) end
			if type(a.reaction) == "number" then Aim.reaction = math.clamp(a.reaction, 0, 0.5) end
			if type(a.wuziLovesVamp) == "number" then Aim.wuziLovesVamp = math.clamp(a.wuziLovesVamp, 0, 100) end
			if type(a.prediction) == "boolean" then Aim.prediction = a.prediction end
			if type(a.predictionAmount) == "number" then Aim.predictionAmount = math.clamp(a.predictionAmount, 0, 100) end
			if type(a.visibleCheck) == "boolean" then
				Aim.visibleCheck = a.visibleCheck
			elseif type(a.flags) == "table" and type(a.flags.visible) == "boolean" then
				Aim.visibleCheck = a.flags.visible
			end
			Aim.fovColor1 = tableToColor(a.fovColor1, Aim.fovColor1)
			Aim.fovColor2 = tableToColor(a.fovColor2, Aim.fovColor2)
			if type(a.fovOpacity) == "number" then Aim.fovOpacity = math.clamp(a.fovOpacity, 0, 1) end
			if type(a.fovThickness) == "number" then Aim.fovThickness = math.clamp(a.fovThickness, 0.5, 12) end
			if type(a.spinFov) == "boolean" then Aim.spinFov = a.spinFov end
			if type(a.spinSpeed) == "number" then Aim.spinSpeed = math.clamp(a.spinSpeed, 0, 720) end
			if type(a.editProfile) == "string" then
				for _, name in WEAPON_PROFILE_NAMES do
					if a.editProfile == name then
						Aim.editProfile = name
						break
					end
				end
			end
			if type(a.profiles) == "table" then
				for _, name in WEAPON_PROFILE_NAMES do
					if name == "Global" then
						continue
					end
					local row = a.profiles[name]
					if type(row) ~= "table" then
						continue
					end
					local dest = Aim.profiles[name]
					if type(dest) ~= "table" then
						dest = {}
						Aim.profiles[name] = dest
					end
					if type(row.fov) == "number" then dest.fov = math.clamp(row.fov, 20, 400) end
					if type(row.silentFov) == "number" then dest.silentFov = math.clamp(row.silentFov, 20, 600) end
					if type(row.smooth) == "number" then dest.smooth = math.clamp(row.smooth, 0, 40) end
					if type(row.deadzone) == "number" then dest.deadzone = math.clamp(row.deadzone, 0, 100) end
					if type(row.humanize) == "number" then dest.humanize = math.clamp(row.humanize, 0, 100) end
					if type(row.reaction) == "number" then dest.reaction = math.clamp(row.reaction, 0, 0.5) end
					if type(row.predictionAmount) == "number" then dest.predictionAmount = math.clamp(row.predictionAmount, 0, 100) end
					if type(row.wuziLovesVamp) == "number" then dest.wuziLovesVamp = math.clamp(row.wuziLovesVamp, 0, 100) end
				end
			end
			restoreHitboxes(Aim.hitboxes, a.hitboxes, a.hitPart)
			if type(a.flags) == "table" then
				for _, item in AIM_CONDITION_ITEMS do
					local v = a.flags[item.id]
					Aim.flags[item.id] = v == true
				end
			end
		end
		if type(data.silent) == "table" then
			local s = data.silent
			if type(s.enabled) == "boolean" then Silent.enabled = s.enabled end
			if type(s.keyName) == "string" then Silent.keyName = s.keyName end
			if type(s.hitPart) == "string" then Silent.hitPart = s.hitPart end
			if type(s.accuracy) == "number" then Silent.accuracy = math.clamp(s.accuracy, 10, 100) end
			if type(s.fov) == "number" then Silent.fov = s.fov end
			if type(s.drawFov) == "boolean" then Silent.drawFov = s.drawFov end
			if type(s.dynamicFov) == "boolean" then Silent.dynamicFov = s.dynamicFov end
			if type(s.targetAimTarget) == "boolean" then Silent.targetAimTarget = s.targetAimTarget end
			if type(s.visibleCheck) == "boolean" then
				Silent.visibleCheck = s.visibleCheck
				Silent.flags.visible = s.visibleCheck
			elseif type(s.flags) == "table" and type(s.flags.visible) == "boolean" then
				Silent.visibleCheck = s.flags.visible
			end
			if type(s.fovOrigin) == "string" then
				local o = string.lower(s.fovOrigin)
				Silent.fovOrigin = if o == "muzzle" then "Muzzle" elseif o == "target" then "Target" else "Center"
			end
			Silent.fovColor1 = tableToColor(s.fovColor1, Silent.fovColor1)
			Silent.fovColor2 = tableToColor(s.fovColor2, Silent.fovColor2)
			if type(s.fovOpacity) == "number" then Silent.fovOpacity = math.clamp(s.fovOpacity, 0, 1) end
			if type(s.fovThickness) == "number" then Silent.fovThickness = math.clamp(s.fovThickness, 0.5, 12) end
			if type(s.spinFov) == "boolean" then Silent.spinFov = s.spinFov end
			if type(s.spinSpeed) == "number" then Silent.spinSpeed = math.clamp(s.spinSpeed, 0, 720) end
			restoreHitboxes(Silent.hitboxes, s.hitboxes, s.hitPart)
			if type(s.flags) == "table" then
				for _, item in CONDITION_ITEMS do
					local v = s.flags[item.id]
					Silent.flags[item.id] = v == true
				end
			end
			if type(s.manipulation) == "boolean" then Silent.manipulation = s.manipulation end
			if type(s.manipRadius) == "number" then Silent.manipRadius = math.clamp(s.manipRadius, 2, 24) end
			if type(s.manipBudget) == "number" then Silent.manipBudget = math.clamp(s.manipBudget, 4, 128) end
			if type(s.manipStatus) == "boolean" then Silent.manipStatus = s.manipStatus end
			if type(s.manipStatusY) == "number" then Silent.manipStatusY = math.clamp(s.manipStatusY, -200, 200) end
			if type(s.manipFont) == "string" and s.manipFont ~= "" then Silent.manipFont = s.manipFont end
			Silent.manipText = tableToColor(s.manipText, Silent.manipText)
			Silent.manipHit = tableToColor(s.manipHit, Silent.manipHit)
			Silent.manipBlock = tableToColor(s.manipBlock, Silent.manipBlock)
			Silent.dynamicFov = false
		end
		if type(data.trigger) == "table" then
			local t = data.trigger
			if type(t.enabled) == "boolean" then Trigger.enabled = t.enabled end
			Trigger.silentAim = false
			Trigger.manipulation = false
			restoreHitboxes(Trigger.hitboxes, t.hitboxes, t.hitPart)
			if type(t.flags) == "table" then
				for _, item in CONDITION_ITEMS do
					local v = t.flags[item.id]
					Trigger.flags[item.id] = v == true
				end
			end
		end
		if type(data.flick) == "table" then
			local f = data.flick
			Flick.enabled = false
			if type(f.keyName) == "string" then Flick.keyName = f.keyName end
			if type(f.fov) == "number" then Flick.fov = f.fov end
			if type(f.speed) == "number" then
				Flick.speed = math.clamp(f.speed, 0.1, 10)
			elseif type(f.smooth) == "number" then
				Flick.speed = math.clamp(f.smooth, 0.1, 10)
			end
			if type(f.shoot) == "boolean" then Flick.shoot = f.shoot end
			restoreHitboxes(Flick.hitboxes, f.hitboxes, f.hitPart)
			if type(f.flags) == "table" then
				for _, item in CONDITION_ITEMS do
					local v = f.flags[item.id]
					Flick.flags[item.id] = v == true
				end
			end
		end
		if type(data.rage) == "table" then
			local r = data.rage
			if type(r.enabled) == "boolean" then Rage.enabled = r.enabled end
			if type(r.keyName) == "string" then Rage.keyName = r.keyName end
			if type(r.weaponSlot) == "string" then
				local slotName = r.weaponSlot
				if slotName == "Free" then
					slotName = "Primary"
				end
				if RAGE_SLOT_NUMBERS[slotName] then
					Rage.weaponSlot = slotName
				end
			end
			if type(r.mode) == "string" then
				local modeName = string.lower(r.mode)
				if modeName == "inside" or modeName == "knife" then
					Rage.mode = "Normal"
					if modeName == "knife" then
						Rage.weaponSlot = "Knife"
					end
				elseif modeName == "random" then
					Rage.mode = "Random"
				elseif modeName == "no skill" or modeName == "noskill" then
					Rage.mode = "No Skill"
				else
					Rage.mode = "Normal"
				end
			end
			if type(r.targetPriority) == "string" then
				local p = string.lower(r.targetPriority)
				if p == "lowest health" or p == "health" then
					Rage.targetPriority = "Lowest Health"
				elseif p == "cheater" or p == "cheaters" then
					Rage.targetPriority = "Cheater"
				elseif p == "crosshair" or p == "fov" then
					Rage.targetPriority = "Crosshair"
				elseif p == "cycle" then
					Rage.targetPriority = "Cycle"
				else
					Rage.targetPriority = "Closest"
				end
			end
			if type(r.cycleInterval) == "number" then Rage.cycleInterval = math.clamp(r.cycleInterval, 0.2, 10) end
			if type(r.fireRate) == "number" then Rage.fireRate = math.clamp(r.fireRate, 0, 1) end
			if type(r.shootAttempts) == "number" then Rage.shootAttempts = math.clamp(math.floor(r.shootAttempts), 1, 20) end
			if type(r.shootInterval) == "number" then Rage.shootInterval = math.clamp(r.shootInterval, 0, 1) end
			if type(r.shootFrames) == "number" then Rage.shootFrames = math.clamp(math.floor(r.shootFrames), 1, 5) end
			if type(r.maxDistance) == "number" then Rage.maxDistance = math.clamp(r.maxDistance, 50, 2000) end
			if type(r.skipDeflect) == "boolean" then Rage.skipDeflect = r.skipDeflect end
			if type(r.prioritizeHackers) == "boolean" then Rage.prioritizeHackers = r.prioritizeHackers end
			if type(r.weaponsEnabled) == "table" then
				for _, slot in { "Primary", "Secondary", "Melee" } do
					if type(r.weaponsEnabled[slot]) == "boolean" then
						Rage.weaponsEnabled[slot] = r.weaponsEnabled[slot]
					end
				end
			end
			if type(r.weaponPriority) == "table" then
				local nextPriority = {}
				for _, slot in r.weaponPriority do
					if slot == "Primary" or slot == "Secondary" or slot == "Melee" then
						table.insert(nextPriority, slot)
					end
				end
				if #nextPriority > 0 then
					Rage.weaponPriority = nextPriority
				end
			end
			if type(r.onEmpty) == "string" then
				local empty = string.lower(r.onEmpty)
				if empty == "reload" then
					Rage.onEmpty = "Reload"
				elseif empty == "swap" then
					Rage.onEmpty = "Swap"
				else
					Rage.onEmpty = "SwapOrReload"
				end
			end
			if type(r.engine) == "string" then
				local e = string.lower(r.engine)
				Rage.engine = if e == "v1" or e == "old" or e == "old ragebot" then "V1" else "V2"
			end
			if type(r.evasionEnabled) == "boolean" then Rage.evasionEnabled = r.evasionEnabled end
			if type(r.evasion) == "string" then
				local ev = string.lower(r.evasion)
				if ev == "off" then
					Rage.evasion = "Off"
				elseif ev == "orbit" then
					Rage.evasion = "Orbit"
				elseif ev == "sky" then
					Rage.evasion = "Sky"
				elseif ev == "underground" then
					Rage.evasion = "Underground"
				else
					Rage.evasion = "Scatter"
				end
			end
			if type(r.evasionRadius) == "number" then Rage.evasionRadius = math.clamp(r.evasionRadius, 5, 1e8) end
			if type(r.evasionRandom) == "number" then Rage.evasionRandom = math.clamp(r.evasionRandom, 0, 1) end
			if type(r.translocateOffset) == "number" then Rage.translocateOffset = math.clamp(r.translocateOffset, -80, -1) end
			Rage.weaponsEnabled.Primary = true
			Rage.weaponsEnabled.Secondary = true
			if type(r.breakerForwardMin) == "number" then Rage.breakerForwardMin = math.clamp(r.breakerForwardMin, 0, 10) end
			if type(r.breakerForwardMax) == "number" then Rage.breakerForwardMax = math.clamp(r.breakerForwardMax, 0, 10) end
			if type(r.breakerUpMin) == "number" then Rage.breakerUpMin = math.clamp(r.breakerUpMin, 0, 10) end
			if type(r.breakerUpMax) == "number" then Rage.breakerUpMax = math.clamp(r.breakerUpMax, 0, 10) end
			if type(r.breakerInterval) == "number" then Rage.breakerInterval = math.clamp(r.breakerInterval, 0.05, 2) end
			if type(r.voidSpam) == "boolean" then Rage.voidSpam = r.voidSpam end
			if type(r.attackTime) == "number" then Rage.attackTime = math.clamp(r.attackTime, 0.05, 10) end
			if type(r.voidTime) == "number" then Rage.voidTime = math.clamp(r.voidTime, 0.05, 10) end
			if type(r.knifeInterval) == "number" then Rage.knifeInterval = math.clamp(r.knifeInterval, 0.1, 5) end
			if type(r.noAmmoAction) == "string" then
				local action = string.lower(r.noAmmoAction)
				if action == "switch to melee" or action == "melee" then
					Rage.noAmmoAction = "switch to melee"
				elseif action == "force reload" or action == "reload" then
					Rage.noAmmoAction = "force reload"
				else
					Rage.noAmmoAction = "switch to other"
				end
			end
			if type(r.underground) == "boolean" then Rage.underground = r.underground end
			if type(r.undergroundY) == "number" then Rage.undergroundY = math.clamp(r.undergroundY, -10, 1) end
			if type(r.fakePos) == "boolean" then Rage.fakePos = r.fakePos end
			if type(r.fakeRadius) == "number" then Rage.fakeRadius = math.clamp(r.fakeRadius, 2, 220) end
			if type(r.fakeSpeed) == "number" then Rage.fakeSpeed = math.clamp(r.fakeSpeed, 1, 100) end
			if type(r.fakeIntensity) == "number" then Rage.fakeIntensity = math.clamp(r.fakeIntensity, 0, 100) end
			if type(r.stability) == "number" then
				local stab = r.stability
				if stab > 1.5 then
					stab = math.clamp(stab / 100 * 1.5, 0, 1.5)
				end
				Rage.stability = math.clamp(stab, 0, 1.5)
			end
			if type(r.extrapolation) == "boolean" then Rage.extrapolation = r.extrapolation end
			if type(r.extrapolationAmount) == "number" then
				Rage.extrapolationAmount = math.clamp(r.extrapolationAmount, 0, 250)
			end
			if type(r.visualizer) == "boolean" then
				Rage.visualizer = r.visualizer
			elseif type(r.status) == "boolean" then
				Rage.visualizer = r.status
			end
			local accentSrc = if r.visualizerAccent ~= nil then r.visualizerAccent else r.statusAccent
			local bodySrc = if r.visualizerColor ~= nil then r.visualizerColor else r.statusColor
			if accentSrc ~= nil then
				Rage.visualizerAccent = tableToColor(accentSrc, Rage.visualizerAccent)
				if bodySrc ~= nil then
					Rage.visualizerColor = tableToColor(bodySrc, Rage.visualizerColor)
				end
			elseif bodySrc ~= nil then
				Rage.visualizerAccent = tableToColor(bodySrc, Rage.visualizerAccent)
			end
			if type(r.visualizerY) == "number" then
				Rage.visualizerY = math.clamp(r.visualizerY, -200, 200)
			elseif type(r.statusY) == "number" then
				Rage.visualizerY = math.clamp(r.statusY, -200, 200)
			end
			if r.visualizerLineColor ~= nil then
				Rage.visualizerLineColor = tableToColor(r.visualizerLineColor, Rage.visualizerLineColor)
			end
			if type(r.visualizerLineThick) == "number" then
				Rage.visualizerLineThick = math.clamp(r.visualizerLineThick, 0.5, 8)
			end
			if type(r.visualizerFont) == "string" and r.visualizerFont ~= "" then
				Rage.visualizerFont = r.visualizerFont
			end
			if type(r.visualizerSize) == "number" then
				Rage.visualizerSize = math.clamp(math.floor(r.visualizerSize), 8, 32)
			end
			if type(r.showAmmo) == "boolean" then
				Rage.showAmmo = r.showAmmo
				Rage.vizElements.ammo = r.showAmmo
			end
			if type(r.vizElements) == "table" then
				for _, id in { "status", "ammo", "line" } do
					if type(r.vizElements[id]) == "boolean" then
						Rage.vizElements[id] = r.vizElements[id]
					end
				end
				Rage.showAmmo = Rage.vizElements.ammo == true
			end
			if type(r.ammoPosition) == "string" then
				local p = string.lower(r.ammoPosition)
				Rage.ammoPosition = if p == "muzzle" then "Muzzle" else "Onscreen"
			end
			if type(r.targetHud) == "boolean" then Rage.targetHud = r.targetHud end
			if type(r.targetHudX) == "number" then Rage.targetHudX = math.clamp(r.targetHudX, 0, 1) end
			if type(r.targetHudY) == "number" then Rage.targetHudY = math.clamp(r.targetHudY, 0, 1) end
		end
		if type(data.movement) == "table" then
			local m = data.movement
			if type(m.speed) == "boolean" then Movement.speed = m.speed end
			if type(m.speedKey) == "string" then Movement.speedKey = m.speedKey end
			if type(m.walkMulti) == "number" then Movement.walkMulti = math.clamp(m.walkMulti, 0.5, 8) end
			if type(m.slide) == "boolean" then Movement.slide = m.slide end
			if type(m.slideKey) == "string" then Movement.slideKey = m.slideKey end
			if type(m.slideMulti) == "number" then Movement.slideMulti = math.clamp(m.slideMulti, 1, 12) end
			if type(m.infJump) == "boolean" then Movement.infJump = m.infJump end
			if type(m.infJumpKey) == "string" then Movement.infJumpKey = m.infJumpKey end
			if type(m.fly) == "boolean" then Movement.fly = m.fly end
			if type(m.flyKey) == "string" then Movement.flyKey = m.flyKey end
