			if type(m.noclip) == "boolean" then Movement.noclip = m.noclip end
			if type(m.noclipKey) == "string" then Movement.noclipKey = m.noclipKey end
			if type(m.velocity) == "boolean" then Movement.velocity = m.velocity end
			if type(m.velocityKey) == "string" then Movement.velocityKey = m.velocityKey end
			if type(m.velocitySpeed) == "number" then Movement.velocitySpeed = math.clamp(m.velocitySpeed, 5, 250) end
		end
		if type(data.exploits) == "table" then
