			if type(e.gunRapid) == "boolean" then Exploits.gunRapid = e.gunRapid end
			if type(e.gunSpeed) == "number" then Exploits.gunSpeed = math.clamp(e.gunSpeed, 1, 100) end
			if type(e.meleeRapid) == "boolean" then Exploits.meleeRapid = e.meleeRapid end
			if type(e.meleeSpeed) == "number" then Exploits.meleeSpeed = math.clamp(e.meleeSpeed, 1, 100) end
			if type(e.noSpread) == "boolean" then Exploits.noSpread = e.noSpread end
