	restoreCombat = restoreCombatInner

	local combatPaint: { (boolean) -> () } = {}
	local combatGates: { () -> () } = {}

	refreshCombatUi = function()
		task.defer(function()
			for _, paint in combatPaint do
				pcall(paint, false)
			end
			for _, gate in combatGates do
				pcall(gate)
			end
		end)
	end

	local duelControllerCache: any = nil
	local fighterControllerCache: any = nil
	local spectateControllerCache: any = nil
	local combatRetryAt = 0

	local function combatControllers(): (any, any, any)
		if fighterControllerCache ~= nil and duelControllerCache ~= nil then
			return fighterControllerCache, duelControllerCache, spectateControllerCache
		end
		local now = os.clock()
		if now - combatRetryAt < 0.5 then
			return fighterControllerCache, duelControllerCache, spectateControllerCache
		end
		combatRetryAt = now
		local lp = Players.LocalPlayer
		if not lp then
			return nil, nil, nil
		end
		local scripts = lp:FindFirstChild("PlayerScripts")
		if not scripts then
			return nil, nil, nil
		end
		local controllers = scripts:FindFirstChild("Controllers")
		if not controllers then
			return nil, nil, nil
		end
		if not fighterControllerCache then
			local mod = controllers:FindFirstChild("FighterController")
			if mod then
				local ok, loaded = pcall(require, mod)
				if ok then
					fighterControllerCache = loaded
				end
			end
		end
		if not duelControllerCache then
			local mod = controllers:FindFirstChild("DuelController") or controllers:FindFirstChild("DuelsController")
			if mod then
				local ok, loaded = pcall(require, mod)
				if ok then
					duelControllerCache = loaded
				end
			end
		end
		if not spectateControllerCache then
			local mod = controllers:FindFirstChild("SpectateController")
			if mod then
				local ok, loaded = pcall(require, mod)
				if ok then
					spectateControllerCache = loaded
				end
			end
		end
		return fighterControllerCache, duelControllerCache, spectateControllerCache
	end

	local inGameMatchCached = false
	local inGameMatchAt = 0
	local function isInGameMatch(): boolean
		local now = os.clock()
		if now - inGameMatchAt < 0.5 then
			return inGameMatchCached
		end
		inGameMatchAt = now
		inGameMatchCached = false
		local lp = Players.LocalPlayer
		if not lp then
			return false
		end
		local _fighter, duelCtrl, spectate = combatControllers()
		if duelCtrl and type(duelCtrl.GetDuel) == "function" then
			local ok, duel = pcall(function()
				return duelCtrl:GetDuel(lp)
			end)
			if ok and duel ~= nil then
				inGameMatchCached = true
				DrawingBridge.inGameMatch = true
				return true
			end
		end
		if spectate then
			local ok, subject = pcall(function()
				return spectate.CurrentDuelSubject
			end)
			if ok and subject ~= nil then
				inGameMatchCached = true
				DrawingBridge.inGameMatch = true
				return true
			end
		end
		if lp and lp.Character and lp.Character:FindFirstChild("Humanoid") then
			inGameMatchCached = true
			DrawingBridge.inGameMatch = true
			return true
		end
		DrawingBridge.inGameMatch = false
		return false
	end
	DrawingBridge.isInGameMatch = isInGameMatch

	local function normalizeFovOrigin(value: any): string
		local o = string.lower(tostring(value or "center"))
		if o == "muzzle" then
			return "Muzzle"
		elseif o == "target" then
			return "Target"
		end
		return "Center"
	end

	local function profileNumber(row: any, key: string, fallback: number, lo: number, hi: number): number
		local value = if type(row) == "table" and type(row[key]) == "number" then row[key] else fallback
		return math.clamp(value, lo, hi)
	end

	local function editingProfileRow(): any?
		local name = Aim.editProfile
		if type(name) ~= "string" or name == "" or name == "Global" then
			return nil
		end
		local row = Aim.profiles[name]
		if type(row) ~= "table" then
			row = {}
			Aim.profiles[name] = row
		end
		return row
	end

	local function editNumber(key: string, fallback: () -> number, writeGlobal: (number) -> (), lo: number, hi: number): (() -> number, (number) -> ())
		return function()
			return profileNumber(editingProfileRow(), key, fallback(), lo, hi)
		end, function(value: number)
			local clamped = math.clamp(value, lo, hi)
			local row = editingProfileRow()
			if row then
				row[key] = clamped
			else
				writeGlobal(clamped)
			end
		end
	end

	do
		local function installLegitRuntime()
		local fovGui = element("ScreenGui", {
			Name = "sonata_fov",
			ResetOnSpawn = false,
			IgnoreGuiInset = true,
			DisplayOrder = 8,
			Parent = resolveParent(nil),
		}) :: ScreenGui

		local fovSeqCache: { [string]: ColorSequence } = {}
		local function smoothFovSeq(c1: Color3, c2: Color3): ColorSequence
			local key = string.format("%.4f,%.4f,%.4f|%.4f,%.4f,%.4f", c1.R, c1.G, c1.B, c2.R, c2.G, c2.B)
			local cached = fovSeqCache[key]
			if cached then
				return cached
			end
			local keys = {}
			local steps = 10
			for i = 0, steps do
				local t = i / steps
				table.insert(keys, ColorSequenceKeypoint.new(t, c1:Lerp(c2, t)))
			end
			local seq = ColorSequence.new(keys)
			fovSeqCache[key] = seq
			return seq
		end

		local function makeFovRing(name: string, c1: Color3, c2: Color3): (Frame, UIStroke, UIGradient, UIGradient)
			local ring = element("Frame", {
				Name = name,
				BackgroundColor3 = Color3.new(1, 1, 1),
				BackgroundTransparency = 0.5,
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(0.5, 0.5),
				Size = UDim2.fromOffset(0, 0),
				Visible = false,
				Parent = fovGui,
			}) :: Frame
			local fillGrad = Instance.new("UIGradient")
			fillGrad.Color = smoothFovSeq(c1, c2)
			fillGrad.Parent = ring
			local stroke = Instance.new("UIStroke")
			stroke.Thickness = 1.5
			stroke.Color = Color3.new(1, 1, 1)
			stroke.Transparency = 0.15
			stroke.Parent = ring
			local strokeGrad = Instance.new("UIGradient")
			strokeGrad.Color = smoothFovSeq(c1, c2)
			strokeGrad.Parent = stroke
			local cornerRing = Instance.new("UICorner")
			cornerRing.CornerRadius = UDim.new(1, 0)
			cornerRing.Parent = ring
			return ring, stroke, fillGrad, strokeGrad
		end

		local lastFovPaint: { [UIGradient]: string } = {}
		local function paintFovGradient(fillGrad: UIGradient, strokeGrad: UIGradient, c1: Color3, c2: Color3)
			local key = string.format("%.4f,%.4f,%.4f|%.4f,%.4f,%.4f", c1.R, c1.G, c1.B, c2.R, c2.G, c2.B)
			if lastFovPaint[fillGrad] == key and lastFovPaint[strokeGrad] == key then
				return
			end
			lastFovPaint[fillGrad] = key
			lastFovPaint[strokeGrad] = key
			local seq = smoothFovSeq(c1, c2)
			fillGrad.Color = seq
			strokeGrad.Color = seq
		end

		local aimRing, aimStroke, aimFillGrad, aimStrokeGrad = makeFovRing("AimFov", Aim.fovColor1, Aim.fovColor2)
		local silentRing, silentStroke, silentFillGrad, silentStrokeGrad = makeFovRing("SilentFov", Silent.fovColor1, Silent.fovColor2)
		aimStroke.Name = "Stroke"
		silentStroke.Name = "Stroke"

		local moveMouse: any = nil
		pcall(function()
			local env = fsGetgenv and fsGetgenv()
			moveMouse = mousemoverel or mouse_move
			if type(moveMouse) ~= "function" and type(env) == "table" then
				moveMouse = env.mousemoverel or env.mouse_move
			end
		end)

		local aimHeld = false
		local aimStickyPart: BasePart? = nil
		local aimReadyAt = 0
		local aimVelX = 0
		local aimVelY = 0
		local aimPredPos: Vector3? = nil
		local aimPredVel = Vector3.zero
		local aimPredAt = 0
		local aimPredPart: BasePart? = nil
		local aimFovDrawPos: Vector2? = nil
		local silentFovDrawPos: Vector2? = nil
		local cachedMuzzle: Instance? = nil
		local lastMuzzleScan = 0

		local function findMuzzleInstance(): Instance?
			local now = os.clock()
			if now - lastMuzzleScan < 0.55 then
				if cachedMuzzle and cachedMuzzle.Parent then
					return cachedMuzzle
				end
				return nil
			end
			lastMuzzleScan = now
			cachedMuzzle = nil
			local function scan(root: Instance?): Instance?
				if not root then
					return nil
				end
				local direct = root:FindFirstChild("_muzzle", true)
				if direct then
					return direct
				end
				return nil
			end
			local cam = Workspace.CurrentCamera
			if cam then
				for _, child in cam:GetChildren() do
					local found = scan(child)
					if found then
						cachedMuzzle = found
						return found
					end
				end
			end
			local vms = Workspace:FindFirstChild("ViewModels")
			if vms then
				local found = scan(vms)
				if found then
					cachedMuzzle = found
					return found
				end
			end
			return nil
		end

		local function muzzleWorldPos(): Vector3?
			local m = findMuzzleInstance()
			if not m then
				return nil
			end
			if m:IsA("Attachment") then
				return m.WorldPosition
			end
			if m:IsA("BasePart") then
				return m.Position
			end
			local parent = m.Parent
			if parent and parent:IsA("BasePart") then
				return parent.Position
			end
			return nil
		end

		local function worldToScreen(cam: Camera, world: Vector3): Vector2?
			local sp, onScreen = cam:WorldToViewportPoint(world)
			if sp.Z <= 0 then
				return nil
			end
			if not onScreen and (sp.X < -200 or sp.X > cam.ViewportSize.X + 200 or sp.Y < -200 or sp.Y > cam.ViewportSize.Y + 200) then
				return nil
			end
			return Vector2.new(sp.X, sp.Y)
		end

		local function resolveFovOriginScreen(mode: string, cam: Camera, lockPart: BasePart?): Vector2
			local center = cam.ViewportSize * 0.5
			local origin = normalizeFovOrigin(mode)
			if origin == "Muzzle" then
				local wp = muzzleWorldPos()
				if wp then
					local screen = worldToScreen(cam, wp)
					if screen then
						return screen
					end
				end
				return center
			elseif origin == "Target" then
				if lockPart and lockPart.Parent then
					local screen = worldToScreen(cam, lockPart.Position)
					if screen then
						return screen
					end
				end
				return center
			end
			return center
		end

		local function rageTargetFovScreen(cam: Camera): Vector2?
			if not Rage.enabled then
				return nil
			end
			local part: BasePart? = RageLive.hitPart
			if (not part or not part.Parent) and RageLive.targetPlayer then
				local ch = RageLive.targetPlayer.Character
				if ch then
					local head = ch:FindFirstChild("Head")
					local hrp = ch:FindFirstChild("HumanoidRootPart")
					if head and head:IsA("BasePart") then
						part = head
					elseif hrp and hrp:IsA("BasePart") then
						part = hrp
					end
				end
			end
			if not part or not part:IsA("BasePart") or not part.Parent then
				return nil
			end
			local sp, onScreen = cam:WorldToViewportPoint(part.Position)
			if not onScreen or sp.Z <= 0 then
				return nil
			end
			return Vector2.new(sp.X, sp.Y)
		end

		local function tweenFovPos(current: Vector2?, target: Vector2, dt: number, speed: number?): Vector2
			if not current then
				return target
			end
			local rate = speed or 14
			local alpha = 1 - math.exp(-math.max(dt, 1 / 240) * rate)
			return current:Lerp(target, math.clamp(alpha, 0, 1))
		end

		local function tweenFovRadius(current: number?, target: number, dt: number): number
			if current == nil or math.abs(current - target) > 10 then
				return target
			end
			local alpha = 1 - math.exp(-math.max(dt, 1 / 240) * 24)
			local nextValue = current + (target - current) * math.clamp(alpha, 0, 1)
			if math.abs(nextValue - target) < 0.2 then
				return target
			end
			return nextValue
		end

		local _activeWeaponProfile = "Global"
		local activeWeaponAt = 0
		local aimItemLib: any = nil
		local resolvedAimFov = Aim.fov
		local resolvedSilentFov = Silent.fov
		local resolvedSmooth = Aim.smooth
		local resolvedDeadzone = Aim.deadzone
		local resolvedHumanize = Aim.humanize
		local resolvedReaction = Aim.reaction
		local resolvedPredAmt = Aim.predictionAmount
		local resolvedVamp = Aim.wuziLovesVamp
		local aimFovDrawRadius: number? = nil
		local silentFovDrawRadius: number? = nil

		local CLASSIFY_KEYS = { "Type", "WeaponType", "Subclass", "Category", "Class" }
		local function classifyWeapon(name: string, info: any): string
			local text = string.lower(name)
			if type(info) == "table" then
				for _, key in CLASSIFY_KEYS do
					local value = info[key]
					if type(value) == "string" then
						text ..= " " .. string.lower(value)
					end
				end
			end
			if string.find(text, "melee", 1, true)
				or string.find(text, "knife", 1, true)
				or string.find(text, "katana", 1, true)
				or string.find(text, "scythe", 1, true)
				or string.find(text, "fist", 1, true)
				or string.find(text, "sword", 1, true)
				or string.find(text, "riot", 1, true)
			then
				return "Melee"
			end
			if string.find(text, "shotgun", 1, true) or string.find(text, "paintball", 1, true) then
				return "Shotguns"
			end
			if string.find(text, "sniper", 1, true) or string.find(text, "crossbow", 1, true) or string.find(text, "bow", 1, true) then
				return "Snipers"
			end
			if string.find(text, "smg", 1, true) or string.find(text, "uzi", 1, true) then
				return "SMGs"
			end
			if string.find(text, "pistol", 1, true)
				or string.find(text, "revolver", 1, true)
				or string.find(text, "handgun", 1, true)
				or string.find(text, "shorty", 1, true)
				or string.find(text, "exogun", 1, true)
				or string.find(text, "slingshot", 1, true)
			then
				return "Pistols"
			end
			if string.find(text, "rifle", 1, true) or string.find(text, "assault", 1, true) or string.find(text, "burst", 1, true) then
				return "Rifles"
			end
			if type(info) == "table" then
				if info.Class == "Melee" then
					return "Melee"
				elseif info.Class == "Primary" then
					return "Rifles"
				elseif info.Class == "Secondary" then
					return "Pistols"
				end
			end
			return "Global"
		end

		local lastProfileItem: any = nil
		local function refreshWeaponProfile()
			local fighter = select(1, combatControllers())
			local item = fighter and fighter.LocalFighter and fighter.LocalFighter.EquippedItem
			if item == lastProfileItem then
				return
			end
			lastProfileItem = item
			activeWeaponAt = os.clock()
			local category = "Global"
			local name: string? = nil
			if type(item) == "table" then
				if type(item.Name) == "string" then
					name = item.Name
				elseif type(item.Get) == "function" then
					local ok, got = pcall(item.Get, item, "Name")
					if ok and type(got) == "string" then
						name = got
					end
				end
			end
			if type(name) == "string" and name ~= "" then
				if not aimItemLib then
					pcall(function()
						aimItemLib = require(ReplicatedStorage.Modules.ItemLibrary)
					end)
				end
				local info = aimItemLib and aimItemLib.Items and aimItemLib.Items[name]
				category = classifyWeapon(name, info)
			end
			_activeWeaponProfile = category
			local row = if Aim.editProfile ~= "Global" and category ~= "Global" and type(Aim.profiles[category]) == "table" and next(Aim.profiles[category]) ~= nil then Aim.profiles[category] else nil
			resolvedAimFov = profileNumber(row, "fov", Aim.fov, 20, 400)
			resolvedSilentFov = profileNumber(row, "silentFov", Silent.fov, 20, 600)
			resolvedSmooth = profileNumber(row, "smooth", Aim.smooth, 0, 40)
			resolvedDeadzone = profileNumber(row, "deadzone", Aim.deadzone, 0, 100)
			resolvedHumanize = profileNumber(row, "humanize", Aim.humanize, 0, 100)
			resolvedReaction = profileNumber(row, "reaction", Aim.reaction, 0, 0.5)
			resolvedPredAmt = profileNumber(row, "predictionAmount", Aim.predictionAmount, 0, 100)
			resolvedVamp = profileNumber(row, "wuziLovesVamp", Aim.wuziLovesVamp, 0, 100)
		end

		local function keyMatches(input: InputObject): boolean
			if Aim.keyName == "MouseButton1" then
				return input.UserInputType == Enum.UserInputType.MouseButton1
			elseif Aim.keyName == "MouseButton2" then
				return input.UserInputType == Enum.UserInputType.MouseButton2
			elseif Aim.keyName == "MouseButton3" then
				return input.UserInputType == Enum.UserInputType.MouseButton3
			end
			return input.KeyCode.Name == Aim.keyName
		end

		table.insert(ears, UserInputService.InputBegan:Connect(function(input: InputObject, processed: boolean)
			if processed then
				return
			end
			if keyMatches(input) then
				aimHeld = true
			end
		end))
		table.insert(ears, UserInputService.InputEnded:Connect(function(input: InputObject)
			if keyMatches(input) then
				aimHeld = false
				aimStickyPart = nil
				aimReadyAt = 0
				aimVelX = 0
				aimVelY = 0
				aimPredPos = nil
				aimPredVel = Vector3.zero
				aimPredPart = nil
			end
		end))

		local function isCombatEnemy(player: Player): boolean
			local lp = Players.LocalPlayer
			if not lp or player == lp then
				return false
			end
			local _f, _d, spectate = combatControllers()
			local duel = spectate and spectate.CurrentDuelSubject
			local localDueler = duel and duel:GetDueler(lp)
			local localTeam = localDueler and localDueler:Get("TeamID") or nil
			if localTeam and duel and duel.Duelers then
				for _, dueler in duel.Duelers do
					if dueler.Player == player then
						local team = dueler:Get("TeamID")
						return team ~= localTeam
					end
				end
			end
			local pTeam = player:GetAttribute("TeamID")
			local lTeam = lp:GetAttribute("TeamID")
			if pTeam and lTeam then
				return pTeam ~= lTeam
			end
			return true
		end

		local legitLosParams = RaycastParams.new()
		legitLosParams.FilterType = Enum.RaycastFilterType.Exclude
		legitLosParams.IgnoreWater = true
		local legitLosExclude: { Instance } = {}
		local function hasLineOfSight(part: BasePart): boolean
			local cam = Workspace.CurrentCamera
			local lp = Players.LocalPlayer
			if not cam or not lp then
				return false
			end
			local origin = cam.CFrame.Position
			local target = part.Position
			local delta = target - origin
			local dist = delta.Magnitude
			if dist < 0.05 then
				return true
			end
			table.clear(legitLosExclude)
			table.insert(legitLosExclude, cam)
			if lp.Character then
				table.insert(legitLosExclude, lp.Character)
			end
			legitLosParams.FilterDescendantsInstances = legitLosExclude
			local hit = Workspace:Raycast(origin, delta.Unit * dist, legitLosParams)
			if not hit then
				return true
			end
			local model = part:FindFirstAncestorOfClass("Model")
			return model ~= nil and hit.Instance:IsDescendantOf(model)
		end

		local function blockedByFlags(character: Model?, flags: any, requireVisible: boolean?): boolean
			if not character then
				return true
			end
			if requireVisible == true or flags.visible then
				local head = character:FindFirstChild("Head") or character:FindFirstChild("HumanoidRootPart")
				if head and head:IsA("BasePart") then
					local cam = Workspace.CurrentCamera
					if cam then
						local _, onScreen = cam:WorldToViewportPoint(head.Position)
						if onScreen == false or not hasLineOfSight(head) then
							return true
						end
					end
				else
					return true
				end
			end
			if flags.flashed then
				local ok, flashed = pcall(function()
					return character:GetAttribute("Flashed") == true or character:FindFirstChild("Flashbang") ~= nil
				end)
				if ok and flashed then
					return true
				end
			end
			if flags.katana then
				local tool = character:FindFirstChildOfClass("Tool")
				if tool and string.find(string.lower(tool.Name), "katana", 1, true) then
					return true
				end
			end
			if flags.riot then
				local tool = character:FindFirstChildOfClass("Tool")
				if tool and (string.find(string.lower(tool.Name), "riot", 1, true) or string.find(string.lower(tool.Name), "shield", 1, true)) then
					return true
				end
			end
			return false
		end

		local unzoomedCamFov = 80
		local function computeEffectiveFov(baseFov: number, isDynamic: boolean, cam: Camera?): number
			if not isDynamic or not cam then
				return baseFov
			end
			local camFov = math.clamp(cam.FieldOfView, 1, 130)
			if camFov >= 68 then
				unzoomedCamFov = camFov
			end
			local baseAngle = unzoomedCamFov or 80
			local baseRad = math.rad(baseAngle * 0.5)
			local currentRad = math.rad(camFov * 0.5)
			local scale = math.tan(baseRad) / math.tan(currentRad)
			return baseFov * scale
		end

		local function bestTarget(radius: number, hitboxes: { [string]: boolean }, flags: any, requireVisible: boolean?, fovCenter: Vector2?): BasePart?
			local cam = Workspace.CurrentCamera
			local lp = Players.LocalPlayer
			if not cam or not lp then
				return nil
			end
			local center = fovCenter or (cam.ViewportSize * 0.5)
			local centerX = center.X
			local centerY = center.Y
			local radiusSq = radius * radius
			local bestPart: BasePart? = nil
			local bestScore = radius
			for _, player in Players:GetPlayers() do
				if not isCombatEnemy(player) then
					continue
				end
				local character = player.Character
				if not character then
					continue
				end
				local humanoid = character:FindFirstChildOfClass("Humanoid")
				if not humanoid or humanoid.Health <= 0 then
					continue
				end
				if blockedByFlags(character, flags, requireVisible) then
					continue
				end
				for _, item in HITBOX_ITEMS do
					if not hitboxes[item.id] then
						continue
					end
					local part = character:FindFirstChild(item.id)
					if not part or not part:IsA("BasePart") then
						continue
					end
					local sp, onScreen = cam:WorldToViewportPoint(part.Position)
					if onScreen and sp.Z > 0 then
						local dx = sp.X - centerX
						local dy = sp.Y - centerY
						local dSq = dx * dx + dy * dy
						if dSq <= radiusSq then
							local d = math.sqrt(dSq)
							local score = d
							if item.id == "Head" then
								score *= 0.68
							elseif item.id == "UpperTorso" or item.id == "HumanoidRootPart" then
								score *= 0.9
							end
							if requireVisible == true or flags.visible then
								if not hasLineOfSight(part) then
									continue
								end
							end
							if score < bestScore then
								bestScore = score
								bestPart = part
							end
						end
					end
				end
			end
			return bestPart
		end

		local function aimPartValid(part: BasePart?): boolean
			if not part or not part.Parent then
				return false
			end
			local character = part:FindFirstAncestorOfClass("Model")
			if not character then
				return false
			end
			local player = Players:GetPlayerFromCharacter(character)
			if not player or not isCombatEnemy(player) then
				return false
			end
			local humanoid = character:FindFirstChildOfClass("Humanoid")
			if not humanoid or humanoid.Health <= 0 then
				return false
			end
			if blockedByFlags(character, Aim.flags, Aim.visibleCheck) then
				return false
			end
			if not Aim.hitboxes[part.Name] then
				local anyHit = false
				for _, item in HITBOX_ITEMS do
					if Aim.hitboxes[item.id] then
						anyHit = true
						break
					end
				end
				if anyHit then
					return false
				end
			end
			return true
		end

		local function resolveStickyAimTarget(): BasePart?
			local cam = Workspace.CurrentCamera
			if not cam then
				aimStickyPart = nil
				return nil
			end
			local effectiveFov = computeEffectiveFov(resolvedAimFov, Aim.dynamicFov, cam)
			local fovCenter = resolveFovOriginScreen(Aim.fovOrigin, cam, aimStickyPart)
			local fovTarget = bestTarget(effectiveFov, Aim.hitboxes, Aim.flags, Aim.visibleCheck, fovCenter)
			if aimStickyPart then
				local stillValid = aimPartValid(aimStickyPart)
				local inCircle = false
				if stillValid then
					local sp, onScreen = cam:WorldToViewportPoint(aimStickyPart.Position)
					if onScreen and sp.Z > 0 then
						local dx = sp.X - fovCenter.X
						local dy = sp.Y - fovCenter.Y
						inCircle = (dx * dx + dy * dy) <= (effectiveFov * effectiveFov)
					end
				end
				if not stillValid or not inCircle then
					aimStickyPart = nil
				end
			end
			if aimStickyPart then
				if fovTarget then
					local stickyModel = aimStickyPart:FindFirstAncestorOfClass("Model")
					local fovModel = fovTarget:FindFirstAncestorOfClass("Model")
					if fovModel and fovModel ~= stickyModel then
						aimStickyPart = fovTarget
						aimReadyAt = os.clock() + math.clamp(resolvedReaction, 0, 0.5)
						aimVelX = 0
						aimVelY = 0
					elseif fovModel == stickyModel then
						aimStickyPart = fovTarget
					end
				end
				return aimStickyPart
			end
			if fovTarget then
				aimStickyPart = fovTarget
				aimReadyAt = os.clock() + math.clamp(resolvedReaction, 0, 0.5)
				aimVelX = 0
				aimVelY = 0
				return aimStickyPart
			end
			aimStickyPart = nil
			return nil
		end

		local silentStickyPart: BasePart? = nil
		local SILENT_STICKY_BIAS = 0.85

		local silentEnemyOf: { [Player]: boolean } = {}
		local silentRosterAt = -1
		local silentInMatch = false
		local function refreshSilentRoster(now: number): boolean
			if now - silentRosterAt < 0.25 then
				return silentInMatch
			end
			silentRosterAt = now
			table.clear(silentEnemyOf)
			local lp = Players.LocalPlayer
			local _f, duelCtrl, spectate = combatControllers()
			local duel: any = nil
			if duelCtrl and type(duelCtrl.GetDuel) == "function" then
				pcall(function()
					duel = duelCtrl:GetDuel(lp)
				end)
			end
			if duel == nil and spectate then
				pcall(function()
					duel = spectate.CurrentDuelSubject
				end)
			end
			silentInMatch = duel ~= nil
			if not duel then
				for _, player in ipairs(Players:GetPlayers()) do
					if player ~= lp then
						silentEnemyOf[player] = true
					end
				end
				return true
			end
			local teams: { [Player]: any } = {}
			local allies: { [Player]: boolean } = {}
			pcall(function()
				for _, dueler in duel.Duelers do
					local player = dueler.Player
					if player then
						local ok, team = pcall(function()
							return dueler:Get("TeamID")
						end)
						teams[player] = if ok then team else nil
						allies[player] = dueler._is_ally == true
					end
				end
			end)
			local localTeam = teams[lp]
			for player, team in teams do
				if player ~= lp then
					silentEnemyOf[player] = not allies[player] and (team == nil or localTeam == nil or team ~= localTeam)
				end
			end
			return true
		end

		local SILENT_SERVER_HITBOX = { Head = "HitboxHead" }
		local function applySilentAccuracy(hitPart: BasePart, point: Vector3): Vector3
			local acc = math.clamp(tonumber(Silent.accuracy) or 100, 10, 100)
			if acc >= 99.5 then
				return point
			end
			local miss = 1 - acc / 100
			local size = hitPart.Size
			local radius = (math.max(size.X, size.Y, size.Z) * 0.55 + 3.2 * miss) * miss
			local dir = Vector3.new(math.random() - 0.5, math.random() - 0.5, math.random() - 0.5)
			if dir.Magnitude < 1e-4 then
				dir = Vector3.new(1, 0, 0)
			end
			return point + dir.Unit * (math.random() * radius)
		end
		local function silentShotPart(part: BasePart): (BasePart, Vector3)
			local character = part.Parent
			local wanted = SILENT_SERVER_HITBOX[part.Name] or "HitboxBody"
			local hitbox = character and character:FindFirstChild(wanted)
			if not (hitbox and hitbox:IsA("BasePart")) then
				return part, applySilentAccuracy(part, part.Position)
			end
			local box = hitbox :: BasePart
			local half = box.Size * 0.45
			local localPoint = box.CFrame:PointToObjectSpace(part.Position)
			local clamped = Vector3.new(
				math.clamp(localPoint.X, -half.X, half.X),
				math.clamp(localPoint.Y, -half.Y, half.Y),
				math.clamp(localPoint.Z, -half.Z, half.Z)
			)
			local point = box.CFrame:PointToWorldSpace(clamped)
			return box, applySilentAccuracy(box, point)
		end

		local silentLosParams = RaycastParams.new()
		silentLosParams.FilterType = Enum.RaycastFilterType.Exclude
		silentLosParams.IgnoreWater = true
		local silentLosFilter: { Instance } = {}
		local function silentClearShot(cam: Camera, character: Instance, point: Vector3): boolean
			table.clear(silentLosFilter)
			table.insert(silentLosFilter, cam)
			table.insert(silentLosFilter, character)
			local lp = Players.LocalPlayer
			if lp and lp.Character then
				table.insert(silentLosFilter, lp.Character)
			end
			local viewModels = Workspace:FindFirstChild("ViewModels")
			if viewModels then
				table.insert(silentLosFilter, viewModels)
			end
			silentLosParams.FilterDescendantsInstances = silentLosFilter
			local origin = cam.CFrame.Position
			return Workspace:Raycast(origin, point - origin, silentLosParams) == nil
		end

		local function silentTarget(): BasePart?
			local cam = Workspace.CurrentCamera
			if not Silent.enabled or not cam then
				silentStickyPart = nil
				return nil
			end
			refreshSilentRoster(os.clock())
			local effectiveFov = computeEffectiveFov(resolvedSilentFov, false, cam)
			local center = resolveFovOriginScreen(Silent.fovOrigin, cam, silentStickyPart)
			local centerX = center.X
			local centerY = center.Y
			local radius = math.max(1, effectiveFov)
			local radiusSq = radius * radius
			local isVisReq = Silent.visibleCheck == true or Silent.flags.visible == true
			local needClear = isVisReq == true
			local anyHitbox = false
			for _, item in HITBOX_ITEMS do
				if Silent.hitboxes[item.id] then
					anyHitbox = true
					break
				end
			end

			if Silent.targetAimTarget and aimStickyPart and aimStickyPart.Parent and aimPartValid(aimStickyPart) then
				local aimChar = aimStickyPart:FindFirstAncestorOfClass("Model")
				if aimChar and not blockedByFlags(aimChar, Silent.flags, isVisReq) then
					local chosenPart: BasePart? = nil
					for _, item in HITBOX_ITEMS do
						if (anyHitbox and Silent.hitboxes[item.id]) or (not anyHitbox and item.id == "Head") then
							local p = aimChar:FindFirstChild(item.id)
							if p and p:IsA("BasePart") then
								chosenPart = p
								break
							end
						end
					end
					if not chosenPart then
						chosenPart = aimStickyPart
					end
					if chosenPart then
						local sp, onScreen = cam:WorldToViewportPoint(chosenPart.Position)
						if onScreen and sp.Z > 0 then
							local dx = sp.X - centerX
							local dy = sp.Y - centerY
							if (dx * dx + dy * dy) <= radiusSq then
								local canHit = true
								if needClear then
									local _hitPart, point = silentShotPart(chosenPart)
									canHit = silentClearShot(cam, aimChar, point)
								end
								if canHit then
									silentStickyPart = chosenPart
									return chosenPart
								end
							end
						end
					end
				end
			end

			local stickyModel = silentStickyPart and silentStickyPart.Parent
			local bestPart: BasePart? = nil
			local bestScore = math.huge
			local rosterReady = next(silentEnemyOf) ~= nil
			local lp = Players.LocalPlayer
			for _, player in Players:GetPlayers() do
				local enemy = if rosterReady then silentEnemyOf[player] == true else (lp ~= nil and player ~= lp)
				if not enemy then
					continue
				end
				local character = player.Character
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				if not humanoid or humanoid.Health <= 0 or blockedByFlags(character, Silent.flags, isVisReq) then
					continue
				end
				for _, item in HITBOX_ITEMS do
					if anyHitbox and not Silent.hitboxes[item.id] then
						continue
					end
					if not anyHitbox and item.id ~= "Head" then
						continue
					end
					local part = (character :: Model):FindFirstChild(item.id)
					if not part or not part:IsA("BasePart") then
						continue
					end
					local sp, onScreen = cam:WorldToViewportPoint(part.Position)
					if not onScreen or sp.Z <= 0 then
						continue
					end
					local dx = sp.X - centerX
					local dy = sp.Y - centerY
					local dSq = dx * dx + dy * dy
					if dSq > radiusSq then
						continue
					end
					local score = math.sqrt(dSq)
					if character == stickyModel then
						score *= SILENT_STICKY_BIAS
					end
					if score < bestScore then
						if needClear then
							local _hitPart, point = silentShotPart(part :: BasePart)
							if not silentClearShot(cam, character :: Model, point) then
								continue
							end
						end
						bestScore = score
						bestPart = part :: BasePart
					end
				end
			end
			silentStickyPart = bestPart
			return bestPart
		end

		local function silentOwnerName(part: BasePart?): string?
			if not part then
				return nil
			end
			local model = part:FindFirstAncestorOfClass("Model") or part.Parent
			if model then
				local plr = Players:GetPlayerFromCharacter(model)
				if plr then
					return plr.Name
				end
				if type(model.Name) == "string" and model.Name ~= "" then
					return model.Name
				end
			end
			return nil
		end

		local kManipulationRadius = 9.99
		local kManipulationRayBudget = 128
		local kManipulationPrepareBudget = 64
		local kManipulationCacheAge = 0.25
		local kManipulationRefresh = 0.04
		local _kManipulationMargin = 0.12
		local kManipulationMotionLimit = 3.5
		local kManipulationMinimum = 0.001
		local kManipulationUnitDirs: { Vector3 } = {}
		do
			local N = 64
			local goldenAngle = math.pi * (3 - math.sqrt(5))
			local rawDirs = {}
			for i = 0, N - 1 do
				local y = 1 - (i / (N - 1)) * 2
				local r = math.sqrt(math.max(0, 1 - y * y))
				local theta = goldenAngle * i
				local x = math.cos(theta) * r
				local z = math.sin(theta) * r
				table.insert(rawDirs, Vector3.new(x, y, z))
			end
			table.sort(rawDirs, function(a, b)
				local scoreA = (a.X * a.X + a.Y * a.Y) + (if a.Y > 0 then 0.25 else 0)
				local scoreB = (b.X * b.X + b.Y * b.Y) + (if b.Y > 0 then 0.25 else 0)
				return scoreA > scoreB
			end)
			kManipulationUnitDirs = rawDirs
		end

		local function finiteVec(position: Vector3): boolean
			return position.X == position.X
				and position.Y == position.Y
				and position.Z == position.Z
				and math.abs(position.X) < math.huge
				and math.abs(position.Y) < math.huge
				and math.abs(position.Z) < math.huge
		end

		local manip = {
			cursor = 1,
			params = RaycastParams.new(),
			rays = 0,
			budget = kManipulationRayBudget,
			prepared = 0,
			refreshed = 0,
			reason = "idle",
			part = nil :: BasePart?,
			item = nil :: any,
			camera = nil :: Camera?,
			character = nil :: Instance?,
			localcharacter = nil :: Instance?,
			equiphash = nil :: any,
			offset = nil :: Vector3?,
			eye = nil :: Vector3?,
			goal = nil :: Vector3?,
			at = nil :: number?,
		}
		manip.params.FilterType = Enum.RaycastFilterType.Exclude
		manip.params.IgnoreWater = true

		local MANIP_EMPTY_FILTER: { Instance } = {}
		local function manipReset()
			manip.part, manip.item, manip.camera, manip.character, manip.localcharacter = nil, nil, nil, nil, nil
			manip.equiphash, manip.offset, manip.eye, manip.goal, manip.at = nil, nil, nil, nil, nil
			manip.cursor, manip.rays, manip.prepared, manip.refreshed, manip.reason = 1, 0, 0, 0, "idle"
			manip.params.FilterDescendantsInstances = MANIP_EMPTY_FILTER
		end

		local function manipCast(origin: Vector3, goal: Vector3): (RaycastResult?, boolean)
			if manip.rays >= manip.budget then
				return nil, false
			end
			manip.rays += 1
			return Workspace:Raycast(origin, goal - origin, manip.params), true
		end

		local kMaxServerRadius = 9.95

		local manipFilterTable: { Instance } = {}

		local function clampToCharacterSphere(cand: Vector3, eye: Vector3, charRef: Vector3?, maxRadius: number): Vector3
			local limit = math.min(maxRadius, kMaxServerRadius)
			local fromEye = cand - eye
			local distEye = fromEye.Magnitude
			if distEye > limit and distEye > 0.001 then
				cand = eye + fromEye.Unit * limit
			end
			if charRef then
				local fromChar = cand - charRef
				local distChar = fromChar.Magnitude
				if distChar > kMaxServerRadius and distChar > 0.001 then
					cand = charRef + fromChar.Unit * (kMaxServerRadius - 0.05)
				end
			end
			return cand
		end

		local function manipAccept(origin: Vector3, eye: Vector3, goal: Vector3, cf: CFrame, charRef: Vector3?, alt1: Vector3?, alt2: Vector3?, alt3: Vector3?): (Vector3?, boolean?)
			local distEye = (origin - eye).Magnitude
			if not finiteVec(origin)
				or distEye <= kManipulationMinimum
				or distEye > kMaxServerRadius + 0.05
				or (goal - origin).Magnitude <= kManipulationMinimum
			then
				return nil, nil
			end
			if charRef and (origin - charRef).Magnitude > kMaxServerRadius then
				return nil, nil
			end
			local wall, wallTested = manipCast(eye, origin)
			if not wallTested or wall then
				return nil, nil
			end
			local hit, tested = manipCast(origin, goal)
			if tested and not hit then
				manip.offset = cf:PointToObjectSpace(origin)
				manip.eye = eye
				manip.goal = goal
				manip.at = os.clock()
				manip.reason = "displaced"
				return origin, true
			end
			if alt1 and tested and hit then
				local altHit, altTested = manipCast(origin, alt1)
				if altTested and not altHit then
					manip.offset = cf:PointToObjectSpace(origin)
					manip.eye = eye
					manip.goal = alt1
					manip.at = os.clock()
					manip.reason = "displaced"
					return origin, true
				end
			end
			if alt2 and tested and hit then
				local altHit, altTested = manipCast(origin, alt2)
				if altTested and not altHit then
					manip.offset = cf:PointToObjectSpace(origin)
					manip.eye = eye
					manip.goal = alt2
					manip.at = os.clock()
					manip.reason = "displaced"
					return origin, true
				end
			end
			if alt3 and tested and hit then
				local altHit, altTested = manipCast(origin, alt3)
				if altTested and not altHit then
					manip.offset = cf:PointToObjectSpace(origin)
					manip.eye = eye
					manip.goal = alt3
					manip.at = os.clock()
					manip.reason = "displaced"
					return origin, true
				end
			end
			return nil, nil
		end

		local function manipSolve(camera: Camera?, part: BasePart?, item: any, character: Instance?, viewmodels: Instance?, goalPoint: Vector3?): (Vector3?, boolean?)
			local now = os.clock()
			manip.rays = 0
			manip.prepared = 0
			manip.budget = math.clamp(Silent.manipBudget or kManipulationRayBudget, 4, kManipulationRayBudget)
			if manip.budget == 0 then
				manip.reason = "budget"
				return nil, nil
			end
			if not camera or not camera.CFrame or not part or not part.Parent or not item then
				manipReset()
				manip.reason = "unavailable"
				return nil, nil
			end
			local head = character and character:FindFirstChild("Head")
			local root = character and character:FindFirstChild("HumanoidRootPart")
			local charRef = if head and head:IsA("BasePart") then head.Position elseif root and root:IsA("BasePart") then root.Position else nil

			local cf, goal = camera.CFrame, goalPoint or part.Position
			local eye = cf.Position
			local rightVec = cf.RightVector
			local alt1 = goal + Vector3.new(0, 0.45, 0)
			local alt2 = goal + rightVec * 0.75
			local alt3 = goal - rightVec * 0.75

			if manip.refreshed > 0
				and (now - manip.refreshed) < kManipulationRefresh
				and manip.offset
				and manip.eye
				and manip.goal
			then
				local origin, shifted = manipAccept(cf:PointToWorldSpace(manip.offset), manip.eye, manip.goal, cf, charRef, alt1, alt2, alt3)
				if origin then
					manip.reason = "refresh"
					return origin, shifted
				end
			end
			local equipped = true
			pcall(function()
				if item.IsEquipped == false then
					equipped = false
				end
			end)
			if not equipped then
				manipReset()
				manip.reason = "unavailable"
				return nil, nil
			end
			if not finiteVec(eye) or not finiteVec(goal) or (goal - eye).Magnitude <= kManipulationMinimum then
				manipReset()
				manip.reason = "degenerate"
				return nil, nil
			end
			local hash = nil
			pcall(function()
				hash = item._equip_hash
			end)
			if manip.part ~= part
				or manip.item ~= item
				or manip.camera ~= camera
				or manip.character ~= part.Parent
				or manip.localcharacter ~= character
				or manip.equiphash ~= hash
			then
				manipReset()
				manip.part = part
				manip.item = item
				manip.camera = camera
				manip.character = part.Parent
				manip.localcharacter = character
				manip.equiphash = hash
			end

			table.clear(manipFilterTable)
			if camera then table.insert(manipFilterTable, camera) end
			if part.Parent then table.insert(manipFilterTable, part.Parent) end
			if character then table.insert(manipFilterTable, character) end
			if viewmodels then table.insert(manipFilterTable, viewmodels) end
			manip.params.FilterType = Enum.RaycastFilterType.Exclude
			manip.params.FilterDescendantsInstances = manipFilterTable

			local obstruction = select(1, manipCast(eye, goal))
			if not obstruction then
				manip.offset = nil
				manip.cursor = 1
				manip.reason = "direct"
				return eye, false
			end
			local projectile = false
			pcall(function()
				projectile = item.Info ~= nil and item.Info.ProjectileClientSided == true
			end)
			if projectile then
				manip.offset = nil
				manip.reason = "projectile"
				return nil, nil
			end
			if manip.offset
				and manip.at
				and os.clock() - manip.at <= kManipulationCacheAge
				and manip.eye
				and manip.goal
				and (manip.eye - eye).Magnitude <= kManipulationMotionLimit
				and (manip.goal - goal).Magnitude <= kManipulationMotionLimit
			then
				local origin, shifted = manipAccept(cf:PointToWorldSpace(manip.offset), eye, goal, cf, charRef, alt1, alt2, alt3)
				if origin then
					manip.reason = "cached"
					manip.refreshed = now
					return origin, shifted
				end
			end
			manip.offset = nil
			local maxR = math.clamp(Silent.manipRadius or kManipulationRadius, 2, 24)
			local safeR = math.min(maxR, kMaxServerRadius)
			local toGoal = goal - eye
			local shotDir = toGoal.Unit
			local hitNorm = obstruction.Normal

			local camRight = cf.RightVector
			local camUp = cf.UpVector

			local wallSlide = shotDir:Cross(hitNorm)
			if wallSlide.Magnitude > 0.001 then
				wallSlide = wallSlide.Unit
			else
				wallSlide = camRight
			end
			local wallUp = hitNorm:Cross(wallSlide).Unit

			local normPush = hitNorm * 0.22

			local priorityDirs: { Vector3 } = {
				(wallSlide + normPush).Unit,
				(-wallSlide + normPush).Unit,
				(wallUp + normPush).Unit,
				(wallSlide + wallUp * 0.7 + normPush).Unit,
				(-wallSlide + wallUp * 0.7 + normPush).Unit,

				(camRight + normPush * 0.4).Unit,
				(-camRight + normPush * 0.4).Unit,
				(camUp + normPush * 0.4).Unit,
				(camRight + camUp * 0.7 + normPush * 0.4).Unit,
				(-camRight + camUp * 0.7 + normPush * 0.4).Unit,
				(camRight * 0.8 + hitNorm * 0.5).Unit,
				(-camRight * 0.8 + hitNorm * 0.5).Unit,
			}

			local block = obstruction.Instance
			if block and block:IsA("BasePart") and not block:IsA("Terrain") then
				local bcf = block.CFrame
				local locHit = bcf:PointToObjectSpace(obstruction.Position)
				local sx = if locHit.X >= 0 then 1 else -1
				local sy = if locHit.Y >= 0 then 1 else -1
				local sz = if locHit.Z >= 0 then 1 else -1

				table.insert(priorityDirs, (bcf:VectorToWorldSpace(Vector3.new(sx, 0, 0)) + normPush).Unit)
				table.insert(priorityDirs, (bcf:VectorToWorldSpace(Vector3.new(0, sy, 0)) + normPush).Unit)
				table.insert(priorityDirs, (bcf:VectorToWorldSpace(Vector3.new(0, 0, sz)) + normPush).Unit)
				table.insert(priorityDirs, (bcf:VectorToWorldSpace(Vector3.new(sx, sy, 0)) + normPush).Unit)
				table.insert(priorityDirs, (bcf:VectorToWorldSpace(Vector3.new(-sx, sy, 0)) + normPush).Unit)
			end

			for _, dir in priorityDirs do
				local rawCand = eye + dir * safeR
				local candOrigin = clampToCharacterSphere(rawCand, eye, charRef, safeR)
				local origin, shifted = manipAccept(candOrigin, eye, goal, cf, charRef, alt1, alt2, alt3)
				if origin then
					manip.refreshed = now
					manip.reason = "adaptive"
					return origin, shifted
				end

				if manip.rays < manip.budget then
					local candMed = clampToCharacterSphere(eye + dir * (safeR * 0.55), eye, charRef, safeR)
					local originMed, shiftedMed = manipAccept(candMed, eye, goal, cf, charRef, alt1, alt2, alt3)
					if originMed then
						manip.refreshed = now
						manip.reason = "adaptive"
						return originMed, shiftedMed
					end
				end

				if manip.rays >= manip.budget then
					break
				end
			end

			local function trySamples(limit: number): (Vector3?, boolean?)
				local count = 0
				local nDirs = #kManipulationUnitDirs
				while manip.rays < limit and count < nDirs do
					local unitDir = kManipulationUnitDirs[manip.cursor]
					manip.cursor = manip.cursor % nDirs + 1
					count += 1
					manip.prepared += 1
					local candOrigin = clampToCharacterSphere(eye + unitDir * safeR, eye, charRef, safeR)
					local origin, shifted = manipAccept(candOrigin, eye, goal, cf, charRef, alt1, alt2, alt3)
					if origin then
						manip.refreshed = now
						return origin, shifted
					end
					if manip.rays < limit then
						candOrigin = clampToCharacterSphere(eye + unitDir * (safeR * 0.60), eye, charRef, safeR)
						origin, shifted = manipAccept(candOrigin, eye, goal, cf, charRef, alt1, alt2, alt3)
						if origin then
							manip.refreshed = now
							return origin, shifted
						end
					end
				end
				return nil, nil
			end
			local prepared, preparedShift = trySamples(math.min(manip.budget, kManipulationPrepareBudget))
			if prepared then
				return prepared, preparedShift
			end
			if manip.rays < manip.budget then
				local origin, shifted = trySamples(manip.budget)
				if origin then
					return origin, shifted
				end
			end
			manip.reason = if manip.rays >= manip.budget then "budget" else "blocked"
			return nil, nil
		end

		local function silentEquippedContext(): (any, Instance?, Instance?)
			local fighter = select(1, combatControllers())
			local localFighter = fighter and fighter.LocalFighter
			local item = localFighter and (localFighter.EquippedItem or (type(localFighter.Get) == "function" and localFighter:Get("EquippedItem")))
			local char = Players.LocalPlayer and Players.LocalPlayer.Character
			local vms = Workspace:FindFirstChild("ViewModels")
			return item, char, vms
		end

		local ManipLive = {
			body = "no target",
			name = nil :: string?,
			hittable = false,
		}

		local function resolveManipulatedOrigin(part: BasePart?, fallback: Vector3, goalPoint: Vector3?): Vector3
			local manipActive = Silent.manipulation == true
			if not manipActive or not part then
				ManipLive.body = if part then (silentOwnerName(part) or "target") .. " hittable" else "no target"
				ManipLive.name = silentOwnerName(part)
				ManipLive.hittable = part ~= nil
				return fallback
			end
			local item, char, vms = silentEquippedContext()
			local origin = manipSolve(Workspace.CurrentCamera, part, item, char, vms, goalPoint)
			local name = silentOwnerName(part)
			ManipLive.name = name
			if origin then
				ManipLive.hittable = true
				ManipLive.body = (name or "target") .. " hittable"
				return origin
			end
			ManipLive.hittable = false
			if name then
				ManipLive.body = name .. " blocked"
			else
				ManipLive.body = "no target"
			end
			return fallback
		end

		local manipPrefixDraw: any = nil
		local manipBodyDraw: any = nil
		pcall(function()
			local DrawingLib = Drawing
			if not DrawingLib then
				local env = fsGetgenv and fsGetgenv()
				DrawingLib = env and env.Drawing
			end
			if not DrawingLib then
				return
			end
			local function makeText()
				local draw = DrawingLib.new("Text")
				pcall(function()
					local fonts = DrawingLib.Fonts
					draw.Font = fonts and (fonts.Plex or fonts.UI or fonts.System or fonts.Monospace)
				end)
				draw.Size = 13
				draw.Center = false
				pcall(function()
					draw.Outline = true
					draw.OutlineColor = Color3.new(0, 0, 0)
				end)
				draw.Transparency = 1
				draw.Visible = false
				draw.ZIndex = 2
				draw.Text = ""
				return draw
			end
			manipPrefixDraw = makeText()
			manipBodyDraw = makeText()
		end)
		table.insert(ears, {
			Disconnect = function()
				for _, draw in { manipPrefixDraw, manipBodyDraw } do
					if draw then
						pcall(function()
							draw.Visible = false
							if type(draw.Remove) == "function" then
								draw:Remove()
							end
						end)
					end
				end
			end,
		} :: any)

		local function paintManipStatus()
			if not manipPrefixDraw or not manipBodyDraw then
				return
			end
			local show = Silent.enabled == true
				and Silent.manipulation == true
				and Silent.manipStatus == true
				and isInGameMatch()
			if not show then
				if manipPrefixDraw.Visible then manipPrefixDraw.Visible = false end
				if manipBodyDraw.Visible then manipBodyDraw.Visible = false end
				return
			end
			local shown = ManipLive.body or "no target"
			local cam = Workspace.CurrentCamera
			local vp = cam and cam.ViewportSize or Vector2.new(1920, 1080)
			local cx = math.floor(vp.X * 0.5 + 0.5)
			local cy = math.floor(vp.Y * 0.5 + 0.5)
			local y = cy + Rage.visualizerY + 16
			local x1 = cx - 110
			if manipPrefixDraw.Text ~= "manipulation: " then
				manipPrefixDraw.Text = "manipulation: "
			end
			if manipPrefixDraw._x ~= x1 or manipPrefixDraw._y ~= y then
				manipPrefixDraw._x = x1
				manipPrefixDraw._y = y
				manipPrefixDraw.Position = Vector2.new(x1, y)
			end
			local fontObj
			pcall(function()
				local fonts = Drawing and Drawing.Fonts
				if type(fonts) ~= "table" then
					return
				end
				local key = tostring(Silent.manipFont or "Plex")
				fontObj = fonts[key] or fonts[string.gsub(key, "%s+", "")] or fonts.Plex or fonts.UI or fonts.System or fonts.Monospace
			end)
			if fontObj ~= nil and manipPrefixDraw.Font ~= fontObj then
				pcall(function()
					manipPrefixDraw.Font = fontObj
					manipBodyDraw.Font = fontObj
				end)
			end
			local textCol = if typeof(Silent.manipText) == "Color3" then Silent.manipText else Color3.fromRGB(235, 163, 255)
			if manipPrefixDraw.Color ~= textCol then
				manipPrefixDraw.Color = textCol
			end
			if not manipPrefixDraw.Visible then
				manipPrefixDraw.Visible = true
			end
			if manipBodyDraw.Text ~= shown then
				manipBodyDraw.Text = shown
			end
			local bCol: Color3
			if ManipLive.hittable then
				bCol = if typeof(Silent.manipHit) == "Color3" then Silent.manipHit else Color3.fromRGB(0, 255, 60)
			elseif ManipLive.name then
				bCol = if typeof(Silent.manipBlock) == "Color3" then Silent.manipBlock else Color3.fromRGB(255, 20, 20)
			else
				bCol = Color3.fromRGB(180, 180, 180)
			end
			if manipBodyDraw.Color ~= bCol then
				manipBodyDraw.Color = bCol
			end
			local x2 = x1 + (manipPrefixDraw.TextBounds and manipPrefixDraw.TextBounds.X or 80)
			if manipBodyDraw._x ~= x2 or manipBodyDraw._y ~= y then
				manipBodyDraw._x = x2
				manipBodyDraw._y = y
				manipBodyDraw.Position = Vector2.new(x2, y)
			end
			if not manipBodyDraw.Visible then
				manipBodyDraw.Visible = true
			end
		end

		table.insert(ears, RunService.RenderStepped:Connect(function(dt: number)
			if DrawingBridge.library and DrawingBridge.library.uiDragging then
				return
			end
			local cam = Workspace.CurrentCamera
			if not cam then
				aimRing.Visible = false
				silentRing.Visible = false
				return
			end
			refreshWeaponProfile()
			local inGame = isInGameMatch()
			local screenCenter = cam.ViewportSize * 0.5
			local manipActive = Silent.manipulation == true
			if Silent.enabled then
				local lock = silentTarget()
				if manipActive then
					if lock then
						local camPos = cam.CFrame.Position
						local goal = select(2, silentShotPart(lock))
						resolveManipulatedOrigin(lock, camPos, goal)
					else
						ManipLive.body = "no target"
						ManipLive.hittable = false
					end
				else
					ManipLive.body = if lock then (silentOwnerName(lock) or "target") .. " hittable" else "no target"
					ManipLive.hittable = lock ~= nil
				end
			else
				silentStickyPart = nil
				ManipLive.body = "no target"
				ManipLive.hittable = false
			end
			paintManipStatus()
			local showAimFov = inGame and Aim.enabled and Aim.drawFov
			local showSilentFov = inGame and Silent.enabled and Silent.drawFov
			if not showAimFov and not showSilentFov then
				aimRing.Visible = false
				silentRing.Visible = false
			else
				local rageFovScreen = rageTargetFovScreen(cam)
				local aimOriginTarget = rageFovScreen or resolveFovOriginScreen(Aim.fovOrigin, cam, aimStickyPart)
				local silentOriginTarget = rageFovScreen or resolveFovOriginScreen(Silent.fovOrigin, cam, silentStickyPart)
				local aimOnTarget = rageFovScreen ~= nil or Aim.fovOrigin == "Target"
				local silentOnTarget = rageFovScreen ~= nil or Silent.fovOrigin == "Target"
				aimFovDrawPos = tweenFovPos(aimFovDrawPos, aimOriginTarget, dt, if aimOnTarget then 16 else 22)
				silentFovDrawPos = tweenFovPos(silentFovDrawPos, silentOriginTarget, dt, if silentOnTarget then 16 else 22)
				local effectiveAimRadius = computeEffectiveFov(resolvedAimFov, Aim.dynamicFov, cam)
				local effectiveSilentRadius = computeEffectiveFov(resolvedSilentFov, false, cam)
				aimFovDrawRadius = tweenFovRadius(aimFovDrawRadius, math.max(2, effectiveAimRadius * 2), dt)
				silentFovDrawRadius = tweenFovRadius(silentFovDrawRadius, math.max(2, effectiveSilentRadius * 2), dt)
				local aimDraw = aimFovDrawPos or screenCenter
				local silentDraw = silentFovDrawPos or screenCenter
				aimRing.Position = UDim2.fromOffset(aimDraw.X, aimDraw.Y)
				silentRing.Position = UDim2.fromOffset(silentDraw.X, silentDraw.Y)
				local rAim = aimFovDrawRadius or 2
				local rSilent = silentFovDrawRadius or 2
				aimRing.Size = UDim2.fromOffset(rAim, rAim)
				silentRing.Size = UDim2.fromOffset(rSilent, rSilent)
				aimRing.Visible = showAimFov
				silentRing.Visible = showSilentFov
				local aimOp = math.clamp(Aim.fovOpacity, 0, 1)
				local silentOp = math.clamp(Silent.fovOpacity, 0, 1)
				aimRing.BackgroundTransparency = 1 - aimOp
				silentRing.BackgroundTransparency = 1 - silentOp
				aimStroke.Transparency = 0
				silentStroke.Transparency = 0
				aimStroke.Thickness = math.clamp(Aim.fovThickness or 1.5, 0.5, 12)
				silentStroke.Thickness = math.clamp(Silent.fovThickness or 1.5, 0.5, 12)
				paintFovGradient(aimFillGrad, aimStrokeGrad, Aim.fovColor1, Aim.fovColor2)
				paintFovGradient(silentFillGrad, silentStrokeGrad, Silent.fovColor1, Silent.fovColor2)
				local spinBoth = Aim.spinFov or Silent.spinFov
				if spinBoth then
					local aimSpin = math.clamp(Aim.spinSpeed, 0, 720) * dt
					local silentSpin = math.clamp(Silent.spinSpeed, 0, 720) * dt
					if Aim.spinFov and aimRing.Visible then
						aimFillGrad.Rotation = (aimFillGrad.Rotation + aimSpin) % 360
						aimStrokeGrad.Rotation = aimFillGrad.Rotation
					end
					if Silent.spinFov and silentRing.Visible then
						silentFillGrad.Rotation = (silentFillGrad.Rotation + silentSpin) % 360
						silentStrokeGrad.Rotation = silentFillGrad.Rotation
					end
				end
			end

			if inGame and Aim.enabled and aimHeld and type(moveMouse) == "function" then
				local part = resolveStickyAimTarget()
				if part and os.clock() >= aimReadyAt then
					local now = os.clock()
					local worldPos = part.Position
					if aimPredPart ~= part or not aimPredPos then
						aimPredPart = part
						aimPredPos = worldPos
						aimPredVel = Vector3.zero
						aimPredAt = now
					else
						local sampleDt = math.max(now - aimPredAt, 1 / 240)
						local rawVel = (worldPos - aimPredPos) / sampleDt
						local blend = math.clamp(sampleDt * 14, 0.08, 1)
						aimPredVel = aimPredVel:Lerp(rawVel, blend)
						aimPredPos = worldPos
						aimPredAt = now
					end
					if Aim.prediction then
						local amount = math.clamp(resolvedPredAmt, 0, 100) / 100
						local speed = aimPredVel.Magnitude
						local lookAhead = (0.02 + amount * 0.22) * (1 + math.clamp(speed / 40, 0, 1.2) * (0.2 + amount * 0.45))
						worldPos = worldPos + aimPredVel * lookAhead
					end
					local sp = cam:WorldToViewportPoint(worldPos)
					if sp.Z > 0 then
						local dx = sp.X - screenCenter.X
						local dy = sp.Y - screenCenter.Y
						local dist = math.sqrt(dx * dx + dy * dy)
						local deadzone = math.clamp(resolvedDeadzone, 0, 100)
						if dist > deadzone then
							local vamp = math.clamp(resolvedVamp, 0, 100) / 100
							local smooth = math.clamp(resolvedSmooth, 0, 40)
							local overshoot = dist - deadzone
							local edge = math.clamp(overshoot / math.max(deadzone * 0.35 + 8, 1), 0, 1)
							local edgeEase = edge * edge * (3 - 2 * edge)
							local mx = 0
							local my = 0
							local t = smooth / 40
							local snap = (1 - t) ^ 2.6
							local lag = t ^ 1.25
							if smooth <= 0.05 then
								local flick = 0.88 + 0.12 * edgeEase
								mx = dx * flick
								my = dy * flick
								aimVelX = mx
								aimVelY = my
							else
								local response = 10 + snap * 72 + (1 - lag) * 18
								response *= (1 - vamp * 0.55)
								local alpha = 1 - math.exp(-math.max(dt, 1 / 240) * response)
								alpha = math.clamp(alpha * (0.22 + 0.78 * edgeEase), 0.002, 1)
								local desiredX = dx * alpha
								local desiredY = dy * alpha
								local damp = math.clamp(0.22 + snap * 0.72 - vamp * 0.12, 0.12, 0.96)
								aimVelX += (desiredX - aimVelX) * damp
								aimVelY += (desiredY - aimVelY) * damp
								local settle = math.clamp(0.15 + lag * 0.55, 0.15, 0.75)
								mx = aimVelX * (1 - settle * 0.08) + desiredX * (settle * 0.08)
								my = aimVelY * (1 - settle * 0.08) + desiredY * (settle * 0.08)
							end
							local human = math.clamp(resolvedHumanize, 0, 100) / 100 * (1 - vamp * 0.9) * edgeEase * (0.35 + 0.65 * lag)
							local jx = 0
							local jy = 0
							if human > 0.001 then
								jx = (math.random() - 0.5) * human * 9
								jy = (math.random() - 0.5) * human * 9
								if math.random() < 0.1 * human then
									jx += (math.random() - 0.5) * human * 5
									jy += (math.random() - 0.5) * human * 5
								end
							end
							pcall(moveMouse, mx + jx, my + jy)
						else
							local decay = math.clamp(0.35 + (1 - math.clamp(resolvedSmooth, 0, 40) / 40) * 0.4, 0.35, 0.9)
							aimVelX *= (1 - decay)
							aimVelY *= (1 - decay)
						end
					end
				end
			elseif not aimHeld then
				aimStickyPart = nil
				aimVelX = 0
				aimVelY = 0
				aimPredPos = nil
				aimPredVel = Vector3.zero
				aimPredPart = nil
			end
			local ragePart = RageLive.hitPart
			if (not ragePart or not ragePart.Parent) and RageLive.targetPlayer then
				local ch = RageLive.targetPlayer.Character
				ragePart = ch and (ch:FindFirstChild("Head") or ch:FindFirstChild("HumanoidRootPart"))
			end
			local followPart = ragePart or silentStickyPart or aimStickyPart
			DrawingBridge.hudAimRage = ragePart ~= nil and ragePart.Parent ~= nil
			if followPart and followPart.Parent then
				local sp, onScreen = cam:WorldToViewportPoint(followPart.Position)
				DrawingBridge.hudAim = if onScreen and sp.Z > 0 then Vector2.new(sp.X, sp.Y) else nil
			else
				DrawingBridge.hudAim = nil
			end
		end))

		local hooked = false
		local raycastHooked = false
		local function installSilent()
			if hooked and raycastHooked then
				return
			end
			local hookfunction = execApi("hookfunction")
			local newcclosure = execApi("newcclosure") or function(fn)
				return fn
			end
			if typeof(hookfunction) ~= "function" then
				return
			end
			local lp = Players.LocalPlayer
			if not lp then
				return
			end
			local okGun, gun = pcall(function()
				return require(lp.PlayerScripts.Modules.ItemTypes.Gun)
			end)
			if okGun and type(gun) == "table" and gun.IsFullyAiming then
				pcall(function()
					gun.IsFullyAiming = function()
						return true
					end
				end)
			end
			local U, EL, GU
			pcall(function()
				U = require(ReplicatedStorage.Modules.Utility)
				EL = require(ReplicatedStorage.Modules.EnumLibrary)
				GU = require(ReplicatedStorage.Modules.GameplayUtility)
			end)

			local function redirectSilentShot(origin: Vector3): (Vector3, BasePart?, Vector3?)
				local t = silentTarget()
				if not t then
					return origin, nil, nil
				end
				local hitPart, point = silentShotPart(t)
				origin = resolveManipulatedOrigin(t, origin, point)
				return origin, hitPart, point
			end

			if not raycastHooked and GU and type(GU.GetEntitiesFromRaycast) == "function" then
				local visual = GU.GetEntitiesFromRaycast
				GU.GetEntitiesFromRaycast = function(self, envID, params, origin, dir, maxDist, ...)
					if Silent.enabled then
						local newOrigin, hitPart, point = redirectSilentShot(origin)
						if hitPart and point then
							origin = newOrigin
							local delta = point - origin
							local dist = delta.Magnitude
							if dist > 0.01 then
								dir = delta.Unit
								if type(maxDist) == "number" and dist > maxDist then
									maxDist = dist + 5
								end
							end
						end
					end
					return visual(self, envID, params, origin, dir, maxDist, ...)
				end
				table.insert(ears, {
					Disconnect = function()
						GU.GetEntitiesFromRaycast = visual
					end,
				} :: any)
				raycastHooked = true
			end

			if hooked or not (U and EL) then
				return
			end

			local SK0, SK1, SK2, SK3 = utf8.char(0), utf8.char(1), utf8.char(2), utf8.char(3)
			local function silentCameraData(origin: Vector3, hitPart: BasePart, point: Vector3, original: any): any
				local aim = U:EncodeCFrame(CFrame.lookAt(origin, point))
				local data: any = {}
				if type(original) == "table" then
					for key, value in original do
						if key ~= SK1 then
							data[key] = value
						end
					end
				end
				data[SK1] = {
					[SK0] = aim,
					[SK1] = aim,
					[SK2] = hitPart,
					[SK3] = U:EncodeCFrame(hitPart.CFrame:ToObjectSpace(CFrame.new(point))),
				}
				return data
			end

			local startEnum
			pcall(function()
				startEnum = EL:ToEnum("StartShooting")
			end)
			local function isStartShooting(enumVal: any): boolean
				if startEnum ~= nil and enumVal == startEnum then
					return true
				end
				if type(enumVal) == "table" then
					local kind = enumVal.Type or enumVal.Name or enumVal.Enum
					if kind == "StartShooting" or kind == startEnum then
						return true
					end
				end
				if type(enumVal) == "string" and string.find(enumVal, "StartShooting", 1, true) then
					return true
				end
				return false
			end

			local function rewriteShot(camdata: any): any
				if not (SESSION.alive and Silent.enabled) then
					return camdata
				end
				local cam = Workspace.CurrentCamera
				if not cam then
					return camdata
				end
				local origin, hitPart, point = redirectSilentShot(cam.CFrame.Position)
				if hitPart and point then
					return silentCameraData(origin, hitPart, point, camdata)
				end
				return camdata
			end

			local remotes = ReplicatedStorage:FindFirstChild("Remotes")
			local replication = remotes and remotes:FindFirstChild("Replication")
			local fighterFolder = replication and replication:FindFirstChild("Fighter")
			local useItem = fighterFolder and fighterFolder:FindFirstChild("UseItem")
			if not useItem then
				return
			end

			if useItem:IsA("RemoteEvent") then
				local hook
				hook = hookfunction(useItem.FireServer, newcclosure(function(self, objID, enumVal, camdata, extra, ...)
					if isStartShooting(enumVal) then
						camdata = rewriteShot(camdata)
					end
					return hook(self, objID, enumVal, camdata, extra, ...)
				end))
				hooked = true
			elseif type((useItem :: any).InvokeServer) == "function" then
				local hook
				hook = hookfunction((useItem :: any).InvokeServer, newcclosure(function(self, objID, enumVal, camdata, extra, ...)
					if isStartShooting(enumVal) then
						camdata = rewriteShot(camdata)
					end
					return hook(self, objID, enumVal, camdata, extra, ...)
				end))
				hooked = true
			end
		end
		task.spawn(function()
			for _ = 1, 60 do
				installSilent()
				if hooked then
					break
				end
				task.wait(0.5)
			end
		end)

		local shotUtil: any = nil
		local shotEnum: any = nil
		local shotRemote: RemoteEvent? = nil
		local function shotApi(): (any, any, RemoteEvent?)
			if shotUtil and shotEnum and shotRemote and shotRemote.Parent then
				return shotUtil, shotEnum, shotRemote
			end
			local util, enumLib
			pcall(function()
				util = require(ReplicatedStorage.Modules.Utility)
				enumLib = require(ReplicatedStorage.Modules.EnumLibrary)
			end)
			local useItem = ReplicatedStorage:FindFirstChild("Remotes")
			useItem = useItem and useItem:FindFirstChild("Replication")
			useItem = useItem and useItem:FindFirstChild("Fighter")
			useItem = useItem and useItem:FindFirstChild("UseItem")
			if util and enumLib and useItem and useItem:IsA("RemoteEvent") then
				shotUtil = util
				shotEnum = enumLib
				shotRemote = useItem
			end
			return shotUtil, shotEnum, shotRemote
		end

		local function fireStartShot(part: BasePart?, finishShot: boolean?, aimAtPart: boolean?, useManip: boolean?)
			local util, enumLib, useItem = shotApi()
			if not (util and enumLib and useItem) then
				return
			end
			local fighter = select(1, combatControllers())
			local localFighter = fighter and fighter.LocalFighter
			local item = localFighter and (localFighter.EquippedItem or (type(localFighter.Get) == "function" and localFighter:Get("EquippedItem")))
			if not item then
				return
			end
			local cam = Workspace.CurrentCamera
			local lp = Players.LocalPlayer
			local root = lp and lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
			local origin = if cam then cam.CFrame.Position elseif root and root:IsA("BasePart") then root.Position else nil
			if not origin then
				return
			end
			local cameradata = {}
			if aimAtPart and part then
				local hitPart, hitPoint = silentShotPart(part)
				local targetPart = hitPart or part
				local aimPos = hitPoint or targetPart.Position
				if useManip or Silent.manipulation then
					local cand = resolveManipulatedOrigin(part, origin, aimPos)
					if cand and (cand - origin).Magnitude > 0.01 then
						origin = cand
					end
				end
				local encodedAim = util:EncodeCFrame(CFrame.lookAt(origin, aimPos))
				cameradata[utf8.char(1)] = {
					[utf8.char(0)] = encodedAim,
					[utf8.char(1)] = encodedAim,
					[utf8.char(2)] = targetPart,
					[utf8.char(3)] = util:EncodeCFrame(targetPart.CFrame:ToObjectSpace(CFrame.new(aimPos))),
				}
			else
				local lookCF = if cam then cam.CFrame else CFrame.new(origin, origin + Vector3.new(0, 0, -1))
				local encLook = util:EncodeCFrame(lookCF)
				cameradata[utf8.char(1)] = {
					[utf8.char(0)] = encLook,
					[utf8.char(1)] = encLook,
				}
			end
			local objectId
			local startEnum
			local stopEnum
			local reloadEnum
			pcall(function()
				objectId = item.ObjectID or (type(item.Get) == "function" and item:Get("ObjectID"))
				startEnum = enumLib:ToEnum("StartShooting")
				stopEnum = enumLib:ToEnum("StopShooting")
				reloadEnum = enumLib:ToEnum("Reload")
			end)
			if not (objectId and startEnum) then
				return
			end
			pcall(function()
				(useItem :: RemoteEvent):FireServer(objectId, startEnum, cameradata, nil)
			end)
			if finishShot then
				task.defer(function()
					if stopEnum then
						pcall(function()
							(useItem :: RemoteEvent):FireServer(objectId, stopEnum, cameradata, nil)
						end)
					end
					task.wait(0.03)
					if reloadEnum then
						pcall(function()
							(useItem :: RemoteEvent):FireServer(objectId, reloadEnum, nil, nil)
						end)
					end
					callAsGame(function()
						if type(item.Reload) == "function" then
							item:Reload()
						elseif type(item.StartReload) == "function" then
							item:StartReload()
						end
					end)
					callAsGame(function()
						if localFighter and type(localFighter.Reload) == "function" then
							localFighter:Reload()
						end
					end)
				end)
			end
		end

		do
			local lastFlickShot = 0
			local flickHeld = false
			local function flickKeyMatches(input: InputObject): boolean
				if Flick.keyName == "MouseButton1" then
					return input.UserInputType == Enum.UserInputType.MouseButton1
				elseif Flick.keyName == "MouseButton2" then
					return input.UserInputType == Enum.UserInputType.MouseButton2
				elseif Flick.keyName == "MouseButton3" then
					return input.UserInputType == Enum.UserInputType.MouseButton3
				end
				return input.KeyCode.Name == Flick.keyName
			end
			table.insert(ears, UserInputService.InputBegan:Connect(function(input: InputObject, processed: boolean)
				if processed then
					return
				end
				if flickKeyMatches(input) then
					flickHeld = true
				end
			end))
			table.insert(ears, UserInputService.InputEnded:Connect(function(input: InputObject)
				if flickKeyMatches(input) then
					flickHeld = false
				end
			end))

			local lmbDown = false
			local lastLmbClick = 0
			local function setLmb(down: boolean)
				local press = execApi("mouse1press")
				local release = execApi("mouse1release")
				if typeof(press) == "function" and typeof(release) == "function" then
					if down == lmbDown then
						return
					end
					lmbDown = down
					pcall(if down then press else release)
					return
				end
				if not down then
					lmbDown = false
					return
				end
				local now = os.clock()
				if now - lastLmbClick < 0.05 then
					return
				end
				lastLmbClick = now
				local click = execApi("mouse1click")
				if typeof(click) == "function" then
					pcall(click)
				end
			end

			table.insert(ears, RunService.Heartbeat:Connect(function(dt: number)
				if not Trigger.enabled then
					setLmb(false)
				end
				if not Trigger.enabled and not (Flick.enabled and flickHeld) then
					return
				end
				if not isInGameMatch() then
					setLmb(false)
					return
				end
				local cam = Workspace.CurrentCamera
				if not cam then
					return
				end

				if Trigger.enabled then
					local lib = DrawingBridge.library
					local menuOpen = lib and lib.open == true
					local targetPart = if menuOpen then nil else bestTarget(Trigger.fov, Trigger.hitboxes, Trigger.flags, false)
					setLmb(targetPart ~= nil)
				end

				if Flick.enabled and flickHeld and type(moveMouse) == "function" then
					local part = bestTarget(Flick.fov, Flick.hitboxes, Flick.flags, Flick.flags.visible == true)
					if part then
						local sp = cam:WorldToViewportPoint(part.Position)
						local center = cam.ViewportSize
						local dx = sp.X - center.X * 0.5
						local dy = sp.Y - center.Y * 0.5
						local speed = math.clamp(Flick.speed, 0.1, 10)
						if speed <= 0.15 then
							pcall(moveMouse, dx, dy)
						else
							local step = math.clamp((dt * 4.5) / speed, 0.02, 1)
							pcall(moveMouse, dx * step, dy * step)
						end
						if Flick.shoot and math.abs(dx) < 10 and math.abs(dy) < 10 then
							local now = os.clock()
							if now - lastFlickShot >= 0.05 then
								lastFlickShot = now
								fireStartShot(part, true, true)
							end
						end
					end
				end
			end))
		end

		end
		installLegitRuntime()
	end

		do
			local function installRagebotRuntime()
			local deflecting, lastFire, rageSession, activeSlot, voidPhaseStart, inVoidPhase, VOID_RADIUS, _voidOrbitT, _voidOrbitSeed, KNIFE_BEHIND_STUD
			local KNIFE_SETTLE, KNIFE_HOLD_AFTER, KNIFE_MANUAL_RANGE, knifePhase, knifeAttackAt, knifeVoidAt, knifeBehindCF, knifeFiredThisStab, burstLeft, burstNextAt
