			local getLocalFighter, setRagePhysics, clearServerReplica, hitscanStandCF, meleeStandCF, targetIsBelow, shouldFireEncoded, evadeCF, applyForcedCrouch, fireEncodedGun
			local fireEncodedMelee, refreshFrameContext, getHeldSlot, isKnifeWeapon, isMeleeWeapon, getConfiguredSlot, slotName, rageMayEquip, ensureWeaponEquipped, resetToMainWeapon
			local startRagebotEquip, setRageStatus, hideRageVisualizer, paintRageStatus, isOutOfAmmo, getUseItemRemote, handleNoAmmo, preferMainWeaponWithAmmo, findFloorUnder, resolveUndergroundAttackCF
			local updateVoidPhase, isDangerRagePos, isStandingInKillZone, desyncLocked, desyncRestoreBound, desyncRestoreCF, desyncShownCF, flushDesyncRestore, sameSpot, applyDesync, isRageV2
			do -- rage helpers
