			burstLeft = 0
			burstNextAt = 0
			cycleReadyAt = 0

			function shootAttempts(): number
				return math.clamp(math.floor(tonumber(Rage.shootAttempts) or 1), 1, 20)
			end

			function shootInterval(): number
				return math.clamp(tonumber(Rage.shootInterval) or 0.03, 0, 1)
			end

			function resetBurst()
				burstLeft = 0
				burstNextAt = 0
			end

			function consumeBurstShot(now: number, cycleCd: number, instant: boolean?): boolean
				local interval = if instant then 0 else shootInterval()
				if burstLeft > 0 then
					if now < burstNextAt then
						return false
					end
					burstLeft -= 1
					lastFire = now
					if burstLeft > 0 then
						burstNextAt = now + interval
					else
						cycleReadyAt = now + math.max(cycleCd, 0)
						burstNextAt = 0
					end
					return true
				end
				if now < cycleReadyAt then
					return false
				end
				burstLeft = shootAttempts() - 1
				lastFire = now
				if burstLeft > 0 then
					burstNextAt = now + interval
				else
					cycleReadyAt = now + math.max(cycleCd, 0)
					burstNextAt = 0
				end
				return true
			end

			function burstWaiting(now: number): boolean
				if burstLeft > 0 then
					return now < burstNextAt
				end
				return now < cycleReadyAt
			end
			frameFighterIndex= {}
			frameTeamOf= {}
