			local ENC_GUN_B_UP = { ["\0"] = 0, ["\1"] = -90000000, ["\2"] = 0, ["\3"] = -1.5707963267948966, ["\4"] = 3.141592653589793, ["\5"] = 3.141592653589793 }
			local ENC_GUN_A_DN = { ["\0"] = -9e37, ["\1"] = 0, ["\2"] = 0, ["\3"] = 1.5707963267948966, ["\4"] = 3.141592653589793, ["\5"] = 3.141592653589793 }
			local ENC_GUN_B_DN = { ["\0"] = 0, ["\1"] = 90000000, ["\2"] = 0, ["\3"] = 1.5707963267948966, ["\4"] = 3.141592653589793, ["\5"] = 3.141592653589793 }
