			local ENC_MEL_B_UP = { ["\0"] = 0, ["\1"] = -90000000, ["\2"] = 0, ["\3"] = -1.5707963267948966, ["\4"] = 3.141592653589793, ["\5"] = 3.141592653589793 }
			local ENC_MEL_A_DN = { ["\0"] = -9e37, ["\1"] = 0, ["\2"] = 0, ["\3"] = 1.5707963267948966, ["\4"] = 3.141592653589793, ["\5"] = 3.141592653589793 }
			local ENC_MEL_B_DN = { ["\0"] = 0, ["\1"] = 90000000, ["\2"] = 0, ["\3"] = 1.5707963267948966, ["\4"] = 3.141592653589793, ["\5"] = 3.141592653589793 }

			local function findCharacterController(fighter: any?): any?
				if cachedCharCtrl and type(cachedCharCtrl.SetServerCFrame) == "function" then
					return cachedCharCtrl
				end
				local seen: { any } = {}
				local function consider(obj: any)
					if obj == nil then
						return
					end
					table.insert(seen, obj)
				end
				if fighter then
					consider(fighter.CharacterController)
					consider(fighter.characterController)
					pcall(function()
						if type(fighter.Get) == "function" then
							consider(fighter:Get("CharacterController"))
						end
					end)
					local char = fighter.Character
					if type(char) == "table" then
						consider(char.Controller)
						consider(char.CharacterController)
					end
				end
				local fc = select(1, combatControllers())
				if fc then
					consider(fc.CharacterController)
					consider(fc.LocalCharacterController)
				end
				pcall(function()
					local lp = Players.LocalPlayer
					local scripts = lp and lp:FindFirstChild("PlayerScripts")
					local controllers = scripts and scripts:FindFirstChild("Controllers")
					local mod = controllers and controllers:FindFirstChild("CharacterController")
					if mod then
						consider(require(mod))
					end
				end)
				for _, obj in seen do
					if type(obj) == "table" and type(obj.SetServerCFrame) == "function" then
						cachedCharCtrl = obj
						return obj
					end
				end
				return nil
			end

			function setRagePhysics(on: boolean)
				if ragePhysicsOn == on then
					return
				end
				ragePhysicsOn = on
				pcall(function()
