					else
						workspace.FallenPartsDestroyHeight = if on then (0 / 0) else fallenHeightSaved
					end
				end)
				if type(setFlag) == "function" then
					pcall(setFlag, "DFIntS2PhysicsSenderRate", if on then "120" else "15")
					pcall(setFlag, "DFIntAssemblyHistoryBufferSize", if on then "2147483648" else "15")
					pcall(setFlag, "DFIntAssemblyHistorySkipSize", if on then "0" else "8")
				end
			end

