			end

			function clearServerReplica()
				setServerReplicaCF(nil, nil)
				lastServerCF = nil
			end
			DrawingBridge.clearRageServer = clearServerReplica

			local function lookAlongGround(from: Vector3, toward: Vector3): CFrame
				local flat = Vector3.new(toward.X - from.X, 0, toward.Z - from.Z)
				if flat.Magnitude < 0.001 then
					flat = Vector3.new(0, 0, -1)
				end
				return CFrame.lookAt(from, from + flat, Vector3.new(0, -1, 0))
			end

			function hitscanStandCF(hitbox: BasePart, below: boolean): CFrame
				local offset = if below then Vector3.new(0, -3.85, 0.05) else Vector3.new(0, -0.7, 0.05)
				local pos = hitbox.CFrame.Position + offset
				if below then
					return lookAlongGround(pos, hitbox.Position)
				end
				return hitbox.CFrame + offset
			end

			function meleeStandCF(hitbox: BasePart, below: boolean): CFrame
				local offset = if below then Vector3.new(0, -3.85, 0.05) else Vector3.new(0, -0.7, 0.05)
				local pos = hitbox.CFrame.Position + offset
				if below then
					return lookAlongGround(pos, hitbox.Position)
				end
				return hitbox.CFrame + offset
			end

			function targetIsBelow(targetRoot: BasePart, myPos: Vector3): boolean
				return targetRoot.Position.Y + 1.5 < myPos.Y
			end

			function shouldFireEncoded(inRange: boolean, dt: number): boolean
				local now = os.clock()
				local locked = shootLockedUntil > 0 and now < shootLockedUntil
				if inRange then
					shootLockedUntil = now + math.max(dt, 1 / 60) * math.clamp(tonumber(Rage.shootFrames) or 1, 1, 5)
				end
				return locked or inRange
			end

			local function withOrientation(src: { [string]: number }, pitch: number, yaw: number, roll: number): { [string]: number }
				return {
					["\0"] = src["\0"],
					["\1"] = src["\1"],
					["\2"] = src["\2"],
					["\3"] = pitch,
					["\4"] = yaw,
					["\5"] = roll,
				}
			end

			local function getImmuneCF(): CFrame
				local x = 1.34217728e8 + math.random() * 2e8
				local y = 400 + math.random() * 2e4
				local z = 1.34217728e8 + math.random() * 2e8
				return CFrame.new(x, y, z) * CFrame.Angles(math.random() * 6.28, math.random() * 6.28, math.random() * 6.28)
			end

			function isRageV2(): boolean
				return Rage.engine ~= "V1"
			end

			local function evasionSpin(pos: Vector3): CFrame
				return CFrame.new(pos) * CFrame.Angles(math.random() * 6.28, math.random() * 6.28, math.random() * 6.28)
			end

			function evadeCF(origin: Vector3, _hasTarget: boolean): CFrame?
				if Rage.evasionEnabled ~= true then
					return nil
				end
				local mode = tostring(Rage.evasion or "Scatter")
				if mode == "Off" then
					return nil
				end
				local radius = math.clamp(tonumber(Rage.evasionRadius) or 100, 5, 1e8)
				local jitter = math.clamp(tonumber(Rage.evasionRandom) or 0.5, 0, 1)
				for _ = 1, 14 do
					local pos: Vector3
					local ang = math.random() * math.pi * 2
					if mode == "Orbit" then
						local r = radius * (0.55 + 0.45 * math.random())
						pos = origin + Vector3.new(math.cos(ang) * r, 2 + math.random() * 5, math.sin(ang) * r)
					elseif mode == "Sky" then
						local r = 6 + math.random() * 16
						pos = origin + Vector3.new(math.cos(ang) * r, radius, math.sin(ang) * r)
					elseif mode == "Underground" then
						local depth = math.clamp(tonumber(Rage.translocateOffset) or -12, -80, -1)
						local r = 3 + math.random() * 12
						pos = origin + Vector3.new(math.cos(ang) * r, depth, math.sin(ang) * r)
					else
						local r = radius + radius * jitter * math.random()
						pos = Vector3.new(math.cos(ang) * r, origin.Y + (math.random() - 0.5) * 14, math.sin(ang) * r)
					end
					if not isDangerRagePos(pos) then
						return evasionSpin(pos)
					end
				end
				return nil
			end

			function applyForcedCrouch(on: boolean)
				local lp = Players.LocalPlayer
				local char = lp and lp.Character
				local hum = char and char:FindFirstChildOfClass("Humanoid")
				if hum then
					pcall(function()
						if on then
							hum:ChangeState(Enum.HumanoidStateType.Crouching)
						end
					end)
				end
				local fighter = getLocalFighter()
				if fighter and type(fighter.Set) == "function" then
					pcall(function()
						fighter:Set("IsCrouching", on)
					end)
				end
			end

			function fireEncodedGun(item: any, hitbox: BasePart, below: boolean): boolean
				if type(item.ShootEncoded) ~= "function" then
					return false
				end
				local a = if below then ENC_GUN_A_DN else ENC_GUN_A_UP
				local b = if below then ENC_GUN_B_DN else ENC_GUN_B_UP
				local ok = false
				callAsGame(function()
					item:ShootEncoded(a, b, hitbox, ENC_PELLET)
					ok = true
				end)
				return ok
			end

			function fireEncodedMelee(item: any, hitbox: BasePart, below: boolean, knife: boolean): boolean
				local pitch, yaw, roll = 0, 0, 0
				pcall(function()
					pitch, yaw, roll = hitbox.CFrame:ToOrientation()
				end)
				local n33 = if below then 1.5707963267948966 else -1.5707963267948966
				local srcA = if below then ENC_MEL_A_DN else ENC_MEL_A_UP
				local srcB = if below then ENC_MEL_B_DN else ENC_MEL_B_UP
				local a = withOrientation(srcA, n33, yaw, roll)
				local b = withOrientation(srcB, n33, yaw, roll)
				local now = os.clock()
				local ok = false
				if knife and type(item.HeavyAttackEncoded) == "function" then
					callAsGame(function()
						item:HeavyAttackEncoded(a, b, hitbox, ENC_PELLET)
						ok = true
					end)
					if ok then
						knifeHitboxUntil = now + 0.625
						knifeAttackCd = now + 1.25
					end
					return ok
				end
				if now < knifeHitboxUntil and type(item.HeavyAttackEncoded) == "function" then
					callAsGame(function()
						item:HeavyAttackEncoded(a, b, hitbox, ENC_PELLET)
						ok = true
					end)
					return ok
				end
				if type(item.AttackEncoded) == "function" then
					callAsGame(function()
						item:AttackEncoded(a, b, hitbox, ENC_PELLET)
						ok = true
					end)
				end
				return ok
			end

			local function slotEnabled(name: string): boolean
				if name == "Primary" or name == "Secondary" then
					return true
				end
				local flags = Rage.weaponsEnabled
				if type(flags) ~= "table" then
					return true
				end
				if flags[name] == nil then
					return true
				end
				return flags[name] == true
			end

			local function slotFromIndex(index: number): string?
				if index == 1 then
					return "Primary"
				elseif index == 2 then
					return "Secondary"
				elseif index == 3 then
					return "Melee"
				end
				return nil
			end

			getLocalFighter = function(): any?
				local fighter = select(1, combatControllers())
				return fighter and fighter.LocalFighter
			end

			local frameCtxAt = 0
			function refreshFrameContext(force: boolean?)
				local now = os.clock()
				if not force and now - frameCtxAt < 0.35 then
					return
				end
				frameCtxAt = now
				table.clear(frameFighterIndex)
				table.clear(frameTeamOf)
				frameLocalTeam = nil
				local fighter, _duel, spectate = combatControllers()
				pcall(function()
					if fighter and fighter.Objects then
						for _, obj in fighter.Objects do
							local p = obj.Player
							if p then
								frameFighterIndex[p] = obj
							end
						end
					end
				end)
				pcall(function()
					local duel = spectate and spectate.CurrentDuelSubject
					if duel and duel.Duelers then
						for _, dueler in duel.Duelers do
							if dueler.Player then
								frameTeamOf[dueler.Player] = dueler:Get("TeamID")
							end
						end
					end
					local lp = Players.LocalPlayer
					if lp then
						frameLocalTeam = frameTeamOf[lp]
					end
				end)
			end

			function getHeldSlot(localFighter: any?): number?
				local fighterObj = localFighter or getLocalFighter()
				if not fighterObj then
					return nil
				end
				local held, items = nil, nil
				pcall(function()
					held = fighterObj.EquippedItem
					items = fighterObj.Items
				end)
				if held == nil or type(items) ~= "table" then
					return nil
				end
				for index, item in items do
					if item == held then
						return if type(index) == "number" then index else nil
					end
				end
				return nil
			end

			function isKnifeWeapon(): boolean
				return Rage.weaponSlot == "Knife" or Rage.mode == "Knife"
			end

			function isMeleeWeapon(): boolean
				return Rage.weaponSlot == "Melee"
			end

			function getConfiguredSlot(): number
				if isKnifeWeapon() or isMeleeWeapon() then
					return 3
				end
				local priority = Rage.weaponPriority
				if type(priority) == "table" then
					for _, name in priority do
						if slotEnabled(tostring(name)) then
							if name == "Melee" then
								return 3
							end
							return RAGE_SLOT_NUMBERS[name] or 1
						end
					end
				end
				if slotEnabled(Rage.weaponSlot) then
					return RAGE_SLOT_NUMBERS[Rage.weaponSlot] or 1
				end
				return 1
			end

			local lastConfiguredMode = Rage.mode
			local function syncActiveSlot()
				if Rage.weaponSlot ~= lastConfiguredSlot or Rage.mode ~= lastConfiguredMode then
					lastConfiguredSlot = Rage.weaponSlot
					lastConfiguredMode = Rage.mode
					activeSlot = getConfiguredSlot()
				end
				if isKnifeWeapon() or isMeleeWeapon() then
					activeSlot = 3
				end
			end

			local function getSlotNumber(): number
				syncActiveSlot()
				return activeSlot
			end

			function slotName(slot: number): string
				if slot == 1 then
					return "primary"
				elseif slot == 2 then
					return "secondary"
				elseif slot == 3 then
					return if isKnifeWeapon() then "knife" else "melee"
				elseif slot == 4 then
					return "utility"
				end
				return "held"
			end

			function rageMayEquip(): boolean
				return Rage.enabled == true
			end

			local lastEquipCall = 0
			local function equipSlot(localFighter: any?, slot: number, force: boolean?)
				if not rageMayEquip() or slot < 1 then
					return
				end
				local fighterObj = localFighter or getLocalFighter()
				if not fighterObj then
					return
				end
				if getHeldSlot(fighterObj) == slot then
					return
				end
				local now = os.clock()
				if not force and now - lastEquipCall < 0.4 then
					return
				end
				lastEquipCall = now
				local session = rageSession
				callAsGame(function()
					if rageMayEquip() and session == rageSession then
						fighterObj:EquipItem(slot)
					end
				end)
			end

			function ensureWeaponEquipped(force: boolean?)
				activeSlot = getSlotNumber()
				equipSlot(nil, activeSlot, force)
			end

			function resetToMainWeapon(localFighter: any?)
				activeSlot = getConfiguredSlot()
				equipSlot(localFighter, activeSlot, true)
			end

			function startRagebotEquip()
				if not rageMayEquip() then
					return
				end
				syncActiveSlot()
				activeSlot = getConfiguredSlot()
				ensureWeaponEquipped(true)
			end
			DrawingBridge.startRagebotEquip = startRagebotEquip

			local function readPlayerHealth(player: Player?): number?
				if not player then
					return nil
				end
				local char = player.Character
				if not char then
					return nil
				end
				local hum = char:FindFirstChildOfClass("Humanoid")
				if hum and hum:IsA("Humanoid") then
					return math.max(0, math.floor(hum.Health + 0.5))
				end
				return nil
			end

			local function rageStatusVerb(step: string, targetName: string?): string
				local s = string.lower(step or "")
				if not Rage.enabled then
					return "off"
				end
				if not isInGameMatch() or s == "waiting match" then
					return "chilling"
				end
				if s == "scanning" then
					return "scanning"
				end
				if string.find(s, "restart", 1, true) then
					return "restarting"
				end
				if string.find(s, "equip", 1, true) then
					return "equipping"
				end
				if s == "spawn grace" then
					if targetName and targetName ~= "" then
						return "waiting on " .. targetName
					end
					return "waiting"
				end
				if s == "waiting safe" then
					return "waiting safe"
				end
				if s == "skip deflect" or s == "skip invincible" then
					if targetName and targetName ~= "" then
						return "skipping " .. targetName
					end
					return "skipping"
				end
				if s == "no root" or s == "no fighter" then
					return "searching"
				end
				if string.find(s, "reload", 1, true) or string.find(s, "force reload", 1, true) then
					return "reloading"
				end
				if string.find(s, "switch", 1, true) then
					return "switching"
				end
				if string.find(s, "knife", 1, true) then
					return "knifing"
				end
				if string.find(s, "void break", 1, true) then
					return "breaking"
				end
				if targetName and targetName ~= "" then
					return "killing"
				end
				return "scanning"
			end

			local function buildRageStatusBody(includeDots: boolean): string
				local verb = rageStatusVerb(RageLive.step, RageLive.target)
				local body: string
				if verb == "killing" and RageLive.target and RageLive.target ~= "" then
					local hp = RageLive.health
					if hp == nil then
						hp = readPlayerHealth(RageLive.targetPlayer)
						RageLive.health = hp
					end
					local hpText = if typeof(hp) == "number" then tostring(hp) else "?"
					body = string.format("killing %s ( %s Health Remaining )", RageLive.target, hpText)
				elseif verb == "knifing" and RageLive.target and RageLive.target ~= "" then
					local hp = RageLive.health or readPlayerHealth(RageLive.targetPlayer)
					RageLive.health = hp
					local hpText = if typeof(hp) == "number" then tostring(hp) else "?"
					body = string.format("knifing %s ( %s Health Remaining )", RageLive.target, hpText)
					local knifeIn = RageLive.knifeIn
					if typeof(knifeIn) == "number" then
						body ..= if knifeIn > 0.005 then string.format(" - next stab %.2fs", knifeIn) else " - stabbing"
					end
				elseif verb == "breaking" and RageLive.target and RageLive.target ~= "" then
					local hp = RageLive.health or readPlayerHealth(RageLive.targetPlayer)
					RageLive.health = hp
					local hpText = if typeof(hp) == "number" then tostring(hp) else "?"
					body = string.format("breaking %s ( %s Health Remaining )", RageLive.target, hpText)
				else
					body = verb
				end
				return body
			end

			local function buildRageStatusDisplay(): string
				return buildRageStatusBody(false)
			end

			local lastStatusKey = ""
			function setRageStatus(step: string, targetName: string?, targetPlayer: Player?)
				local health = readPlayerHealth(targetPlayer)
				local key = tostring(step) .. "|" .. tostring(targetName) .. "|" .. tostring(health)
				if key == lastStatusKey and RageLive.targetPlayer == targetPlayer then
					return
				end
				lastStatusKey = key
				RageLive.step = step
				RageLive.target = targetName
				RageLive.targetPlayer = targetPlayer
				RageLive.health = health
				RageLive.prefix = "ragebot: "
				RageLive.body = buildRageStatusBody(false)
				RageLive.text = RageLive.prefix .. RageLive.body
			end

			local AMMO_KEYS = { "Ammo", "MagazineAmmo", "ClipAmmo", "CurrentAmmo", "Bullets", "Rounds" }
			local function readItemAmmo(item: any): number?
				if item == nil then
					return nil
				end
				local keys = AMMO_KEYS
				for _, key in keys do
					local ok, value = pcall(function()
						if type(item.Get) == "function" then
							return item:Get(key)
						end
						return nil
					end)
					if ok and typeof(value) == "number" then
						return value
					end
					local okField, field = pcall(function()
						return (item :: any)[key]
					end)
					if okField and typeof(field) == "number" then
						return field
					end
				end
				local okStats, stats = pcall(function()
					if type(item.Get) == "function" then
						return item:Get("Stats")
					end
					return (item :: any).Stats
				end)
				if okStats and type(stats) == "table" then
					for _, key in keys do
						local value = stats[key]
						if typeof(value) == "number" then
							return value
						end
					end
				end
				return nil
			end

			local function rageAmmoText(): string?
				local fighter = getLocalFighter()
				local item = fighter and fighter.EquippedItem
				if item == nil and fighter and type(fighter.Get) == "function" then
					pcall(function()
						item = fighter:Get("EquippedItem")
					end)
				end
				local ammo = readItemAmmo(item)
				if typeof(ammo) ~= "number" then
					return nil
				end
				return tostring(math.max(0, math.floor(ammo)))
			end

			local rageAmmoMuzzle: Instance? = nil
			local rageAmmoMuzzleAt = 0
			local function rageMuzzleScreen(cam: Camera): Vector2?
				local now = os.clock()
				if not (rageAmmoMuzzle and rageAmmoMuzzle.Parent) or now - rageAmmoMuzzleAt >= 0.55 then
					rageAmmoMuzzleAt = now
					rageAmmoMuzzle = nil
					local function scan(root: Instance?): Instance?
						return root and root:FindFirstChild("_muzzle", true) or nil
					end
					if cam then
						for _, child in cam:GetChildren() do
							local found = scan(child)
							if found then
								rageAmmoMuzzle = found
								break
							end
						end
					end
					if not rageAmmoMuzzle then
						local vms = Workspace:FindFirstChild("ViewModels")
						rageAmmoMuzzle = scan(vms)
					end
				end
				local m = rageAmmoMuzzle
				if not m then
					return nil
				end
				local world: Vector3? = nil
				if m:IsA("Attachment") then
					world = m.WorldPosition
				elseif m:IsA("BasePart") then
					world = m.Position
				elseif m.Parent and m.Parent:IsA("BasePart") then
					world = (m.Parent :: BasePart).Position
				end
				if not world then
					return nil
				end
				local sp, onScreen = cam:WorldToViewportPoint(world)
				if not onScreen or sp.Z <= 0 then
					return nil
				end
				return Vector2.new(sp.X, sp.Y)
			end

			local StatusDrawing: any = nil
			pcall(function()
				StatusDrawing = Drawing
			end)
			if not StatusDrawing then
				pcall(function()
					local env = fsGetgenv and fsGetgenv()
					if type(env) == "table" then
						StatusDrawing = env.Drawing
					end
				end)
			end
			local function newStatusText(): any?
				local make = DrawingBridge.newEspText
				if type(make) == "function" then
					local ok, draw = pcall(make)
					if ok and draw then
						draw.Font = "Plex"
						draw.Size = 13
						draw.Center = false
						draw.Outline = true
						draw.OutlineColor = Color3.new(0, 0, 0)
						draw.Transparency = 1
						draw.Visible = false
						draw.Text = ""
						return draw
					end
				end
				if not StatusDrawing then
					return nil
				end
				local ok, draw = pcall(function()
					return StatusDrawing.new("Text")
				end)
				if not ok or not draw then
					return nil
				end
				pcall(function()
					local fonts = StatusDrawing.Fonts
					draw.Font = fonts and (fonts.Plex or fonts.UI or fonts.System or fonts.Monospace)
				end)
				draw.Size = 13
				draw.Center = false
				pcall(function()
					draw.Outline = true
					draw.OutlineColor = Color3.new(0, 0, 0)
				end)
				draw.Transparency = 1
				draw.Visible = false
				draw.ZIndex = 2
				draw.Text = ""
				return draw
			end
			local statusPrefixDraw = newStatusText()
			local statusBodyDraw = newStatusText()
			local statusAmmoDraw = newStatusText()
			local visualizerLine: any = nil
			pcall(function()
				if StatusDrawing then
					visualizerLine = StatusDrawing.new("Line")
					visualizerLine.Visible = false
					visualizerLine.ZIndex = 3
					visualizerLine.Thickness = Rage.visualizerLineThick
					visualizerLine.Color = Rage.visualizerLineColor
					visualizerLine.Transparency = 1
				end
			end)
			table.insert(ears, {
				Disconnect = function()
					for _, draw in { statusPrefixDraw, statusBodyDraw, statusAmmoDraw, visualizerLine } do
						if draw then
							pcall(function()
								draw.Visible = false
								if type(draw.Remove) == "function" then
									draw:Remove()
								elseif type(draw.Destroy) == "function" then
									draw:Destroy()
								end
							end)
						end
					end
				end,
			} :: any)
			local lastRagePaintKey = ""
			local lastRagePaintAt = 0
			function hideRageVisualizer()
				if statusPrefixDraw then
					statusPrefixDraw.Visible = false
				end
				if statusBodyDraw then
					statusBodyDraw.Visible = false
				end
				if statusAmmoDraw then
					statusAmmoDraw.Visible = false
				end
				if visualizerLine then
					visualizerLine.Visible = false
				end
				lastRagePaintKey = "hidden"
			end
			local function vizHas(id: string): boolean
				local elements = Rage.vizElements
				return type(elements) == "table" and elements[id] == true
			end

			local function setDrawVisible(draw: any, on: boolean)
				if draw and draw.Visible ~= on then
					draw.Visible = on
				end
			end

			local rageAmmoCached: string? = nil
			function paintRageStatus()
				local now = os.clock()
				if Rage.visualizer ~= true or statusPrefixDraw == nil or statusBodyDraw == nil then
					if lastRagePaintKey ~= "hidden" then
						hideRageVisualizer()
					end
					return
				end
				local rageLive = Rage.enabled == true and isInGameMatch()
				local showStatus = rageLive and vizHas("status")
				local showLine = rageLive and vizHas("line") and visualizerLine ~= nil
				local showAmmo = vizHas("ammo") and statusAmmoDraw ~= nil
				if not (showStatus or showLine or showAmmo) then
					if lastRagePaintKey ~= "hidden" then
						hideRageVisualizer()
					end
					return
				end
				local cam = Workspace.CurrentCamera
				if not cam then
					return
				end

				if lastRagePaintKey == "hidden" or now - lastRagePaintAt >= 0.05 then
					lastRagePaintKey = "shown"
					lastRagePaintAt = now
					if showStatus then
						if RageLive.targetPlayer then
							RageLive.health = readPlayerHealth(RageLive.targetPlayer) or RageLive.health
						end
						local prefix = RageLive.prefix
						local body = buildRageStatusDisplay()
						RageLive.body = body
						RageLive.text = prefix .. body
						if statusPrefixDraw.Text ~= prefix then
							statusPrefixDraw.Text = prefix
						end
						if statusBodyDraw.Text ~= body then
							statusBodyDraw.Text = body
						end
						statusPrefixDraw.Color = Rage.visualizerAccent
						statusBodyDraw.Color = Rage.visualizerColor
						statusPrefixDraw.Gradient = nil
						statusBodyDraw.Gradient = nil
					end
					rageAmmoCached = if showAmmo then rageAmmoText() else nil
					if showAmmo and rageAmmoCached then
						if statusAmmoDraw.Text ~= rageAmmoCached then
							statusAmmoDraw.Text = rageAmmoCached
						end
						statusAmmoDraw.Color = Rage.visualizerColor
						statusAmmoDraw.Gradient = nil
					end
				end

				local vp = cam.ViewportSize
				local useMuzzle = string.lower(tostring(Rage.ammoPosition or "Onscreen")) == "muzzle"
				local muzzlePos: Vector2? = if useMuzzle then rageMuzzleScreen(cam) else nil
				local anchorX = if muzzlePos then muzzlePos.X else vp.X * 0.5
				local anchorY = if muzzlePos then muzzlePos.Y - 2 else vp.Y * 0.5 + Rage.visualizerY
				local statusY = math.floor(anchorY + 0.5)

				local fontName = tostring(Rage.visualizerFont or "Plex")
				local textSize = math.clamp(math.floor(tonumber(Rage.visualizerSize) or 13), 8, 32)
				for _, draw in { statusPrefixDraw, statusBodyDraw, statusAmmoDraw } do
					if draw and type(draw.Font) == "string" and draw.Font ~= fontName then
						draw.Font = fontName
					end
					if draw and draw.Size ~= textSize then
						draw.Size = textSize
					end
				end

				if showStatus then
					local prefixW = statusPrefixDraw.TextBounds.X
					local totalW = prefixW + statusBodyDraw.TextBounds.X
					local statusX = math.floor(anchorX - totalW * 0.5 + 0.5)
					statusPrefixDraw.Position = Vector2.new(statusX, statusY)
					statusBodyDraw.Position = Vector2.new(statusX + prefixW, statusY)
				end
				setDrawVisible(statusPrefixDraw, showStatus)
				setDrawVisible(statusBodyDraw, showStatus)

				local ammoOn = showAmmo and rageAmmoCached ~= nil
				if ammoOn then
					local ammoW = statusAmmoDraw.TextBounds.X
					local ammoGap = math.max(statusAmmoDraw.TextBounds.Y, textSize) + 2
					local ammoY = if showStatus then statusY - ammoGap else statusY
					statusAmmoDraw.Position = Vector2.new(math.floor(anchorX - ammoW * 0.5 + 0.5), ammoY)
				end
				setDrawVisible(statusAmmoDraw, ammoOn)

				local lineOn = false
				if showLine then
					local hit = RageLive.hitPart
					if hit and hit.Parent then
						local sp = cam:WorldToViewportPoint(hit.Position)
						if sp.Z > 0 then
							visualizerLine.From = Vector2.new(math.floor(anchorX + 0.5), statusY)
							visualizerLine.To = Vector2.new(math.floor(sp.X + 0.5), math.floor(sp.Y + 0.5))
							visualizerLine.Color = Rage.visualizerLineColor
							visualizerLine.Thickness = math.clamp(Rage.visualizerLineThick, 0.5, 8)
							lineOn = true
						end
					end
				end
				setDrawVisible(visualizerLine, lineOn)
			end

			function isOutOfAmmo(item: any): boolean
				local ammo = readItemAmmo(item)
				if ammo == nil then
					return false
				end
				return ammo <= 0
			end

			local cachedUseItem: RemoteEvent? = nil
			function getUseItemRemote(): RemoteEvent?
				if cachedUseItem and cachedUseItem.Parent then
					return cachedUseItem
				end
				cachedUseItem = nil
				local remotes = ReplicatedStorage:FindFirstChild("Remotes")
				local replication = remotes and remotes:FindFirstChild("Replication")
				local fighterFolder = replication and replication:FindFirstChild("Fighter")
				local useItem = fighterFolder and fighterFolder:FindFirstChild("UseItem")
				if useItem and useItem:IsA("RemoteEvent") then
					cachedUseItem = useItem
				end
				return cachedUseItem
			end

			local function forceReloadItem(item: any)
				local _, enumLib = getUtilityAndEnum()
				local useItem = getUseItemRemote()
				local objectId
				local reloadEnum
				pcall(function()
					objectId = item:Get("ObjectID")
					if enumLib then
						reloadEnum = enumLib:ToEnum("Reload")
					end
				end)
				if objectId and reloadEnum and useItem then
					pcall(function()
						useItem:FireServer(objectId, reloadEnum, nil, nil)
					end)
				end
				callAsGame(function()
					if type(item.Reload) == "function" then
						item:Reload()
					elseif type(item.StartReload) == "function" then
						item:StartReload()
					end
				end)
				local fighter = select(1, combatControllers())
				local localFighter = fighter and fighter.LocalFighter
				callAsGame(function()
					if localFighter and type(localFighter.Reload) == "function" then
						localFighter:Reload()
					end
				end)
			end

			function handleNoAmmo(item: any, localFighter: any): string
				local now = tick()
				if now - lastNoAmmo < 0.35 then
					return "no ammo - wait"
				end
				lastNoAmmo = now
				local onEmpty = tostring(Rage.onEmpty or Rage.noAmmoAction or "SwapOrReload")
				local action = string.lower(onEmpty)
				if action == "reload" or action == "force reload" then
					applyDesync(getImmuneCF(), false, true)
					forceReloadItem(item)
					return "no ammo - force reload"
				end
				if not rageMayEquip() then
					return "no ammo - rage off"
				end
				if action == "swap" or action == "switch to melee" then
					activeSlot = 3
					equipSlot(localFighter, 3, true)
					return "no ammo - switch to melee"
				end
				if action == "swaporreload" or action == "swap or reload" then
					if slotEnabled("Melee") then
						activeSlot = 3
						equipSlot(localFighter, 3, true)
						return "no ammo - swap or reload"
					end
					applyDesync(getImmuneCF(), false, true)
					forceReloadItem(item)
					return "no ammo - force reload"
				end
				local configured = getConfiguredSlot()
				local current = activeSlot
				if configured == 3 then
					forceReloadItem(item)
					return "no ammo - force reload"
				end
				if current == 1 then
					activeSlot = 2
				elseif current == 2 then
					activeSlot = 1
				else
					activeSlot = if configured == 1 then 2 else 1
				end
				equipSlot(localFighter, activeSlot, true)
				return "no ammo - switch to other -> " .. slotName(activeSlot)
			end

			function preferMainWeaponWithAmmo(localFighter: any): boolean
				if not localFighter or isKnifeWeapon() or isMeleeWeapon() then
					return false
				end
				local main = getConfiguredSlot()
				if main < 1 or main > 2 then
					return false
				end
				if activeSlot == main then
					return false
				end
				local items = nil
				pcall(function()
					items = localFighter.Items
				end)
				if type(items) ~= "table" then
					return false
				end
				local mainItem = items[main]
				if not mainItem or isOutOfAmmo(mainItem) then
					return false
				end
				activeSlot = main
				equipSlot(localFighter, main, true)
				return true
			end

			local floorRayParams = RaycastParams.new()
			floorRayParams.FilterType = Enum.RaycastFilterType.Exclude
			floorRayParams.IgnoreWater = true
			function findFloorUnder(worldPos: Vector3, ignore: { Instance }): (BasePart?, Vector3?, Vector3?)
				floorRayParams.FilterDescendantsInstances = ignore
				local origin = worldPos + Vector3.new(0, 6, 0)
				local result = Workspace:Raycast(origin, Vector3.new(0, -120, 0), floorRayParams)
				if result and result.Instance and result.Instance:IsA("BasePart") then
					return result.Instance, result.Position, result.Normal
				end
				for _, offset in {
					Vector3.new(2, 6, 0),
					Vector3.new(-2, 6, 0),
					Vector3.new(0, 6, 2),
					Vector3.new(0, 6, -2),
				} do
					local side = Workspace:Raycast(worldPos + offset, Vector3.new(0, -120, 0), floorRayParams)
					if side and side.Instance and side.Instance:IsA("BasePart") then
						return side.Instance, side.Position, side.Normal
					end
				end
				return nil, nil, nil
			end

			function resolveUndergroundAttackCF(targetRoot: BasePart, lookAt: Vector3): CFrame?
				local lp = Players.LocalPlayer
				local myChar = lp and lp.Character
				local targetChar = targetRoot:FindFirstAncestorOfClass("Model")
				local ignore: { Instance } = {}
				if myChar then
					table.insert(ignore, myChar)
				end
				if targetChar then
					table.insert(ignore, targetChar)
				end
				local _floor, hitPos, hitNormal = findFloorUnder(targetRoot.Position, ignore)
				local yOff = math.clamp(Rage.undergroundY, -10, 1)
				local underPos: Vector3
				if hitPos then
					underPos = Vector3.new(targetRoot.Position.X, hitPos.Y + yOff, targetRoot.Position.Z)
				else
					underPos = targetRoot.Position + Vector3.new(0, yOff, 0)
				end
				local normal = if hitNormal and hitNormal.Magnitude > 0.001 then hitNormal.Unit else Vector3.yAxis
				if (lookAt - underPos).Magnitude < 0.05 then
					lookAt = underPos + normal
				end
				return CFrame.lookAt(underPos, lookAt)
			end

			function updateVoidPhase(now: number): boolean
				if not Rage.voidSpam then
					inVoidPhase = false
					return false
				end
				local attackDur = math.clamp(Rage.attackTime, 0.05, 10)
				local voidDur = math.clamp(Rage.voidTime, 0.05, 10)
				local elapsed = now - voidPhaseStart
				if inVoidPhase then
					if elapsed >= voidDur then
						inVoidPhase = false
						voidPhaseStart = now
					end
				elseif elapsed >= attackDur then
					inVoidPhase = true
					voidPhaseStart = now
				end
				return inVoidPhase
			end

			local rageGameplayUtil: any = nil
			local rageUtilityMod: any = nil
			local function ensureRageOobModules()
				if rageGameplayUtil == nil then
					pcall(function()
						rageGameplayUtil = require(ReplicatedStorage.Modules.GameplayUtility)
					end)
					if rageGameplayUtil == nil then
						rageGameplayUtil = false
					end
				end
				if rageUtilityMod == nil then
					pcall(function()
						rageUtilityMod = require(ReplicatedStorage.Modules.Utility)
					end)
					if rageUtilityMod == nil then
						rageUtilityMod = false
					end
				end
			end

			function isDangerRagePos(pos: Vector3): boolean
				ensureRageOobModules()
				local gu = rageGameplayUtil
				if type(gu) == "table" and type(gu.IsWithinOOBPart) == "function" then
					local ok, oob = pcall(function()
						return gu:IsWithinOOBPart(pos)
					end)
					if ok and oob then
						return true
					end
				end
				local util = rageUtilityMod
				if type(util) == "table" and type(util.IsWithinTaggedParts) == "function" then
					local ok, hit = pcall(function()
						return util:IsWithinTaggedParts("Barrier", pos)
					end)
					if ok and hit then
						return true
					end
				end
				return false
			end

			local SAFE_TP_OFFSETS = {
				Vector3.zero,
				Vector3.new(0, 2, 0),
				Vector3.new(0, 4, 0),
				Vector3.new(2, 2, 0),
				Vector3.new(-2, 2, 0),
				Vector3.new(0, 2, 2),
				Vector3.new(0, 2, -2),
				Vector3.new(3, 1, 3),
				Vector3.new(-3, 1, 3),
				Vector3.new(3, 1, -3),
				Vector3.new(-3, 1, -3),
				Vector3.new(0, 6, 0),
				Vector3.new(0, 1, 4),
				Vector3.new(0, 1, -4),
				Vector3.new(4, 1, 0),
				Vector3.new(-4, 1, 0),
			}

			local BAIT_OFFSETS = {
				Vector3.zero,
				Vector3.new(0, 1.7, 0),
				Vector3.new(0, -2.6, 0),
				Vector3.new(0, 1, 2),
				Vector3.new(0, 0.2, -2.5),
				Vector3.new(0, 5, 0),
				Vector3.new(1.4, 0.5, 0),
				Vector3.new(-1.4, 0.5, 0),
			}
			local killZoneCache: { [BasePart]: { at: number, hit: boolean } } = setmetatable({}, { __mode = "k" }) :: any
			function isStandingInKillZone(root: BasePart): boolean
				local now = os.clock()
				local cached = killZoneCache[root]
				if cached and now - cached.at < 0.35 then
					return cached.hit
				end
				local cf = root.CFrame
				local hit = false
				for _, off in BAIT_OFFSETS do
					if isDangerRagePos((cf * CFrame.new(off)).Position) then
						hit = true
						break
					end
				end
				killZoneCache[root] = { at = now, hit = hit }
				return hit
			end

			local function resolveSafeDesyncCF(desiredCF: CFrame, strict: boolean?): CFrame?
				local lookAt = desiredCF.Position + desiredCF.LookVector * 8
				if (lookAt - desiredCF.Position).Magnitude < 0.05 then
					lookAt = desiredCF.Position + Vector3.new(0, 0, -1)
				end
				local desired = desiredCF.Position
				if isDangerRagePos(desired) then
					if strict then
						return nil
					end
				else
					return CFrame.lookAt(desired, lookAt)
				end
				for _, off in SAFE_TP_OFFSETS do
					local p = desired + off
					if not isDangerRagePos(p) then
						return CFrame.lookAt(p, lookAt)
					end
				end
				local lp = Players.LocalPlayer
				local root = lp and lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
				if root and root:IsA("BasePart") and not isDangerRagePos(root.Position) then
					for t = 0.15, 1, 0.15 do
						local p = desired:Lerp(root.Position, t)
						if not isDangerRagePos(p) then
							return CFrame.lookAt(p, lookAt)
						end
					end
					return CFrame.lookAt(root.Position, lookAt)
				end
				return nil
			end

			desyncLocked = false
			desyncRestoreBound = false
			local desyncRestoreRoot: BasePart? = nil
			desyncRestoreCF= nil
			desyncShownCF= nil
			local desyncRestoreVel: Vector3 = Vector3.zero
			local desyncRestoreRot: Vector3 = Vector3.zero
			function flushDesyncRestore()
				if desyncRestoreBound then
					desyncRestoreBound = false
					pcall(function()
						RunService:UnbindFromRenderStep("__sonata_rage_restore")
					end)
				end
				local root = desyncRestoreRoot
				local cf = desyncRestoreCF
				desyncRestoreRoot = nil
				desyncRestoreCF = nil
				desyncShownCF = nil
				if root and root.Parent and cf then
					pcall(function()
						root.CFrame = cf
						root.AssemblyLinearVelocity = desyncRestoreVel
						root.AssemblyAngularVelocity = desyncRestoreRot
					end)
				end
			end

			function sameSpot(a: CFrame?, b: CFrame?): boolean
				return a ~= nil and b ~= nil and (a.Position - b.Position).Magnitude < 0.2
			end

			function applyDesync(desyncCF: CFrame, lock: boolean?, force: boolean?): (boolean, CFrame?)
				local safeCF = if force then desyncCF else resolveSafeDesyncCF(desyncCF, lock == true)
				if not safeCF then
					return false, nil
				end
				if isRageV2() and setServerReplicaCF(safeCF) then
					desyncShownCF = safeCF
					if lock then
						desyncLocked = true
					end
					return true, safeCF
				end
				local lp = Players.LocalPlayer
				local char = lp and lp.Character
				local myRoot = char and char:FindFirstChild("HumanoidRootPart")
				if not myRoot or not myRoot:IsA("BasePart") then
					return false, nil
				end
				local keepAnchor = desyncRestoreCF ~= nil and (desyncRestoreBound or sameSpot(myRoot.CFrame, desyncShownCF))
				if not keepAnchor or desyncRestoreRoot ~= myRoot then
					desyncRestoreRoot = myRoot
					desyncRestoreCF = myRoot.CFrame
					desyncRestoreVel = myRoot.AssemblyLinearVelocity
					desyncRestoreRot = myRoot.AssemblyAngularVelocity
				end
				myRoot.CFrame = safeCF
				desyncShownCF = safeCF
				if lock then
					desyncLocked = true
				end
				if not desyncRestoreBound then
					desyncRestoreBound = true
					local priority = Enum.RenderPriority.Camera.Value - 1
					RunService:BindToRenderStep("__sonata_rage_restore", priority, flushDesyncRestore)
				end
				return true, safeCF
			end
			pcall(function()
				local pre = (RunService :: any).PreSimulation
				if typeof(pre) == "RBXScriptSignal" then
					table.insert(ears, pre:Connect(function()
						if desyncRestoreBound or desyncRestoreCF then
							flushDesyncRestore()
						end
					end))
				end
			end)

			end
			do -- rage combat
			local deflectAt = 0
			local function updateDeflection()
				local now = os.clock()
				if now - deflectAt < 0.1 then
					return
				end
				deflectAt = now
				local fighter = select(1, combatControllers())
				if not fighter or not fighter.Objects then
					return
				end
				for _, fighterObj in fighter.Objects do
					local player = fighterObj.Player
					if not player then
						continue
					end
					local entity = fighterObj.Entity
					if not entity or not entity:IsAlive() then
						deflecting[player] = false
						continue
					end
					local okSpec, spectating = pcall(function()
						return fighterObj:Get("IsSpectating") == true
					end)
					if okSpec and spectating then
						deflecting[player] = false
						continue
					end
					local equipped = fighterObj.EquippedItem
					local vm = equipped and equipped.ViewModel
					local isDeflecting = false
					if vm and vm.Name == "Katana" then
						isDeflecting = (equipped._attack_cooldown and equipped._attack_cooldown > tick()) or false
					end
					deflecting[player] = isDeflecting
				end
			end

			local IMMUNE_ATTRS = { "IsInvincible", "Immune", "IsImmune", "SpawnProtection" }
			local function isTargetImmune(player: Player): boolean
				local fighterObj = frameFighterIndex[player]
				if fighterObj then
					local entity = fighterObj.Entity
					if entity and type(entity.Get) == "function" then
						local ok, inv = pcall(entity.Get, entity, "IsInvincible")
						if ok and inv == true then
							return true
						end
						local okImmune, immune = pcall(entity.Get, entity, "IsImmune")
						if okImmune and immune == true then
							return true
						end
					end
				end
				local character = player.Character
				if character then
					if character:FindFirstChildOfClass("ForceField") then
						return true
					end
					for _, name in IMMUNE_ATTRS do
						if character:GetAttribute(name) == true then
							return true
						end
					end
				end
				for _, name in IMMUNE_ATTRS do
					if player:GetAttribute(name) == true then
						return true
					end
				end
				return false
			end

			local function isRageOpponent(player: Player): boolean
				local lp = Players.LocalPlayer
				if not lp or player == lp then
					return false
				end
				if frameLocalTeam ~= nil then
					local team = frameTeamOf[player]
					if team ~= nil then
						return team ~= frameLocalTeam
					end
				end
				local pTeam = player:GetAttribute("TeamID")
				local lTeam = lp:GetAttribute("TeamID")
				if pTeam and lTeam then
					return pTeam ~= lTeam
				end
				return true
			end

			local cheatTrack: { [Player]: { pos: Vector3, at: number, score: number } } = {}
			table.insert(ears, Players.PlayerRemoving:Connect(function(player: Player)
				cheatTrack[player] = nil
			end))

			local function cheaterScore(player: Player, root: BasePart, now: number): number
				local t = cheatTrack[player]
				if not t then
					cheatTrack[player] = { pos = root.Position, at = now, score = 0 }
					return 0
				end
				local dt = now - t.at
				if dt < 0.08 then
					return t.score
				end
				local delta = root.Position - t.pos
				local dist = delta.Magnitude
				local speed = dist / math.max(dt, 1e-3)
				local score = t.score
				if root.Position.Magnitude > 8000 or math.abs(root.Position.Y) > 2500 then
					score += 2.2
				elseif speed > 280 and dist > 35 then
					score += 2
				elseif speed > 140 and dist > 22 then
					score += 1
				else
					score = math.max(0, score - 0.2)
				end
				t.pos = root.Position
				t.at = now
				t.score = math.clamp(score, 0, 24)
				return t.score
			end

			local function isLikelyCheater(player: Player, root: BasePart, now: number): boolean
				return cheaterScore(player, root, now) >= 4.5
			end

			local cycleTarget: Player? = nil
			local cycleSwitchAt = 0
			local cycleLastAt: { [Player]: number } = setmetatable({}, { __mode = "k" }) :: any

			local function getClosestRageTarget(myRoot: BasePart, now: number): (Player?, BasePart?, BasePart?, Player?, Player?)
				local cam = Workspace.CurrentCamera
				local screenCenter = if cam then cam.ViewportSize * 0.5 else Vector2.new(0, 0)
				local priority = Rage.targetPriority or "Closest"
				local bestPlayer: Player? = nil
				local bestRoot: BasePart? = nil
				local bestHead: BasePart? = nil
				local bestKey: number? = nil
				local bestDist = math.huge
				local graceP: Player? = nil
				local graceDist = math.huge
				local dangerP: Player? = nil
				local dangerDist = math.huge
				local maxDist = tonumber(Rage.maxDistance) or 500
				local myPos = myRoot.Position

				for _, player in Players:GetPlayers() do
					if not isRageOpponent(player) then
						continue
					end
					local pChar = player.Character
					if not pChar then
						continue
					end
					local pRoot = pChar:FindFirstChild("HumanoidRootPart")
					local pHead = pChar:FindFirstChild("Head")
					local pHum = pChar:FindFirstChildOfClass("Humanoid")
					if not (pRoot and pRoot:IsA("BasePart") and pHead and pHead:IsA("BasePart") and pHum and pHum.Health > 0) then
						continue
					end
					local dist = (myPos - pRoot.Position).Magnitude
					if dist > maxDist then
						continue
					end
					if isTargetImmune(player) then
						if dist < graceDist then
							graceDist = dist
							graceP = player
						end
						continue
					end
					if isStandingInKillZone(pRoot) then
						if dist < dangerDist then
							dangerDist = dist
							dangerP = player
						end
						continue
					end

					local key: number
					if priority == "Lowest Health" then
						key = pHum.Health * 1000 + dist
					elseif priority == "Cheater" then
						local cheater = isLikelyCheater(player, pRoot, now)
						key = if cheater then dist else (1e6 + dist)
					elseif priority == "Crosshair" then
						key = 1e7 + dist
						if cam then
							local sp, onScreen = cam:WorldToViewportPoint(pHead.Position)
							if onScreen and sp.Z > 0 then
								key = (Vector2.new(sp.X, sp.Y) - screenCenter).Magnitude
							end
						end
					elseif priority == "Cycle" then
						if player == cycleTarget and now < cycleSwitchAt then
							key = -1
						else
							key = (cycleLastAt[player] or 0) + dist * 1e-6
						end
					else
						key = dist
					end
					if Rage.prioritizeHackers and isLikelyCheater(player, pRoot, now) then
						key -= 1e7
					end

					if bestKey == nil or key < bestKey or (key == bestKey and dist < bestDist) then
						bestKey = key
						bestDist = dist
						bestPlayer = player
						bestRoot = pRoot
						bestHead = pHead
					end
				end
				if priority == "Cycle" and bestPlayer then
					if bestPlayer ~= cycleTarget or now >= cycleSwitchAt then
						cycleTarget = bestPlayer
						cycleSwitchAt = now + math.clamp(tonumber(Rage.cycleInterval) or 1.5, 0.2, 10)
						cycleLastAt[bestPlayer] = now
					end
				elseif priority == "Cycle" then
					cycleTarget = nil
				end
				return bestPlayer, bestRoot, bestHead, graceP, dangerP
			end

			local function itemNameIsKnife(item: any): boolean
				if type(item) ~= "table" then
					return false
				end
				local name = item.Name
				if type(name) ~= "string" and type(item.Get) == "function" then
					pcall(function()
						name = item:Get("Name")
					end)
				end
				if type(name) ~= "string" then
					local info = item.Info
					if type(info) == "table" and type(info.Name) == "string" then
						name = info.Name
					elseif type(info) == "table" and type(info.DisplayName) == "string" then
						name = info.DisplayName
					end
				end
				if type(name) ~= "string" then
					return false
				end
				return string.find(string.lower(name), "knife", 1, true) ~= nil
			end

			local function fighterHasKnifeLoadout(fighterObj: any): boolean
				if type(fighterObj) ~= "table" then
					return false
				end
				local items = fighterObj.Items
				if type(items) ~= "table" and type(fighterObj.Get) == "function" then
					pcall(function()
						items = fighterObj:Get("Items")
					end)
				end
				if type(items) == "table" then
					for _, item in items do
						if itemNameIsKnife(item) then
							return true
						end
					end
				end
				if itemNameIsKnife(fighterObj.EquippedItem) then
					return true
				end
				local behaviors = fighterObj.ItemBehaviors
				if type(behaviors) == "table" and type(behaviors.FindMeleeByName) == "function" then
					local ok, found = pcall(behaviors.FindMeleeByName, behaviors, "Knife")
					if ok and found ~= nil then
						return true
					end
				end
				return false
			end

			local function hasKnifeViewModel(targetPlayer: Player?): boolean
				if not targetPlayer then
					return false
				end
				local viewModels = Workspace:FindFirstChild("ViewModels")
				if not viewModels then
					return false
				end
				local targetName = targetPlayer.Name
				for _, model in viewModels:GetChildren() do
					if model:IsA("Model")
						and string.find(model.Name, targetName, 1, true)
						and string.find(model.Name, "Knife", 1, true)
					then
						return true
					end
				end
				return false
			end

			local function getRageTargetVelocity(targetPart: BasePart): Vector3
				local vel = Vector3.zero
				pcall(function()
					vel = targetPart.AssemblyLinearVelocity
				end)
				if vel.Magnitude >= 0.05 then
					return vel
				end
				local parent = targetPart.Parent
				local hrp = parent and parent:FindFirstChild("HumanoidRootPart")
				if hrp and hrp:IsA("BasePart") then
					pcall(function()
						vel = (hrp :: BasePart).AssemblyLinearVelocity
					end)
				end
				return vel
			end

			local ragePing = 0.06
			local ragePingAt = 0
			local function getRageLookAhead(vel: Vector3): number
				local amount = math.clamp(Rage.extrapolationAmount or 100, 0, 250) / 100
				local ping = 0.06
				local clock = os.clock()
				if clock - ragePingAt >= 1 then
					ragePingAt = clock
					pcall(function()
						local lp = Players.LocalPlayer
						if lp then
							ragePing = math.clamp(lp:GetNetworkPing(), 0, 0.5)
						end
					end)
				end
				ping = ragePing
				local speed = vel.Magnitude
				local lookAhead = (ping * 1.2 + 0.016) * amount
				lookAhead *= 1 + math.clamp(speed / 40, 0, 1.6) * 0.4
				return math.clamp(lookAhead, 0, 0.5)
			end

			local function extrapolateRagePos(targetPart: BasePart): Vector3
				local pos = targetPart.Position
				if not Rage.extrapolation then
					return pos
				end
				local vel = getRageTargetVelocity(targetPart)
				if vel.Magnitude < 0.05 then
					return pos
				end
				return pos + vel * getRageLookAhead(vel)
			end

			local K0, K1, K2, K3 = utf8.char(0), utf8.char(1), utf8.char(2), utf8.char(3)
			local startShootingEnum: any = nil

			local SHOOT_EYE_OFFSET = Vector3.new(0, 1.5, 0)
			local pelletCacheItem: any = nil
			local pelletCacheCount = 1
			local function shootPelletCount(item: any): number
				if item == pelletCacheItem then
					return pelletCacheCount
				end
				pelletCacheItem = item
				pelletCacheCount = 1
				local info = item and item.Info
				if type(info) == "table" and type(info.ShootPellets) == "number" then
					pelletCacheCount = math.max(1, math.floor(info.ShootPellets))
				end
				return pelletCacheCount
			end

			local function fireRageShot(item: any, originPos: Vector3, targetPart: BasePart, _perfect: boolean?, leadPos: Vector3?, aiming: boolean?, count: number?, alignBody: boolean?): boolean
				local below = false
				pcall(function()
					below = originPos.Y > targetPart.Position.Y + 1.5
				end)
				if isRageV2() and fireEncodedGun(item, targetPart, below) then
					return true
				end
				local util, enumLib = getUtilityAndEnum()
				local useItem = getUseItemRemote()
				if not (util and enumLib and useItem) then
					return false
				end
				local shots = math.clamp(math.floor(count or 1), 1, 20)
				local ok = pcall(function()
					if startShootingEnum == nil then
						startShootingEnum = enumLib:ToEnum("StartShooting")
					end
					local objectId = item:Get("ObjectID")
					if objectId == nil or startShootingEnum == nil then
						error("no id")
					end
					local partCF = targetPart.CFrame
					local hitPoint = partCF.Position
					local aimPoint = leadPos or hitPoint
					local eye = if alignBody then originPos else originPos + SHOOT_EYE_OFFSET
					if (eye - aimPoint).Magnitude < 0.1 then
						eye = aimPoint - partCF.LookVector * 0.5 + Vector3.new(0, 0.1, 0)
					end
                    local look = CFrame.lookAt(eye, aimPoint)
					local encodedAim = util:EncodeCFrame(look)
					local encodedCam = encodedAim
					local encodedOffset = util:EncodeCFrame(partCF:ToObjectSpace(CFrame.new(hitPoint)))
					local cameradata: { [string]: any } = {
						[K1] = {
							[K0] = encodedCam,
							[K1] = encodedAim,
							[K2] = targetPart,
							[K3] = encodedOffset,
						},
					}
					if shootPelletCount(item) > 1 or aiming then
						cameradata[K2] = true
					end
					for _ = 1, shots do
						useItem:FireServer(objectId, startShootingEnum, cameradata, nil)
					end
				end)
				return ok
			end

			local function itemShotCooldown(item: any): number
				local cd = 0
				pcall(function()
					local info = item.Info
					if type(info) ~= "table" then
						return
					end
					cd = tonumber(info.ShootCooldown) or 0
					local burst = tonumber(info.BurstCount) or 1
					local burstCd = tonumber(info.BurstCooldown)
					if burst > 1 and burstCd then
						cd = math.min(cd, burstCd)
					end
				end)
				return math.clamp(cd, 0, 5)
			end

			local SCOPE_HOLD = 0.32
			local scopeItem: any = nil
			local scopeStartedAt = 0

			local scopedCacheItem: any = nil
			local scopedCacheValue = false
			local function isScopedGun(item: any): boolean
				if item == scopedCacheItem then
					return scopedCacheValue
				end
				scopedCacheItem = item
				local info = item and item.Info
				scopedCacheValue = type(info) == "table" and info.AimScopePercent ~= nil and info.IsRaycast == true
				return scopedCacheValue
			end

			local bodyAimCacheItem: any = nil
			local bodyAimCacheValue = false
			local function isBodyAimWeapon(item: any): boolean
				if item == bodyAimCacheItem then
					return bodyAimCacheValue
				end
				bodyAimCacheItem = item
				local name = ""
				if type(item) == "table" then
					if type(item.Name) == "string" then
						name = item.Name
					elseif type(item.Info) == "table" and type(item.Info.Name) == "string" then
						name = item.Info.Name
					end
				end
				name = string.lower(name)
				bodyAimCacheValue = string.find(name, "dagger", 1, true) ~= nil
				return bodyAimCacheValue
			end

			local function sendItemAction(item: any, action: string)
				local _, enumLib = getUtilityAndEnum()
				local useItem = getUseItemRemote()
				if not (enumLib and useItem) then
					return
				end
				pcall(function()
					local objectId = item:Get("ObjectID")
					local actionEnum = enumLib:ToEnum(action)
					if objectId ~= nil and actionEnum ~= nil then
						useItem:FireServer(objectId, actionEnum)
					end
				end)
			end

			local function cancelScope()
				local item = scopeItem
				scopeItem = nil
				if item then
					sendItemAction(item, "FinishAiming")
				end
			end

			local function scopeReady(item: any, now: number, cooldown: number): (boolean, string)
				if scopeItem ~= nil and scopeItem ~= item then
					cancelScope()
				end
				local readyAt = lastFire + cooldown
				if scopeItem == nil then
					if now < readyAt - SCOPE_HOLD then
						return false, "sniper cooldown"
					end
					sendItemAction(item, "StartAiming")
					scopeItem = item
					scopeStartedAt = now
					return false, "sniper scoping"
				end
				if now - scopeStartedAt < SCOPE_HOLD or now < readyAt then
					return false, "sniper scoping"
				end
				return true, "sniper ready"
			end

			local function resolveHitbox(targetRoot: BasePart, targetHead: BasePart, body: boolean): BasePart
				local char = targetRoot.Parent
				if char then
					local hb = char:FindFirstChild(if body then "HitboxBody" else "HitboxHead")
					if hb and hb:IsA("BasePart") then
						return hb
					end
				end
				return if body then targetRoot else targetHead
			end

			local function voidParkCF(_myRoot: BasePart, _lookAt: Vector3): CFrame
				local u = math.random()
				local v = math.random()
				local theta = math.pi * 2 * u
				local phi = math.acos(math.clamp(2 * v - 1, -1, 1))
				local r = VOID_RADIUS
				local pos = Vector3.new(
					r * math.sin(phi) * math.cos(theta),
					r * math.cos(phi),
					r * math.sin(phi) * math.sin(theta)
				)
				return CFrame.lookAt(pos, Vector3.zero)
			end

			local function targetFacing(targetRoot: BasePart): Vector3
				local look = targetRoot.CFrame.LookVector
				local flat = Vector3.new(look.X, 0, look.Z)
				if flat.Magnitude < 0.05 then
					return Vector3.new(0, 0, -1)
				end
				return flat.Unit
			end

			local function behindTargetCF(targetRoot: BasePart): CFrame
				local facing = targetFacing(targetRoot)
				local predicted = extrapolateRagePos(targetRoot)
				local at = predicted - facing * KNIFE_BEHIND_STUD
				return CFrame.lookAt(at, Vector3.new(predicted.X, at.Y, predicted.Z) + facing * 0.01)
			end

			local function knifeBackPoint(targetRoot: BasePart, hitPart: BasePart): Vector3
				local depth = math.min(hitPart.Size.Z * 0.4, 0.6)
				return hitPart.Position - targetFacing(targetRoot) * depth
			end

			local function knifeDesync(targetRoot: BasePart): boolean
				local ok, cf = applyDesync(behindTargetCF(targetRoot), true)
				if ok then
					knifeBehindCF = cf
				end
				return ok
			end

			local function isHeavyMelee(item: any): boolean
				local ok, yes = pcall(function()
					return type(item.Info) == "table" and tonumber(item.Info.HeavyAttackCooldown) ~= nil
				end)
				return ok and yes == true
			end

			local cameraRotationRemote: any = nil
			local function sendKnifeCameraRotation(util: any, aim: CFrame)
				if cameraRotationRemote == nil then
					pcall(function()
						cameraRotationRemote = ReplicatedStorage.Remotes.Replication.Fighter.UpdateCameraRotation
					end)
				end
				if not cameraRotationRemote then
					return
				end
				local lv = aim.LookVector
				local pitch = math.atan2(lv.Y, math.sqrt(lv.X * lv.X + lv.Z * lv.Z))
				local yaw = math.atan2(-lv.X, -lv.Z)
				pcall(function()
					cameraRotationRemote:FireServer(util:EncodeCameraRotation(Vector2.new(pitch, yaw)), nil)
				end)
			end

			local function fireKnifeBackstab(item: any, originCF: CFrame, targetRoot: BasePart, heavy: boolean): boolean
				local char = targetRoot.Parent
				local hitPart = char and char:FindFirstChild("HitboxHead")
				if not (hitPart and hitPart:IsA("BasePart")) then
					hitPart = char and char:FindFirstChild("HitboxBody")
				end
				if not (hitPart and hitPart:IsA("BasePart")) then
					hitPart = targetRoot
				end
				local below = originCF.Position.Y > targetRoot.Position.Y + 1.5
				if fireEncodedMelee(item, hitPart :: BasePart, below, true) then
					return true
				end
				local util, enumLib = getUtilityAndEnum()
				local useItem = getUseItemRemote()
				if not (util and enumLib and useItem) then
					return false
				end
				if not (hitPart and hitPart:IsA("BasePart")) then
					hitPart = targetRoot
				end
				local partCF = (hitPart :: BasePart).CFrame
				local hitPoint = knifeBackPoint(targetRoot, hitPart :: BasePart)
				local eye = originCF.Position + SHOOT_EYE_OFFSET
				if (eye - hitPoint).Magnitude < 0.1 then
					eye = hitPoint - targetFacing(targetRoot)
				end
				local aim = CFrame.lookAt(eye, hitPoint)
				sendKnifeCameraRotation(util, aim)
				local action = heavy and "StartAiming" or "StartShooting"
				local res = table.pack(callAsGame(function()
					return item[action](item, true)
				end))
				local token = res[1] and res[5] or nil
				if token == nil then
					pcall(function()
						token = enumLib:ToEnum(heavy and "HeavyAttack1" or "Attack1")
					end)
				end
				local ok = pcall(function()
					local objectId = item:Get("ObjectID")
					local actionEnum = enumLib:ToEnum(action)
					if objectId == nil or actionEnum == nil then
						error("no id")
					end
					local encodedAim = util:EncodeCFrame(aim)
					useItem:FireServer(objectId, actionEnum, {
						[K1] = {
							[K0] = encodedAim,
							[K1] = encodedAim,
							[K2] = hitPart,
							[K3] = util:EncodeCFrame(partCF:ToObjectSpace(CFrame.new(hitPoint))),
						},
						[K2] = token,
					}, nil)
				end)
				return ok
			end

			local manualStabBusy = false
			local function findManualStabTarget(myRoot: BasePart): BasePart?
				refreshFrameContext()
				local lp = Players.LocalPlayer
				local cam = Workspace.CurrentCamera
				local best: BasePart? = nil
				local bestScore = math.huge
				for _, plr in Players:GetPlayers() do
					if plr ~= lp and isRageOpponent(plr) and not isTargetImmune(plr) then
						local ch = plr.Character
						local root = ch and ch:FindFirstChild("HumanoidRootPart")
						local hum = ch and ch:FindFirstChildOfClass("Humanoid")
						if root and root:IsA("BasePart") and hum and hum.Health > 0 then
							local d = (root.Position - myRoot.Position).Magnitude
							if d <= KNIFE_MANUAL_RANGE then
								local score = d
								if cam then
									local dir = root.Position - cam.CFrame.Position
									if dir.Magnitude > 0.1 then
										score = d * (2 - cam.CFrame.LookVector:Dot(dir.Unit))
									end
								end
								if score < bestScore then
									best = root
									bestScore = score
								end
							end
						end
					end
				end
				return best
			end

			local function manualBackstab(item: any, targetRoot: BasePart)
				manualStabBusy = true
				pcall(function()
					local t0 = tick()
					repeat
						RunService.Heartbeat:Wait()
						if not targetRoot.Parent or not knifeDesync(targetRoot) then
							return
						end
					until tick() - t0 >= KNIFE_SETTLE
					RunService.Heartbeat:Wait()
					if not targetRoot.Parent or not knifeDesync(targetRoot) then
						return
					end
					fireKnifeBackstab(item, knifeBehindCF or behindTargetCF(targetRoot), targetRoot, true)
					local t1 = tick()
					while tick() - t1 < KNIFE_HOLD_AFTER and targetRoot.Parent do
						RunService.Heartbeat:Wait()
						knifeDesync(targetRoot)
					end
				end)
				knifeBehindCF = nil
				manualStabBusy = false
			end

			local hookedHeavyClasses: { [any]: any } = setmetatable({}, { __mode = "k" }) :: any
			local function hookHeavyClass(item: any)
				local class = getmetatable(item)
				while type(class) == "table" and rawget(class, "StartAiming") == nil do
					class = getmetatable(class)
				end
				if type(class) ~= "table" or hookedHeavyClasses[class] then
					return
				end
				local original = rawget(class, "StartAiming")
				if type(original) ~= "function" then
					return
				end
				hookedHeavyClasses[class] = original
				rawset(class, "StartAiming", function(self: any, force: any, ...: any)
					if not force and Exploits.alwaysBackstab and not manualStabBusy and knifePhase ~= "stab" and isHeavyMelee(self) then
						local ready = false
						pcall(function()
							ready = tick() >= (self._attack_cooldown or 0) and not self:IsEquipping()
						end)
						local lp = Players.LocalPlayer
						local myRoot = lp and lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
						if ready and myRoot and myRoot:IsA("BasePart") then
							local target = findManualStabTarget(myRoot)
							if target then
								task.spawn(manualBackstab, self, target)
								return false
							end
						end
					end
					return original(self, force, ...)
				end)
			end
			table.insert(ears, {
				Disconnect = function()
					for class, original in hookedHeavyClasses do
						pcall(rawset, class, "StartAiming", original)
					end
					table.clear(hookedHeavyClasses)
				end,
			} :: any)
			local heavyHookCheckAt = 0
			table.insert(ears, RunService.Heartbeat:Connect(function()
				local clock = os.clock()
				if clock - heavyHookCheckAt < 0.55 then
					return
				end
				heavyHookCheckAt = clock
				local localFighter = getLocalFighter()
				local item = localFighter and localFighter.EquippedItem
				if type(item) == "table" and isHeavyMelee(item) then
					pcall(hookHeavyClass, item)
				end
			end))

			local function softResetRageState(equipMain: boolean)
				inVoidPhase = false
				voidPhaseStart = tick()
				_voidOrbitT = 0
				_voidOrbitSeed = math.random() * 1000
				knifePhase = "void"
				knifeFiredThisStab = false
				knifeBehindCF = nil
				resetBurst()
				cycleReadyAt = 0
				flushDesyncRestore()
				cancelScope()
				activeSlot = getConfiguredSlot()
				if equipMain and rageMayEquip() then
					resetToMainWeapon(nil)
				end
			end

			local function shutdownRagebot()
				rageSession += 1
				softResetRageState(false)
				setRagePhysics(false)
				clearServerReplica()
				applyForcedCrouch(false)
				RageLive.hitPart = nil
				setRageStatus("off", nil)
				paintRageStatus()
			end
			DrawingBridge.shutdownRagebot = shutdownRagebot

			local rageWasEnabled = false
			local rageWasInMatch = false
			local lastRageErrAt = 0
			local rageCtx: any = {}

			local function getMyRoot(): BasePart?
				local lp = Players.LocalPlayer
				local char = lp and lp.Character
				local root = char and char:FindFirstChild("HumanoidRootPart")
				if root and root:IsA("BasePart") then
					return root
				end
				return nil
			end

			local knifeVmPlayer: Player? = nil
			local knifeVmAt = 0
			local knifeVmValue = false
			local function targetHoldsKnife(player: Player, now: number): boolean
				if player ~= knifeVmPlayer or now - knifeVmAt >= 0.4 then
					knifeVmPlayer = player
					knifeVmAt = now
					local hasKnife = fighterHasKnifeLoadout(frameFighterIndex[player])
					if not hasKnife then
						local fighter = select(1, combatControllers())
						local objects = fighter and fighter.Objects
						if type(objects) == "table" then
							for _, obj in objects do
								if obj and obj.Player == player then
									hasKnife = fighterHasKnifeLoadout(obj)
									break
								end
							end
						end
					end
					if not hasKnife then
						hasKnife = hasKnifeViewModel(player)
					end
					knifeVmValue = hasKnife
				end
				return knifeVmValue
			end

			local KNIFE_LOADOUT_UNDER = 5
			local function knifeUnderCF(root: BasePart, lookAt: Vector3): CFrame
				local pos = root.Position + Vector3.new(0, -KNIFE_LOADOUT_UNDER, 0)
				if (lookAt - pos).Magnitude < 0.05 then
					lookAt = root.Position
				end
				return CFrame.lookAt(pos, lookAt)
			end

			local function resetKnifeCycle()
				knifePhase = "void"
				knifeFiredThisStab = false
				knifeBehindCF = nil
				RageLive.knifeIn = nil
				resetBurst()
			end

			local ATTACK_NEAR = 24
			local function atAttackPos(fromPos: Vector3, targetPos: Vector3): boolean
				return (fromPos - targetPos).Magnitude <= ATTACK_NEAR
			end

			local function voidParkStep(ctx: any, lookAt: Vector3, okStep: string): string
				if applyDesync(voidParkCF(ctx.myRoot, lookAt), false, true) then
					return okStep
				end
				return "waiting safe"
			end

			local function knifeInterval(): number
				return math.clamp(tonumber(Rage.knifeInterval) or 1.3, 0.1, 5)
			end

			local function runKnifeMode(ctx: any): string
				local now = ctx.now
				local targetRoot = ctx.targetRoot
				local item = ctx.item
				if activeSlot ~= 3 then
					activeSlot = 3
					resetKnifeCycle()
					ensureWeaponEquipped(true)
					return "equip knife"
				end
				local interval = knifeInterval()
				local remaining = math.max(interval - (now - lastFire), 0)
				if burstLeft > 0 then
					remaining = math.max(burstNextAt - now, 0)
				end
				RageLive.knifeIn = remaining

				if knifePhase ~= "stab" then
					if remaining > KNIFE_SETTLE and burstLeft <= 0 then
						return voidParkStep(ctx, ctx.targetHead.Position, "knife void")
					end
					knifePhase = "stab"
					knifeFiredThisStab = false
					knifeAttackAt = now + KNIFE_SETTLE
				end
				if not knifeDesync(targetRoot) then
					resetKnifeCycle()
					return "waiting safe"
				end
				if now >= knifeAttackAt and (burstLeft > 0 or remaining <= 0) then
					local behind = knifeBehindCF
					if not behind or not atAttackPos(behind.Position, targetRoot.Position) then
						return "waiting near"
					end
					if consumeBurstShot(now, interval) then
						knifeFiredThisStab = true
						knifeVoidAt = now + KNIFE_HOLD_AFTER
						RageLive.knifeIn = if burstLeft > 0 then math.max(burstNextAt - now, 0) else interval
						fireKnifeBackstab(item, knifeBehindCF or behindTargetCF(targetRoot), targetRoot, isHeavyMelee(item))
						return if burstLeft > 0 then "knife burst" else "knife backstab"
					end
					return "knife burst wait"
				end
				if knifeFiredThisStab and burstLeft <= 0 and now >= knifeVoidAt and remaining > KNIFE_SETTLE + KNIFE_HOLD_AFTER then
					resetKnifeCycle()
					RageLive.knifeIn = remaining
					return voidParkStep(ctx, ctx.targetHead.Position, "knife void")
				end
				return "knife behind"
			end

			local function insideMeleeCF(targetRoot: BasePart): CFrame
				local center = targetRoot.Position
				local t = os.clock()
				local pos = center + Vector3.new(
					(math.noise(t * 91, 0.11) - 0.5) * 0.22,
					(math.noise(t * 97, 1.37) - 0.5) * 0.18,
					(math.noise(t * 83, 2.91) - 0.5) * 0.22
				)
				local look = center
				if (pos - look).Magnitude < 0.06 then
					look += targetFacing(targetRoot) * 0.5
				end
				return CFrame.lookAt(pos, look)
			end

			local meleeNet = { ready = false, shoot = nil :: any, attack = nil :: any, item = nil :: any, id = nil :: any }
			local function fireMeleeSlash(item: any, originCF: CFrame, hitPart: BasePart, aimPoint: Vector3): boolean
				local below = originCF.Position.Y > hitPart.Position.Y + 1.5
				local knife = isHeavyMelee(item)
				pcall(function()
					knife = knife or item.Name == "Knife"
				end)
				if fireEncodedMelee(item, hitPart, below, knife) then
					return true
				end
				local util, enumLib = getUtilityAndEnum()
				local useItem = getUseItemRemote()
				if not (util and enumLib and useItem) then
					return false
				end
				if not meleeNet.ready then
					local shoot = enumLib:ToEnum("StartShooting")
					local attack = enumLib:ToEnum("Attack1")
					if shoot == nil then
						return false
					end
					meleeNet.shoot = shoot
					meleeNet.attack = attack
					meleeNet.ready = true
				end
				if meleeNet.item ~= item then
					meleeNet.item = item
					meleeNet.id = nil
					pcall(function()
						meleeNet.id = item:Get("ObjectID")
					end)
				end
				local objectId = meleeNet.id
				local actionEnum = meleeNet.shoot
				if objectId == nil or actionEnum == nil then
					return false
				end
				local partCF = hitPart.CFrame
				local hitPoint = aimPoint
				local eye = originCF.Position
				if (eye - hitPoint).Magnitude < 0.04 then
					eye = hitPoint + Vector3.new(0, 0.12, 0)
				end
				local aim = CFrame.lookAt(eye, hitPoint)
				sendKnifeCameraRotation(util, aim)
				local encodedAim = util:EncodeCFrame(aim)
				local cameradata: { [string]: any } = {
					[K1] = {
						[K0] = encodedAim,
						[K1] = encodedAim,
						[K2] = hitPart,
						[K3] = util:EncodeCFrame(partCF:ToObjectSpace(CFrame.new(hitPoint))),
					},
				}
				local token = meleeNet.attack
				if token ~= nil then
					cameradata[K2] = token
				end
				return pcall(function()
					useItem:FireServer(objectId, actionEnum, cameradata, nil)
				end)
			end

			local function runMeleeMode(ctx: any): string
				local now = ctx.now
				local targetRoot: BasePart = ctx.targetRoot
				if activeSlot ~= 3 then
					activeSlot = 3
					ensureWeaponEquipped(true)
					return "equip melee"
				end
				local cycleCd = math.clamp(tonumber(ctx.fireRate) or 0, 0, 5)
				local standCF: CFrame
				if targetHoldsKnife(ctx.targetPlayer, now) then
					standCF = knifeUnderCF(targetRoot, targetRoot.Position)
				else
					local below = targetIsBelow(targetRoot, ctx.myRoot.Position)
					standCF = meleeStandCF(resolveHitbox(targetRoot, ctx.targetHead, false), below)
				end
				local ok, usedCF = applyDesync(standCF, true)
				if not ok or not usedCF then
					return "waiting safe"
				end
				if not atAttackPos(usedCF.Position, targetRoot.Position) then
					return "waiting near"
				end
				local root = getMyRoot()
				if root then
					pcall(function()
						root.AssemblyLinearVelocity = Vector3.zero
						root.AssemblyAngularVelocity = Vector3.zero
					end)
				end
				RageLive.hitPart = targetRoot
				local maxShots = math.clamp(shootAttempts(), 1, 20)
				local shots = 0
				while consumeBurstShot(now, cycleCd, true) and shots < maxShots do
					shots += 1
				end
				if shots <= 0 then
					return "melee inside"
				end
				local fired = false
				local aimPoint = targetRoot.Position
				for _ = 1, shots do
					if fireMeleeSlash(ctx.item, usedCF, targetRoot, aimPoint) then
						fired = true
					end
				end
				if fired then
					return if burstLeft > 0 then "melee burst" else "melee slash"
				end
				return "melee inside"
			end

			local directBodyAimCF: (BasePart, BasePart) -> CFrame

			local function alignBodyAt(cf: CFrame, targetRoot: BasePart): CFrame
				local aim = targetRoot.Position
				if (cf.Position - aim).Magnitude < 0.2 then
					aim += Vector3.new(0, 0, -1)
				end
				local aimed = CFrame.lookAt(cf.Position, aim)
				local root = getMyRoot()
				if root then
					root.CFrame = aimed
				end
				return aimed
			end

			local function runNoSkillMode(ctx: any): string
				local head: BasePart = ctx.targetHead
				local headPos = if ctx.bodyAim then ctx.targetRoot.Position else extrapolateRagePos(head)
				if isOutOfAmmo(ctx.item) then
					applyDesync(voidParkCF(ctx.myRoot, headPos))
					resetBurst()
					return handleNoAmmo(ctx.item, ctx.localFighter)
				end
				local scoped = isScopedGun(ctx.item)
				local cycleCd = ctx.fireRate
				if scoped then
					local ready, scopeStep = scopeReady(ctx.item, ctx.now, math.max(cycleCd, itemShotCooldown(ctx.item)))
					if not ready and burstLeft <= 0 then
						return voidParkStep(ctx, headPos, scopeStep)
					end
				elseif burstWaiting(ctx.now) then
					return voidParkStep(ctx, headPos, "no skill void")
				end
				local headLive = head.Position
				local origin = (head.CFrame * CFrame.new(0, 0.12, 0)).Position
				if (origin - headPos).Magnitude < 0.05 then
					origin = headLive + Vector3.new(0, 0.2, 0)
				end
				local aimCF: CFrame
				if targetHoldsKnife(ctx.targetPlayer, ctx.now) then
					aimCF = knifeUnderCF(ctx.targetRoot, headPos)
				elseif ctx.bodyAim then
					aimCF = directBodyAimCF(ctx.myRoot, ctx.targetRoot)
				else
					aimCF = CFrame.lookAt(origin, headPos)
				end
				local ok, safeCF = applyDesync(aimCF, true)
				if not ok or not safeCF then
					return "waiting safe"
				end
				if ctx.bodyAim and targetHoldsKnife(ctx.targetPlayer, ctx.now) ~= true then
					safeCF = alignBodyAt(safeCF, ctx.targetRoot)
					headPos = ctx.targetRoot.Position
				end
				if not atAttackPos(safeCF.Position, ctx.targetRoot.Position) then
					return "waiting near"
				end
				local shots = 0
				if shootInterval() <= 0 then
					while consumeBurstShot(ctx.now, cycleCd) and shots < 20 do
						shots += 1
					end
				elseif consumeBurstShot(ctx.now, cycleCd) then
					shots = 1
				end
				local shotPart = if ctx.bodyAim then ctx.targetRoot else (ctx.hitPart or head)
				local firedAny = shots > 0 and fireRageShot(ctx.item, safeCF.Position, shotPart, true, headPos, scoped or ctx.bodyAim == true, shots, ctx.bodyAim == true)
				if scoped and burstLeft <= 0 then
					cancelScope()
				end
				if firedAny then
					return if burstLeft > 0 then "no skill burst" else "no skill head"
				end
				return "no skill void"
			end

			local function resolveGunOrigin(ctx: any, hitLook: Vector3): (CFrame, string)
				local targetRoot: BasePart = ctx.targetRoot
				if targetHoldsKnife(ctx.targetPlayer, ctx.now) then
					return knifeUnderCF(targetRoot, hitLook), "desync under"
				end
				if Rage.evasionEnabled == true and Rage.underground then
					local cf = resolveUndergroundAttackCF(targetRoot, hitLook)
					if not cf then
						local under = targetRoot.Position + Vector3.new(0, math.clamp(Rage.undergroundY, -10, 1), 0)
						if (hitLook - under).Magnitude < 0.05 then
							under -= Vector3.new(0, 0.5, 0)
						end
						cf = CFrame.lookAt(under, hitLook)
					end
					return cf, "desync underground"
				end
				local mode = Rage.mode
				if mode == "Random" then
					local dir = Vector3.new(math.random() - 0.5, math.random() - 0.5, math.random() - 0.5)
					dir = if dir.Magnitude < 1e-3 then Vector3.yAxis else dir.Unit
					local pos = targetRoot.Position + dir * (0.5 + math.random() * 1.5)
					return CFrame.lookAt(pos, hitLook), "desync random"
				end
				return CFrame.lookAt((targetRoot.CFrame * CFrame.new(0, 1, 2)).Position, hitLook), "desync normal"
			end

			local losParams = RaycastParams.new()
			losParams.FilterType = Enum.RaycastFilterType.Exclude
			losParams.IgnoreWater = true
			local losIgnore: { Instance } = {}
			local function hasLineOfSight(from: Vector3, to: Vector3, ignore: { Instance }): boolean
				local dir = to - from
				if dir.Magnitude < 0.05 then
					return true
				end
				losParams.FilterDescendantsInstances = ignore
				return Workspace:Raycast(from, dir, losParams) == nil
			end

			local CLEAR_SHOT_OFFSETS = {
				CFrame.new(0, 1, 2),
				CFrame.new(0, 3.5, 0),
				CFrame.new(0, 1, -2),
				CFrame.new(2, 1, 0),
				CFrame.new(-2, 1, 0),
				CFrame.new(0, 6, 0),
			}
			local function fillShotIgnore(myChar: Instance?, targetChar: Instance?): { Instance }
				table.clear(losIgnore)
				if myChar then
					table.insert(losIgnore, myChar)
				end
				if targetChar then
					table.insert(losIgnore, targetChar)
				end
				return losIgnore
			end
			local BODY_AIM_GAP = 4
			directBodyAimCF = function(myRoot: BasePart, targetRoot: BasePart): CFrame
				local aim = targetRoot.Position
				local ignore = fillShotIgnore(myRoot.Parent, targetRoot.Parent)
				local facing = targetFacing(targetRoot)
				local side = Vector3.new(facing.Z, 0, -facing.X)
				local dirs: { Vector3 } = { facing, -facing, side, -side }
				local flat = Vector3.new(myRoot.Position.X - aim.X, 0, myRoot.Position.Z - aim.Z)
				if flat.Magnitude > 0.25 then
					table.insert(dirs, 1, flat.Unit)
				end
				for _, dir in dirs do
					local stand = aim + dir * BODY_AIM_GAP
					if hasLineOfSight(stand, aim, ignore) then
						return CFrame.lookAt(stand, aim)
					end
				end
				return CFrame.lookAt(aim + facing * BODY_AIM_GAP, aim)
			end

			local function resolveClearShotCF(ctx: any, hitPart: BasePart, aimPoint: Vector3): CFrame?
				local ignore = fillShotIgnore(ctx.myRoot.Parent, ctx.targetRoot.Parent)
				local rootCF: CFrame = ctx.targetRoot.CFrame
				for _, offset in CLEAR_SHOT_OFFSETS do
					local pos = (rootCF * offset).Position
					if hasLineOfSight(pos + SHOOT_EYE_OFFSET, hitPart.Position, ignore) and not isDangerRagePos(pos) then
						return CFrame.lookAt(pos, aimPoint)
					end
				end
				return nil
			end

			local function runGunMode(ctx: any, hitPart: BasePart, hitLook: Vector3): string
				if isOutOfAmmo(ctx.item) then
					resetBurst()
					return handleNoAmmo(ctx.item, ctx.localFighter)
				end
				local scoped = isScopedGun(ctx.item)
				if scoped then
					hitPart = resolveHitbox(ctx.targetRoot, ctx.targetHead, false)
					hitLook = extrapolateRagePos(hitPart)
				end

				local cycleCd = ctx.fireRate
				local firing: boolean
				local waitStep: string? = nil
				if scoped and burstLeft <= 0 then
					local ready, scopeStep = scopeReady(ctx.item, ctx.now, math.max(cycleCd, itemShotCooldown(ctx.item)))
					firing = ready
					if not ready then
						waitStep = scopeStep
					end
				else
					firing = shouldFireEncoded(not burstWaiting(ctx.now), 1 / 60)
				end

				local desyncCF: CFrame
				local desyncStep: string
				local knifeUnder = targetHoldsKnife(ctx.targetPlayer, ctx.now)
				if knifeUnder then
					desyncCF = knifeUnderCF(ctx.targetRoot, hitLook)
					desyncStep = "encoded under"
				elseif ctx.bodyAim then
					hitPart = ctx.targetRoot
					hitLook = ctx.targetRoot.Position
					desyncCF = directBodyAimCF(ctx.myRoot, ctx.targetRoot)
					desyncStep = "desync body"
				else
					local below = targetIsBelow(ctx.targetRoot, ctx.myRoot.Position)
					desyncCF = hitscanStandCF(hitPart, below)
					desyncStep = if below then "encoded below" else "encoded head"
					if firing then
						local eye = desyncCF.Position + SHOOT_EYE_OFFSET
						local ignore = fillShotIgnore(ctx.myRoot.Parent, ctx.targetRoot.Parent)
						if not hasLineOfSight(eye, hitPart.Position, ignore) then
							local clearCF = resolveClearShotCF(ctx, hitPart, hitLook)
							if clearCF then
								desyncCF = clearCF
								desyncStep = "encoded clear"
							end
						end
					end
				end
				local ok, usedCF = applyDesync(desyncCF, true)
				if not ok or not usedCF then
					return "waiting safe"
				end
				if ctx.bodyAim and not knifeUnder then
					usedCF = alignBodyAt(usedCF, ctx.targetRoot)
					hitLook = ctx.targetRoot.Position
				end
				if not atAttackPos(usedCF.Position, ctx.targetRoot.Position) then
					return "waiting near"
				end
				if not firing then
					return waitStep or (desyncStep .. " - cooldown")
				end
				local shots = 0
				if shootInterval() <= 0 then
					while consumeBurstShot(ctx.now, cycleCd) and shots < 20 do
						shots += 1
					end
				elseif consumeBurstShot(ctx.now, cycleCd) then
					shots = 1
				end
				local firedAny = shots > 0 and fireRageShot(ctx.item, usedCF.Position, hitPart, false, hitLook, scoped or ctx.bodyAim == true, shots, ctx.bodyAim == true)
				if scoped and burstLeft <= 0 then
					cancelScope()
				end
				if firedAny then
					if burstLeft > 0 then
						return "burst - " .. slotName(activeSlot)
					end
					return "firing - " .. slotName(activeSlot)
				end
				return desyncStep
			end

			local lastPreferMainAt = 0
			local lastEnsureEquipAt = 0
			local function rageStep(): (string, string?, Player?)
				local now = tick()
				local clock = os.clock()
				RageLive.knifeIn = nil
				refreshFrameContext()
				if Rage.skipDeflect then
					updateDeflection()
				end
				if clock - lastEnsureEquipAt >= 0.12 then
					lastEnsureEquipAt = clock
					ensureWeaponEquipped()
				end
				local voiding = updateVoidPhase(now)

				local myRoot = getMyRoot()
				if not myRoot then
					RageLive.hitPart = nil
					resetKnifeCycle()
					return "no root"
				end

				local targetPlayer, targetRoot, targetHead, graceP, dangerP = getClosestRageTarget(myRoot, now)
				if not (targetPlayer and targetRoot and targetHead) then
					RageLive.hitPart = nil
					resetKnifeCycle()
					cancelScope()
					if activeSlot ~= getConfiguredSlot() then
						resetToMainWeapon(nil)
						return "restart - return " .. slotName(activeSlot)
					end
					if graceP then
						return "skip invincible", graceP.Name, graceP
					end
					if dangerP then
						return "skip kill zone", dangerP.Name, dangerP
					end
					applyForcedCrouch(false)
					local idle = evadeCF(myRoot.Position, false)
					if idle and applyDesync(idle) then
						return if Rage.evasion == "Off" then "scanning" else "evade"
					end
					return "scanning"
				end

				local targetName = targetPlayer.Name
				local mode = Rage.mode
				local meleeAim = Rage.weaponSlot == "Melee" or Rage.weaponSlot == "Knife"
				local hitPart: BasePart = resolveHitbox(targetRoot, targetHead, meleeAim)
				RageLive.hitPart = hitPart

				if isTargetImmune(targetPlayer) then
					resetKnifeCycle()
					return "skip invincible", targetName, targetPlayer
				end
				if isStandingInKillZone(targetRoot) then
					resetKnifeCycle()
					return "skip kill zone", targetName, targetPlayer
				end

				if Rage.skipDeflect and deflecting[targetPlayer] then
					resetKnifeCycle()
					return "skip deflect", targetName, targetPlayer
				end

				local localFighter = getLocalFighter()
				if not localFighter then
					resetKnifeCycle()
					return "no fighter", targetName, targetPlayer
				end
				if clock - lastPreferMainAt >= 0.55 then
					lastPreferMainAt = clock
					if preferMainWeaponWithAmmo(localFighter) then
						return "switch to " .. slotName(activeSlot), targetName, targetPlayer
					end
				end
				local item = localFighter.EquippedItem
				local heldSlot = getHeldSlot(localFighter)
				if not item then
					return "equip " .. slotName(activeSlot), targetName, targetPlayer
				end
				if heldSlot ~= nil and heldSlot ~= activeSlot then
					return "equip " .. slotName(activeSlot), targetName, targetPlayer
				end

				local ctx = rageCtx
				ctx.now = now
				ctx.myRoot = myRoot
				ctx.targetPlayer = targetPlayer
				ctx.targetRoot = targetRoot
				ctx.targetHead = targetHead
				ctx.hitPart = hitPart
				ctx.localFighter = localFighter
				ctx.item = item
				ctx.fireRate = math.clamp(tonumber(Rage.fireRate) or 0, 0, 5)
				ctx.bodyAim = isBodyAimWeapon(item)
				if ctx.bodyAim then
					hitPart = targetRoot
					ctx.hitPart = targetRoot
					RageLive.hitPart = targetRoot
				end
				applyForcedCrouch(true)

				if voiding then
					return voidParkStep(ctx, ctx.targetHead.Position, "void park"), targetName, targetPlayer
				end
				if isKnifeWeapon() then
					return runKnifeMode(ctx), targetName, targetPlayer
				end
				if isMeleeWeapon() then
					if knifePhase == "stab" then
						resetKnifeCycle()
					end
					return runMeleeMode(ctx), targetName, targetPlayer
				end
				if knifePhase == "stab" then
					resetKnifeCycle()
				end

				local hitLook = if ctx.bodyAim then targetRoot.Position else extrapolateRagePos(hitPart)
				if mode == "No Skill" then
					return runNoSkillMode(ctx), targetName, targetPlayer
				end
				return runGunMode(ctx, hitPart, hitLook), targetName, targetPlayer
			end

			local function safePaint()
				local ok = pcall(paintRageStatus)
				if not ok then
					pcall(hideRageVisualizer)
				end
			end

			do
				local bindName = "sonataRageVisualizer"
				local bound = pcall(function()
					RunService:BindToRenderStep(bindName, Enum.RenderPriority.Last.Value, safePaint)
				end)
				if bound then
					table.insert(ears, {
						Disconnect = function()
							pcall(function()
								RunService:UnbindFromRenderStep(bindName)
							end)
							pcall(hideRageVisualizer)
						end,
					} :: any)
				else
					table.insert(ears, RunService.RenderStepped:Connect(safePaint))
				end
			end

			table.insert(ears, RunService.Heartbeat:Connect(function()
				desyncLocked = false
				if not Rage.enabled then
					if rageWasEnabled then
						rageWasEnabled = false
						rageWasInMatch = false
						pcall(shutdownRagebot)
						setRagePhysics(false)
						clearServerReplica()
						applyForcedCrouch(false)
					end
					return
				end
				if not rageWasEnabled then
					rageWasEnabled = true
					setRagePhysics(true)
					pcall(startRagebotEquip)
				end
				if not isInGameMatch() then
					if rageWasInMatch then
						rageWasInMatch = false
						pcall(softResetRageState, false)
					end
					RageLive.hitPart = nil
					if RageLive.step ~= "waiting match" then
						setRageStatus("waiting match", nil)
					end
					return
				end
				if not rageWasInMatch then
					rageWasInMatch = true
					pcall(startRagebotEquip)
				end

				local ok, step, targetName, targetPlayer = pcall(rageStep)
				if ok then
					setRageStatus(step or "scanning", targetName, targetPlayer)
				else
					local t = os.clock()
					if t - lastRageErrAt >= 5 then
						lastRageErrAt = t
						warn("ragebot ate dirt")
					end
					RageLive.hitPart = nil
					pcall(resetKnifeCycle)
					setRageStatus("scanning", nil)
				end
			end))

			local function antiAimUndergroundCF(myRoot: BasePart): CFrame
				local char = myRoot.Parent
				local yOff = math.clamp(tonumber(Rage.undergroundY) or -2, -10, 1)
				local _floor, hitPos = findFloorUnder(myRoot.Position, if char then { char } else {})
				local floorY: number
				if hitPos then
					floorY = hitPos.Y
				else
					local hum = char and char:FindFirstChildOfClass("Humanoid")
					local hip = if hum then hum.HipHeight else 2
					floorY = myRoot.Position.Y - hip - myRoot.Size.Y * 0.5
				end
				local pos = myRoot.Position
				return myRoot.CFrame.Rotation + Vector3.new(pos.X, floorY + yOff, pos.Z)
			end

			table.insert(ears, RunService.Heartbeat:Connect(function()
				if Rage.evasionEnabled ~= true or not Rage.underground or desyncRestoreBound or not isInGameMatch() then
					return
				end
				pcall(function()
					local myRoot = getMyRoot()
					local hum = myRoot and myRoot.Parent and myRoot.Parent:FindFirstChildOfClass("Humanoid")
					if not myRoot or not hum or hum.Health <= 0 then
						return
					end
					applyDesync(antiAimUndergroundCF(myRoot))
				end)
			end))

			local function startFakePosition()
				local nextBlink = 0
				local function stab(): number
					return math.clamp((tonumber(Rage.stability) or 0.15) / 1.5, 0.05, 1)
				end
				local function blinkWait(): number
					local speed = math.clamp(tonumber(Rage.fakeSpeed) or 96, 1, 100) / 100
					return (1 - speed) * 0.22 * stab()
				end
				local function reach(): number
					local radius = math.clamp(tonumber(Rage.fakeRadius) or 72, 2, 220)
					local intensity = math.clamp(tonumber(Rage.fakeIntensity) or 100, 0, 100) / 100
					local loose = 1 + (1 - stab()) * 2.4
					return radius * math.max(intensity, 0.35) * loose
				end
				local function pickFakeCF(origin: Vector3, rot: CFrame): CFrame?
					local dist = reach()
					local s = stab()
					for _ = 1, 12 do
						local ang = math.random() * math.pi * 2
						local flat = dist * (0.35 + math.random() * 0.65)
						local lift = (math.random() - 0.35) * dist * (0.4 + (1 - s))
						if s > 0.97 then
							lift = (if math.random() < 0.5 then 1 else -1) * dist
							flat = 0
						end
						local pos = origin + Vector3.new(math.cos(ang) * flat, lift, math.sin(ang) * flat)
						if not isDangerRagePos(pos) then
							return CFrame.new(pos) * rot
						end
					end
					return nil
				end
				local function blink()
					if inVoidPhase or not Rage.enabled or not Rage.fakePos or not isInGameMatch() then
						return
					end
					local now = os.clock()
					local waitFor = blinkWait()
					if waitFor > 0 and now < nextBlink then
						return
					end
					nextBlink = now + waitFor
					local root = getMyRoot()
					local hum = root and root.Parent and root.Parent:FindFirstChildOfClass("Humanoid")
					if not root or not hum or hum.Health <= 0 then
						return
					end
					local origin = root.Position
					local rot = root.CFrame.Rotation
					if desyncRestoreCF and (desyncLocked or desyncRestoreBound or sameSpot(root.CFrame, desyncShownCF)) then
						origin = desyncRestoreCF.Position
						rot = desyncRestoreCF.Rotation
					end
					local cf = pickFakeCF(origin, rot)
					if cf then
						applyDesync(cf)
					end
				end
				local pre = (RunService :: any).PreSimulation
				if typeof(pre) == "RBXScriptSignal" then
					table.insert(ears, pre:Connect(function()
						if inVoidPhase and Rage.enabled and Rage.voidSpam and isInGameMatch() then
							local root = getMyRoot()
							if root then
								applyDesync(voidParkCF(root, Vector3.zero), false, true)
							end
							return
						end
						blink()
					end))
				else
					table.insert(ears, RunService.Heartbeat:Connect(blink))
				end
			end
			startFakePosition()
			end
			end
			installRagebotRuntime()
		end

		do
			local function installTargetHudRuntime()
			local objs: any = nil
			local lastHealthRatio = -1
			local lastWeaponSig = ""
			local lastName = ""
			local previewWeaponIndex = 1
