				hpText.BackgroundTransparency = 1
				hpText.Font = Enum.Font.GothamBold
				hpText.TextSize = 12
				hpText.TextColor3 = Color3.fromRGB(190, 190, 205)
				hpText.TextXAlignment = Enum.TextXAlignment.Right
				hpText.Text = "100 / 100"
				hpText.Parent = panel

				local weaponsCont = Instance.new("Frame")
				weaponsCont.Name = "WeaponsContainer"
				weaponsCont.Position = UDim2.new(0, 10, 0, 66)
				weaponsCont.Size = UDim2.new(0, 350, 0, 46)
				weaponsCont.BackgroundTransparency = 1
				weaponsCont.Parent = panel

