					icon.Name = "Icon"
					icon.Size = UDim2.new(2.4, 0, 2.4, 0)
					icon.AnchorPoint = Vector2.new(0.5, 0.5)
					icon.Position = UDim2.new(0.5, 0, 0.5, 0)
					icon.BackgroundTransparency = 1
					icon.ScaleType = Enum.ScaleType.Crop
					icon.Image = ""
					icon.Parent = clip

					local nameLbl = Instance.new("TextLabel")
					nameLbl.Name = "NameLabel"
					nameLbl.Position = UDim2.new(0, 2, 0, 29)
					nameLbl.Size = UDim2.new(1, -4, 0, 15)
					nameLbl.BackgroundTransparency = 1
					nameLbl.Font = Enum.Font.GothamBold
					nameLbl.TextSize = 10
					nameLbl.TextColor3 = Color3.fromRGB(180, 180, 195)
					nameLbl.TextTruncate = Enum.TextTruncate.AtEnd
					nameLbl.Text = ""
					nameLbl.Parent = card

					cards[i] = {
						card = card,
						stroke = cStroke,
						icon = icon,
						label = nameLbl,
					}
				end

				panel.InputBegan:Connect(function(input: InputObject)
					if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
						dragging = true
						dragStart = UserInputService:GetMouseLocation()
						startPos = Vector2.new(panel.AbsolutePosition.X, panel.AbsolutePosition.Y)
					end
				end)

				table.insert(ears, UserInputService.InputChanged:Connect(function(input: InputObject)
					if not dragging or not dragStart or not startPos or not objs or not objs.panel then
						return
					end
					if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then
						return
					end
					local vp = hudViewport()
					local cur = UserInputService:GetMouseLocation()
					local delta = cur - dragStart
					local nextX = math.clamp(startPos.X + delta.X, 4, math.max(4, vp.X - panelW - 4))
					local nextY = math.clamp(startPos.Y + delta.Y, 4, math.max(4, vp.Y - panelH - 4))
					objs.panel.Position = UDim2.new(0, nextX, 0, nextY)
					Rage.targetHudX = (nextX + panelW * 0.5) / math.max(vp.X, 1)
					Rage.targetHudY = nextY / math.max(vp.Y, 1)
				end))

				table.insert(ears, UserInputService.InputEnded:Connect(function(input: InputObject)
					if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
						dragging = false
					end
				end))

				screen.Parent = parent

				objs = {
					screen = screen,
					panel = panel,
					topAccent = topAccent,
					avStroke = avStroke,
					headshot = headshot,
					headshotFallback = headshotFallback,
					nameLabel = nameLabel,
					hpFill = hpFill,
					hpText = hpText,
					cards = cards,
				}

				table.insert(ears, {
					Disconnect = function()
						if screen and screen.Parent then
							pcall(function() screen:Destroy() end)
						end
						objs = nil
					end,
				} :: any)

				return true
			end

			local lastAccentColor: Color3? = nil
			local function applyTheme()
				if not objs then return end
				local accent = getAccentColor()
				if accent == lastAccentColor then return end
				lastAccentColor = accent
				if objs.topAccent then objs.topAccent.BackgroundColor3 = accent end
				if objs.avStroke then objs.avStroke.Color = accent end
				if objs.hpFill then objs.hpFill.BackgroundColor3 = accent end
			end

			local lastPaintedHp = -1
			local function paintHealthBar()
				if not objs or not objs.hpFill then return end
				local r = math.clamp(displayHp, 0, 1)
				if math.abs(r - lastPaintedHp) < 0.002 then return end
				lastPaintedHp = r
				objs.hpFill.Size = UDim2.new(r, 0, 1, 0)
			end

			local function setHealthRatio(ratio: number, animate: boolean)
				ratio = math.clamp(ratio, 0, 1)
				if math.abs(ratio - lastHealthRatio) < 0.002 and animate then
					return
				end
				lastHealthRatio = ratio
				targetHp = ratio
				if not animate then
					displayHp = ratio
					paintHealthBar()
				end
			end

			local function setWeapons(items: { { name: string, icon: string? } }, highlight: number?)
				local sigParts = {}
				for _, it in ipairs(items) do
					table.insert(sigParts, it.name .. ":" .. (it.icon or ""))
				end
				local sig = table.concat(sigParts, ",") .. "|" .. tostring(highlight or 0)
				if sig == lastWeaponSig then
					return
				end
				lastWeaponSig = sig
				local accent = getAccentColor()
				for i = 1, 4 do
					local entry = objs and objs.cards and objs.cards[i]
					local item = items[i]
					if entry and item and item.name and item.name ~= "" then
						local isEquipped = (highlight == i)
						entry.card.Visible = true
						entry.label.Text = item.name
						entry.label.TextColor3 = if isEquipped then Color3.fromRGB(255, 255, 255) else Color3.fromRGB(180, 180, 195)
						entry.card.BackgroundColor3 = if isEquipped then Color3.fromRGB(30, 24, 42) else Color3.fromRGB(20, 20, 27)
						entry.stroke.Color = if isEquipped then accent else Color3.fromRGB(38, 38, 48)
						entry.stroke.Thickness = if isEquipped then 1.2 else 1
						local img = item.icon
						if not img or img == "" then
							if itemLib and type(itemLib.GetViewModelImage) == "function" then
								img = itemLib:GetViewModelImage(item.name)
							end
						end
						entry.icon.Image = img or ""
					elseif entry then
						entry.card.Visible = false
						entry.label.Text = ""
						entry.icon.Image = ""
					end
				end
			end

			local function readTargetWeapons(player: Player?): ({ { name: string, icon: string? } }, number?)
				local items: { { name: string, icon: string? } } = {}
				local equippedIndex: number? = nil
				if not player then
					return items, nil
				end
				pcall(function()
					local _f, _d, spectate = combatControllers()
					local duel = spectate and spectate.CurrentDuelSubject
					local dueler = duel and duel.GetDueler and duel:GetDueler(player)
					local fighter = dueler and dueler.ClientFighter
					if type(fighter) ~= "table" then
						return
					end
					local equippedName: string? = nil
					local eq = fighter.EquippedItem or (type(fighter.Get) == "function" and fighter:Get("EquippedItem"))
					if type(eq) == "string" then
						equippedName = eq
					elseif type(eq) == "table" then
						equippedName = eq.Name
					end
					if type(fighter.Items) == "table" then
						for _, item in fighter.Items do
							local n: string? = nil
							local img: string? = nil
							if type(item) == "table" then
								n = item.Name
								if item.ViewModel and type(item.ViewModel.GetImage) == "function" then
									img = item.ViewModel:GetImage()
								end
							elseif type(item) == "string" then
								n = item
							end
							if type(n) == "string" and n ~= "" then
								local already = false
								for _, existing in items do
									if existing.name == n then
										already = true
										break
									end
								end
								if not already then
									if not img or img == "" then
										if itemLib and type(itemLib.GetViewModelImage) == "function" then
											img = itemLib:GetViewModelImage(n)
										end
									end
									table.insert(items, { name = n, icon = img })
								end
							end
						end
					end
					if equippedName then
						for idx, entry in ipairs(items) do
							if entry.name == equippedName then
								equippedIndex = idx
								break
							end
						end
					end
				end)
				if #items == 0 then
					local char = player.Character
					if char then
						for _, child in char:GetChildren() do
							if child:IsA("Tool") then
								local n = child.Name
								local already = false
								for _, existing in items do
									if existing.name == n then
										already = true
										break
									end
								end
								if not already then
									local img: string? = nil
									if itemLib and type(itemLib.GetViewModelImage) == "function" then
										img = itemLib:GetViewModelImage(n)
									end
									table.insert(items, { name = n, icon = img })
								end
							end
						end
					end
				end
				while #items > 4 do
					table.remove(items)
				end
				return items, equippedIndex
			end

			local function showPreview(now: number)
				if not ensureHud() or not objs then return end
				setVisible(true)
				applyTheme()
				if not dragging then
					local p = panelPos()
					objs.panel.Position = UDim2.new(0, p.X, 0, p.Y)
				end
				local lp = Players.LocalPlayer
				local previewName = (lp and lp.DisplayName or "Preview") .. " (@" .. (lp and lp.Name or "preview") .. ")"
				if lastName ~= previewName then
					lastName = previewName
					objs.nameLabel.Text = previewName
					local uid = lp and lp.UserId or 1
					objs.headshot.Image = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(uid) .. "&w=150&h=150"
					objs.headshot.Visible = true
					objs.headshotFallback.Visible = false
				end
				if lastHealthRatio < 0 then
					previewHpDir = -1
					previewHpAt = now
					setHealthRatio(1, false)
				elseif now - previewHpAt > 1.2 then
					previewHpAt = now
					previewHpDir = -previewHpDir
					setHealthRatio(if previewHpDir > 0 then 1 else 0.25, true)
				end
				if now - previewWeaponAt > 1.5 then
					previewWeaponAt = now
					previewWeaponIndex = (previewWeaponIndex % #PREVIEW_WEAPONS) + 1
					local bag: { { name: string, icon: string? } } = {}
					for i = 0, 3 do
						local idx = ((previewWeaponIndex - 1 + i) % #PREVIEW_WEAPONS) + 1
						local wName = PREVIEW_WEAPONS[idx]
						local wIcon: string? = nil
						if itemLib and type(itemLib.GetViewModelImage) == "function" then
							wIcon = itemLib:GetViewModelImage(wName)
						end
						table.insert(bag, { name = wName, icon = wIcon })
					end
					lastWeaponSig = ""
					setWeapons(bag, 1)
				elseif lastWeaponSig == "" then
					local bag: { { name: string, icon: string? } } = {}
					for i = 1, 4 do
						local wName = PREVIEW_WEAPONS[i]
						local wIcon: string? = nil
						if itemLib and type(itemLib.GetViewModelImage) == "function" then
							wIcon = itemLib:GetViewModelImage(wName)
						end
						table.insert(bag, { name = wName, icon = wIcon })
					end
					setWeapons(bag, 1)
				end
			end

			local lastTargetWeaponsAt = 0
			local lastWeaponsTargetPlayer = nil
			local function showLive()
				if not ensureHud() or not objs then return end
				local player = RageLive.targetPlayer
				if not player or not player.Parent then
					setVisible(false)
					return
				end
				setVisible(true)
				applyTheme()
				if not dragging then
					local p = panelPos()
					objs.panel.Position = UDim2.new(0, p.X, 0, p.Y)
				end
				local display = player.DisplayName
				if type(display) ~= "string" or display == "" then
					display = player.Name
				end
				local fullTitle = display .. " (@" .. player.Name .. ")"
				if fullTitle ~= lastName then
					lastName = fullTitle
					objs.nameLabel.Text = fullTitle
					if player.UserId and player.UserId > 0 then
						objs.headshot.Image = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(player.UserId) .. "&w=150&h=150"
						objs.headshot.Visible = true
						objs.headshotFallback.Visible = false
					else
						objs.headshot.Visible = false
						objs.headshotFallback.Visible = true
						objs.headshotFallback.Text = string.upper(string.sub(display, 1, 1))
					end
				end
				local char = player.Character
				local hum = char and char:FindFirstChildOfClass("Humanoid")
				local hp = RageLive.health or (hum and hum.Health) or 0
				local maxHp = (hum and hum.MaxHealth) or 100
				if maxHp < 1 then maxHp = 100 end
				setHealthRatio(math.clamp(hp / maxHp, 0, 1), true)
				objs.hpText.Text = string.format("%d / %d", math.floor(hp + 0.5), math.floor(maxHp + 0.5))
				local now = os.clock()
				if player ~= lastWeaponsTargetPlayer or now - lastTargetWeaponsAt > 0.25 then
					lastWeaponsTargetPlayer = player
					lastTargetWeaponsAt = now
					local weapons, equipped = readTargetWeapons(player)
					setWeapons(weapons, equipped)
				end
			end

			table.insert(ears, RunService.RenderStepped:Connect(function(dt)
				if not Rage.targetHud then
					setVisible(false)
					inPreview = false
					return
				end
				local now = os.clock()
				if menuIsOpen() then
					if not inPreview then
						inPreview = true
						lastWeaponSig = ""
						lastHealthRatio = -1
						lastName = ""
						previewWeaponAt = 0
						previewHpAt = 0
						displayHp = 1
						targetHp = 1
					end
					showPreview(now)
				elseif Rage.enabled and RageLive.targetPlayer then
					inPreview = false
					showLive()
				else
					inPreview = false
					setVisible(false)
					lastWeaponSig = ""
					lastHealthRatio = -1
					lastName = ""
					return
				end
				local alpha = 1 - math.exp(-(dt or 0.016) * 12)
				displayHp = displayHp + (targetHp - displayHp) * alpha
				if math.abs(displayHp - targetHp) < 0.001 then
					displayHp = targetHp
				end
				paintHealthBar()
				if inPreview and objs and objs.hpText then
					local hpVal = math.floor(math.clamp(displayHp, 0, 1) * 100 + 0.5)
					if hpVal ~= lastPreviewHpVal then
						lastPreviewHpVal = hpVal
						objs.hpText.Text = string.format("%d / 100", hpVal)
					end
				end
			end))
			end
			installTargetHudRuntime()
		end

		do
			local function installMovementRuntime()
			local mechCache: any = nil
			local mechHooked = false
			local oldGetWalkSpeed: any = nil
			local oldDoubleJumpRequest: any = nil
			local noclipParts: { [BasePart]: boolean } = {}
			local flyBv: BodyVelocity? = nil

			local function speedBlocksSlide(): boolean
				return (Movement.speed == true or Movement.velocity == true) and Movement.slide ~= true
			end

			local function mechIsSliding(mech: any): boolean
				if not mech then
					return false
				end
				local ok, sliding = pcall(function()
					local v = mech.IsSliding
					if type(v) == "function" then
						return mech:IsSliding() == true
					end
					return v == true
				end)
				return ok and sliding == true
			end

			local function forceStopSlide(mech: any)
				if not mech or not speedBlocksSlide() then
					return
				end
				pcall(function()
					if type(mech.StopSliding) == "function" then
						mech:StopSliding()
					end
				end)
				pcall(function()
					mech.IsSliding = false
				end)
				pcall(function()
					local fighter = mech.LocalFighter
					if fighter and type(fighter.Set) == "function" then
						fighter:Set("IsSliding", false)
						fighter:Set("Sliding", false)
						fighter:Set("SlidingSpeedMax", 0)
					end
				end)
			end

			local function getMechanics(): any?
				if mechCache then
					return mechCache
				end
				local lp = Players.LocalPlayer
				local scripts = lp and lp:FindFirstChild("PlayerScripts")
				local controllers = scripts and scripts:FindFirstChild("Controllers")
				local mod = controllers and controllers:FindFirstChild("MechanicsController")
				if not mod then
					return nil
				end
				local ok, loaded = pcall(require, mod)
				if ok and type(loaded) == "table" then
					mechCache = loaded
					return loaded
				end
				return nil
			end

			local slideHookNames = { "Slide", "StartSliding", "BeginSlide", "TrySlide", "SlideRequest", "EasySlide" }
			local oldSlideFns: { [string]: any } = {}

			local function ensureMechHooks()
				if mechHooked then
					return
				end
				local mech = getMechanics()
				if not mech then
					return
				end
				if type(mech._GetWalkSpeed) == "function" then
					oldGetWalkSpeed = mech._GetWalkSpeed
					mech._GetWalkSpeed = function(self, ...)
						local base = oldGetWalkSpeed(self, ...)
						if type(base) ~= "number" then
							return base
						end
						if Movement.speed then
							return base * math.clamp(Movement.walkMulti, 0.5, 8)
						end
						return base
					end
				end
				if type(mech.DoubleJumpRequest) == "function" then
					oldDoubleJumpRequest = mech.DoubleJumpRequest
					mech.DoubleJumpRequest = function(self, ...)
						if Movement.infJump then
							if type(self.IsAlive) == "function" and not self:IsAlive() then
								return
							end
							local fighter = self.LocalFighter
							if fighter and type(fighter.IsGrounded) == "function" and not fighter:IsGrounded() then
								if type(self._double_jumps_used) == "table" then
									table.clear(self._double_jumps_used)
								end
								if type(self.DoubleJump) == "function" then
									self:DoubleJump()
								end
								return
							end
						end
						return oldDoubleJumpRequest(self, ...)
					end
				end
				for _, name in slideHookNames do
					if type(mech[name]) == "function" and oldSlideFns[name] == nil then
						local original = mech[name]
						oldSlideFns[name] = original
						mech[name] = function(self, ...)
							if speedBlocksSlide() then
								return
							end
							return original(self, ...)
						end
					end
				end
				mechHooked = true
			end

			local function keyNameMatches(input: InputObject, keyName: string?): boolean
				if type(keyName) ~= "string" or keyName == "" or keyName == "None" or keyName == "NONE" then
					return false
				end
				if keyName == "MouseButton1" then
					return input.UserInputType == Enum.UserInputType.MouseButton1
				elseif keyName == "MouseButton2" then
					return input.UserInputType == Enum.UserInputType.MouseButton2
				elseif keyName == "MouseButton3" then
					return input.UserInputType == Enum.UserInputType.MouseButton3
				end
				return input.KeyCode.Name == keyName
			end

			local function setRageEnabled(on: boolean)
				if Rage.enabled == on then
					return
				end
				Rage.enabled = on
				if on then
					if DrawingBridge.startRagebotEquip then
						pcall(DrawingBridge.startRagebotEquip)
					end
				elseif DrawingBridge.shutdownRagebot then
					pcall(DrawingBridge.shutdownRagebot)
				end
				if DrawingBridge.requestSync then
					pcall(DrawingBridge.requestSync)
				end
			end

			table.insert(ears, UserInputService.InputBegan:Connect(function(input: InputObject, processed: boolean)
				if processed or UserInputService:GetFocusedTextBox() then
					return
				end
				if keyNameMatches(input, Rage.keyName) then
					setRageEnabled(not Rage.enabled)
				end
				if keyNameMatches(input, Silent.keyName) then
					Silent.enabled = not Silent.enabled
					if DrawingBridge.requestSync then
						pcall(DrawingBridge.requestSync)
					end
				end
				if keyNameMatches(input, Movement.speedKey) then
					Movement.speed = not Movement.speed
					if DrawingBridge.requestSync then
						pcall(DrawingBridge.requestSync)
					end
				end
				if keyNameMatches(input, Movement.slideKey) then
					Movement.slide = not Movement.slide
					if DrawingBridge.requestSync then
						pcall(DrawingBridge.requestSync)
					end
				end
				if keyNameMatches(input, Movement.infJumpKey) then
					Movement.infJump = not Movement.infJump
					if DrawingBridge.requestSync then
						pcall(DrawingBridge.requestSync)
					end
				end
				if keyNameMatches(input, Movement.flyKey) then
					Movement.fly = not Movement.fly
					if DrawingBridge.requestSync then
						pcall(DrawingBridge.requestSync)
					end
				end
				if keyNameMatches(input, Movement.noclipKey) then
					Movement.noclip = not Movement.noclip
					if DrawingBridge.requestSync then
						pcall(DrawingBridge.requestSync)
					end
				end
				if keyNameMatches(input, Movement.velocityKey) then
					Movement.velocity = not Movement.velocity
					if DrawingBridge.requestSync then
						pcall(DrawingBridge.requestSync)
					end
				end
			end))

			local function clearNoclip()
				if next(noclipParts) == nil then
					return
				end
				for part, was in noclipParts do
					if part.Parent then
						pcall(function()
							part.CanCollide = was
						end)
					end
				end
				table.clear(noclipParts)
			end

			local function applyNoclip(char: Model)
				for _, inst in char:GetChildren() do
					if inst:IsA("BasePart") then
						if noclipParts[inst] == nil then
							noclipParts[inst] = inst.CanCollide
						end
						if inst.CanCollide then
							inst.CanCollide = false
						end
					end
				end
			end

			local function destroyFly()
				if flyBv then
					pcall(function()
						flyBv:Destroy()
					end)
					flyBv = nil
				end
			end

			local function movementTick(_dt: number)
				ensureMechHooks()
				local mech = getMechanics()
				if mech and type(mech._UpdateWalkSpeed) == "function" and (Movement.speed or mechHooked) then
					pcall(function()
						mech:_UpdateWalkSpeed()
					end)
				end
				forceStopSlide(mech)
				if mech and Movement.slide and mechIsSliding(mech) and mech.LocalFighter then
					pcall(function()
						local fighter = mech.LocalFighter
						if type(fighter.Set) == "function" then
							fighter:Set("SlidingSpeedMax", math.clamp(Movement.slideMulti, 1, 12))
						end
					end)
				end

				local lp = Players.LocalPlayer
				local char = lp and lp.Character
				local root = char and char:FindFirstChild("HumanoidRootPart")
				local hum = char and char:FindFirstChildOfClass("Humanoid")
				if not char or not root or not root:IsA("BasePart") then
					destroyFly()
					clearNoclip()
					return
				end

				if Movement.noclip then
					applyNoclip(char)
				else
					clearNoclip()
				end

				if Movement.velocity and not Movement.fly then
					forceStopSlide(mech)
					local target = math.clamp(Movement.velocitySpeed, 5, 250)
					local vel = root.AssemblyLinearVelocity
					local flat = Vector3.new(vel.X, 0, vel.Z)
					local dir: Vector3? = nil
					if hum and hum.MoveDirection.Magnitude > 0.05 then
						dir = hum.MoveDirection.Unit
					elseif flat.Magnitude > 0.05 then
						dir = flat.Unit
					end
					if dir then
						local nextVel = Vector3.new(dir.X * target, vel.Y, dir.Z * target)
						root.AssemblyLinearVelocity = nextVel
						pcall(function()
							(root :: any).Velocity = nextVel
						end)
					end
					forceStopSlide(mech)
				end

				if Movement.fly then
					local cam = Workspace.CurrentCamera
					if not cam then
						return
					end
					if hum then
						pcall(function()
							hum.PlatformStand = true
						end)
					end
					if not flyBv or not flyBv.Parent then
						local bv = Instance.new("BodyVelocity")
						bv.MaxForce = Vector3.new(1e5, 1e5, 1e5)
						bv.P = 1e4
						bv.Velocity = Vector3.zero
						bv.Parent = root
						flyBv = bv
					end
					local look = cam.CFrame.LookVector
					local right = cam.CFrame.RightVector
					local move = Vector3.zero
					if UserInputService:IsKeyDown(Enum.KeyCode.W) then
						move += look
					end
					if UserInputService:IsKeyDown(Enum.KeyCode.S) then
						move -= look
					end
					if UserInputService:IsKeyDown(Enum.KeyCode.D) then
						move += right
					end
					if UserInputService:IsKeyDown(Enum.KeyCode.A) then
						move -= right
					end
					if UserInputService:IsKeyDown(Enum.KeyCode.Space) then
						move += Vector3.yAxis
					end
					if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.C) then
						move -= Vector3.yAxis
					end
					local speed = math.clamp(Movement.flySpeed, 5, 500)
					if move.Magnitude > 0 then
						flyBv.Velocity = move.Unit * speed
					else
						flyBv.Velocity = Vector3.zero
					end
				else
					destroyFly()
					if hum and hum.PlatformStand then
						pcall(function()
							hum.PlatformStand = false
						end)
					end
				end
			end

			table.insert(ears, RunService.RenderStepped:Connect(movementTick))
			pcall(function()
				RunService:BindToRenderStep("__sonata_anti_slide", Enum.RenderPriority.Last.Value, function()
					if speedBlocksSlide() then
						forceStopSlide(getMechanics())
					end
				end)
			end)
			table.insert(ears, {
				Disconnect = function()
					pcall(function()
						RunService:UnbindFromRenderStep("__sonata_anti_slide")
					end)
					destroyFly()
					clearNoclip()
					local mech = mechCache
					if mech and mechHooked then
						if oldGetWalkSpeed then
							mech._GetWalkSpeed = oldGetWalkSpeed
						end
						if oldDoubleJumpRequest then
							mech.DoubleJumpRequest = oldDoubleJumpRequest
						end
						for name, original in oldSlideFns do
							mech[name] = original
						end
					end
				end,
			} :: any)
			end
			installMovementRuntime()
		end

		do
			local function installExploitsRuntime()
			local originals: { [any]: { [string]: any } } = {}
			local gunHooked = false
			local previousAim: any = nil

			local function cooldownFromSpeed(speed: number): number
				local t = math.clamp(speed, 1, 100) / 100
				return math.max(1e-15, 0.08 * (1 - t) + 1e-15 * t)
			end

			local GUN_KEYS = { "ShootCooldown", "BurstCooldown" }
			local MELEE_KEYS = { "AttackCooldown", "HeavyAttackCooldown" }
			local RECOIL_KEYS = {
				"Recoil",
				"RecoilKick",
				"RecoilScale",
				"VerticalRecoil",
				"HorizontalRecoil",
				"CameraRecoil",
				"AimRecoil",
				"Kick",
				"KickScale",
				"RecoilPattern",
				"RecoilStrength",
				"CameraKick",
			}

			local function remember(tbl: any, key: string, value: any)
				local bag = originals[tbl]
				if not bag then
					bag = {}
					originals[tbl] = bag
				end
				if bag[key] == nil then
					bag[key] = value
				end
			end

			local function restoreAll()
				for tbl, bag in originals do
					if type(tbl) == "table" and type(bag) == "table" then
						for key, value in bag do
							pcall(function()
								tbl[key] = value
							end)
						end
					end
				end
			end

			local function restoreKeyGroup(keys: { string })
				for tbl, bag in originals do
					if type(tbl) == "table" and type(bag) == "table" then
						for _, keyName in keys do
							local original = bag[keyName]
							if original ~= nil then
								pcall(function()
									tbl[keyName] = original
								end)
							end
						end
					end
				end
			end

			local function patchLibrary()
				local ok, itemLibrary = pcall(function()
					return require(ReplicatedStorage.Modules.ItemLibrary)
				end)
				if not ok or type(itemLibrary) ~= "table" then
					return
				end
				local gunCd = cooldownFromSpeed(Exploits.gunSpeed)
				local meleeCd = cooldownFromSpeed(Exploits.meleeSpeed)

				local function scan(tbl: any, depth: number)
					if type(tbl) ~= "table" or depth > 8 then
						return
					end
					for key, value in tbl do
						if type(value) == "number" then
							local keyName = tostring(key)
							if table.find(GUN_KEYS, keyName) then
								remember(tbl, keyName, value)
								if Exploits.gunRapid then
									tbl[key] = gunCd
								end
							elseif table.find(MELEE_KEYS, keyName) then
								remember(tbl, keyName, value)
								if Exploits.meleeRapid then
									tbl[key] = meleeCd
								end
							elseif Exploits.noRecoil and table.find(RECOIL_KEYS, keyName) then
								remember(tbl, keyName, value)
								tbl[key] = 0
							end
						elseif type(value) == "table" then
							if Exploits.noRecoil and type(key) == "string" and string.find(string.lower(key), "recoil", 1, true) then
								for nestedKey, nestedVal in value do
									if type(nestedVal) == "number" then
										remember(value, tostring(nestedKey), nestedVal)
										value[nestedKey] = 0
									elseif typeof(nestedVal) == "Vector3" then
										remember(value, tostring(nestedKey), nestedVal)
										value[nestedKey] = Vector3.zero
									end
								end
							end
							scan(value, depth + 1)
						elseif Exploits.noRecoil and typeof(value) == "Vector3" then
							local keyName = tostring(key)
							if string.find(string.lower(keyName), "recoil", 1, true) or string.find(string.lower(keyName), "kick", 1, true) then
								remember(tbl, keyName, value)
								tbl[key] = Vector3.zero
							end
						end
					end
				end
				scan(itemLibrary, 0)
			end

			local function syncExploits()
				restoreAll()
				if Exploits.gunRapid or Exploits.meleeRapid or Exploits.noRecoil then
					patchLibrary()
				else
					restoreKeyGroup(GUN_KEYS)
					restoreKeyGroup(MELEE_KEYS)
				end
			end

			local function ensureNoSpreadHook()
				if gunHooked then
					return
				end
				local ok, gun = pcall(function()
					local lp = Players.LocalPlayer
					return require((lp :: Player).PlayerScripts.Modules.ItemTypes.Gun)
				end)
				if not ok or type(gun) ~= "table" or type(gun.IsFullyAiming) ~= "function" then
					return
				end
				previousAim = gun.IsFullyAiming
				gun.IsFullyAiming = function(self, ...)
					if SESSION.alive and (Silent.enabled or Exploits.noSpread) then
						return true
					end
					if type(previousAim) == "function" then
						return previousAim(self, ...)
					end
					return false
				end
				gunHooked = true
			end

			local meleeReachHooked = false
			local function meleeReachScale(): number
				return math.clamp(tonumber(Exploits.meleeReach) or 2, 1, 8)
			end
			local function ensureMeleeReachHook()
				if meleeReachHooked then
					return
				end
				local lp = Players.LocalPlayer
				if not lp then
					return
				end
				local ok, melee = pcall(function()
					return require(lp.PlayerScripts.Modules.ItemTypes.Melee)
				end)
				if not ok or type(melee) ~= "table" then
					return
				end
				local slash = melee._ImpactMarkerSlash
				if type(slash) ~= "function" then
					local okMt, mt = pcall(getmetatable, melee)
					local parent = if okMt and type(mt) == "table" then mt.__index else nil
					if type(parent) == "table" then
						slash = parent._ImpactMarkerSlash
					end
				end
				if type(slash) ~= "function" or not hookGameMethod(slash, function(old, self, reach, ...)
					if Exploits.meleeRange and type(reach) == "number" then
						reach = reach * meleeReachScale()
					end
					return old(self, reach, ...)
				end) then
					return
				end
				if type(melee.GetAutoShootReach) == "function" then
					hookGameMethod(melee.GetAutoShootReach, function(old, self, ...)
						local reach = old(self, ...)
						if Exploits.meleeRange and type(reach) == "number" then
							return reach * meleeReachScale()
						end
						return reach
					end)
				end
				meleeReachHooked = true
			end

			local lastPatch = 0
			local lastGunRapid = Exploits.gunRapid
			local lastMeleeRapid = Exploits.meleeRapid
			local lastNoRecoil = Exploits.noRecoil
			table.insert(ears, RunService.Heartbeat:Connect(function()
				ensureNoSpreadHook()
				ensureMeleeReachHook()
				local now = os.clock()
				local toggled = lastGunRapid ~= Exploits.gunRapid
					or lastMeleeRapid ~= Exploits.meleeRapid
					or lastNoRecoil ~= Exploits.noRecoil
				if toggled then
					lastGunRapid = Exploits.gunRapid
					lastMeleeRapid = Exploits.meleeRapid
					lastNoRecoil = Exploits.noRecoil
					lastPatch = now
					syncExploits()
					return
				end
				if now - lastPatch < 0.75 then
					return
				end
				lastPatch = now
				syncExploits()
			end))
			table.insert(ears, {
				Disconnect = function()
					restoreAll()
					table.clear(originals)
					if gunHooked and type(previousAim) == "function" then
						pcall(function()
							local lp = Players.LocalPlayer
							local gun = require((lp :: Player).PlayerScripts.Modules.ItemTypes.Gun)
							gun.IsFullyAiming = previousAim
						end)
						gunHooked = false
					end
				end,
			} :: any)

			local function nudgeExploits()
				lastPatch = 0
				lastGunRapid = Exploits.gunRapid
				lastMeleeRapid = Exploits.meleeRapid
				lastNoRecoil = Exploits.noRecoil
				syncExploits()
			end
			table.insert(combatPaint, nudgeExploits)
			DrawingBridge.nudgeExploits = nudgeExploits
			end
			installExploitsRuntime()
		end

		DrawingBridge.builders.combat = function(kit: any)
			local function nudge(_value: any?)
				local fn = DrawingBridge.nudgeExploits
				if fn then
					pcall(fn)
				end
			end
			local function filterFonts(query: string): { string }
				local names = DrawingBridge.EspFontNames
				if type(names) ~= "table" or #names == 0 then
					names = { "Plex", "UI", "System", "Monospace" }
				end
				local q = string.lower(tostring(query or ""))
				if q == "" then
					return names
				end
				local out = {}
				for _, name in names do
					if string.find(string.lower(tostring(name)), q, 1, true) then
						table.insert(out, name)
					end
				end
				return if #out > 0 then out else names
			end
			local function bindFontSearch(list: any, getQuery: () -> string, getSelected: () -> string)
				local stamp = ""
				table.insert(DrawingBridge.syncers, function()
					if not list then
						return
					end
					local names = filterFonts(getQuery())
					local nextStamp = tostring(getQuery()) .. "#" .. #names .. "#" .. tostring(names[1]) .. "#" .. tostring(names[#names])
					pcall(function()
						if stamp ~= nextStamp then
							stamp = nextStamp
							if list.SetValues then
								list:SetValues(names)
							else
								list:ClearValues()
								for _, name in names do
									list:AddValue(name)
								end
							end
						end
						list:Select(tostring(getSelected()), true)
					end)
				end)
			end

			Flick.enabled = false

			local rageTab = kit.tab("rage")
			local rage = rageTab:AddSection("ragebot", 1)
			local rageRefresh: () -> ()
			if Rage.engine ~= "V1" then
				Rage.engine = "V2"
			end
			local rageEngine = kit.choice(rage, "version", { "V1", "V2" }, function()
				return if Rage.engine == "V1" then "V1" else "V2"
			end, function(value: string)
				Rage.engine = if string.lower(value) == "v1" then "V1" else "V2"
				if Rage.engine == "V1" and DrawingBridge.clearRageServer then
					pcall(DrawingBridge.clearRageServer)
				end
				if rageRefresh then
					rageRefresh()
				end
			end)
			kit.flag(rage, "enabled", Rage, "enabled", nil, function(on: boolean)
				if on == true then
					if DrawingBridge.startRagebotEquip then
						pcall(DrawingBridge.startRagebotEquip)
					end
				elseif DrawingBridge.shutdownRagebot then
					pcall(DrawingBridge.shutdownRagebot)
				end
				rageRefresh()
			end)
			local rageKey = kit.bind(rage, "keybind", function()
				return Rage.keyName
			end, function(name: string)
				Rage.keyName = name
			end, {
				label = "ragebot",
				active = function()
					return Rage.enabled == true
				end,
			})
			if Rage.mode == "Knife" then
				Rage.mode = "Normal"
				Rage.weaponSlot = "Knife"
			end
			if Rage.weaponSlot == "Free" then
				Rage.weaponSlot = "Primary"
			end
			Rage.weaponsEnabled.Primary = true
			Rage.weaponsEnabled.Secondary = true
			local rageHackers = kit.flag(rage, "prioritize hackers", Rage, "prioritizeHackers")
			local rageStab = kit.number(rage, "stability", Rage, "stability", 0, 1500, 1, { scale = 1000, suffix = "ms" })
			local rageFrames = kit.number(rage, "shoot frames", Rage, "shootFrames", 1, 5, 1)
			local rageAttempts = kit.number(rage, "shoot attempts", Rage, "shootAttempts", 1, 20, 1)
			local rageInterval = kit.number(rage, "shoot interval", Rage, "shootInterval", 0, 1000, 1, { scale = 1000, suffix = "ms" })
			local rageKnifeInt = kit.number(rage, "knife interval", Rage, "knifeInterval", 100, 5000, 10, { scale = 1000, suffix = "ms" })
			local rageMelee = kit.flag(rage, "melee", Rage.weaponsEnabled, "Melee", nil, function()
				if rageRefresh then rageRefresh() end
			end)
			local rageWeapon = kit.choice(rage, "priority", { "Primary", "Secondary", "Melee" }, function()
				return tostring(Rage.weaponPriority[1] or Rage.weaponSlot or "Primary")
			end, function(value: string)
				Rage.weaponSlot = value
				local rest = {}
				for _, name in { "Primary", "Secondary", "Melee" } do
					if name ~= value then
						table.insert(rest, name)
					end
				end
				Rage.weaponPriority = { value, table.unpack(rest) }
				if Rage.enabled and DrawingBridge.startRagebotEquip then
					pcall(DrawingBridge.startRagebotEquip)
				end
				if rageRefresh then
					rageRefresh()
				end
			end)
			local rageNoAmmo = kit.choice(rage, "on empty", { "Reload", "Swap", "Swap or Reload" }, function()
				local v = tostring(Rage.onEmpty or "SwapOrReload")
				if v == "Reload" then
					return "Reload"
				end
				if v == "Swap" then
					return "Swap"
				end
				return "Swap or Reload"
			end, function(value: string)
				local action = string.lower(value)
				if action == "reload" then
					Rage.onEmpty = "Reload"
					Rage.noAmmoAction = "force reload"
				elseif action == "swap" then
					Rage.onEmpty = "Swap"
					Rage.noAmmoAction = "switch to melee"
				else
					Rage.onEmpty = "SwapOrReload"
					Rage.noAmmoAction = "switch to other"
				end
			end)
			local rageCycle: any
			local ragePriority = kit.choice(rage, "targeting", RAGE_TARGET_PRIORITIES, function()
				return Rage.targetPriority
			end, function(value: string)
				local p = string.lower(value)
				if p == "lowest health" or p == "health" then
					Rage.targetPriority = "Lowest Health"
				elseif p == "cheater" or p == "cheaters" then
					Rage.targetPriority = "Cheater"
				elseif p == "crosshair" or p == "fov" then
					Rage.targetPriority = "Crosshair"
				elseif p == "cycle" then
					Rage.targetPriority = "Cycle"
				else
					Rage.targetPriority = "Closest"
				end
				if rageRefresh then
					rageRefresh()
				end
			end)
			rageCycle = kit.number(rage, "cycle interval", Rage, "cycleInterval", 200, 10000, 50, { scale = 1000, suffix = "ms" })
			local rageFire = kit.number(rage, "fire rate", Rage, "fireRate", 0, 1000, 1, { scale = 1000, suffix = "ms" })
			local rageDist = kit.number(rage, "max distance", Rage, "maxDistance", 50, 1000, 10)
			local rageSkip = kit.flag(rage, "skip deflecting", Rage, "skipDeflect")
			local rageExtraAmt: any
			local rageExtra = kit.flag(rage, "extrapolation", Rage, "extrapolation", nil, function()
				rageRefresh()
			end)
			rageExtraAmt = kit.number(rage, "extrapolation amount", Rage, "extrapolationAmount", 0, 250, 5, { suffix = "%" })
			rageRefresh = function()
				local on = Rage.enabled == true
				local v2 = on and Rage.engine ~= "V1"
				for _, opt in { rageKey, rageHackers, rageStab, rageAttempts, rageInterval, rageKnifeInt, rageMelee, rageWeapon, rageNoAmmo, ragePriority, rageFire, rageDist, rageSkip, rageExtra } do
					opt.enabled = on
				end
				rageEngine.enabled = on
				rageFrames.enabled = v2
				rageKey.enabled = true
				rageCycle.enabled = on and Rage.targetPriority == "Cycle"
				rageExtraAmt.enabled = on and Rage.extrapolation
				pcall(function()
					rage:UpdateOptions()
					rageTab:UpdateSections()
				end)
			end
			table.insert(DrawingBridge.syncers, rageRefresh)
			rageRefresh()

			local evadeBox = rageTab:AddSection("evasion", 1)
			local evadeRefresh: () -> ()
			local evNow = tostring(Rage.evasion or "Scatter")
			if evNow == "Random" or evNow == "ProjectileBreaker" or evNow == "Translocate" then
				Rage.evasion = if evNow == "Translocate" then "Sky" else "Scatter"
			end
			Rage.evasionEnabled = Rage.evasionEnabled == true
			Rage.underground = Rage.underground == true
			kit.flag(evadeBox, "enabled", Rage, "evasionEnabled", nil, function(on: boolean)
