				if v == "off" then
					Rage.evasion = "Off"
				elseif v == "orbit" then
					Rage.evasion = "Orbit"
				elseif v == "sky" then
					Rage.evasion = "Sky"
				elseif v == "underground" then
					Rage.evasion = "Underground"
				else
					Rage.evasion = "Scatter"
				end
				if evadeRefresh then
					evadeRefresh()
				end
			end)
			local evadeRadius = kit.number(evadeBox, "radius", Rage, "evasionRadius", 5, 100000, 1)
			local evadeRand = kit.number(evadeBox, "random", Rage, "evasionRandom", 0, 1, 0.1)
			local evadeDepth = kit.number(evadeBox, "depth", Rage, "translocateOffset", -80, -1, 0.5)
