				evadeMode.enabled = on
				evadeRadius.enabled = on and (ev == "Scatter" or ev == "Orbit" or ev == "Sky")
				evadeRand.enabled = on and ev == "Scatter"
				evadeDepth.enabled = on and ev == "Underground"
				evadeStay.enabled = on
				evadeY.enabled = on and (Rage.underground == true or ev == "Underground")
