	local lastAttrStreak: number? = nil
	local lastDisplayApplied: string? = nil
	local lastNameApplied: string? = nil
	local lastDeviceApplied: string? = nil

	local aliasTargets: { [Instance]: boolean } = {}
	local aliasReal: { [Instance]: { name: string, display: string } } = {}
	local aliasWritten: { [Instance]: { original: string, written: string } } = {}
	local aliasLabels: { Instance } = {}
	local aliasLabelsAt = 0
	local aliasCheckCaller = execApi("checkcaller")
	if typeof(aliasCheckCaller) ~= "function" then
		aliasCheckCaller = nil
	end

	local function enemyAliasText(): string?
		if not SESSION.alive then
			return nil
		end
		local esp = DrawingBridge.Esp
		local text = esp and esp.nameText
		if type(text) == "string" and string.find(text, "%S") then
			return text
		end
		return nil
	end

	local function refreshAliasTargets()
		local lp = Players.LocalPlayer
		if not enemyAliasText() or not lp then
			table.clear(aliasTargets)
			return
		end
		local myTeam = lp:GetAttribute("TeamID")
		local seen: { [Instance]: boolean } = {}
		for _, player in Players:GetPlayers() do
			if player ~= lp then
				local team = player:GetAttribute("TeamID")
				if myTeam == nil or team == nil or team ~= myTeam then
					if not aliasReal[player] then
						aliasTargets[player] = nil
						aliasReal[player] = { name = player.Name, display = player.DisplayName }
					end
					aliasTargets[player] = true
					seen[player] = true
				end
			end
		end
		for player in aliasTargets do
			if not seen[player] then
				aliasTargets[player] = nil
			end
		end
		for player in aliasReal do
			if player.Parent == nil then
				aliasReal[player] = nil
			end
		end
	end

	local function replacePlain(text: string, find: string, repl: string): string
		local first = string.find(text, find, 1, true)
		if not first then
			return text
		end
		local parts = {}
		local i = 1
		while true do
			local s, e = string.find(text, find, i, true)
			if not s then
				break
			end
			table.insert(parts, string.sub(text, i, s - 1))
			table.insert(parts, repl)
			i = e + 1
		end
		table.insert(parts, string.sub(text, i))
		return table.concat(parts)
	end

	local function collectAliasLabels()
		table.clear(aliasLabels)
		local function add(root: Instance?)
			if not root then
				return
			end
			for _, d in root:GetDescendants() do
				if d:IsA("TextLabel") or d:IsA("TextButton") then
					table.insert(aliasLabels, d)
				end
			end
		end
		local lp = Players.LocalPlayer
		pcall(add, lp and lp:FindFirstChildOfClass("PlayerGui"))
		for player in aliasTargets do
			pcall(add, (player :: Player).Character)
		end
		aliasLabelsAt = os.clock()
	end

	local function paintAliasUi()
		local alias = enemyAliasText()
		if not alias or next(aliasTargets) == nil then
			for label, rec in aliasWritten do
				pcall(function()
					if label.Parent and (label :: TextLabel).Text == rec.written then
						(label :: TextLabel).Text = rec.original
					end
				end)
			end
			table.clear(aliasWritten)
			return
		end
		if os.clock() - aliasLabelsAt > 4 then
			collectAliasLabels()
		end
		for _, label in aliasLabels do
			if label.Parent then
				local text = (label :: TextLabel).Text
				local rec = aliasWritten[label]
				if text ~= "" and not (rec and rec.written == text) then
					local nextText = text
					for player in aliasTargets do
						local real = aliasReal[player]
						if real then
							if #real.name >= 3 then
								nextText = replacePlain(nextText, real.name, alias)
							end
							if #real.display >= 3 and real.display ~= real.name then
								nextText = replacePlain(nextText, real.display, alias)
							end
						end
					end
					if nextText ~= text then
						aliasWritten[label] = { original = text, written = nextText }
						pcall(function()
							(label :: TextLabel).Text = nextText
						end)
					end
				end
			end
		end
	end

	local function spoofAnyOn(): boolean
		return Spoof.nameOn
			or Spoof.levelOn
			or Spoof.xpOn
			or Spoof.streakOn
			or Spoof.rankOn
			or Spoof.eloOn
			or Spoof.keysOn
			or Spoof.deviceOn
			or enemyAliasText() ~= nil
	end

	local function spoofNameText(): string
		local n = Spoof.name
		if type(n) == "string" and n ~= "" then
			return n
		end
		return "sonata"
	end

	local spoofPdcCache: any = nil
	local spoofPdcAt = 0
	local function spoofPlayerData(): any?
		local now = os.clock()
		if spoofPdcCache ~= nil and now - spoofPdcAt < 5 then
			return spoofPdcCache
		end
		local lp = Players.LocalPlayer
		if not lp then
			return nil
		end
		local ok, pdc = pcall(function()
			return require(lp.PlayerScripts.Controllers.PlayerDataController)
		end)
		if ok and pdc ~= nil then
			spoofPdcCache = pdc
			spoofPdcAt = now
			return pdc
		end
		return spoofPdcCache
	end

	local function spoofFireChanged(pdc: any, key: string, value: any?)
		pcall(function()
			local sig = pdc:GetDataChangedSignal(key)
			if sig and type(sig.Fire) == "function" then
				local v = value
				if v == nil and spoofOriginalPdcGet then
					v = spoofOriginalPdcGet(pdc, key)
				elseif v == nil and spoofOriginalPdcGet == nil then
					v = pdc:Get(key)
				end
				sig:Fire(v, key)
			end
		end)
	end

	local function refreshSeasonCache()
		pcall(function()
			local sl = require(ReplicatedStorage.Modules.SeasonLibrary)
			if sl and sl.CurrentSeason and type(sl.CurrentSeason.Name) == "string" then
				cachedSeasonName = sl.CurrentSeason.Name
			end
			local rankName = Spoof.rank
			if cachedEloRank == rankName then
				return
			end
			cachedEloRank = rankName
			cachedEloValue = 3700
			local profile = sl and sl.CurrentSeason and sl.CurrentSeason.RankProfile
			if not profile then
				return
			end
			local ranks = profile.Ranks
			local order = profile.RanksOrder
			local info = ranks and ranks[rankName]
			if type(info) ~= "table" or typeof(info.RequiredELO) ~= "number" then
				return
			end
			local required = info.RequiredELO
			if required < 0 then
				cachedEloValue = 0
				return
			end
			if info.RequiredELOLeaderboardRanking then
				cachedEloValue = required + 400
				return
			end
			if type(order) == "table" then
				local idx = table.find(order, rankName)
				if idx and order[idx + 1] and ranks[order[idx + 1]] then
					local nextReq = ranks[order[idx + 1]].RequiredELO
					if typeof(nextReq) == "number" and nextReq > required then
						cachedEloValue = math.floor((required + nextReq) * 0.5)
						return
					end
				end
			end
			cachedEloValue = required + 50
		end)
	end

	local function spoofEloForRank(rankName: string): number
		if cachedEloRank ~= rankName then
			refreshSeasonCache()
		end
		return cachedEloValue
	end

	local function spoofSeasonElo(): number
		if Spoof.eloOn then
			return math.clamp(math.floor(Spoof.elo), 0, 999999)
		end
		if Spoof.rankOn then
			return spoofEloForRank(Spoof.rank)
		end
		return cachedEloValue
	end

	local realDisplayElo: number? = nil
	local realSeasonElo: number? = nil
	local lastAppliedElo: number? = nil
	local eloSpoofApplied = false
	local spoofRankHooked = false

	local function eloSpoofOn(): boolean
		return Spoof.rankOn == true or Spoof.eloOn == true
	end

	local function isLocalUserId(id: any): boolean
		local lp = Players.LocalPlayer
		return lp ~= nil and id ~= nil and tostring(id) == tostring(lp.UserId)
	end

	local function isLocalElo(elo: any): boolean
		if type(elo) ~= "number" then
			return false
		end
		return elo == spoofSeasonElo() or elo == realDisplayElo or elo == realSeasonElo
	end

	local function ensureRankHooks()
		if spoofRankHooked then
			return
		end
		local ok, sl = pcall(function()
			return require(ReplicatedStorage.Modules.SeasonLibrary)
		end)
		if not ok or type(sl) ~= "table" then
			return
		end
		if type(sl.GetHighestELOLeaderboardRanking) == "function" then
			hookGameMethod(sl.GetHighestELOLeaderboardRanking, function(old, self: any, elo: any, userId: any, ...: any): any
				if Spoof.rankOn and isLocalUserId(userId) then
					return if Spoof.rank == "Archnemesis" then 1 else nil
				end
				return old(self, elo, userId, ...)
			end)
		end
		if type(sl.GetRank) == "function" then
			hookGameMethod(sl.GetRank, function(old, self: any, elo: any, userId: any, ranking: any, profileName: any, ...: any): any
				if Spoof.rankOn and profileName == nil and isLocalUserId(userId) and isLocalElo(elo) then
					local season = type(self) == "table" and self.CurrentSeason
					local ranks = season and season.RankProfile and season.RankProfile.Ranks
					if type(ranks) ~= "table" or ranks[Spoof.rank] ~= nil then
						return Spoof.rank
					end
				end
				return old(self, elo, userId, ranking, profileName, ...)
			end)
		end
		spoofRankHooked = true
	end

	local function rawDisplayElo(lp: Player): any
		local ok, value = pcall(lp.GetAttribute, lp, "DisplayELO")
		return if ok then value else nil
	end

	local function currentSeasonEntry(pdc: any): (any, any)
		local seasons = if spoofOriginalPdcGet then spoofOriginalPdcGet(pdc, "Seasons") else pdc:Get("Seasons")
		if type(seasons) ~= "table" then
			return nil, nil
		end
		return seasons, seasons[cachedSeasonName]
	end

	local function applyEloSpoof(lp: Player, pdc: any?)
		local elo = spoofSeasonElo()
		local raw = rawDisplayElo(lp)
		if type(raw) == "number" and raw ~= elo and raw ~= lastAppliedElo then
			realDisplayElo = raw
		end
		if raw ~= elo then
			pcall(lp.SetAttribute, lp, "DisplayELO", elo)
		end
		if pdc then
			pcall(function()
				local seasons, season = currentSeasonEntry(pdc)
				if type(seasons) ~= "table" then
					seasons = {}
					pdc:Set("Seasons", seasons)
				end
				if type(season) ~= "table" then
					season = { ResetCounter = 0, CurrentELO = elo, RankedPerformances = { ranked = {} } }
					seasons[cachedSeasonName] = season
				end
				local cur = season.CurrentELO
				if type(cur) == "number" and cur ~= elo and cur ~= lastAppliedElo then
					realSeasonElo = cur
				end
				if cur ~= elo or lastAppliedElo ~= elo then
					season.CurrentELO = elo
					spoofFireChanged(pdc, "Seasons", seasons)
				end
			end)
		end
		lastAppliedElo = elo
		eloSpoofApplied = true
	end

	local function restoreEloSpoof()
		if not eloSpoofApplied then
			return
		end
		eloSpoofApplied = false
		lastAppliedElo = nil
		local lp = Players.LocalPlayer
		if lp and realDisplayElo ~= nil then
			pcall(lp.SetAttribute, lp, "DisplayELO", realDisplayElo)
		end
		local pdc = spoofPlayerData()
		if pdc and realSeasonElo ~= nil then
			pcall(function()
				local seasons, season = currentSeasonEntry(pdc)
				if type(season) == "table" then
					season.CurrentELO = realSeasonElo
					spoofFireChanged(pdc, "Seasons", seasons)
				end
			end)
		end
	end

	local function spoofScalarGet(key: any): any?
		if key == "Level" and Spoof.levelOn then
			return math.clamp(math.floor(Spoof.level), 0, 99999)
		end
		if key == "XP" and Spoof.xpOn then
			return math.clamp(math.floor(Spoof.xp), 0, 99999999)
		end
		if key == "StatisticDuelsWinStreak" and Spoof.streakOn then
			return math.clamp(math.floor(Spoof.streak), 0, 999999)
		end
		if key == "WeaponKeys" and Spoof.keysOn then
			return math.clamp(math.floor(Spoof.keys), 0, 9999999)
		end
		return nil
	end

	local function captureRealNames(lp: Player)
		spoofLocalPlayer = lp
		if realUserName == nil then
			realUserName = lp.Name
		end
		if realDisplayName == nil then
			realDisplayName = lp.DisplayName
		end
	end

	local function ensureNameMetamethod()
		if spoofNameHooked then
			return
		end
		local hookmetamethod = execApi("hookmetamethod")
		if typeof(hookmetamethod) ~= "function" then
			return
		end
		local lp = Players.LocalPlayer
		if not lp then
			return
		end
		captureRealNames(lp)
		local ok = pcall(function()
			local oldIndex
			oldIndex = hookmetamethod(game, "__index", function(self: any, key: any)
				if SESSION.alive and (key == "Name" or key == "DisplayName") then
					local me = spoofLocalPlayer
					if Spoof.nameOn and me ~= nil and self == me then
						return spoofNameText()
					end
					if key == "DisplayName" and aliasTargets[self] and not (aliasCheckCaller and aliasCheckCaller()) then
						local alias = enemyAliasText()
						if alias then
							return alias
						end
					end
				end
				return oldIndex(self, key)
			end)
		end)
		if ok then
			spoofNameHooked = true
		end
	end

	local function ensureAttrMetamethod()
		if spoofAttrHooked then
			return
		end
		local hookmetamethod = execApi("hookmetamethod")
		local getnamecallmethod = execApi("getnamecallmethod")
		if typeof(hookmetamethod) ~= "function" or typeof(getnamecallmethod) ~= "function" then
			return
		end
		local ok = pcall(function()
			local oldNamecall
			oldNamecall = hookmetamethod(game, "__namecall", function(self: any, ...: any)
				local me = spoofLocalPlayer
				if SESSION.alive and me ~= nil and self == me then
					local method = getnamecallmethod()
					if method == "GetAttribute" then
						local key = ...
						if key == "Level" and Spoof.levelOn then
							return math.clamp(math.floor(Spoof.level), 0, 99999)
						end
						if key == "StatisticDuelsWinStreak" and Spoof.streakOn then
							return math.clamp(math.floor(Spoof.streak), 0, 999999)
						end
						if key == "DisplayELO" and eloSpoofOn() then
							return spoofSeasonElo()
						end
					end
				end
				return oldNamecall(self, ...)
			end)
		end)
		if ok then
			spoofAttrHooked = true
		end
	end

	local function ensureSpoofHooks()
		if spoofHooksReady then
			ensureNameMetamethod()
			ensureAttrMetamethod()
			ensureRankHooks()
			return
		end
		local lp = Players.LocalPlayer
		if not lp then
			return
		end
		spoofLocalPlayer = lp
		refreshSeasonCache()
		ensureNameMetamethod()
		ensureAttrMetamethod()
		ensureRankHooks()
		local okCc, cc = pcall(function()
			return require(lp.PlayerScripts.Controllers.ComplianceController)
		end)
		if okCc and type(cc) == "table" then
			if type(cc.GetName) == "function" and spoofOriginalGetName == nil then
				local oldName = hookGameMethod(cc.GetName, function(old, self: any, player: any, ...: any): any
					if Spoof.nameOn and player == Players.LocalPlayer then
						return spoofNameText()
					end
					if aliasTargets[player] then
						local alias = enemyAliasText()
						if alias then
							return alias
						end
					end
					local ok, result = pcall(old, self, player, ...)
					return if ok then result else nil
				end)
				if oldName then
					spoofOriginalGetName = oldName
				end
			end
			if type(cc.GetUserInfos) == "function" and spoofOriginalGetUserInfos == nil then
				local oldInfos = hookGameMethod(cc.GetUserInfos, function(old, self: any, ids: any, ...: any): any
					local ok, result = pcall(old, self, ids, ...)
					if not ok or type(result) ~= "table" then
						return if ok then result else nil
					end
					local function rename(userId: number, n: string)
						local entry = result[tostring(userId)] or result[userId]
						if type(entry) == "table" then
							entry.DisplayName = n
							entry.Username = n
							entry.Name = n
						end
					end
					local lp2 = Players.LocalPlayer
					if lp2 and Spoof.nameOn then
						rename(lp2.UserId, spoofNameText())
					end
					local alias = enemyAliasText()
					if alias then
						for player in aliasTargets do
							rename((player :: Player).UserId, alias)
						end
					end
					return result
				end)
				if oldInfos then
					spoofOriginalGetUserInfos = oldInfos
				end
			end
		end
		local pdc = spoofPlayerData()
		if pdc and type(pdc.Get) == "function" and spoofOriginalPdcGet == nil then
			local oldGet = hookGameMethod(pdc.Get, function(old, self: any, key: any, ...: any): any
				local forced = spoofScalarGet(key)
				if forced ~= nil then
					return forced
				end
				local ok, value = pcall(old, self, key, ...)
				if not ok then
					return nil
				end
				if key == "Seasons" and eloSpoofOn() and type(value) == "table" then
					local season = value[cachedSeasonName]
					if type(season) == "table" then
						local elo = spoofSeasonElo()
						local cur = season.CurrentELO
						if type(cur) == "number" and cur ~= elo and cur ~= lastAppliedElo then
							realSeasonElo = cur
						end
						season.CurrentELO = elo
					end
				end
				return value
			end)
			if oldGet then
				spoofOriginalPdcGet = oldGet
			end
		end
		pcall(function()
			local data = pdc and pdc.CurrentData
			if data and type(data.Get) == "function" and data.__sonataLevelGet ~= true then
				local oldDataGet = hookGameMethod(data.Get, function(old, self: any, key: any, ...: any): any
					local forced = spoofScalarGet(key)
					if forced ~= nil then
						return forced
					end
					local ok, value = pcall(old, self, key, ...)
					return if ok then value else nil
				end)
				if oldDataGet then
					data.__sonataLevelGet = true
				end
			end
		end)
		pcall(function()
			if spoofSetControlsHooked then
				return
			end
			local remotes = ReplicatedStorage:FindFirstChild("Remotes")
			local replication = remotes and remotes:FindFirstChild("Replication")
			local fighterFolder = replication and replication:FindFirstChild("Fighter")
			local rem = fighterFolder and fighterFolder:FindFirstChild("SetControls")
			if not (rem and rem:IsA("RemoteEvent")) then
				return
			end
			spoofSetControlsRemote = rem
			local oldFire = rem.FireServer
			rem.FireServer = function(self: any, scheme: any, ...: any)
				if Spoof.deviceOn then
					scheme = DEVICE_TO_CONTROLS[Spoof.device] or scheme
				end
				return oldFire(self, scheme, ...)
			end
			spoofSetControlsHooked = true
		end)
		spoofHooksReady = true
	end

	local function applySpoofName()
		local lp = Players.LocalPlayer
		if not lp or not Spoof.nameOn then
			return
		end
		captureRealNames(lp)
		ensureSpoofHooks()
		local n = spoofNameText()
		if lastDisplayApplied == n and lastNameApplied == n then
			return
		end
		lastDisplayApplied = n
		lastNameApplied = n
		pcall(function()
			lp.DisplayName = n
		end)
		pcall(function()
			lp.Name = n
		end)
		pcall(function()
			local setHidden = execApi("sethiddenproperty")
			if typeof(setHidden) == "function" then
				setHidden(lp, "DisplayName", n)
			end
		end)
	end

	local spoofOriginals: { [string]: { value: any, attr: string?, attrValue: any } } = {}
	local function readUnhooked(fn: () -> any): any
		local was = SESSION.alive
		SESSION.alive = false
		local ok, value = pcall(fn)
		SESSION.alive = was
		return if ok then value else nil
	end

	local function spoofWriteKey(pdc: any, key: string, value: any, attrName: string?)
		pcall(function()
			local data = pdc.CurrentData
			if data and type(data.Set) == "function" then
				data:Set(key, value)
			else
				pdc:Set(key, value)
			end
			if attrName then
				local lp = Players.LocalPlayer
				if lp then
					lp:SetAttribute(attrName, value)
				end
			end
			spoofFireChanged(pdc, key, value)
		end)
	end

	local function spoofSetKey(pdc: any, key: string, value: any, attrName: string?)
		if spoofOriginals[key] == nil then
			local lp = Players.LocalPlayer
			spoofOriginals[key] = {
				value = readUnhooked(function()
					local data = pdc.CurrentData
					if data and type(data.Get) == "function" then
						return data:Get(key)
					end
					return pdc:Get(key)
				end),
				attr = attrName,
				attrValue = if attrName and lp
					then readUnhooked(function()
						return lp:GetAttribute(attrName)
					end)
					else nil,
			}
		end
		spoofWriteKey(pdc, key, value, attrName)
	end

	local function applySpoofProfile()
		local lp = Players.LocalPlayer
		local pdc = spoofPlayerData()
		if not lp or not pdc then
			return
		end
		ensureSpoofHooks()
		if Spoof.nameOn then
			applySpoofName()
		end
		if Spoof.levelOn then
			local level = math.clamp(math.floor(Spoof.level), 0, 99999)
			if lastAttrLevel ~= level then
				lastAttrLevel = level
				spoofSetKey(pdc, "Level", level, "Level")
			else
				pcall(function()
					lp:SetAttribute("Level", level)
					spoofFireChanged(pdc, "Level", level)
				end)
			end
		end
		if Spoof.xpOn then
			local xp = math.clamp(math.floor(Spoof.xp), 0, 99999999)
			spoofSetKey(pdc, "XP", xp, nil)
		end
		if Spoof.streakOn then
			local streak = math.clamp(math.floor(Spoof.streak), 0, 999999)
			if lastAttrStreak ~= streak then
				lastAttrStreak = streak
				spoofSetKey(pdc, "StatisticDuelsWinStreak", streak, "StatisticDuelsWinStreak")
			else
				pcall(function()
					lp:SetAttribute("StatisticDuelsWinStreak", streak)
					spoofFireChanged(pdc, "StatisticDuelsWinStreak", streak)
				end)
			end
		end
		if eloSpoofOn() then
			if Spoof.rankOn then
				refreshSeasonCache()
			end
			applyEloSpoof(lp, pdc)
		else
			restoreEloSpoof()
		end
	end

	local function applySpoofKeys()
		local pdc = spoofPlayerData()
		if not pdc or not Spoof.keysOn then
			return
		end
		ensureSpoofHooks()
		spoofSetKey(pdc, "WeaponKeys", math.clamp(math.floor(Spoof.keys), 0, 9999999), nil)
	end

	local function realLocalControls(): string?
		local ok, mod = pcall(function()
			local lp = Players.LocalPlayer
			return lp and require(lp.PlayerScripts.Controllers.ControlsController)
		end)
		if ok and type(mod) == "table" and type(mod.CurrentControls) == "string" then
			return mod.CurrentControls
		end
		return nil
	end

	local function fireDeviceControls(scheme: string)
		ensureSpoofHooks()
		local rem = spoofSetControlsRemote
		if not rem then
			pcall(function()
				local remotes = ReplicatedStorage:FindFirstChild("Remotes")
				local replication = remotes and remotes:FindFirstChild("Replication")
				local fighterFolder = replication and replication:FindFirstChild("Fighter")
				local found = fighterFolder and fighterFolder:FindFirstChild("SetControls")
				if found and found:IsA("RemoteEvent") then
					spoofSetControlsRemote = found
					rem = found
				end
			end)
		end
		if rem then
			pcall(function()
				rem:FireServer(scheme)
			end)
		end
	end

	local function applyDeviceSpoof()
		ensureSpoofHooks()
		if not Spoof.deviceOn then
			if lastDeviceApplied ~= nil then
				lastDeviceApplied = nil
				local real = realLocalControls()
				if real then
					fireDeviceControls(real)
				end
			end
			return
		end
		local controls = DEVICE_TO_CONTROLS[Spoof.device] or "MouseKeyboard"
		if lastDeviceApplied == controls then
			return
		end
		lastDeviceApplied = controls
		fireDeviceControls(controls)
	end

	local function addSpoofCases()
		local pdc = spoofPlayerData()
		if not pdc then
			return
		end
		local amount = math.clamp(math.floor(Spoof.caseAmount), 1, 100)
		local caseName = Spoof.caseName
		if type(caseName) ~= "string" or caseName == "" then
			caseName = "Skin Case"
		end
		pcall(function()
			local list = if spoofOriginalPdcGet then spoofOriginalPdcGet(pdc, "UnclaimedRewards") else pdc:Get("UnclaimedRewards")
			if type(list) ~= "table" then
				list = {}
			end
			for _ = 1, amount do
				table.insert(list, { Quantity = 1, Name = caseName, Weapon = "IsRandom" })
			end
			local data = pdc.CurrentData
			if data and type(data.Set) == "function" then
				data:Set("UnclaimedRewards", list)
			else
				pdc:Set("UnclaimedRewards", list)
			end
			spoofFireChanged(pdc, "UnclaimedRewards", list)
		end)
	end
	DrawingBridge.addSpoofCases = addSpoofCases

	local function nameSlotValid(slot: any): boolean
		return type(slot) == "table"
			and typeof(slot.label) == "Instance"
			and slot.label.Parent ~= nil
			and slot.label:IsA("TextLabel")
	end

	local function rediscoverNameUi(lp: Player)
		table.clear(nameUiSlots)
		local NAME_KEYS = {
			displayname = true,
			username = true,
			name = true,
			playername = true,
		}
		local function consider(label: Instance)
			if not label:IsA("TextLabel") and not label:IsA("TextButton") then
				return
			end
			local lower = string.lower(label.Name)
			if not NAME_KEYS[lower] then
				return
			end
			nameUiSlots[#nameUiSlots + 1] = { label = label, kind = label.Name }
		end
		local function walk(root: Instance?)
			if not root then
				return
			end
			for _, gui in root:GetDescendants() do
				if gui.Name == "LeaderboardPlayerSlot" then
					local left = gui:FindFirstChild("Left")
					if left then
						for _, child in left:GetChildren() do
							consider(child)
						end
					end
				else
					consider(gui)
				end
			end
		end
		pcall(function()
			local scripts = lp:FindFirstChild("PlayerScripts")
			walk(scripts and scripts:FindFirstChild("UserInterface"))
		end)
		pcall(function()
			walk(lp:FindFirstChild("PlayerGui"))
		end)
		pcall(function()
			for _, inst in Workspace:GetChildren() do
				if inst:IsA("SurfaceGui") or inst:IsA("BillboardGui") then
					for _, gui in inst:GetDescendants() do
						if gui.Name == "LeaderboardPlayerSlot" then
							local left = gui:FindFirstChild("Left")
							if left then
								for _, child in left:GetChildren() do
									consider(child)
								end
							end
						end
					end
				end
			end
		end)
		nameUiSlotsAt = os.clock()
	end

	local function paintNameUi(lp: Player)
		if not Spoof.nameOn then
			return
		end
		local n = spoofNameText()
		local atUser = "@" .. n
		for i = #nameUiSlots, 1, -1 do
			local slot = nameUiSlots[i]
			if not nameSlotValid(slot) then
				table.remove(nameUiSlots, i)
			else
				local label = slot.label :: TextLabel
				local kind = string.lower(tostring(slot.kind or ""))
				local text = label.Text
				if kind == "username" or (type(text) == "string" and string.sub(text, 1, 1) == "@") then
					if text ~= atUser then
						label.Text = atUser
					end
				elseif type(text) == "string" then
					local realName = realUserName or lp.Name
					local realDisplay = realDisplayName or lp.DisplayName
					local nextText = text
					if realName and realName ~= "" and realName ~= n then
						nextText = string.gsub(nextText, realName, n)
					end
					if realDisplay and realDisplay ~= "" and realDisplay ~= n and realDisplay ~= realName then
						nextText = string.gsub(nextText, realDisplay, n)
					end
					if nextText == text and (kind == "displayname" or kind == "name" or kind == "playername") then
						nextText = n
					end
					if nextText ~= text then
						label.Text = nextText
					end
				end
			end
		end
	end

	local function applyNameUiSpoof(forceDiscover: boolean?)
		ensureSpoofHooks()
		if not Spoof.nameOn then
			return
		end
		local lp = Players.LocalPlayer
		if not lp then
			return
		end
		if forceDiscover or #nameUiSlots == 0 or (os.clock() - nameUiSlotsAt) > 10 then
			rediscoverNameUi(lp)
		end
		paintNameUi(lp)
	end

	local function restoreSpoofedNameUi(lp: Player)
		local n = spoofNameText()
		local realName = realUserName or lp.Name
		local realDisplay = realDisplayName or realName
		for _, slot in nameUiSlots do
			if nameSlotValid(slot) then
				local label = slot.label :: TextLabel
				local text = label.Text
				if text == "@" .. n then
					label.Text = "@" .. realName
				elseif type(text) == "string" and n ~= "" then
					local restored = replacePlain(text, n, realDisplay)
					if restored ~= text then
						label.Text = restored
					end
				end
			end
		end
	end

	DrawingBridge.revertSpoof = function()
		local lp = Players.LocalPlayer
		local nameWasOn = Spoof.nameOn == true
		for key, value in Spoof do
			if type(value) == "boolean" and string.sub(key, -2) == "On" then
				Spoof[key] = false
			end
		end
		if DrawingBridge.Esp then
			DrawingBridge.Esp.nameText = ""
		end
		table.clear(aliasTargets)
		pcall(paintAliasUi)
		pcall(restoreEloSpoof)
		pcall(applyDeviceSpoof)
		local pdc = spoofPlayerData()
		for key, rec in spoofOriginals do
			if pdc and rec.value ~= nil then
				spoofWriteKey(pdc, key, rec.value, nil)
			end
			if lp and rec.attr and rec.attrValue ~= nil then
				pcall(lp.SetAttribute, lp, rec.attr, rec.attrValue)
			end
		end
		table.clear(spoofOriginals)
		if lp and nameWasOn then
			pcall(restoreSpoofedNameUi, lp)
			if realDisplayName then
				pcall(function()
					lp.DisplayName = realDisplayName
				end)
				pcall(function()
					local setHidden = execApi("sethiddenproperty")
					if typeof(setHidden) == "function" then
						setHidden(lp, "DisplayName", realDisplayName)
					end
				end)
			end
			if realUserName then
				pcall(function()
					lp.Name = realUserName
				end)
			end
		end
	end

	local function applySpoofAll()
		lastAttrLevel = nil
		lastAttrStreak = nil
		lastDisplayApplied = nil
		lastNameApplied = nil
		lastDeviceApplied = nil
		cachedEloRank = nil
		applySpoofProfile()
		applySpoofKeys()
		applyDeviceSpoof()
		applyNameUiSpoof(true)
	end
	DrawingBridge.applySpoofAll = applySpoofAll
	DrawingBridge.spoofAutoApply = function()
		spoofAutoToken += 1
		local token = spoofAutoToken
		task.delay(0.1, function()
			if token ~= spoofAutoToken then
				return
			end
			if not eloSpoofOn() then
				restoreEloSpoof()
			end
			if not spoofAnyOn() then
				return
			end
			ensureSpoofHooks()
			if Spoof.rankOn then
				cachedEloRank = nil
			end
			applySpoofProfile()
			if Spoof.keysOn then
				applySpoofKeys()
			end
			if Spoof.deviceOn then
				lastDeviceApplied = nil
				applyDeviceSpoof()
			end
			if Spoof.nameOn then
				applyNameUiSpoof(true)
			end
		end)
	end

	local lastSpoofPulse = 0
	local lastNameUiPulse = 0
	local lastStatsPulse = 0
	local lastAliasPulse = 0
	table.insert(ears, RunService.Heartbeat:Connect(function()
		local now = os.clock()
		if now - lastAliasPulse >= 0.4 then
			lastAliasPulse = now
			if enemyAliasText() then
				refreshAliasTargets()
				paintAliasUi()
			elseif next(aliasTargets) ~= nil or next(aliasWritten) ~= nil then
				table.clear(aliasTargets)
				paintAliasUi()
			end
		end
		if not spoofAnyOn() then
			return
		end
		if not spoofHooksReady then
			ensureSpoofHooks()
		end
		if now - lastSpoofPulse < 1.5 then
			return
		end
		lastSpoofPulse = now
		local lp = Players.LocalPlayer
		if not lp then
			return
		end
		spoofLocalPlayer = lp
		if Spoof.nameOn then
			applySpoofName()
			if now - lastNameUiPulse >= 3 then
				lastNameUiPulse = now
				applyNameUiSpoof(false)
			end
		end
		if Spoof.levelOn then
			local level = math.clamp(math.floor(Spoof.level), 0, 99999)
			if lp:GetAttribute("Level") ~= level then
				lp:SetAttribute("Level", level)
			end
		end
		if Spoof.streakOn then
			local streak = math.clamp(math.floor(Spoof.streak), 0, 999999)
			if lp:GetAttribute("StatisticDuelsWinStreak") ~= streak then
				lp:SetAttribute("StatisticDuelsWinStreak", streak)
			end
		end
		if eloSpoofOn() and rawDisplayElo(lp) ~= spoofSeasonElo() then
			applyEloSpoof(lp, nil)
		end
		if now - lastStatsPulse >= 4 then
			lastStatsPulse = now
			if Spoof.xpOn or Spoof.keysOn or Spoof.rankOn or Spoof.eloOn or Spoof.levelOn or Spoof.streakOn then
				applySpoofProfile()
			end
			if Spoof.keysOn then
				applySpoofKeys()
			end
		end
		if Spoof.deviceOn then
			applyDeviceSpoof()
		end
	end))

	local WorldMap = {
		removeDecals = false,
		worldMaterial = false,
		material = "SmoothPlastic",
		materialColor = Color3.fromRGB(160, 160, 160),
		reflectance = 0,
		opacity = 1,
	}

	local WorldSky = {
		clock = false,
		clockTime = 14,
		ambience = false,
		ambient = Color3.fromRGB(138, 138, 138),
		outdoorAmbient = Color3.fromRGB(128, 128, 128),
		atmosphere = false,
		atmDensity = 0.35,
		atmOffset = 0,
		atmColor = Color3.fromRGB(200, 200, 200),
		atmDecay = Color3.fromRGB(120, 120, 120),
		atmGlare = 0,
		atmHaze = 0,
		brightness = false,
		brightnessVal = 2,
		exposure = false,
		exposureVal = 0,
		fog = false,
		fogColor = Color3.fromRGB(192, 192, 192),
