	local decalsStrippedOnce = false
	local DECAL_AREA_RADIUS = 120

	local applyWorldSky: () -> ()
	local applyWorldMap: (() -> ())?

	local function worldMatchActive(): boolean
		local probe = DrawingBridge.isInGameMatch
		if type(probe) == "function" then
			local ok, result = pcall(probe)
			if ok then
				return result == true
			end
		end
		return DrawingBridge.inGameMatch == true
	end

	local function anyWorldFxActive(): boolean
		return WorldFx.blur or WorldFx.dof or WorldFx.sunRays
	end

	local function anyWorldSkyActive(): boolean
		return WorldSky.clock
			or WorldSky.ambience
			or WorldSky.atmosphere
			or WorldSky.brightness
			or WorldSky.exposure
			or WorldSky.fog
			or WorldSky.colorCorrection
			or WorldSky.bloom
			or WorldSky.skybox
			or anyWorldFxActive()
	end

	local stashedGameSkies: { Instance } = {}
	local skyboxWatchConn: RBXScriptConnection? = nil

	local function skyAssetId(value: any): string
		if type(value) == "string" then
			if string.find(value, "rbxasset", 1, true) or string.find(value, "http", 1, true) then
				return value
			end
			return "rbxassetid://" .. value
		end
		return "rbxassetid://" .. tostring(value)
	end

	local function resolveSkyboxEntry(name: string?): any
		if type(name) == "string" and SKYBOX_CATALOG[name] then
			return SKYBOX_CATALOG[name], name
		end
		local fallback = SKYBOX_NAMES[1] or "Afternoon"
		return SKYBOX_CATALOG[fallback], fallback
	end

	local function restoreStashedSkies()
		for _, sky in stashedGameSkies do
			pcall(function()
				if sky and sky.Parent == nil then
					sky.Parent = Lighting
				end
			end)
		end
		table.clear(stashedGameSkies)
	end

	local function stashOtherSkies()
		for _, child in Lighting:GetChildren() do
			if child:IsA("Sky") and child.Name ~= "sonata_skybox" then
				table.insert(stashedGameSkies, child)
				pcall(function()
					child.Parent = nil
				end)
			end
		end
	end

	local function applySkyboxOverride()
		local ours = Lighting:FindFirstChild("sonata_skybox")
		if not WorldSky.skybox then
			if ours then
				pcall(function()
					ours:Destroy()
				end)
			end
			restoreStashedSkies()
			if skyboxWatchConn then
				pcall(function()
					skyboxWatchConn:Disconnect()
				end)
				skyboxWatchConn = nil
			end
			return
		end

		local entry, resolvedName = resolveSkyboxEntry(WorldSky.skyboxName)
		WorldSky.skyboxName = resolvedName :: string
		if not entry then
			return
		end

		stashOtherSkies()
		local sky = ours
		if not sky or not sky:IsA("Sky") then
			sky = Instance.new("Sky")
			sky.Name = "sonata_skybox"
			sky.Parent = Lighting
		end

		local bk, dn, ft, lf, rt, up
		if entry.all ~= nil then
			local a = skyAssetId(entry.all)
			bk, dn, ft, lf, rt, up = a, a, a, a, a, a
		else
			bk = skyAssetId(entry.SkyboxBk or entry.bk)
			dn = skyAssetId(entry.SkyboxDn or entry.dn)
			ft = skyAssetId(entry.SkyboxFt or entry.ft)
			lf = skyAssetId(entry.SkyboxLf or entry.lf)
			rt = skyAssetId(entry.SkyboxRt or entry.rt)
			up = skyAssetId(entry.SkyboxUp or entry.up)
		end
		sky.SkyboxBk = bk
		sky.SkyboxDn = dn
		sky.SkyboxFt = ft
		sky.SkyboxLf = lf
		sky.SkyboxRt = rt
		sky.SkyboxUp = up
		local stars = entry.StarCount
		if type(stars) ~= "number" then
			stars = entry.stars
		end
		sky.StarCount = if type(stars) == "number" then stars else 3000
		if type(entry.SunAngularSize) == "number" then
			sky.SunAngularSize = entry.SunAngularSize
		end
		if type(entry.MoonAngularSize) == "number" then
			sky.MoonAngularSize = entry.MoonAngularSize
		end
		if type(entry.SunTextureId) == "string" then
			sky.SunTextureId = entry.SunTextureId
		end
		if type(entry.MoonTextureId) == "string" then
			sky.MoonTextureId = entry.MoonTextureId
		end
		local sunSize = if type(entry.SunAngularSize) == "number" then entry.SunAngularSize else 21
		local moonSize = if type(entry.MoonAngularSize) == "number" then entry.MoonAngularSize else 11
		if entry.celestial ~= nil then
			sky.CelestialBodiesShown = entry.celestial == true
		else
			sky.CelestialBodiesShown = sunSize > 0 or moonSize > 0
		end
		sky.Parent = Lighting

		if not skyboxWatchConn then
			skyboxWatchConn = Lighting.ChildAdded:Connect(function(child)
				if WorldSky.skybox and child:IsA("Sky") and child.Name ~= "sonata_skybox" then
					table.insert(stashedGameSkies, child)
					task.defer(function()
						pcall(function()
							child.Parent = nil
						end)
					end)
				end
			end)
			if skyboxWatchConn then
				table.insert(ears, skyboxWatchConn)
			end
		end
	end

	local function anyWorldMapActive(): boolean
		return WorldMap.removeDecals or WorldMap.worldMaterial
	end

	exportWorldQol = function(): any
		return {
			qol = {
				aspect = Qol.aspect,
				aspectX = Qol.aspectX,
				removeFlash = Qol.removeFlash,
				thirdPerson = Qol.thirdPerson,
				thirdPersonKey = Qol.thirdPersonKey,
				thirdPersonDistance = Qol.thirdPersonDistance,
				autoPickup = Qol.autoPickup,
				autoRespawn = Qol.autoRespawn,
				autoLoadout = Qol.autoLoadout,
				loadoutPrimary = Qol.loadoutPrimary,
				loadoutSecondary = Qol.loadoutSecondary,
				loadoutMelee = Qol.loadoutMelee,
				loadoutUtility = Qol.loadoutUtility,
			},
			map = {
				removeDecals = WorldMap.removeDecals,
				worldMaterial = WorldMap.worldMaterial,
				material = WorldMap.material,
				materialColor = colorToTable(WorldMap.materialColor),
				reflectance = WorldMap.reflectance,
				opacity = WorldMap.opacity,
			},
			sky = {
