	restoreWorldQol = function(data: any)
		if type(data) ~= "table" then
			return
		end
		if type(data.qol) == "table" then
			local q = data.qol
			if type(q.aspect) == "boolean" then Qol.aspect = q.aspect end
			if type(q.aspectX) == "number" then Qol.aspectX = math.clamp(q.aspectX, 0, 1.5) end
			if type(q.removeFlash) == "boolean" then Qol.removeFlash = q.removeFlash end
			if type(q.thirdPerson) == "boolean" then Qol.thirdPerson = q.thirdPerson end
			if type(q.thirdPersonKey) == "string" then Qol.thirdPersonKey = q.thirdPersonKey end
			if type(q.thirdPersonDistance) == "number" then
				Qol.thirdPersonDistance = math.clamp(q.thirdPersonDistance, 3, 30)
			end
			if type(q.autoPickup) == "boolean" then Qol.autoPickup = q.autoPickup end
			if type(q.autoRespawn) == "boolean" then Qol.autoRespawn = q.autoRespawn end
			if type(q.autoLoadout) == "boolean" then Qol.autoLoadout = q.autoLoadout end
			if type(q.loadoutPrimary) == "string" then Qol.loadoutPrimary = q.loadoutPrimary end
			if type(q.loadoutSecondary) == "string" then Qol.loadoutSecondary = q.loadoutSecondary end
			if type(q.loadoutMelee) == "string" then Qol.loadoutMelee = q.loadoutMelee end
			if type(q.loadoutUtility) == "string" then Qol.loadoutUtility = q.loadoutUtility end
		end
		if type(data.map) == "table" then
			local m = data.map
			if type(m.removeDecals) == "boolean" then WorldMap.removeDecals = m.removeDecals end
			if type(m.worldMaterial) == "boolean" then WorldMap.worldMaterial = m.worldMaterial end
			if type(m.material) == "string" then WorldMap.material = m.material end
			WorldMap.materialColor = tableToColor(m.materialColor, WorldMap.materialColor)
			if type(m.reflectance) == "number" then WorldMap.reflectance = math.clamp(m.reflectance, 0, 1) end
			if type(m.opacity) == "number" then WorldMap.opacity = math.clamp(m.opacity, 0, 1) end
		end
		if type(data.sky) == "table" then
			local s = data.sky
			if type(s.clock) == "boolean" then WorldSky.clock = s.clock end
			if type(s.clockTime) == "number" then WorldSky.clockTime = s.clockTime end
			if type(s.ambience) == "boolean" then WorldSky.ambience = s.ambience end
			WorldSky.ambient = tableToColor(s.ambient, WorldSky.ambient)
			WorldSky.outdoorAmbient = tableToColor(s.outdoorAmbient, WorldSky.outdoorAmbient)
			if type(s.atmosphere) == "boolean" then WorldSky.atmosphere = s.atmosphere end
			if type(s.atmDensity) == "number" then WorldSky.atmDensity = s.atmDensity end
			if type(s.atmOffset) == "number" then WorldSky.atmOffset = s.atmOffset end
			WorldSky.atmColor = tableToColor(s.atmColor, WorldSky.atmColor)
			WorldSky.atmDecay = tableToColor(s.atmDecay, WorldSky.atmDecay)
			if type(s.atmGlare) == "number" then WorldSky.atmGlare = s.atmGlare end
			if type(s.atmHaze) == "number" then WorldSky.atmHaze = s.atmHaze end
			if type(s.brightness) == "boolean" then WorldSky.brightness = s.brightness end
			if type(s.brightnessVal) == "number" then WorldSky.brightnessVal = s.brightnessVal end
			if type(s.exposure) == "boolean" then WorldSky.exposure = s.exposure end
			if type(s.exposureVal) == "number" then WorldSky.exposureVal = s.exposureVal end
			if type(s.fog) == "boolean" then WorldSky.fog = s.fog end
			WorldSky.fogColor = tableToColor(s.fogColor, WorldSky.fogColor)
			if type(s.fogStart) == "number" then WorldSky.fogStart = s.fogStart end
			if type(s.fogEnd) == "number" then WorldSky.fogEnd = s.fogEnd end
			if type(s.colorCorrection) == "boolean" then WorldSky.colorCorrection = s.colorCorrection end
			if type(s.ccBrightness) == "number" then WorldSky.ccBrightness = s.ccBrightness end
			if type(s.ccContrast) == "number" then WorldSky.ccContrast = s.ccContrast end
			if type(s.ccSaturation) == "number" then WorldSky.ccSaturation = s.ccSaturation end
			WorldSky.ccTint = tableToColor(s.ccTint, WorldSky.ccTint)
			if type(s.bloom) == "boolean" then WorldSky.bloom = s.bloom end
			if type(s.bloomIntensity) == "number" then WorldSky.bloomIntensity = s.bloomIntensity end
			if type(s.bloomSize) == "number" then WorldSky.bloomSize = s.bloomSize end
			if type(s.bloomThreshold) == "number" then WorldSky.bloomThreshold = s.bloomThreshold end
			if type(s.weather) == "boolean" then WorldSky.weather = s.weather end
			if type(s.weatherType) == "string" then
				local kind = string.lower(s.weatherType)
				if kind == "rain" then
					WorldSky.weatherType = "Rain"
				elseif kind == "blizzard" then
					WorldSky.weatherType = "Blizzard"
				else
					WorldSky.weatherType = "Snow"
				end
			end
			if type(s.weatherHeight) == "number" then
				WorldSky.weatherHeight = math.clamp(s.weatherHeight, 8, 160)
			end
			if type(s.weatherGlow) == "number" then
				WorldSky.weatherGlow = math.clamp(s.weatherGlow, 0, 1)
			end
			if type(s.weatherSpread) == "number" then
				WorldSky.weatherSpread = math.clamp(s.weatherSpread, 0, 4)
			end
			if type(s.weatherOpacity) == "number" then
				WorldSky.weatherOpacity = math.clamp(s.weatherOpacity, 0, 100)
			end
			if type(s.weatherRadius) == "number" then
				WorldSky.weatherRadius = math.clamp(s.weatherRadius, 10, 200)
			end
			if type(s.weatherIntensity) == "number" then
				WorldSky.weatherIntensity = math.clamp(s.weatherIntensity, 0, 100)
			end
			WorldSky.weatherColor = tableToColor(s.weatherColor, WorldSky.weatherColor)
			if type(s.weatherSize) == "number" then WorldSky.weatherSize = math.clamp(s.weatherSize, 0.05, 4) end
			if type(s.weatherAmount) == "number" then WorldSky.weatherAmount = math.clamp(s.weatherAmount, 0, 400) end
			if type(s.weatherSpeed) == "number" then WorldSky.weatherSpeed = math.clamp(s.weatherSpeed, 0, 80) end
			if type(s.weatherDuration) == "number" then WorldSky.weatherDuration = math.clamp(s.weatherDuration, 0.2, 20) end
			if type(s.weatherAlive) == "number" then WorldSky.weatherAlive = math.clamp(s.weatherAlive, 0.2, 20) end
			if type(s.weatherWind) == "number" then WorldSky.weatherWind = math.clamp(s.weatherWind, 0, 80) end
			if type(s.weatherDirection) == "number" then WorldSky.weatherDirection = math.clamp(s.weatherDirection, 0, 360) end
			if type(s.weatherRandom) == "boolean" then WorldSky.weatherRandom = s.weatherRandom end
			if type(s.weatherSpeedMin) == "number" then WorldSky.weatherSpeedMin = math.clamp(s.weatherSpeedMin, 0, 80) end
			if type(s.weatherSpeedMax) == "number" then WorldSky.weatherSpeedMax = math.clamp(s.weatherSpeedMax, 0, 80) end
			if type(s.weatherSizeMin) == "number" then WorldSky.weatherSizeMin = math.clamp(s.weatherSizeMin, 0.05, 4) end
			if type(s.weatherSizeMax) == "number" then WorldSky.weatherSizeMax = math.clamp(s.weatherSizeMax, 0.05, 4) end
			if type(s.skybox) == "boolean" then WorldSky.skybox = s.skybox end
			if type(s.skyboxName) == "string" and SKYBOX_CATALOG[s.skyboxName] then
				WorldSky.skyboxName = s.skyboxName
			end
			if type(s.theme) == "string" then WorldSky.theme = s.theme end
			if type(s.shadows) == "boolean" then WorldSky.shadows = s.shadows end
			if type(s.shadowsOn) == "boolean" then WorldSky.shadowsOn = s.shadowsOn end
			if type(s.envDiffuse) == "boolean" then WorldSky.envDiffuse = s.envDiffuse end
			if type(s.envDiffuseVal) == "number" then WorldSky.envDiffuseVal = math.clamp(s.envDiffuseVal, 0, 3) end
		end
		if type(data.fx) == "table" then
			local f = data.fx
			if type(f.blur) == "boolean" then WorldFx.blur = f.blur end
			if type(f.blurSize) == "number" then WorldFx.blurSize = math.clamp(f.blurSize, 0, 56) end
			if type(f.dof) == "boolean" then WorldFx.dof = f.dof end
			if type(f.dofFar) == "number" then WorldFx.dofFar = math.clamp(f.dofFar, 0, 1) end
			if type(f.dofFocus) == "number" then WorldFx.dofFocus = math.clamp(f.dofFocus, 1, 200) end
			if type(f.dofIn) == "number" then WorldFx.dofIn = math.clamp(f.dofIn, 0, 100) end
			if type(f.dofNear) == "number" then WorldFx.dofNear = math.clamp(f.dofNear, 0, 1) end
			if type(f.sunRays) == "boolean" then WorldFx.sunRays = f.sunRays end
			if type(f.sunIntensity) == "number" then WorldFx.sunIntensity = math.clamp(f.sunIntensity, 0, 1) end
			if type(f.sunSpread) == "number" then WorldFx.sunSpread = math.clamp(f.sunSpread, 0, 1) end
		end
		task.defer(function()
			for _, paint in worldPaint do
				pcall(paint, false)
			end
			for _, gate in worldGates do
				pcall(gate)
			end
			pcall(applyWorldSky)
			if applyWorldMap then
				pcall(applyWorldMap)
			end
		end)
	end

	local function isPlayerCharacter(inst: Instance): boolean
		local model = inst:FindFirstAncestorOfClass("Model")
		if not model then
			return false
		end
		if not model:FindFirstChildOfClass("Humanoid") then
			return false
		end
		return Players:GetPlayerFromCharacter(model) ~= nil
	end

	local function isViewModelOrWeapon(inst: Instance): boolean
		local cur: Instance? = inst
		for _ = 1, 10 do
			if not cur then
				break
			end
			local n = string.lower(cur.Name)
			if string.find(n, "viewmodel", 1, true) or string.find(n, "firstperson", 1, true) then
				return true
			end
			cur = cur.Parent
		end
		local tool = inst:FindFirstAncestorOfClass("Tool")
		if tool and isPlayerCharacter(tool) then
			return true
		end
		return false
	end

