		mapgeometry = true,
	}

	local function pathHasToken(path: string, tokens: { string }): boolean
		for _, token in tokens do
			if string.find(path, token, 1, true) then
				return true
			end
		end
		return false
	end

	local function isSpawnedFxOrHitbox(inst: Instance): boolean
		local path = string.lower(inst:GetFullName())
		local name = string.lower(inst.Name)
		if pathHasToken(name, SKIP_NAME_TOKENS) or pathHasToken(path, SKIP_NAME_TOKENS) then
			return true
		end
		if pathHasToken(path, SKIP_FOLDER_TOKENS) then
			return true
		end
		return false
	end

	local cachedMapRoots: { Instance } = {}
	local cachedMapRootsAt = 0
	local function collectMapRoots(): { Instance }
		local now = os.clock()
		if #cachedMapRoots > 0 and (now - cachedMapRootsAt) < 2.5 then
			local alive = true
			for _, root in cachedMapRoots do
				if not root.Parent then
					alive = false
					break
				end
			end
			if alive then
				return cachedMapRoots
			end
		end
		local roots: { Instance } = {}
		local seen: { [Instance]: boolean } = {}
		local function add(inst: Instance?)
			if inst and not seen[inst] then
				seen[inst] = true
				table.insert(roots, inst)
			end
		end
		for _, child in Workspace:GetChildren() do
			local lower = string.lower(child.Name)
			if MAP_ROOT_NAMES[lower] then
				add(child)
			end
			if child:IsA("Folder") or child:IsA("Model") then
				for _, nested in child:GetChildren() do
					if MAP_ROOT_NAMES[string.lower(nested.Name)] then
						add(nested)
					end
				end
			end
		end
		cachedMapRoots = roots
		cachedMapRootsAt = now
		return roots
	end

	local function isMapGeometryPart(part: BasePart): boolean
		if isPlayerCharacter(part) or isViewModelOrWeapon(part) then
			return false
		end
		if isSpawnedFxOrHitbox(part) then
			return false
		end
		if part.Transparency >= 0.85 then
			return false
		end
		local ltmOk, ltm = pcall(function()
			return part.LocalTransparencyModifier
		end)
		if ltmOk and type(ltm) == "number" and ltm >= 0.85 then
			return false
		end
		if not part.Anchored then
			return false
		end
		if part:IsA("Terrain") then
			return false
		end
		return true
	end

	local function eachMapPart(callback: (BasePart) -> ())
		local roots = collectMapRoots()
		if #roots == 0 then
			for _, desc in Workspace:GetDescendants() do
				if desc:IsA("BasePart") and isMapGeometryPart(desc) then
					callback(desc)
				end
			end
			return
		end
		for _, root in roots do
			if root:IsA("BasePart") and isMapGeometryPart(root) then
				callback(root)
			end
			for _, desc in root:GetDescendants() do
				if desc:IsA("BasePart") and isMapGeometryPart(desc) then
					callback(desc)
				end
			end
		end
	end

	local worldUndo: any = {
		parts = setmetatable({}, { __mode = "k" }),
		decals = {},
		texProps = setmetatable({}, { __mode = "k" }),
		props = {},
		atmosphere = nil,
	}

	function worldUndo.stashDecal(decal: Instance)
		local parent = decal.Parent
		if not parent then
			return
		end
		if worldUndo.decals[decal] == nil then
			worldUndo.decals[decal] = parent
		end
		pcall(function()
			decal.Parent = nil
		end)
	end

	function worldUndo.stashTexProp(inst: Instance, prop: string, blank: any)
		local ok, current = pcall(function()
			return (inst :: any)[prop]
		end)
		if not ok then
			return
		end
		if current == nil or current == blank or current == "" then
			return
		end
		local bag = worldUndo.texProps[inst]
		if not bag then
			bag = {}
			worldUndo.texProps[inst] = bag
		end
		if bag[prop] == nil then
			bag[prop] = current
		end
		pcall(function()
			(inst :: any)[prop] = blank
		end)
	end

	function worldUndo.restoreDecals()
		for decal, parent in worldUndo.decals do
			pcall(function()
				if parent:IsDescendantOf(game) then
					decal.Parent = parent
				end
			end)
		end
		table.clear(worldUndo.decals)
		for inst, bag in worldUndo.texProps do
			for prop, value in bag do
				pcall(function()
					(inst :: any)[prop] = value
				end)
			end
		end
		table.clear(worldUndo.texProps)
	end

	function worldUndo.restoreMapParts()
		for part, o in worldUndo.parts do
			pcall(function()
				part.Material = o[1]
				part.Color = o[2]
				part.Reflectance = o[3]
				part.Transparency = o[4]
			end)
		end
		table.clear(worldUndo.parts)
	end

	local DECAL_SKIP_ANCESTOR = {
		viewmodels = true,
		characters = true,
		fighters = true,
		effects = true,
		projectiles = true,
		debris = true,
		vfx = true,
	}

	local function isSonataWorldInst(inst: Instance): boolean
		local n = string.lower(inst.Name)
		return string.sub(n, 1, 8) == "sonata_" or string.sub(n, 1, 9) == "__sonata" or n == "weatheremitter"
	end

	local function shouldSkipWorldDecal(inst: Instance): boolean
		if isPlayerCharacter(inst) or isViewModelOrWeapon(inst) then
			return true
		end
		local cur: Instance? = inst
		for _ = 1, 16 do
			if not cur or cur == Workspace then
				break
			end
			if isSonataWorldInst(cur) then
				return true
			end
			if DECAL_SKIP_ANCESTOR[string.lower(cur.Name)] then
				return true
			end
			if cur == Workspace.CurrentCamera then
				return true
			end
			cur = cur.Parent
		end
		return false
	end

	local function isWorldDecalInst(inst: Instance): boolean
		return inst:IsA("Decal") or inst:IsA("Texture") or inst:IsA("SurfaceAppearance")
	end

	local function stripTexturesOnInstance(inst: Instance)
		if shouldSkipWorldDecal(inst) then
			return
		end
		if isWorldDecalInst(inst) then
			worldUndo.stashDecal(inst)
			return
		end
		if inst:IsA("MeshPart") then
			worldUndo.stashTexProp(inst, "TextureID", "")
			pcall(function()
				worldUndo.stashTexProp(inst, "TextureContent", "")
			end)
			worldUndo.stashTexProp(inst, "MaterialVariant", "")
		elseif inst:IsA("SpecialMesh") or inst:IsA("FileMesh") then
			worldUndo.stashTexProp(inst, "TextureId", "")
		elseif inst:IsA("BasePart") then
			worldUndo.stashTexProp(inst, "MaterialVariant", "")
		end
	end

	local function worldDecalOrigin(): Vector3?
		local lp = Players.LocalPlayer
		local char = lp and lp.Character
		local root = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso") or char.PrimaryPart)
		if typeof(root) == "Instance" and root:IsA("BasePart") then
			return root.Position
		end
		local cam = Workspace.CurrentCamera
		if cam then
			return cam.CFrame.Position
		end
		return nil
	end

	local function stopDecalWatchers()
		if mapDescendantConn then
			mapDescendantConn:Disconnect()
			mapDescendantConn = nil
		end
		if decalSweepConn then
			decalSweepConn:Disconnect()
			decalSweepConn = nil
		end
	end

	local function stripDecalsNearPlayer()
		if not WorldMap.removeDecals then
			return
		end
		local origin = worldDecalOrigin()
		if not origin then
			return
		end
		local params = OverlapParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		local exclude: { Instance } = {}
		local lp = Players.LocalPlayer
		if lp and lp.Character then
			table.insert(exclude, lp.Character)
		end
		local vms = Workspace:FindFirstChild("ViewModels")
		if vms then
			table.insert(exclude, vms)
		end
		local chars = Workspace:FindFirstChild("Characters")
		if chars then
			table.insert(exclude, chars)
		end
		params.FilterDescendantsInstances = exclude
		pcall(function()
			params.MaxParts = 2000
		end)
		local ok, nearby = pcall(function()
			return Workspace:GetPartBoundsInRadius(origin, DECAL_AREA_RADIUS, params)
		end)
		if not ok or type(nearby) ~= "table" then
			return
		end
		for _, part in nearby do
			if typeof(part) == "Instance" and part:IsA("BasePart") and isMapGeometryPart(part) then
				stripTexturesOnInstance(part)
				for _, child in part:GetChildren() do
					stripTexturesOnInstance(child)
				end
			end
		end
	end

	applyWorldMap = function()
		if not WorldMap.worldMaterial and next(worldUndo.parts) ~= nil then
			worldUndo.restoreMapParts()
		end
		if not WorldMap.removeDecals then
			if next(worldUndo.decals) ~= nil or next(worldUndo.texProps) ~= nil then
				worldUndo.restoreDecals()
			end
			stopDecalWatchers()
			decalsStrippedOnce = false
		end
		if not worldMatchActive() then
			return
		end
		if not anyWorldMapActive() then
			return
		end

		stopDecalWatchers()
		if WorldMap.removeDecals and not decalsStrippedOnce then
			stripDecalsNearPlayer()
			decalsStrippedOnce = true
		end

		if not WorldMap.worldMaterial then
			return
		end

		local mat = Enum.Material.SmoothPlastic
		pcall(function()
			mat = Enum.Material[WorldMap.material]
		end)
		local reflectance = math.clamp(WorldMap.reflectance, 0, 1)
		local transparency = 1 - math.clamp(WorldMap.opacity, 0, 1)
		eachMapPart(function(part)
			if worldUndo.parts[part] == nil then
				worldUndo.parts[part] = { part.Material, part.Color, part.Reflectance, part.Transparency }
			end
			pcall(function()
				part.Material = mat
				part.Color = WorldMap.materialColor
				part.Reflectance = reflectance
				if WorldMap.opacity < 0.999 then
					part.Transparency = transparency
				end
			end)
		end)
	end

	local function ensureLightingChild(className: string): Instance
		local found = Lighting:FindFirstChildOfClass(className)
		if found then
			return found
		end
		local inst = Instance.new(className)
		inst.Parent = Lighting
		return inst
	end

	local function ensureSonataEffect(className: string, name: string): Instance
		local existing = Lighting:FindFirstChild(name)
		if existing and existing:IsA(className) then
			return existing
		end
		if existing then
			pcall(function()
				existing:Destroy()
			end)
		end
		local inst = Instance.new(className)
		inst.Name = name
		inst.Parent = Lighting
		return inst
	end

	local function setEffectEnabled(inst: Instance?, on: boolean)
		if not inst then
			return
		end
		pcall(function()
			(inst :: any).Enabled = on
		end)
	end

	function worldUndo.setProp(inst: Instance, prop: string, value: any)
		local bag = worldUndo.props[inst]
		if not bag then
			bag = {}
			worldUndo.props[inst] = bag
		end
		local ok, current = pcall(function()
			return (inst :: any)[prop]
		end)
		if not ok then
			return
		end
		if bag[prop] == nil then
			bag[prop] = current
		end
		if current ~= value then
			pcall(function()
				(inst :: any)[prop] = value
			end)
		end
	end

	DrawingBridge.revertWorld = function()
		for key, value in WorldSky do
			if type(value) == "boolean" and key ~= "shadowsOn" then
				WorldSky[key] = false
			end
		end
		for _, key in { "blur", "dof", "sunRays" } do
			WorldFx[key] = false
		end
		WorldMap.removeDecals = false
		WorldMap.worldMaterial = false
		pcall(applySkyboxOverride)
		worldUndo.restoreDecals()
		worldUndo.restoreMapParts()
		for inst, bag in worldUndo.props do
			for prop, value in bag do
				pcall(function()
					(inst :: any)[prop] = value
				end)
			end
		end
		table.clear(worldUndo.props)
		if worldUndo.atmosphere then
			pcall(function()
				(worldUndo.atmosphere :: Instance):Destroy()
			end)
			worldUndo.atmosphere = nil
		end
		for _, name in { "sonata_cc", "sonata_bloom", "sonata_blur", "sonata_dof", "sonata_sunrays", "sonata_skybox" } do
			local inst = Lighting:FindFirstChild(name)
			if inst then
				pcall(function()
					inst:Destroy()
				end)
			end
		end
	end

	applyWorldSky = function()
		if WorldSky.clock then
			worldUndo.setProp(Lighting, "ClockTime", WorldSky.clockTime)
		end
		if WorldSky.ambience then
			worldUndo.setProp(Lighting, "Ambient", WorldSky.ambient)
			worldUndo.setProp(Lighting, "OutdoorAmbient", WorldSky.outdoorAmbient)
		end
		if WorldSky.brightness then
			worldUndo.setProp(Lighting, "Brightness", WorldSky.brightnessVal)
		end
		if WorldSky.exposure then
			worldUndo.setProp(Lighting, "ExposureCompensation", WorldSky.exposureVal)
		end
		if WorldSky.fog then
			worldUndo.setProp(Lighting, "FogColor", WorldSky.fogColor)
			worldUndo.setProp(Lighting, "FogStart", WorldSky.fogStart)
			worldUndo.setProp(Lighting, "FogEnd", WorldSky.fogEnd)
		end
		if WorldSky.shadows then
			worldUndo.setProp(Lighting, "GlobalShadows", WorldSky.shadowsOn == true)
		end
		if WorldSky.envDiffuse then
			worldUndo.setProp(Lighting, "EnvironmentDiffuseScale", math.clamp(WorldSky.envDiffuseVal, 0, 3))
		end
		if WorldSky.atmosphere then
			local existed = Lighting:FindFirstChildOfClass("Atmosphere")
			local atm = ensureLightingChild("Atmosphere") :: Atmosphere
			if not existed then
				worldUndo.atmosphere = atm
			end
			worldUndo.setProp(atm, "Density", WorldSky.atmDensity)
			worldUndo.setProp(atm, "Offset", WorldSky.atmOffset)
			worldUndo.setProp(atm, "Color", WorldSky.atmColor)
			worldUndo.setProp(atm, "Decay", WorldSky.atmDecay)
			worldUndo.setProp(atm, "Glare", WorldSky.atmGlare)
			worldUndo.setProp(atm, "Haze", WorldSky.atmHaze)
		end

		if WorldSky.colorCorrection then
			local cc = ensureSonataEffect("ColorCorrectionEffect", "sonata_cc") :: ColorCorrectionEffect
			cc.Brightness = WorldSky.ccBrightness
			cc.Contrast = WorldSky.ccContrast
			cc.Saturation = WorldSky.ccSaturation
			cc.TintColor = WorldSky.ccTint
			setEffectEnabled(cc, true)
		else
			setEffectEnabled(Lighting:FindFirstChild("sonata_cc"), false)
		end

		if WorldSky.bloom then
			local bloom = ensureSonataEffect("BloomEffect", "sonata_bloom") :: BloomEffect
			bloom.Intensity = WorldSky.bloomIntensity
			bloom.Size = WorldSky.bloomSize
			bloom.Threshold = WorldSky.bloomThreshold
			setEffectEnabled(bloom, true)
		else
			setEffectEnabled(Lighting:FindFirstChild("sonata_bloom"), false)
		end

		if WorldFx.blur then
			local blur = ensureSonataEffect("BlurEffect", "sonata_blur") :: BlurEffect
			blur.Size = math.clamp(WorldFx.blurSize, 0, 56)
			setEffectEnabled(blur, true)
		else
			setEffectEnabled(Lighting:FindFirstChild("sonata_blur"), false)
		end

		if WorldFx.dof then
			local dof = ensureSonataEffect("DepthOfFieldEffect", "sonata_dof") :: DepthOfFieldEffect
			dof.FarIntensity = math.clamp(WorldFx.dofFar, 0, 1)
			dof.FocusDistance = math.clamp(WorldFx.dofFocus, 1, 200)
			dof.InFocusRadius = math.clamp(WorldFx.dofIn, 0, 100)
			dof.NearIntensity = math.clamp(WorldFx.dofNear, 0, 1)
			setEffectEnabled(dof, true)
		else
			setEffectEnabled(Lighting:FindFirstChild("sonata_dof"), false)
		end

		if WorldFx.sunRays then
			local rays = ensureSonataEffect("SunRaysEffect", "sonata_sunrays") :: SunRaysEffect
			rays.Intensity = math.clamp(WorldFx.sunIntensity, 0, 1)
			rays.Spread = math.clamp(WorldFx.sunSpread, 0, 1)
			setEffectEnabled(rays, true)
		else
			setEffectEnabled(Lighting:FindFirstChild("sonata_sunrays"), false)
		end

		applySkyboxOverride()
	end

	do
		local SOFT_TEX = "rbxasset://textures/particles/smoke_main.dds"
		local SPARKLE_TEX = "rbxasset://textures/particles/sparkles_main.dds"
		local KICIA_WEATHER = {
			Snow = {
				{
					Texture = SOFT_TEX, TransparencyMax = 0.22, LifetimeMin = 6, LifetimeMax = 9, BaseRate = 200,
					SpeedMin = 5, SpeedMax = 9, SizeStart = 0.32, SizeEnd = 0.22, BaseSpread = 0.35, BaseAccelerationY = -0.8,
				},
				{
					Texture = SPARKLE_TEX, TransparencyMax = 0.42, LifetimeMin = 6, LifetimeMax = 9, BaseRate = 48,
					SpeedMin = 4, SpeedMax = 7, SizeStart = 0.16, SizeEnd = 0.12, BaseSpread = 0.5, BaseAccelerationY = -0.4,
				},
			},
			Rain = {
				{
					Texture = SOFT_TEX, TransparencyMax = 0.4, LifetimeMin = 1.15, LifetimeMax = 1.7, BaseRate = 560,
					SpeedMin = 68, SpeedMax = 88, SizeStart = 0.1, SizeEnd = 0.08, BaseSpread = 0.04, BaseAccelerationY = -38,
					RotationMin = 0, RotationMax = 0, RotationSpeedMin = 0, RotationSpeedMax = 0,
					Orientation = Enum.ParticleOrientation.VelocityParallel,
				},
			},
			Blizzard = {
				{
					Texture = SOFT_TEX, TransparencyMax = 0.2, LifetimeMin = 3, LifetimeMax = 5, BaseRate = 620,
					SpeedMin = 16, SpeedMax = 26, SizeStart = 0.26, SizeEnd = 0.18, BaseSpread = 0.7, BaseAccelerationY = -5,
				},
				{
					Texture = SOFT_TEX, TransparencyMax = 0.82, LifetimeMin = 3, LifetimeMax = 5, BaseRate = 90,
					SpeedMin = 12, SpeedMax = 20, SizeStart = 2.4, SizeEnd = 4.2, BaseSpread = 0.9, BaseAccelerationY = -1.6,
				},
			},
		}
		local weatherPart: BasePart? = nil
		local weatherEmitters: { ParticleEmitter } = {}
		local lastWeatherType = ""

		local function weatherKind(): string
			local kind = string.lower(tostring(WorldSky.weatherType or "Snow"))
			if kind == "rain" then
				return "Rain"
			end
			if kind == "blizzard" then
				return "Blizzard"
			end
			return "Snow"
		end

		local function destroyWeather()
			for _, emitter in weatherEmitters do
				pcall(function()
					emitter:Destroy()
				end)
			end
			table.clear(weatherEmitters)
			if weatherPart then
				pcall(function()
					weatherPart:Destroy()
				end)
				weatherPart = nil
			end
			lastWeatherType = ""
		end

		local function fadeSequence(peak: number): NumberSequence
			peak = math.clamp(peak, 0, 1)
			local mid = peak + (1 - peak) * 0.22
			return NumberSequence.new({
				NumberSequenceKeypoint.new(0, 1),
				NumberSequenceKeypoint.new(0.1, mid),
				NumberSequenceKeypoint.new(0.22, peak),
				NumberSequenceKeypoint.new(0.78, peak),
				NumberSequenceKeypoint.new(0.9, mid),
				NumberSequenceKeypoint.new(1, 1),
			})
		end

		local function scaleSize(startS: number, endS: number, mul: number): NumberSequence
			return NumberSequence.new(startS * mul, endS * mul)
		end

		local function ensureWeather(): BasePart?
			local kind = weatherKind()
			if weatherPart and weatherPart.Parent and lastWeatherType == kind and #weatherEmitters > 0 then
				return weatherPart
			end
			destroyWeather()
			local part = Instance.new("Part")
			part.Name = "WeatherEmitter"
			part.Anchored = true
			part.CanCollide = false
			part.CanQuery = false
			part.CanTouch = false
			part.Transparency = 1
			part.Size = Vector3.new(148, 2, 148)
			part.CastShadow = false
			part.Massless = true
			part.Parent = Workspace
			local specs = KICIA_WEATHER[kind] or KICIA_WEATHER.Snow
			for _, spec in specs do
				local emitter = Instance.new("ParticleEmitter")
				emitter.Name = "Weather"
				emitter.Shape = Enum.ParticleEmitterShape.Box
				emitter.EmissionDirection = Enum.NormalId.Bottom
				emitter.Enabled = true
				emitter.Texture = spec.Texture
				emitter.Transparency = fadeSequence(spec.TransparencyMax)
				emitter.Lifetime = NumberRange.new(spec.LifetimeMin, spec.LifetimeMax)
				emitter.Rotation = NumberRange.new(spec.RotationMin or 0, spec.RotationMax or 360)
				emitter.RotSpeed = NumberRange.new(spec.RotationSpeedMin or -40, spec.RotationSpeedMax or 40)
				emitter.LightInfluence = 0
				emitter.LockedToPart = false
				emitter.ZOffset = 0
				if spec.Orientation then
					emitter.Orientation = spec.Orientation
				end
				emitter.Parent = part
				table.insert(weatherEmitters, emitter)
			end
			weatherPart = part
			lastWeatherType = kind
			return part
		end

		local lastWeatherSig = ""
		local function weatherSignature(): string
			local sky = WorldSky
			return table.concat({
				weatherKind(),
				string.format("%.2f", sky.weatherIntensity),
				string.format("%.2f", sky.weatherAmount),
				string.format("%.2f", sky.weatherHeight),
				string.format("%.2f", sky.weatherSize),
				string.format("%.2f", sky.weatherSpeed),
				string.format("%.2f", sky.weatherGlow),
				string.format("%.2f", sky.weatherSpread),
				string.format("%.2f", sky.weatherOpacity or 85),
				string.format("%.2f", sky.weatherWind),
				string.format("%.0f", sky.weatherDirection),
				tostring(sky.weatherColor),
			}, "|")
		end

		local function paintWeather(part: BasePart)
			local kind = weatherKind()
			local specs = KICIA_WEATHER[kind] or KICIA_WEATHER.Snow
			local sky = WorldSky
			local intensity = math.clamp((tonumber(sky.weatherIntensity) or 100) / 100, 0, 3)
			local rate = math.clamp((tonumber(sky.weatherAmount) or 100) / 100, 0, 4)
			local speed = math.clamp(tonumber(sky.weatherSpeed) or 1, 0.05, 8)
			local size = math.clamp(tonumber(sky.weatherSize) or 1, 0.05, 6)
			local glow = math.clamp(tonumber(sky.weatherGlow) or 0, 0, 1)
			local spread = math.clamp(tonumber(sky.weatherSpread) or 1, 0, 4)
			local opacity = math.clamp((tonumber(sky.weatherOpacity) or 85) / 100, 0, 1)
			local wind = math.clamp(tonumber(sky.weatherWind) or 6, 0, 80)
			local rad = math.rad(math.clamp(tonumber(sky.weatherDirection) or 20, 0, 360))
			local tint = if typeof(sky.weatherColor) == "Color3" then sky.weatherColor else Color3.fromRGB(255, 255, 255)
			local color = ColorSequence.new(tint)
			part.Size = Vector3.new(148, 2, 148)
			for i, emitter in weatherEmitters do
				local spec = specs[i] or specs[1]
				local peak = 1 - (1 - (spec.TransparencyMax or 0.2)) * opacity
				emitter.Rate = spec.BaseRate * intensity * rate
				emitter.Speed = NumberRange.new(spec.SpeedMin * speed, spec.SpeedMax * speed)
				emitter.Size = scaleSize(spec.SizeStart, spec.SizeEnd, size)
				emitter.LightEmission = glow
				emitter.Transparency = fadeSequence(peak)
				emitter.Drag = if kind == "Rain" then 0 else 1.15
				local ang = spec.BaseSpread * spread
				emitter.SpreadAngle = Vector2.new(ang, ang)
				emitter.Color = color
				emitter.Acceleration = Vector3.new(math.sin(rad) * wind, spec.BaseAccelerationY, math.cos(rad) * wind)
				emitter.Enabled = opacity > 0.01 and intensity > 0 and rate > 0
			end
		end

		local function syncWeather()
			if not WorldSky.weather then
				if weatherPart then
					destroyWeather()
				end
				lastWeatherSig = ""
				return
			end
			local part = ensureWeather()
			if not part then
				return
			end
			local cam = Workspace.CurrentCamera
			if not cam then
				return
			end
			local height = math.clamp(tonumber(WorldSky.weatherHeight) or 40, 8, 160)
			part.CFrame = CFrame.new(cam.CFrame.Position + Vector3.new(0, height, 0))
			local sig = weatherSignature()
			if sig ~= lastWeatherSig then
				lastWeatherSig = sig
				paintWeather(part)
			end
		end

		table.insert(ears, RunService.Heartbeat:Connect(function()
			if DrawingBridge.library and DrawingBridge.library.uiDragging then
				return
			end
			syncWeather()
		end))
		table.insert(ears, {
			Disconnect = function()
				destroyWeather()
			end,
		} :: any)
	end

	local function requestWorldMapApply()
		if applyWorldMap then
			applyWorldMap()
		end
	end

	do
		local cleanCF: CFrame? = nil
		local stretchedCF: CFrame? = nil
		local function unstretch(cf: CFrame, sx: number): CFrame
			local x, y, z, r00, r01, r02, r10, r11, r12, r20, r21, r22 = cf:GetComponents()
			local mag = math.sqrt(r00 * r00 + r10 * r10 + r20 * r20)
			if mag > 1e-4 and math.abs(mag - sx) < 0.05 and math.abs(sx - 1) > 0.001 then
				local inv = 1 / sx
				return CFrame.new(x, y, z, r00 * inv, r01, r02, r10 * inv, r11, r12, r20 * inv, r21, r22)
			end
			return cf
		end
		local function stretchOf(cf: CFrame, sx: number): CFrame
			local x, y, z, r00, r01, r02, r10, r11, r12, r20, r21, r22 = cf:GetComponents()
			return CFrame.new(x, y, z, r00 * sx, r01, r02, r10 * sx, r11, r12, r20 * sx, r21, r22)
		end
		local function restoreAspect()
			local cam = Workspace.CurrentCamera
			if not cam or not cleanCF or not stretchedCF then
				return
			end
			if cam.CFrame == stretchedCF then
				cam.CFrame = cleanCF
			end
		end
		local function clearAspect(cam: Camera?)
			if cam and cleanCF and stretchedCF and cam.CFrame == stretchedCF then
				cam.CFrame = cleanCF
			end
			cleanCF = nil
			stretchedCF = nil
		end
		local function applyAspect()
			local cam = Workspace.CurrentCamera
			if not cam or not Qol.aspect then
				clearAspect(cam)
				return
			end
			local sx = math.clamp(Qol.aspectX, 0.05, 1.5)
			if math.abs(sx - 1) < 0.0008 then
				clearAspect(cam)
				return
			end
			local current = cam.CFrame
			local base = if stretchedCF and cleanCF and current == stretchedCF then cleanCF else unstretch(current, sx)
			local stretched = stretchOf(base, sx)
			cleanCF = base
			stretchedCF = stretched
			if current ~= stretched then
				cam.CFrame = stretched
			end
		end
		local function bindAspect(name: string, priority: number, fn: () -> ())
			local ok = pcall(function()
				RunService:BindToRenderStep(name, priority, fn)
			end)
			if ok then
				table.insert(ears, {
					Disconnect = function()
						pcall(function()
							RunService:UnbindFromRenderStep(name)
						end)
					end,
				} :: any)
			end
			return ok
		end
		bindAspect("__sonata_aspect_restore", Enum.RenderPriority.First.Value, restoreAspect)
		if not bindAspect("__sonata_aspect", Enum.RenderPriority.Last.Value, applyAspect) then
			table.insert(ears, RunService.RenderStepped:Connect(applyAspect))
		end
	end

	do
		local camCtrlCache: any = nil
		local wasThird = false
		local savedMinZoom: number? = nil
		local savedMaxZoom: number? = nil
		local lastForce = 0

		local function getCameraController(): any?
			if camCtrlCache then
				return camCtrlCache
			end
			local lp = Players.LocalPlayer
			if not lp then
				return nil
			end
			local scripts = lp:FindFirstChild("PlayerScripts")
			local controllers = scripts and scripts:FindFirstChild("Controllers")
			local mod = controllers and controllers:FindFirstChild("CameraController")
			if not mod then
				return nil
			end
			local ok, ctrl = pcall(require, mod)
			if ok and type(ctrl) == "table" then
				camCtrlCache = ctrl
				return ctrl
			end
			return nil
		end

		local function applyThirdPerson(enabled: boolean)
			local ctrl = getCameraController()
			local lp = Players.LocalPlayer
			if not ctrl then
				return
			end
			if enabled then
				pcall(function()
					ctrl:SetThirdPersonOverride(true)
				end)
				pcall(function()
					local cs = ctrl.CameraState
					if cs and cs.States then
						if cs._pov_state == cs.States.FirstPerson or cs._pov_state == nil then
							cs:_SetPOVState(cs.States.ThirdPerson)
						end
						cs:VerifyPOV()
					end
				end)
				if lp then
					if savedMinZoom == nil then
						savedMinZoom = lp.CameraMinZoomDistance
						savedMaxZoom = lp.CameraMaxZoomDistance
					end
					local dist = math.clamp(Qol.thirdPersonDistance or 10, 2, 50)
					pcall(function()
						lp.CameraMinZoomDistance = dist
						lp.CameraMaxZoomDistance = dist
						lp.CameraMode = Enum.CameraMode.Classic
					end)
				end
			else
				pcall(function()
					ctrl:SetThirdPersonOverride(nil)
				end)
				pcall(function()
					local cs = ctrl.CameraState
					if cs and cs.States then
						cs:_SetPOVState(cs.States.FirstPerson)
						cs:VerifyPOV()
					end
				end)
				if lp and savedMinZoom ~= nil then
					pcall(function()
						lp.CameraMinZoomDistance = savedMinZoom :: number
						lp.CameraMaxZoomDistance = savedMaxZoom or 128
					end)
					savedMinZoom = nil
					savedMaxZoom = nil
				end
			end
		end
		DrawingBridge.forceThirdPersonUpdate = function()
			if Qol.thirdPerson == true then
				applyThirdPerson(true)
			end
		end

		table.insert(ears, UserInputService.InputBegan:Connect(function(input: InputObject, processed: boolean)
			if processed or UserInputService:GetFocusedTextBox() then
				return
			end
			local keyName = Qol.thirdPersonKey
			if type(keyName) ~= "string" or keyName == "" or keyName == "None" or keyName == "NONE" then
				return
			end
			local hit = if keyName == "MouseButton1" then input.UserInputType == Enum.UserInputType.MouseButton1
				elseif keyName == "MouseButton2" then input.UserInputType == Enum.UserInputType.MouseButton2
				elseif keyName == "MouseButton3" then input.UserInputType == Enum.UserInputType.MouseButton3
				else input.KeyCode.Name == keyName
			if hit then
				Qol.thirdPerson = not Qol.thirdPerson
				if DrawingBridge.requestSync then
					pcall(DrawingBridge.requestSync)
				end
			end
		end))

		table.insert(ears, RunService.Heartbeat:Connect(function()
			local want = Qol.thirdPerson == true
			if want ~= wasThird then
				wasThird = want
				applyThirdPerson(want)
				lastForce = os.clock()
				return
			end
			if want and os.clock() - lastForce > 0.35 then
				lastForce = os.clock()
				applyThirdPerson(true)
			end
		end))
	end

	local flashHooksInstalled = false
	local function installFlashHooks()
		if flashHooksInstalled then
			return
		end
		local lp = Players.LocalPlayer
		if not lp then
			return
		end
		local flashedMod: any = nil
		pcall(function()
			flashedMod = require((lp :: Player).PlayerScripts.Modules.ClientReplicatedClasses.ClientFighter.FighterInterface.Flashed)
		end)
		if type(flashedMod) == "table" then
			if type(flashedMod.AttemptToFlash) == "function" then
				local previousAttempt = flashedMod.AttemptToFlash
				flashedMod.AttemptToFlash = function(self, ...)
					if Qol.removeFlash then
						return
					end
					return previousAttempt(self, ...)
				end
				table.insert(ears, {
					Disconnect = function()
						flashedMod.AttemptToFlash = previousAttempt
					end,
				} :: any)
			end
			if type(flashedMod.Flash) == "function" then
				local previousFlash = flashedMod.Flash
				flashedMod.Flash = function(self, ...)
					if Qol.removeFlash then
						return
					end
					return previousFlash(self, ...)
				end
				table.insert(ears, {
					Disconnect = function()
						flashedMod.Flash = previousFlash
					end,
				} :: any)
			end
			flashHooksInstalled = true
		end
		pcall(function()
			local effectMod = (lp :: Player).PlayerScripts.Modules.Functions:FindFirstChild("FlashbangEffect")
			if effectMod then
				local ok, flashFn = pcall(require, effectMod)
				if ok and type(flashFn) == "function" then
					local parent = effectMod.Parent
					local _ = parent
					local _ = flashFn
				end
			end
		end)
	end

	local function scrubFlashEffects()
		if not Qol.removeFlash then
			return
		end
		local lp = Players.LocalPlayer
		if not lp then
			return
		end
		local gui = lp:FindFirstChild("PlayerGui")
		if gui then
			for _, child in gui:GetChildren() do
				local name = string.lower(child.Name)
				if string.find(name, "flashbang", 1, true) or string.find(name, "flash", 1, true) and string.find(name, "bang", 1, true) then
					pcall(function()
						child:Destroy()
					end)
				end
			end
		end
		pcall(function()
			for _, child in Lighting:GetChildren() do
				if child:IsA("ColorCorrectionEffect") and (child.Name == "Flashbang" or string.find(string.lower(child.Name), "flash", 1, true)) then
					child:Destroy()
				end
			end
		end)
		pcall(function()
			local char = lp.Character
			if char and char:GetAttribute("Flashed") == true then
				char:SetAttribute("Flashed", false)
			end
		end)
	end

	task.spawn(function()
		for _ = 1, 40 do
			installFlashHooks()
			if flashHooksInstalled then
				break
			end
			task.wait(0.5)
		end
	end)

	local lastFlashScrub = 0
	table.insert(ears, RunService.Heartbeat:Connect(function()
		if not Qol.removeFlash then
			return
		end
		installFlashHooks()
		local now = os.clock()
		if now - lastFlashScrub < 0.15 then
			return
		end
		lastFlashScrub = now
		scrubFlashEffects()
	end))

	do
		local DROP_MODEL_NAMES: { [string]: boolean } = {
			Weapon = true,
			Health = true,
			Ammo = true,
			Revive = true,
			AmmoBalanced = true,
		}
		local itemLibCache: any = nil
		local weaponsByClass: { [string]: { string } } = {
			Primary = {},
			Secondary = {},
			Melee = {},
			Utility = {},
		}
		local weaponsByClassAt = 0
		local lastRespawnAt = 0
		local lastLoadoutAt = 0
		local loadoutHooked = false
		local oldOpenPickWeapons: any = nil

		local function getItemLibrary(): any?
			if itemLibCache then
				return itemLibCache
			end
			local ok, lib = pcall(function()
				return require(ReplicatedStorage.Modules.ItemLibrary)
			end)
			if ok and type(lib) == "table" then
				itemLibCache = lib
				return lib
			end
			return nil
		end

		local function refreshWeaponLists(force: boolean?)
			local now = os.clock()
			if not force and now - weaponsByClassAt < 8 and #weaponsByClass.Primary > 0 then
				return
			end
			local lib = getItemLibrary()
			if not lib or type(lib.Items) ~= "table" then
				return
			end
			local nextLists: { [string]: { string } } = {
				Primary = {},
				Secondary = {},
				Melee = {},
				Utility = {},
			}
			local alphabetized = lib.ItemsAlphabetized
			if type(alphabetized) == "table" then
				for _, name in alphabetized do
					if type(name) == "string" then
						local info = lib.Items[name]
						local className = info and info.Class
						local bucket = className and nextLists[className]
						if bucket then
							table.insert(bucket, name)
						end
					end
				end
			else
				for name, info in lib.Items do
					if type(name) == "string" and type(info) == "table" then
						local bucket = nextLists[info.Class]
						if bucket then
							table.insert(bucket, name)
						end
					end
				end
				for _, bucket in nextLists do
					table.sort(bucket)
				end
			end
			weaponsByClass = nextLists
			weaponsByClassAt = now
		end

		DrawingBridge.getLoadoutWeaponOptions = function(className: string): { string }
			refreshWeaponLists(false)
			local list = weaponsByClass[className]
			local out = { "Random" }
			if type(list) == "table" then
				for _, name in list do
					table.insert(out, name)
				end
			end
			return out
		end

		local function playerDataController(): any?
			local lp = Players.LocalPlayer
			if not lp then
				return nil
			end
			local ok, pdc = pcall(function()
				return require(lp.PlayerScripts.Controllers.PlayerDataController)
			end)
			if ok then
				return pdc
			end
			return nil
		end

		local function ownsWeapon(name: string): boolean
			if type(name) ~= "string" or name == "" or name == "Random" then
				return false
			end
			local pdc = playerDataController()
			if not pdc then
				return false
			end
			local ok, data = pcall(function()
				return pdc:GetWeaponData(name)
			end)
			return ok and data ~= nil
		end

		local function ownedWeaponsOfClass(className: string): { string }
			refreshWeaponLists(false)
			local owned = {}
			local list = weaponsByClass[className]
			if type(list) ~= "table" then
				return owned
			end
			for _, name in list do
				if ownsWeapon(name) then
					table.insert(owned, name)
				end
			end
			return owned
		end

		local function pickWeaponForClass(className: string, preferred: string): string?
			local owned = ownedWeaponsOfClass(className)
			if #owned == 0 then
				refreshWeaponLists(false)
				local all = weaponsByClass[className]
				if type(all) == "table" and #all > 0 then
					return all[math.random(1, #all)]
				end
				return nil
			end
			if type(preferred) == "string" and preferred ~= "" and preferred ~= "Random" then
				for _, name in owned do
					if name == preferred then
						return name
					end
				end
			end
			return owned[math.random(1, #owned)]
		end

		local function buildChosenWeapons(): { [number]: string }
			local chosen: { [number]: string } = {}
			local prefs = {
				Qol.loadoutPrimary,
				Qol.loadoutSecondary,
				Qol.loadoutMelee,
				Qol.loadoutUtility,
			}
			local classes = { "Primary", "Secondary", "Melee", "Utility" }
			local maxSlots = 4
			pcall(function()
				local lp = Players.LocalPlayer
				local fc = require(lp.PlayerScripts.Controllers.FighterController)
				local fighter = fc and (fc.LocalFighter or (fc.GetFighter and fc:GetFighter(lp)))
				if fighter and type(fighter.GetMaxEquippableWeapons) == "function" then
					maxSlots = math.clamp(math.floor(fighter:GetMaxEquippableWeapons()), 1, 4)
				end
			end)
			for slot = 1, maxSlots do
				local picked = pickWeaponForClass(classes[slot], prefs[slot])
				if type(picked) == "string" then
					chosen[slot] = picked
				end
			end
			return chosen
		end

		local function submitAutoLoadout()
			if not Qol.autoLoadout then
				return
			end
			local now = os.clock()
			if now - lastLoadoutAt < 0.35 then
				return
			end
			lastLoadoutAt = now
			local chosen = buildChosenWeapons()
			if next(chosen) == nil then
				return
			end
			pcall(function()
				local lp = Players.LocalPlayer
				local duelCtrl = require(lp.PlayerScripts.Controllers.DuelController)
				local duel = duelCtrl and duelCtrl:GetDuel(lp)
				local ahead = false
				if duel and duel.LocalDueler and type(duel.LocalDueler.GetStaggeredSpawnsTurn) == "function" then
					ahead = duel.LocalDueler:GetStaggeredSpawnsTurn() == true
				end
				if ahead then
					ReplicatedStorage.Remotes.Duels.PickWeaponsAheadOfTime:FireServer(chosen)
				else
					ReplicatedStorage.Remotes.Replication.Fighter.PickWeapons:FireServer(chosen)
				end
			end)
			pcall(function()
				local pages = require(Players.LocalPlayer.PlayerScripts.Modules.UserInterface.Pages)
				if pages and pages.PageSystem and type(pages.PageSystem.CloseCurrentPage) == "function" then
					pages.PageSystem:CloseCurrentPage()
				elseif pages and type(pages.CloseRequest) == "function" then
					pages:CloseRequest()
				end
			end)
		end

		local function ensureLoadoutHook()
			if loadoutHooked then
				return
			end
			local lp = Players.LocalPlayer
			if not lp then
				return
			end
			local ok, pages = pcall(function()
				return require(lp.PlayerScripts.Modules.UserInterface.Pages)
			end)
			if not ok or type(pages) ~= "table" or type(pages.OpenPickWeaponsPage) ~= "function" then
				return
			end
			oldOpenPickWeapons = pages.OpenPickWeaponsPage
			pages.OpenPickWeaponsPage = function(self, ...)
				local result = oldOpenPickWeapons(self, ...)
				if Qol.autoLoadout then
					task.defer(submitAutoLoadout)
				end
				return result
			end
			loadoutHooked = true
			table.insert(ears, {
				Disconnect = function()
					pages.OpenPickWeaponsPage = oldOpenPickWeapons
				end,
			} :: any)
		end

		local cachedFireTouch: any = false
		local function resolveFireTouch(): any?
			if cachedFireTouch == false then
				local fn: any = nil
				if typeof(rawGetgenv) == "function" then
					local ok, env = pcall(rawGetgenv)
					if ok and type(env) == "table" then
						fn = env.firetouchinterest
					end
				end
				if type(fn) ~= "function" then
					fn = (_G :: any).firetouchinterest
				end
				cachedFireTouch = if type(fn) == "function" then fn else nil
			end
			return cachedFireTouch
		end

		local function dropHrpOf(inst: Instance): BasePart?
			if inst:IsA("BasePart") and (inst.Name == "_drop" or inst.Name == "HumanoidRootPart") then
				return inst :: BasePart
			end
			local hrp = inst:FindFirstChild("HumanoidRootPart")
			if hrp and hrp:IsA("BasePart") then
				return hrp
			end
			local dropPart = inst:FindFirstChild("_drop")
			if dropPart and dropPart:IsA("BasePart") then
				return dropPart
			end
			return nil
		end

		local dropCache: { BasePart } = {}
		local dropCacheAt = 0
		local function invalidateDropCache()
			dropCacheAt = 0
		end
		table.insert(ears, Workspace.ChildAdded:Connect(function(inst)
			if inst.Name == "_drop" or DROP_MODEL_NAMES[inst.Name] then
				invalidateDropCache()
			end
		end))
		table.insert(ears, Workspace.ChildRemoved:Connect(function(inst)
			if inst.Name == "_drop" or DROP_MODEL_NAMES[inst.Name] then
				invalidateDropCache()
			end
		end))

		local function collectDropHrps(): { BasePart }
			local now = os.clock()
			if dropCacheAt > 0 and now - dropCacheAt < 0.35 then
				return dropCache
			end
			local out: { BasePart } = {}
			for _, inst in Workspace:GetChildren() do
				if inst:IsA("BasePart") and inst.Name == "_drop" then
					table.insert(out, inst)
				elseif inst:IsA("Model") and (inst.Name == "_drop" or DROP_MODEL_NAMES[inst.Name]) then
					local hrp = dropHrpOf(inst)
					if hrp then
						table.insert(out, hrp)
					end
				end
			end
			dropCache = out
			dropCacheAt = now
			return out
		end

		local function vacuumOneDrop(fireTouch: any, dropHrp: BasePart, playerHrp: BasePart)
			fireTouch(playerHrp, dropHrp, 0)
			fireTouch(playerHrp, dropHrp, 1)
		end

		local vacuumCursor = 1
		local lastVacuumAt = 0
		local VACUUM_INTERVAL = 0.1
		local VACUUM_BATCH = 3
		local vacuumRoot: BasePart? = nil
		local vacuumRootAt = 0

		local function tryAutoPickup()
			if not Qol.autoPickup or not worldMatchActive() then
				return
			end
			local now = os.clock()
			if now - lastVacuumAt < VACUUM_INTERVAL then
				return
			end
			lastVacuumAt = now

			local fireTouch = resolveFireTouch()
			if not fireTouch then
				return
			end

			local root = vacuumRoot
			if not root or not root.Parent or now - vacuumRootAt > 0.5 then
				local lp = Players.LocalPlayer
				local char = lp and lp.Character
				local hum = char and char:FindFirstChildOfClass("Humanoid")
				root = char and (char:FindFirstChild("HumanoidRootPart") :: BasePart?)
				if not root or not root:IsA("BasePart") or (hum and hum.Health <= 0) then
					vacuumRoot = nil
					return
				end
				vacuumRoot = root
				vacuumRootAt = now
			end

			local drops = collectDropHrps()
			local count = #drops
			if count == 0 then
				return
			end

			if vacuumCursor > count then
				vacuumCursor = 1
			end

			local batch = math.min(VACUUM_BATCH, count)
			for _ = 1, batch do
				local dropHrp = drops[vacuumCursor]
				vacuumCursor += 1
				if vacuumCursor > count then
					vacuumCursor = 1
				end
				if dropHrp and dropHrp.Parent then
					pcall(vacuumOneDrop, fireTouch, dropHrp, root)
				end
			end
		end

		local cachedDuelCtrl: any = nil
		local function tryAutoRespawn()
			if not Qol.autoRespawn or not worldMatchActive() then
				return
			end
			local now = os.clock()
			if now - lastRespawnAt < 0.5 then
				return
			end
			local lp = Players.LocalPlayer
			if not lp then
				return
			end
			local fired = false
			pcall(function()
				if not cachedDuelCtrl then
					cachedDuelCtrl = require(lp.PlayerScripts.Controllers.DuelController)
				end
				local duel = cachedDuelCtrl and cachedDuelCtrl:GetDuel(lp)
				local buttons = duel and duel.DuelInterface and duel.DuelInterface.Buttons
				if not buttons then
					return
				end
				if type(buttons.IsRespawnNowVisible) == "function" and not buttons:IsRespawnNowVisible() then
					return
				end
				if buttons._respawn_now_is_timer_only == true then
					return
				end
				if buttons.RespawnNowWaitingFrame and buttons.RespawnNowWaitingFrame.Visible then
					return
				end
				if type(buttons.RespawnNowRequest) == "function" then
					buttons:RespawnNowRequest()
					fired = true
				end
			end)
			if not fired then
				pcall(function()
					local remote = ReplicatedStorage.Remotes.Duels:FindFirstChild("RespawnNow")
					if remote and remote:IsA("RemoteEvent") then
						local gui = lp:FindFirstChild("PlayerGui")
						local frame = gui and gui:FindFirstChild("RespawnNow", true)
						if frame and frame:IsA("GuiObject") and frame.Visible then
							remote:FireServer()
							fired = true
						end
					end
				end)
			end
			if fired then
				lastRespawnAt = now
			end
		end

		local cachedPages: any = nil
		local lastLoadoutPollAt = 0
		local function tryAutoLoadoutPoll()
			if not Qol.autoLoadout then
				return
			end
			local now = os.clock()
			if now - lastLoadoutPollAt < 0.4 then
				return
			end
			lastLoadoutPollAt = now
			ensureLoadoutHook()
			pcall(function()
				if not cachedPages then
					cachedPages = require(Players.LocalPlayer.PlayerScripts.Modules.UserInterface.Pages)
				end
				local ps = cachedPages and cachedPages.PageSystem
				local current = ps and ps.CurrentPage
				local name = current and current.Name
				if name == "PickWeapons" or name == "PickWeaponsList" then
					submitAutoLoadout()
				end
			end)
		end

		table.insert(ears, RunService.Heartbeat:Connect(function()
			if not (Qol.autoPickup or Qol.autoRespawn or Qol.autoLoadout) then
				return
			end
			if Qol.autoPickup then
				tryAutoPickup()
			end
			if Qol.autoRespawn then
				tryAutoRespawn()
			end
			if Qol.autoLoadout then
				tryAutoLoadoutPoll()
			end
		end))

		task.defer(function()
			refreshWeaponLists(true)
			ensureLoadoutHook()
		end)
	end

	table.insert(ears, RunService.Heartbeat:Connect(function()
		local inMatch = worldMatchActive()
		if inMatch and not wasInMatch then
			wasInMatch = true
			decalsStrippedOnce = false
			if anyWorldMapActive() then
				requestWorldMapApply()
			end
		elseif not inMatch and wasInMatch then
			wasInMatch = false
			decalsStrippedOnce = false
		end
	end))

	local lastSkyPass = 0
	table.insert(ears, RunService.Heartbeat:Connect(function()
		if not anyWorldSkyActive() then
			return
		end
		local now = os.clock()
		local interval = 1
		if now - lastSkyPass < interval then
			return
		end
		lastSkyPass = now
		applyWorldSky()
	end))

	local lastAutoQueueAt = 0
	local autoQueueInvoking = false
	table.insert(ears, RunService.Heartbeat:Connect(function()
		if not AutoQueue.enabled then
			return
		end
		local now = os.clock()
		if now - lastAutoQueueAt < 1.0 or autoQueueInvoking then
			return
		end
		if worldMatchActive() then
			return
		end
		lastAutoQueueAt = now
		autoQueueInvoking = true
		task.spawn(function()
			pcall(function()
				local remotes = ReplicatedStorage:FindFirstChild("Remotes")
				local mm = remotes and remotes:FindFirstChild("Matchmaking")
				local joinQueue = mm and mm:FindFirstChild("JoinQueue")
				if joinQueue and (joinQueue:IsA("RemoteFunction") or type((joinQueue :: any).InvokeServer) == "function") then
					(joinQueue :: any):InvokeServer(AutoQueue.match or "1v1")
				end
			end)
			autoQueueInvoking = false
		end)
	end))

	if not mapChildConn then
		mapChildConn = Workspace.ChildAdded:Connect(function(child)
			cachedMapRootsAt = 0
			if not anyWorldMapActive() or not worldMatchActive() then
				return
			end
			if MAP_ROOT_NAMES[string.lower(child.Name)] then
				task.defer(function()
					task.wait(0.35)
					cachedMapRootsAt = 0
					if WorldMap.removeDecals then
						decalsStrippedOnce = false
					end
					requestWorldMapApply()
				end)
			end
		end)
		if mapChildConn then
			table.insert(ears, mapChildConn)
		end
	end

	local function installHudRuntime()
		local HUD_MODES = { "default", "Not See - Wuzi", "Admin" }
		local Hud = {
			enabled = false,
			overlay = false,
			mode = "default",
			gap = 6,
			thickness = 2,
			length = 14,
			spin = false,
			spinSpeed = 90,
			bounce = false,
			bounceMin = 2,
			bounceMax = 22,
			bounceSpeed = 3.2,
			follow = false,
			colors = {
				Color3.fromRGB(255, 255, 255),
				Color3.fromRGB(255, 255, 255),
				Color3.fromRGB(255, 255, 255),
				Color3.fromRGB(255, 255, 255),
			},
		}

		local hudPaint: { (boolean) -> () } = {}
		local hudGates: { () -> () } = {}
		local defaultStems: { Frame } = {}
		local bouncePhase = 0
		local bounceDir = 1
		local syncBounceUi: (() -> ())? = nil

		local crossGui = element("ScreenGui", {
			Name = "sonata_crosshair",
			ResetOnSpawn = false,
			IgnoreGuiInset = true,
			DisplayOrder = 120,
			ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
			Parent = resolveParent(nil),
		}) :: ScreenGui
		crossGui.Enabled = false

		local crossHolder = element("Frame", {
			Name = "Holder",
			BackgroundTransparency = 1,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(0, 0),
			Parent = crossGui,
		}) :: Frame

		local DrawingLib: any = nil
		pcall(function()
			DrawingLib = Drawing
		end)
		if not DrawingLib then
			pcall(function()
				local env = fsGetgenv and fsGetgenv()
				if type(env) == "table" then
					DrawingLib = env.Drawing
				end
			end)
		end

		local drawLines: { any } = {}
		local drawSpinAngle = 0
		local crossPos: Vector2? = nil

		local function aimScreen(cam: Camera, dt: number): Vector2
			local mid = cam.ViewportSize * 0.5
			local goal = mid
			local rageFollow = false
			if Hud.follow == true then
				local aim = DrawingBridge.hudAim
				if typeof(aim) == "Vector2" then
					goal = aim
					rageFollow = DrawingBridge.hudAimRage == true
				end
			end
			if not crossPos then
				crossPos = goal
			end
			local rate = if rageFollow then 28 else 16
			local alpha = 1 - math.exp(-rate * math.clamp(dt, 0, 0.05))
			crossPos = (crossPos :: Vector2):Lerp(goal, alpha)
			return crossPos :: Vector2
		end

		local function clearCrossChildren()
			for _, child in crossHolder:GetChildren() do
				child:Destroy()
			end
		end

		local function clearDrawLines()
			for _, line in drawLines do
				pcall(function()
					line.Visible = false
					if type(line.Remove) == "function" then
						line:Remove()
					elseif type(line.Destroy) == "function" then
						line:Destroy()
					end
				end)
			end
			table.clear(drawLines)
		end

		local function acquireLine(): any?
			if not DrawingLib then
				return nil
			end
			local ok, line = pcall(function()
				return DrawingLib.new("Line")
			end)
			if not ok or not line then
				return nil
			end
			line.Visible = false
			line.Transparency = 1
			line.Thickness = 1
			line.ZIndex = 50
			return line
		end

		local function ensureDrawLines(count: number)
			while #drawLines < count do
				local line = acquireLine()
				if not line then
					break
				end
				table.insert(drawLines, line)
			end
			for i = count + 1, #drawLines do
				pcall(function()
					drawLines[i].Visible = false
				end)
			end
		end

		local function applyBarOutline(bar: Frame)
			local stroke = Instance.new("UIStroke")
			stroke.Name = "Outline"
			stroke.Color = Color3.new(0, 0, 0)
			stroke.Thickness = 1
			stroke.Transparency = 0
			stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
			stroke.LineJoinMode = Enum.LineJoinMode.Miter
			stroke.Parent = bar
		end

		local function makeBar(
			parent: Instance,
			name: string,
			tint: Color3,
			size: Vector2,
			pos: Vector2,
			anchor: Vector2,
			outlined: boolean
		): Frame
			local bar = element("Frame", {
				Name = name,
				BackgroundColor3 = tint,
				BackgroundTransparency = 0,
				BorderSizePixel = 0,
				AnchorPoint = anchor,
				Position = UDim2.fromOffset(math.floor(pos.X + 0.5), math.floor(pos.Y + 0.5)),
				Size = UDim2.fromOffset(math.max(1, math.floor(size.X + 0.5)), math.max(1, math.floor(size.Y + 0.5))),
				Rotation = 0,
				ZIndex = 10,
				Parent = parent,
			}) :: Frame
			if outlined then
				applyBarOutline(bar)
			end
			return bar
		end

		local function makeArm(rotationDeg: number): Frame
			return element("Frame", {
				Name = "Arm",
				BackgroundTransparency = 1,
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromOffset(0, 0),
				Size = UDim2.fromOffset(0, 0),
				Rotation = rotationDeg,
				Parent = crossHolder,
			}) :: Frame
		end

		local function rot2(p: Vector2, ang: number): Vector2
			local c = math.cos(ang)
			local s = math.sin(ang)
			return Vector2.new(p.X * c - p.Y * s, p.X * s + p.Y * c)
		end

		local function paintDrawSegment(index: number, from: Vector2, to: Vector2, tint: Color3, thick: number, crisp: boolean?)
			local line = drawLines[index]
			if not line then
				return
			end
			pcall(function()
				if crisp == false then
					line.From = Vector2.new(math.floor(from.X + 0.5), math.floor(from.Y + 0.5))
					line.To = Vector2.new(math.floor(to.X + 0.5), math.floor(to.Y + 0.5))
				else
					line.From = from
					line.To = to
				end
				line.Color = tint
				line.Thickness = math.max(1, math.floor(thick + 0.5))
				line.Transparency = 1
				line.Visible = true
				line.ZIndex = 60
			end)
		end

		local function hideAllDrawLines()
			for _, line in drawLines do
				pcall(function()
					line.Visible = false
				end)
			end
		end

		local function crosshairInMatch(): boolean
			return worldMatchActive()
		end

		local function rebuildCrosshair()
			clearCrossChildren()
			table.clear(defaultStems)
			hideAllDrawLines()
			if not Hud.enabled or not crosshairInMatch() then
				crossGui.Enabled = false
				clearDrawLines()
				return
			end
			local mode = Hud.mode
			if mode ~= "default" and mode ~= "Not See - Wuzi" and mode ~= "Admin" then
				mode = "default"
			end

			if mode == "Admin" or mode == "Not See - Wuzi" then
				crossHolder.Rotation = 0
				if DrawingLib then
					crossGui.Enabled = false
					local needed = if mode == "Admin" then 6 else 8
					ensureDrawLines(needed)
					return
				end
				crossGui.Enabled = true
				crossGui.DisplayOrder = if Hud.overlay then 120 else 12
				local thick = math.max(1, math.clamp(Hud.thickness, 1, 20))
				local len = math.max(2, math.clamp(Hud.length, 2, 80))
				if mode == "Not See - Wuzi" then
					for i = 1, 4 do
						local tint = Hud.colors[i]
						local arm = makeArm((i - 1) * 90)
						makeBar(arm, "Stem", tint, Vector2.new(thick, len), Vector2.new(0, 0), Vector2.new(0.5, 1), false)
						makeBar(arm, "Hook", tint, Vector2.new(len, thick), Vector2.new(thick * 0.5, -len), Vector2.new(0, 0.5), false)
					end
				else
					local radius = math.max(10, len + 6)
					local function tri(offset: number, tint: Color3)
						local verts: { Vector2 } = {}
						for i = 0, 2 do
							local a = offset + i * (math.pi * 2 / 3)
							table.insert(verts, Vector2.new(math.cos(a) * radius, math.sin(a) * radius))
						end
						for i = 1, 3 do
							local a = verts[i]
							local b = verts[(i % 3) + 1]
							local mid = (a + b) * 0.5
							local delta = b - a
							local dist = delta.Magnitude
							local angle = math.deg(math.atan2(delta.Y, delta.X))
							element("Frame", {
								Name = "Star",
								BackgroundColor3 = tint,
								BorderSizePixel = 0,
								AnchorPoint = Vector2.new(0.5, 0.5),
								Position = UDim2.fromOffset(mid.X, mid.Y),
								Size = UDim2.fromOffset(math.max(1, dist), thick),
								Rotation = angle,
								ZIndex = 10,
								Parent = crossHolder,
							})
						end
					end
					tri(-math.pi * 0.5, Hud.colors[1])
					tri(math.pi * 0.5, Hud.colors[2])
				end
				return
			end

			clearDrawLines()
			crossGui.Enabled = true
			crossGui.DisplayOrder = if Hud.overlay then 120 else 12
			local thick = math.max(1, math.clamp(Hud.thickness, 1, 20))
			local len = math.max(2, math.clamp(Hud.length, 2, 80))
			local gap = math.clamp(Hud.gap, 0, 80)
			for i = 1, 4 do
				local tint = Hud.colors[i]
				local arm = makeArm((i - 1) * 90)
				local stem = makeBar(arm, "Stem", tint, Vector2.new(thick, len), Vector2.new(0, -gap), Vector2.new(0.5, 1), true)
				defaultStems[i] = stem
			end
		end

		local function easeOutCubic(t: number): number
			local u = 1 - math.clamp(t, 0, 1)
			return 1 - u * u * u
		end

		local function liveDefaultGap(): number
			if not Hud.bounce then
				return math.clamp(Hud.gap, 0, 80)
			end
			local lo = math.clamp(math.min(Hud.bounceMin, Hud.bounceMax), 0, 80)
			local hi = math.clamp(math.max(Hud.bounceMin, Hud.bounceMax), 0, 80)
			local travel = math.clamp(bouncePhase, 0, 1)
			local animT
			if bounceDir >= 0 then
				animT = easeOutCubic(travel)
			else
				animT = 1 - easeOutCubic(1 - travel)
			end
			return lo + (hi - lo) * animT
		end

		local function applyDefaultStemGap(gap: number)
			local g = math.floor(gap + 0.5)
			for _, stem in defaultStems do
				if stem and stem.Parent then
					stem.Position = UDim2.fromOffset(0, -g)
				end
			end
		end

		local function refreshHudUi()
			for _, paint in hudPaint do
				pcall(paint, false)
			end
			for _, gate in hudGates do
				pcall(gate)
			end
			rebuildCrosshair()
		end

		local wasCrossMatch = false
		table.insert(ears, RunService.RenderStepped:Connect(function(dt: number)
			if DrawingBridge.library and DrawingBridge.library.uiDragging then
				return
			end
			if not Hud.enabled then
				if crossGui.Enabled then
					crossGui.Enabled = false
				end
				hideAllDrawLines()
				return
			end

			local inMatch = crosshairInMatch()
			if inMatch ~= wasCrossMatch then
				wasCrossMatch = inMatch
				rebuildCrosshair()
			end

			if not inMatch then
				if crossGui.Enabled then
					crossGui.Enabled = false
				end
				hideAllDrawLines()
				return
			end

			local mode = Hud.mode
			if mode ~= "default" and mode ~= "Not See - Wuzi" and mode ~= "Admin" then
				mode = "default"
			end

			if Hud.spin then
				drawSpinAngle = (drawSpinAngle + math.clamp(Hud.spinSpeed, 0, 720) * dt) % 360
			else
				drawSpinAngle = 0
			end

			if mode == "default" then
				hideAllDrawLines()
				if not crossGui.Enabled then
					crossGui.Enabled = true
				end
				crossGui.DisplayOrder = if Hud.overlay then 120 else 12

				local rot = drawSpinAngle
				if Hud.bounce then
					local speed = math.clamp(Hud.bounceSpeed, 0.2, 20)
					bouncePhase += bounceDir * speed * dt
					if bouncePhase >= 1 then
						bouncePhase = 1
						bounceDir = -1
					elseif bouncePhase <= 0 then
						bouncePhase = 0
						bounceDir = 1
					end
					applyDefaultStemGap(liveDefaultGap())
				else
					bouncePhase = 0
					bounceDir = 1
					applyDefaultStemGap(math.clamp(Hud.gap, 0, 80))
				end
				crossHolder.Rotation = rot
				local cam = Workspace.CurrentCamera
				if cam then
					local p = aimScreen(cam, dt)
					crossHolder.Position = UDim2.fromOffset(p.X, p.Y)
				end
				return
			end

			crossGui.Enabled = false
			crossHolder.Rotation = 0
			local cam = Workspace.CurrentCamera
			if not cam or not DrawingLib then
				hideAllDrawLines()
				return
			end
			local center = aimScreen(cam, dt)
			local thick = math.max(1, math.clamp(Hud.thickness, 1, 20))
			local len = math.max(2, math.clamp(Hud.length, 2, 80))
			local ang = math.rad(drawSpinAngle)

			if mode == "Not See - Wuzi" then
				ensureDrawLines(8)
				local idx = 1
				for i = 0, 3 do
					local armAng = ang + math.rad(i * 90)
					local tint = Hud.colors[i + 1]
					local p0 = center + rot2(Vector2.new(0, 0), armAng)
					local p1 = center + rot2(Vector2.new(0, -len), armAng)
					local p2 = center + rot2(Vector2.new(len, -len), armAng)
					paintDrawSegment(idx, p0, p1, tint, thick, false)
					idx += 1
					paintDrawSegment(idx, p1, p2, tint, thick, false)
					idx += 1
				end
				return
			end

			ensureDrawLines(6)
			local radius = math.max(10, len + 6)
			local idx = 1
			local function paintTriangle(phase: number, tint: Color3)
				local verts: { Vector2 } = table.create(3)
				for i = 0, 2 do
					local a = phase + i * (math.pi * 2 / 3)
					verts[i + 1] = center + rot2(Vector2.new(math.cos(a) * radius, math.sin(a) * radius), ang)
				end
				for i = 1, 3 do
					paintDrawSegment(idx, verts[i], verts[(i % 3) + 1], tint, thick, true)
					idx += 1
				end
			end
			paintTriangle(-math.pi * 0.5, Hud.colors[1])
			paintTriangle(math.pi * 0.5, Hud.colors[2])
		end))

		local prevExportWorld = exportWorldQol
		exportWorldQol = function(): any
			local base = if prevExportWorld then prevExportWorld() else {}
			if type(base) ~= "table" then
				base = {}
			end
			base.hud = {
				enabled = Hud.enabled,
				overlay = Hud.overlay,
				mode = Hud.mode,
				gap = Hud.gap,
				thickness = Hud.thickness,
				length = Hud.length,
				spin = Hud.spin,
				spinSpeed = Hud.spinSpeed,
				bounce = Hud.bounce,
				bounceMin = Hud.bounceMin,
				bounceMax = Hud.bounceMax,
				bounceSpeed = Hud.bounceSpeed,
				follow = Hud.follow,
				colors = {
					colorToTable(Hud.colors[1]),
					colorToTable(Hud.colors[2]),
					colorToTable(Hud.colors[3]),
					colorToTable(Hud.colors[4]),
				},
			}
			return base
		end

		local prevRestoreWorld = restoreWorldQol
		restoreWorldQol = function(data: any)
			if prevRestoreWorld then
				prevRestoreWorld(data)
			end
			if type(data) ~= "table" or type(data.hud) ~= "table" then
				task.defer(rebuildCrosshair)
				return
			end
			local h = data.hud
			if type(h.enabled) == "boolean" then Hud.enabled = h.enabled end
			if type(h.overlay) == "boolean" then Hud.overlay = h.overlay end
			if type(h.mode) == "string" then
				Hud.mode = h.mode
			elseif h.notSee == true then
				Hud.mode = "Not See - Wuzi"
			elseif h.fourBars == false then
				Hud.mode = "default"
			end
			if Hud.mode ~= "default" and Hud.mode ~= "Not See - Wuzi" and Hud.mode ~= "Admin" then
				Hud.mode = "default"
			end
			if type(h.gap) == "number" then Hud.gap = math.clamp(h.gap, 0, 80) end
			if type(h.thickness) == "number" then Hud.thickness = math.clamp(h.thickness, 1, 20) end
			if type(h.length) == "number" then Hud.length = math.clamp(h.length, 2, 80) end
			if type(h.spin) == "boolean" then Hud.spin = h.spin end
			if type(h.spinSpeed) == "number" then Hud.spinSpeed = math.clamp(h.spinSpeed, 0, 720) end
			if type(h.bounce) == "boolean" then Hud.bounce = h.bounce end
			if type(h.bounceMin) == "number" then Hud.bounceMin = math.clamp(h.bounceMin, 0, 80) end
			if type(h.bounceMax) == "number" then Hud.bounceMax = math.clamp(h.bounceMax, 0, 80) end
			if type(h.bounceSpeed) == "number" then Hud.bounceSpeed = math.clamp(h.bounceSpeed, 0.2, 20) end
			if type(h.follow) == "boolean" then Hud.follow = h.follow end
			if type(h.colors) == "table" then
				for i = 1, 4 do
					Hud.colors[i] = tableToColor(h.colors[i], Hud.colors[i])
				end
			end
			task.defer(function()
				pcall(refreshHudUi)
				if syncBounceUi then
					pcall(syncBounceUi)
				end
			end)
		end

		DrawingBridge.builders.world = function(kit: any)
			local function rebuild()
				pcall(rebuildCrosshair)
			end
			local function mapChanged(_value: any?)
