			end)
			local envDiff = kit.number(lighting, "env scale", WorldSky, "envDiffuseVal", 0, 300, 1, { scale = 100, onSet = skyTouch })
			lightRefresh = function()
				clockTime.enabled = WorldSky.clock
				atmDens.enabled = WorldSky.atmosphere
				atmOff.enabled = WorldSky.atmosphere
				atmGlare.enabled = WorldSky.atmosphere
				atmHaze.enabled = WorldSky.atmosphere
