			local customRefresh: () -> ()

			local MODEL_DIR = CONFIG_FOLDER .. "/models"
			local modelNames: { string } = { "none" }
			local modelIds: { [string]: string } = {}
			ClientFx.playerModelName = if type(ClientFx.playerModelName) == "string" then ClientFx.playerModelName else "none"
			ClientFx.playerModelLabel = if type(ClientFx.playerModelLabel) == "string" then ClientFx.playerModelLabel else ""
			ClientFx.customModelReplaceWeapon = false
			ClientFx.customModelReplaceLeftHand = false
			ClientFx.customModelReplaceRightHand = false

			local function scanPlayerModels()
				table.clear(modelNames)
				table.clear(modelIds)
				if hasFsApi("makefolder") then
					if not fsIsfolder(CONFIG_FOLDER) then
						pcall(fsMakefolder, CONFIG_FOLDER)
					end
					if not fsIsfolder(MODEL_DIR) then
						pcall(fsMakefolder, MODEL_DIR)
					end
				end
				if hasFsApi("listfiles") and hasFsApi("readfile") then
					local ok, files = pcall(fsListfiles, MODEL_DIR)
					if ok and type(files) == "table" then
						for _, path in files do
							local file = string.match(tostring(path), "[^/\\]+$") or ""
							if string.sub(string.lower(file), -4) == ".txt" then
								local label = string.sub(file, 1, #file - 4)
								local readOk, body = pcall(fsReadfile, tostring(path))
								if readOk and type(body) == "string" and label ~= "" then
									local id = string.match(body, "%d+")
									if id then
										modelIds[label] = id
										table.insert(modelNames, label)
									end
								end
							end
						end
					end
				end
				table.sort(modelNames)
				if #modelNames == 0 then
					table.insert(modelNames, "none")
				end
				if modelIds[ClientFx.playerModelName] == nil then
					ClientFx.playerModelName = modelNames[1]
				end
			end
			scanPlayerModels()

			local modelList: any
			local function paintModelList()
				if not modelList then
					return
				end
				pcall(function()
					modelList:ClearValues()
					for _, name in modelNames do
						modelList:AddValue(name)
					end
					modelList:Select(tostring(ClientFx.playerModelName), true)
				end)
			end

			local pmOn = kit.flag(customModelBox, "player model", ClientFx, "customModel", nil, function()
				if ClientFx.customModel ~= true then
					ClientFx.customModelReplaceChar = false
				end
				customRefresh()
			end)
			modelList = kit.choice(customModelBox, "saved", modelNames, function()
				return tostring(ClientFx.playerModelName)
			end, function(value: string)
				ClientFx.playerModelName = value
			end)
			local function loadPlayerModel()
				scanPlayerModels()
				paintModelList()
				local label = tostring(ClientFx.playerModelName)
				local id = modelIds[label]
				if not id then
					return
				end
				ClientFx.customModel = true
				ClientFx.customModelReplaceChar = true
				ClientFx.customModelCharAsset = id
				ClientFx.playerModelLabel = label
				ClientFx.customModelReplaceWeapon = false
				ClientFx.customModelReplaceLeftHand = false
				ClientFx.customModelReplaceRightHand = false
				if pmOn and type(pmOn.SetState) == "function" then
					pcall(pmOn.SetState, pmOn, true, true)
				end
				if DrawingBridge.clearCustomAssetCache then
					pcall(DrawingBridge.clearCustomAssetCache)
				end
				customRefresh()
			end
			kit.buttons(customModelBox, {
				{ text = "load", callback = loadPlayerModel },
