			customRefresh = function()
				local on = ClientFx.customModel == true
				modelList.enabled = on
				cmCharSpin.enabled = on
				cmCharSpinSpd.enabled = on and ClientFx.characterSpin == true
				cmScale.enabled = on
				cmX.enabled = on
