	installHudRuntime()

	local function installClientFxRuntime()
		local ClientFx = DrawingBridge.ClientFx
		local SOUND_DIR = CONFIG_FOLDER .. "/sounds"
		local _SOUND_BASE = "https://raw.githubusercontent.com/Cyerc/LuaFiles/main/Sounds/"
		local AMBIENCE_FILES: { [string]: string } = {
			city = "https://files.catbox.moe/3tyvqg.mp3",
			forest = "https://files.catbox.moe/lo2fio.mp3",
			rain = "https://files.catbox.moe/ak4nc0.mp3",
			snow = "https://files.catbox.moe/8g5veg.mp3",
		}
		local soundAssets: { [string]: string } = {}
		local ambienceAssets: { [string]: string } = {}
		local ambienceSound: Sound? = nil
		local ambienceEchoFx: EchoSoundEffect? = nil
		local ambienceTrackLoaded: string? = nil
		local function coerceColor3(value: any, fallback: Color3): Color3
			if typeof(value) == "Color3" then
				return Color3.new(value.R, value.G, value.B)
			end
			if type(value) == "table" then
				local r = value[1] or value.R or value.r
				local g = value[2] or value.G or value.g
				local b = value[3] or value.B or value.b
				if type(r) == "number" and type(g) == "number" and type(b) == "number" then
					if r > 1 or g > 1 or b > 1 then
						return Color3.fromRGB(r, g, b)
					end
					return Color3.new(r, g, b)
				end
			end
			return fallback
		end
		local function sequenceColor(c: Color3): ColorSequence
			return ColorSequence.new({
				ColorSequenceKeypoint.new(0, c),
				ColorSequenceKeypoint.new(1, c),
			})
		end
		local function stampAdornmentColor(inst: Instance, c: Color3)
			pcall(function()
				(inst :: any).Color3 = c
			end)
			pcall(function()
				(inst :: any).Color = c
			end)
		end
		local function stampEffectColor(inst: Instance, c: Color3)
			pcall(function()
				if inst:IsA("Beam") then
					inst.Color = sequenceColor(c)
					inst.Texture = ""
					inst.LightInfluence = 0
				elseif inst:IsA("Trail") then
					inst.Color = sequenceColor(c)
					inst.Texture = ""
					inst.LightInfluence = 0
				elseif inst:IsA("ParticleEmitter") then
					inst.Color = sequenceColor(c)
				end
			end)
		end
		local function currentTracerColor(): Color3
			return coerceColor3(ClientFx.tracerColor, Color3.fromRGB(255, 180, 60))
		end

		local function getCustomAsset(path: string): string?
			local fn = execApi("getcustomasset") or execApi("GetCustomAsset")
			if typeof(fn) ~= "function" then
				return nil
			end
			local ok, asset = pcall(fn :: (string) -> string, path)
			if ok and type(asset) == "string" then
				return asset
			end
			return nil
		end

		local function fileExists(path: string): boolean
			if not hasFsApi("readfile") then
				return false
			end
			local ok, data = pcall(fsReadfile, path)
			return ok and type(data) == "string" and #data > 64
		end

		local function ensureSoundFolder()
			if hasFsApi("makefolder") and not fsIsfolder(CONFIG_FOLDER) then
				pcall(fsMakefolder, CONFIG_FOLDER)
			end
			if hasFsApi("makefolder") and not fsIsfolder(SOUND_DIR) then
				pcall(fsMakefolder, SOUND_DIR)
			end
		end

		local function downloadOne(path: string, url: string, force: boolean?): boolean
			if not force and fileExists(path) then
				return true
			end
			if not hasFsApi("writefile") then
				return fileExists(path)
			end
			local ok, body = pcall(function()
				return game:HttpGet(url)
			end)
			if ok and type(body) == "string" and #body > 64 then
				local wrote = pcall(fsWritefile, path, body)
				return wrote
			end
			return false
		end

		local function downloadAmbienceSounds(force: boolean?)
			ensureSoundFolder()
			for name, url in AMBIENCE_FILES do
				local path = SOUND_DIR .. "/" .. name .. ".mp3"
				downloadOne(path, url, force)
				local asset = getCustomAsset(path)
				if asset then
					ambienceAssets[name] = asset
				end
			end
		end

		local function downloadClientSounds(force: boolean?)
			ensureSoundFolder()
			downloadAmbienceSounds(force)
		end

		local function ensureAmbiencePlayer()
			if ambienceSound and ambienceSound.Parent then
				return ambienceSound
			end
			local holder = SoundService:FindFirstChild("sonata_ambience")
			if not holder then
				holder = Instance.new("SoundGroup")
				holder.Name = "sonata_ambience"
				holder.Parent = SoundService
			end
			local sound = Instance.new("Sound")
			sound.Name = "Ambience"
			sound.Looped = true
			sound.RollOffMode = Enum.RollOffMode.Linear
			sound.Parent = holder
			local echo = Instance.new("EchoSoundEffect")
			echo.Name = "Echo"
			echo.Delay = 0.22
			echo.Feedback = 0.35
			echo.DryLevel = 0
			echo.WetLevel = -15
			echo.Parent = sound
			ambienceSound = sound
			ambienceEchoFx = echo
			return sound
		end

		local function syncAmbience()
			local sound = ensureAmbiencePlayer()
			if not ClientFx.ambience then
				if sound.IsPlaying then
					sound:Stop()
				end
				return
			end
			local track = string.lower(tostring(ClientFx.ambienceTrack or "city"))
			if not AMBIENCE_FILES[track] then
				track = "city"
			end
			local asset = ambienceAssets[track]
			if not asset then
				local path = SOUND_DIR .. "/" .. track .. ".mp3"
				if not fileExists(path) then
					downloadAmbienceSounds(false)
				end
				asset = getCustomAsset(path) or ambienceAssets[track]
				if asset then
					ambienceAssets[track] = asset
				end
			end
			if asset and (ambienceTrackLoaded ~= track or sound.SoundId ~= asset) then
				sound.SoundId = asset
				ambienceTrackLoaded = track
			end
			sound.Looped = true
			sound.Volume = math.clamp(ClientFx.ambienceVolume, 0, 5)
			sound.PlaybackSpeed = math.clamp(ClientFx.ambiencePitch, 0.1, 3)
			if ambienceEchoFx then
				local wet = math.clamp(ClientFx.ambienceEcho, 0, 1)
				ambienceEchoFx.Enabled = wet > 0.01
				ambienceEchoFx.WetLevel = -40 + wet * 40
				ambienceEchoFx.Feedback = 0.15 + wet * 0.55
				ambienceEchoFx.Delay = 0.12 + wet * 0.35
			end
			if asset and not sound.IsPlaying then
				pcall(function()
					sound:Play()
				end)
			elseif asset and sound.IsPlaying then
			end
		end

		DrawingBridge.downloadClientSounds = downloadClientSounds
		DrawingBridge.syncAmbience = syncAmbience
		DrawingBridge.ensureClientSounds = function()
			if next(soundAssets) == nil or next(ambienceAssets) == nil then
				task.spawn(downloadClientSounds, false)
			end
		end

		task.spawn(function()
			downloadClientSounds(false)
			syncAmbience()
		end)

		local lastAmbiencePulse = 0
		local lastAmbienceSig = ""
		table.insert(ears, RunService.Heartbeat:Connect(function()
			local now = os.clock()
			if now - lastAmbiencePulse < 0.75 then
				return
			end
			lastAmbiencePulse = now
			if ClientFx.ambience then
				local sig = table.concat({
					"1",
					tostring(ClientFx.ambienceTrack),
					string.format("%.2f", ClientFx.ambienceVolume),
					string.format("%.2f", ClientFx.ambiencePitch),
					string.format("%.2f", ClientFx.ambienceEcho),
				}, "|")
				if sig ~= lastAmbienceSig or not (ambienceSound and ambienceSound.IsPlaying) then
					lastAmbienceSig = sig
					syncAmbience()
				end
			elseif ambienceSound and ambienceSound.IsPlaying then
				lastAmbienceSig = ""
				ambienceSound:Stop()
			end
		end))

		local function resolveCatalogSoundId(bucket: any, name: any): string?
			if type(bucket) ~= "table" or type(name) ~= "string" then
				return nil
			end
			local entry = bucket[name]
			if type(entry) == "table" and type(entry.SoundId) == "string" then
				return entry.SoundId
			end
			return nil
		end

		local gunSoundIds: { [string]: boolean } = {}
		local hitSoundIds: { [string]: boolean } = {
			["rbxassetid://13110130082"] = true,
			["rbxassetid://16537449730"] = true,
			["rbxassetid://16537337310"] = true,
		}
		local function shouldSkipMuteKey(key: any): boolean
			local s = string.lower(tostring(key or ""))
			return string.find(s, "horn", 1, true) ~= nil
				or string.find(s, "whistle", 1, true) ~= nil
				or string.find(s, "megaphone", 1, true) ~= nil
				or string.find(s, "trumpet", 1, true) ~= nil
				or string.find(s, "warhorn", 1, true) ~= nil
		end
		local function collectSoundIds(bucket: any)
			if type(bucket) ~= "table" then
				return
			end
			for k, v in bucket do
				if shouldSkipMuteKey(k) then
					continue
				end
				if type(v) == "string" and string.find(v, "rbxassetid", 1, true) then
					gunSoundIds[v] = true
				elseif type(v) == "table" then
					collectSoundIds(v)
				end
			end
		end
		local function rebuildGunSoundIds()
			table.clear(gunSoundIds)
			pcall(function()
				local sl = require(ReplicatedStorage.Modules.SoundLibrary)
				collectSoundIds(sl.ViewModelSounds)
				collectSoundIds(sl.ItemSounds)
			end)
			gunSoundIds["rbxassetid://120111163675397"] = nil
			gunSoundIds["rbxassetid://106759378699826"] = nil
		end
		rebuildGunSoundIds()
		local function isGunSoundId(soundId: any): boolean
			return type(soundId) == "string" and gunSoundIds[soundId] == true
		end
		local function isHitSoundId(soundId: any): boolean
			return type(soundId) == "string" and hitSoundIds[soundId] == true
		end
		local function muteSoundInstance(sound: any)
			if typeof(sound) == "Instance" and sound:IsA("Sound") then
				pcall(function()
					sound.Volume = 0
					sound.PlaybackSpeed = 0.01
				end)
			end
		end

		local fxSoundFolder = SoundService:FindFirstChild("sonata_fx_sounds")
		if not fxSoundFolder then
			fxSoundFolder = Instance.new("Folder")
			fxSoundFolder.Name = "sonata_fx_sounds"
			fxSoundFolder.Parent = SoundService
		end
		local fxLiveCounts: { [string]: number } = { hit = 0, shoot = 0, kill = 0, hit_preview = 0, shoot_preview = 0, kill_preview = 0 }
		local FX_MAX_LIVE = 8
		local function playFxSound(kind: string, soundId: string?, volume: number?, pitch: number?, minGap: number?)
			if type(soundId) ~= "string" or soundId == "" then
				return
			end
			local now = os.clock()
			local gap = minGap or 0.01
			local key = "__sonata_last_" .. kind
			local last = (DrawingBridge :: any)[key]
			if type(last) == "number" and now - last < gap then
				return
			end
			;(DrawingBridge :: any)[key] = now
			local live = fxLiveCounts[kind] or 0
			if live >= FX_MAX_LIVE then
				return
			end
			local snd = Instance.new("Sound")
			snd.Name = "sonata_" .. kind
			snd.SoundId = soundId
			snd.Volume = math.clamp(if type(volume) == "number" then volume else 1, 0, 5)
			snd.PlaybackSpeed = math.clamp(if type(pitch) == "number" then pitch else 1, 0.1, 3)
			snd.RollOffMaxDistance = 10000
			snd.Parent = fxSoundFolder
			fxLiveCounts[kind] = live + 1
			local cleaned = false
			local function cleanup()
				if cleaned then
					return
				end
				cleaned = true
				fxLiveCounts[kind] = math.max(0, (fxLiveCounts[kind] or 1) - 1)
				pcall(function()
					snd:Destroy()
				end)
			end
			pcall(function()
				snd.Ended:Connect(cleanup)
			end)
			pcall(function()
				snd:Play()
			end)
			task.delay(6, cleanup)
		end

		local function playHitSound()
			if not ClientFx.hitSound then
