		local KILL_WINDOW = 0.75
		local lastDamageAt = -math.huge
		local function playKillSound(kind: string)
			playFxSound(
				kind,
				resolveCatalogSoundId(DrawingBridge.HitSounds, ClientFx.killSoundName),
				ClientFx.killVolume,
				ClientFx.killPitch,
				if kind == "kill" then 0.05 else 0
			)
		end
		DrawingBridge.previewKillSound = function()
			playKillSound("kill_preview")
		end
		do
			local killConns: { [Player]: RBXScriptConnection } = {}
			local function isTeammate(plr: Player): boolean
				local lp = Players.LocalPlayer
				local mine = lp and lp:GetAttribute("TeamID")
				return mine ~= nil and plr:GetAttribute("TeamID") == mine
			end
			local function watchCharacter(plr: Player, char: Model)
				local old = killConns[plr]
				if old then
					old:Disconnect()
					killConns[plr] = nil
				end
				local hum = char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 10)
				if not hum or not hum:IsA("Humanoid") or plr.Character ~= char then
					return
				end
				local dead = hum.Health <= 0
				killConns[plr] = hum.HealthChanged:Connect(function(hp: number)
					if hp > 0 then
						dead = false
						return
					end
					if dead then
						return
					end
					dead = true
					if os.clock() - lastDamageAt <= KILL_WINDOW and not isTeammate(plr) then
						if ClientFx.killSound then
							playKillSound("kill")
						end
					end
				end)
			end
			local function hookPlayer(plr: Player)
				if plr == Players.LocalPlayer then
					return
				end
				table.insert(ears, plr.CharacterAdded:Connect(function(char)
					watchCharacter(plr, char)
				end))
				if plr.Character then
					task.spawn(watchCharacter, plr, plr.Character)
				end
			end
			for _, plr in Players:GetPlayers() do
				hookPlayer(plr)
			end
			table.insert(ears, Players.PlayerAdded:Connect(hookPlayer))
			table.insert(ears, Players.PlayerRemoving:Connect(function(plr)
				local conn = killConns[plr]
				if conn then
					conn:Disconnect()
					killConns[plr] = nil
				end
			end))
			table.insert(ears, {
				Disconnect = function()
					for plr, conn in killConns do
						conn:Disconnect()
						killConns[plr] = nil
					end
				end,
			} :: any)
		end

		local tracerFolder = Instance.new("Folder")
		tracerFolder.Name = "sonata_tracers"
		do
			local cam = Workspace.CurrentCamera
			tracerFolder.Parent = cam or (fsGethui and fsGethui()) or game:GetService("CoreGui")
		end
		table.insert(ears, {
			Disconnect = function()
				pcall(function()
					tracerFolder:Destroy()
				end)
			end,
		} :: any)
		local lastGameTracerAt = 0
		local TRACER_MAX_LIVE = 48
		local liveTracers: { any } = {}
		local tracerMuzzle: Instance? = nil
		local tracerMuzzleAt = 0
		local function muzzleInstanceWorld(m: Instance?): Vector3?
			if not m or not m.Parent then
				return nil
			end
			if m:IsA("Attachment") then
				return m.WorldPosition
			elseif m:IsA("BasePart") then
				return m.Position
			elseif m.Parent:IsA("BasePart") then
				return (m.Parent :: BasePart).Position
			end
			return nil
		end
		local function findTracerMuzzle(): Instance?
			local now = os.clock()
			if tracerMuzzle and tracerMuzzle.Parent and now - tracerMuzzleAt < 0.25 then
				return tracerMuzzle
			end
			tracerMuzzleAt = now
			tracerMuzzle = nil
			local cam = Workspace.CurrentCamera
			local lp = Players.LocalPlayer
			local char = lp and lp.Character
			local head = char and char:FindFirstChild("Head")
			local thirdPerson = cam ~= nil and head ~= nil and head:IsA("BasePart")
				and (cam.CFrame.Position - head.Position).Magnitude > 2.5
			if thirdPerson and char then
				tracerMuzzle = char:FindFirstChild("_muzzle", true)
				if tracerMuzzle then
					return tracerMuzzle
				end
			end
			if cam then
				for _, child in cam:GetChildren() do
					local found = child:FindFirstChild("_muzzle", true)
					if found then
						tracerMuzzle = found
						return found
					end
				end
			end
			local vms = Workspace:FindFirstChild("ViewModels")
			if vms then
				local fp = vms:FindFirstChild("FirstPerson")
				tracerMuzzle = (fp and fp:FindFirstChild("_muzzle", true)) or vms:FindFirstChild("_muzzle", true)
				if tracerMuzzle then
					return tracerMuzzle
				end
			end
			if char then
				tracerMuzzle = char:FindFirstChild("_muzzle", true)
			end
			return tracerMuzzle
		end
		local function getTracerMuzzlePos(item: any, hint: Vector3?): Vector3?
			local world = muzzleInstanceWorld(findTracerMuzzle())
			if world then
				return world
			end
			if typeof(hint) == "Vector3" then
				return hint
			end
			if type(item) == "table" then
				local vm = item.ViewModel
				if type(vm) == "table" and type(vm.GetMuzzlePosition) == "function" then
					local ok, pos = pcall(vm.GetMuzzlePosition, vm)
					if ok and typeof(pos) == "Vector3" then
						return pos
					end
				end
			end
			local cam = Workspace.CurrentCamera
			local lp = Players.LocalPlayer
			local char = lp and lp.Character
			local root = char and char:FindFirstChild("HumanoidRootPart")
			if cam then
				local origin = cam.CFrame.Position + cam.CFrame.LookVector * 1.2
				if root and root:IsA("BasePart") then
					origin = root.Position + Vector3.new(0, 1.2, 0) + cam.CFrame.LookVector * 1.5
				end
				return origin
			end
			return nil
		end
		local function spawnWorldTracer(from: Vector3, to: Vector3)
			if not ClientFx.tracers then
				return
			end
			do
				local lp = Players.LocalPlayer
				local fc = DrawingBridge._tracerFc
				if type(fc) ~= "table" and lp then
					local ok, loaded = pcall(function()
						return require(lp.PlayerScripts.Controllers.FighterController)
					end)
					if ok and type(loaded) == "table" then
						DrawingBridge._tracerFc = loaded
						fc = loaded
					end
				end
				local item = fc and fc.LocalFighter and fc.LocalFighter.EquippedItem
				local name = if type(item) == "table" then item.Name else nil
				if type(name) == "string" then
					local n = string.lower(name)
					if n == "bow"
						or string.find(n, "slingshot", 1, true)
						or string.find(n, "paintball", 1, true)
						or string.find(n, "dagger", 1, true)
					then
						return
					end
				end
			end
			local dist = (to - from).Magnitude
			if dist < 0.35 or dist ~= dist then
				return
			end
			if #liveTracers >= TRACER_MAX_LIVE then
				local oldest = table.remove(liveTracers, 1)
				pcall(function()
					oldest.part:Destroy()
				end)
			end
			local color = currentTracerColor()
			local width = math.clamp(tonumber(ClientFx.tracerWidth) or 0.18, 0.01, 1.2)
			local life = math.clamp(tonumber(ClientFx.tracerLifetime) or 0.35, 0.05, 3)
			local bright = math.clamp(tonumber(ClientFx.tracerBrightness) or 1, 0, 3)
			local part = Instance.new("Part")
			part.Name = "tracer"
			part.Anchored = true
			part.CanCollide = false
			part.CanQuery = false
			part.CanTouch = false
			part.CastShadow = false
			part.Transparency = 1
			part.Size = Vector3.new(0.05, 0.05, 0.05)
			part.CFrame = CFrame.new(from)
			part.Parent = tracerFolder
			local a0 = Instance.new("Attachment")
			a0.Parent = part
			local a1 = Instance.new("Attachment")
			a1.Parent = part
			a0.WorldPosition = from
			a1.WorldPosition = to
			local beam = Instance.new("Beam")
			beam.Attachment0 = a0
			beam.Attachment1 = a1
			local beamColor = if bright < 1 then Color3.new(0, 0, 0):Lerp(color, bright) else color
			beam.Color = sequenceColor(beamColor)
			beam.Texture = ""
			beam.Width0 = width
			beam.Width1 = width
			beam.LightEmission = math.min(bright, 1)
			beam.LightInfluence = 0
			pcall(function()
				beam.Brightness = math.max(bright, 1)
			end)
			beam.FaceCamera = true
			beam.Segments = 1
			beam.TextureSpeed = 0
			beam.Transparency = NumberSequence.new(0)
			beam.Parent = part
			table.insert(liveTracers, {
				part = part,
				beam = beam,
				width = width,
				life = life,
				t0 = os.clock(),
			})
		end
		table.insert(ears, RunService.RenderStepped:Connect(function()
			local n = #liveTracers
			if n == 0 then
				return
			end
			local now = os.clock()
			for i = n, 1, -1 do
				local t = liveTracers[i]
				local f = (now - t.t0) / t.life
				if f >= 1 or not t.part.Parent then
					pcall(function()
						t.part:Destroy()
					end)
					liveTracers[i] = liveTracers[n]
					liveTracers[n] = nil
					n -= 1
				else
					local e = f * f
					local liveColor = currentTracerColor()
					local brightNow = math.clamp(tonumber(ClientFx.tracerBrightness) or 1, 0, 3)
					local painted = if brightNow < 1 then Color3.new(0, 0, 0):Lerp(liveColor, brightNow) else liveColor
					stampEffectColor(t.beam, painted)
					t.beam.Transparency = NumberSequence.new(e)
					local w = t.width * (1 - e * 0.5)
					t.beam.Width0 = w
					t.beam.Width1 = w
				end
			end
		end))
		local function spawnTracersFromRaycasts(data: any, ctx: any)
			if type(data) ~= "table" or type(data.RaycastResults) ~= "table" then
				return
			end
			local hint: Vector3? = nil
			if type(ctx) == "table" and typeof(ctx.MuzzlePosition) == "Vector3" then
				hint = ctx.MuzzlePosition
			end
			local muzzle = getTracerMuzzlePos(nil, hint)
			local count = 0
			for _, result in data.RaycastResults do
				if type(result) == "table" and typeof(result.Position) == "Vector3" then
					local from = muzzle or (if typeof(result.StartPosition) == "Vector3" then result.StartPosition else nil)
					if typeof(from) == "Vector3" then
						spawnWorldTracer(from, result.Position)
						count += 1
					end
				end
			end
			if count > 0 then
				lastGameTracerAt = os.clock()
			end
		end
		local function spawnFallbackTracers(item: any)
			if os.clock() - lastGameTracerAt < 0.07 then
				return
			end
			local muzzle = getTracerMuzzlePos(item)
			local cam = Workspace.CurrentCamera
			if not muzzle or not cam then
				return
			end
			local pellets = 1
			local spread = 0
			pcall(function()
				local info = item and item.Info
				if type(info) == "table" then
					pellets = math.clamp(math.floor(tonumber(info.ShootPellets) or 1), 1, 16)
					spread = math.clamp(tonumber(info.ShootSpread) or 0, 0, 0.35)
				end
			end)
			local look = cam.CFrame
			local maxDist = 800
			pcall(function()
				local constants = require(ReplicatedStorage.Modules.CONSTANTS)
				if type(constants) == "table" and type(constants.MAX_RAYCAST_DISTANCE) == "number" then
					maxDist = constants.MAX_RAYCAST_DISTANCE
				end
			end)
			local params = RaycastParams.new()
			params.FilterType = Enum.RaycastFilterType.Exclude
			local exclude: { Instance } = {}
			local lp = Players.LocalPlayer
			if lp and lp.Character then
				table.insert(exclude, lp.Character)
			end
			local vms = Workspace:FindFirstChild("ViewModels")
			if vms then
				table.insert(exclude, vms)
			end
			params.FilterDescendantsInstances = exclude
			for i = 1, pellets do
				local cf = look
				if pellets > 1 or spread > 0 then
					local yaw = (math.random() - 0.5) * spread * 2
					local pitch = (math.random() - 0.5) * spread * 2
					cf = look * CFrame.Angles(pitch, yaw, 0)
					local _ = i
				end
				local origin = muzzle
				local direction = cf.LookVector * maxDist
				local hit = Workspace:Raycast(origin, direction, params)
				local dest = if hit then hit.Position else origin + direction
				spawnWorldTracer(origin, dest)
			end
			lastGameTracerAt = os.clock()
		end

		local function isOwnTracerShot(data: any, ctx: any): boolean
			if type(data) ~= "table" then
				return false
			end
			if data.IsLocal == false then
				return false
			end
			if data.IsLocal == true then
				return true
			end
			if type(ctx) == "table" and (ctx.IsLocal == true or ctx.Local == true) then
				return true
			end
			return false
		end
		local function looksLikeBulletTracer(obj: Instance): boolean
			if not (obj:IsA("Beam") or obj:IsA("Trail") or obj:IsA("ParticleEmitter")) then
				return false
			end
			if obj:IsDescendantOf(tracerFolder) then
				return true
			end
			local n = string.lower(obj.Name)
			if string.find(n, "tracer", 1, true) then
				return true
			end
			local p = obj.Parent
			if typeof(p) == "Instance" and string.find(string.lower(p.Name), "tracer", 1, true) then
				return true
			end
			local cam = Workspace.CurrentCamera
			if cam and obj:IsDescendantOf(cam) and (obj:IsA("Beam") or obj:IsA("Trail")) then
				return true
			end
			return false
		end
		local function tintGameTracer(obj: Instance)
			if not ClientFx.tracers then
				return
			end
			if looksLikeBulletTracer(obj) then
				stampEffectColor(obj, currentTracerColor())
			end
		end
		local function tintWorldTracers()
			if not ClientFx.tracers then
				return
			end
			local col = currentTracerColor()
			local function scan(root: Instance?)
				if not root then
					return
				end
				for _, obj in root:GetDescendants() do
					if looksLikeBulletTracer(obj) then
						stampEffectColor(obj, col)
					end
				end
			end
			scan(Workspace.CurrentCamera)
			local vms = Workspace:FindFirstChild("ViewModels")
			scan(vms)
			scan(tracerFolder)
		end
		pcall(function()
			local genv = fsGetgenv()
			if type(genv) == "table" and genv.__sonataTracerEffectV1 then
				return
			end
			if DrawingBridge.__sonataTracerEffectV1 then
				return
			end
			local lp = Players.LocalPlayer
			if not lp then
				return
			end
			local okReq, tracerMod = pcall(function()
				return require(lp.PlayerScripts.Modules.TracerEffect)
			end)
			if not okReq or type(tracerMod) ~= "table" or type(tracerMod.Play) ~= "function" then
				return
			end
			local hookfunction = execApi("hookfunction")
			local newcclosure = execApi("newcclosure") or function(fn: any): any
				return fn
			end
			if typeof(hookfunction) == "function" then
				local oldPlay
				oldPlay = hookfunction(
					tracerMod.Play,
					newcclosure(function(self: any, data: any, opts: any, ctx: any, ...)
						if SESSION.alive and ClientFx.tracers and type(data) == "table" and isOwnTracerShot(data, ctx) then
							pcall(spawnTracersFromRaycasts, data, ctx)
							if ClientFx.tracerReplace ~= false then
								return
							end
						end
						return oldPlay(self, data, opts, ctx, ...)
					end)
				)
			else
				local oldPlay = tracerMod.Play
				tracerMod.Play = function(self: any, data: any, opts: any, ctx: any, ...)
					if SESSION.alive and ClientFx.tracers and type(data) == "table" and isOwnTracerShot(data, ctx) then
						pcall(spawnTracersFromRaycasts, data, ctx)
						if ClientFx.tracerReplace ~= false then
							return
						end
					end
					return oldPlay(self, data, opts, ctx, ...)
				end
			end
			DrawingBridge.__sonataTracerEffectV1 = true
			if type(genv) == "table" then
				genv.__sonataTracerEffectV1 = true
			end
		end)
		local function watchTracerRoot(root: Instance?)
			if not root then
				return
			end
			table.insert(ears, root.DescendantAdded:Connect(function(obj)
				if ClientFx.tracers then
					task.defer(tintGameTracer, obj)
				end
			end))
		end
		watchTracerRoot(Workspace.CurrentCamera)
		watchTracerRoot(Workspace:FindFirstChild("ViewModels"))
		table.insert(ears, Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
			watchTracerRoot(Workspace.CurrentCamera)
			if tracerFolder.Parent ~= Workspace.CurrentCamera then
				tracerFolder.Parent = Workspace.CurrentCamera or tracerFolder.Parent
			end
		end))

		local shotHookItem: any = nil
		local shotHookConn: RBXScriptConnection? = nil
		local cachedFighterController: any = nil
		local function bindShootSoundToItem(item: any)
			if shotHookConn then
				pcall(function()
					shotHookConn:Disconnect()
				end)
				shotHookConn = nil
			end
			shotHookItem = item
			if type(item) ~= "table" then
				return
			end
			local shot = item.Shot
			if type(shot) == "table" and type(shot.Connect) == "function" then
				local ok, conn = pcall(function()
					return shot:Connect(function()
						pcall(playShootSound)
						if ClientFx.tracers then
							pcall(spawnFallbackTracers, item)
						end
					end)
				end)
				if ok then
					shotHookConn = conn
					table.insert(ears, conn)
				end
			end
		end
		local lastShotBindAt = 0
		table.insert(ears, RunService.Heartbeat:Connect(function()
			local needBind = ClientFx.shootSound == true or ClientFx.tracers == true
			if not needBind then
				if shotHookConn then
					bindShootSoundToItem(nil)
				end
				return
			end
			local now = os.clock()
			if now - lastShotBindAt < 0.55 then
				return
			end
			lastShotBindAt = now
			local lp = Players.LocalPlayer
			if not lp then
				return
			end
			if type(cachedFighterController) ~= "table" then
				local ok, fc = pcall(function()
					return require(lp.PlayerScripts.Controllers.FighterController)
				end)
				if ok and type(fc) == "table" then
					cachedFighterController = fc
				else
					return
				end
			end
			local fighter = cachedFighterController.LocalFighter
			local item = fighter and (fighter.EquippedItem or (type(fighter.Get) == "function" and fighter:Get("EquippedItem")))
			if item ~= shotHookItem then
				bindShootSoundToItem(item)
			end
		end))

