			local function afterCreate(result: any, soundId: any)
				if type(soundId) ~= "string" or soundId == "" then
					return
				end
				if ClientFx.muteGameShoot and isGunSoundId(soundId) then
					muteSoundInstance(result)
				elseif ClientFx.muteGameHit and isHitSoundId(soundId) then
					muteSoundInstance(result)
				end
			end
			if typeof(hookfunction) == "function" then
				local oldCreate
				oldCreate = hookfunction(
					utility.CreateSound,
					newcclosure(function(...)
						local soundId = select(2, ...)
						local packed = table.pack(oldCreate(...))
						if SESSION.alive then pcall(afterCreate, packed[1], soundId) end
						return table.unpack(packed, 1, packed.n)
					end)
				)
			else
				local oldCreate = utility.CreateSound
				utility.CreateSound = function(self: any, soundId: any, ...)
					local packed = table.pack(oldCreate(self, soundId, ...))
					if SESSION.alive then pcall(afterCreate, packed[1], soundId) end
					return table.unpack(packed, 1, packed.n)
				end
			end
