		local cachedViewModel: any = nil
		local cachedViewModelItem: any = nil
		local cachedViewModelAt = 0
		local function getEquippedViewModel(): any?
			local now = os.clock()
			if cachedViewModel and now - cachedViewModelAt < 0.05 then
				local held = cachedViewModel.Model
				if typeof(held) == "Instance" and held.Parent then
					return cachedViewModel
				end
			end
			local lp = Players.LocalPlayer
			if not lp then
				cachedViewModel = nil
				cachedViewModelItem = nil
				return nil
			end
			local fc = cachedFighterController
			if type(fc) ~= "table" then
				local ok, loaded = pcall(function()
					return require(lp.PlayerScripts.Controllers.FighterController)
				end)
				if ok and type(loaded) == "table" then
					cachedFighterController = loaded
					fc = loaded
				end
			end
			if type(fc) ~= "table" then
				cachedViewModel = nil
				cachedViewModelItem = nil
				return nil
			end
			local fighter = fc.LocalFighter
			local item = fighter and (fighter.EquippedItem or (type(fighter.Get) == "function" and fighter:Get("EquippedItem")))
			if type(item) ~= "table" then
				cachedViewModel = nil
				cachedViewModelItem = nil
				return nil
			end
			if item == cachedViewModelItem and cachedViewModel then
				local held = cachedViewModel.Model
				if typeof(held) == "Instance" and held.Parent then
					cachedViewModelAt = now
					return cachedViewModel
				end
			end
			local vm = item.ViewModel
			if type(vm) == "table" and typeof(vm.Model) == "Instance" then
				cachedViewModel = vm
				cachedViewModelItem = item
				cachedViewModelAt = now
				return vm
			end
			cachedViewModel = nil
			cachedViewModelItem = nil
			return nil
		end

		local function isArmInstance(inst: Instance, model: Model): boolean
			local cur: Instance? = inst
			while cur and cur ~= (model :: any) do
				local n = string.lower(cur.Name)
				if
					n == "leftarm"
					or n == "rightarm"
					or n == "left arm"
					or n == "right arm"
					or n == "left_arm"
					or n == "right_arm"
					or n == "larm"
					or n == "rarm"
					or n == "leftupperarm"
					or n == "leftlowerarm"
					or n == "lefthand"
					or n == "rightupperarm"
					or n == "rightlowerarm"
					or n == "righthand"
					or n == "arms"
					or n == "arm"
					or (string.find(n, "hand", 1, true) ~= nil and string.find(n, "handle", 1, true) == nil)
					or ((string.find(n, "left", 1, true) ~= nil or string.find(n, "right", 1, true) ~= nil) and string.find(n, "arm", 1, true) ~= nil and string.find(n, "charm", 1, true) == nil)
				then
					return true
				end
				cur = cur.Parent
			end
			return false
		end

		local function isIgnoredPart(part: BasePart, model: Model, skipOrig: boolean?): boolean
			if part == model.PrimaryPart then
				return true
			end
			local name = string.lower(part.Name)
			if name == "humanoidrootpart" or name == "rootpart" or name == "root" or name == "aimpart" or name == "camera" then
				return true
			end
			if string.sub(part.Name, 1, 1) == "_" then
				return true
			end
			if string.find(name, "hitbox", 1, true) ~= nil
				or string.find(name, "point", 1, true) ~= nil
				or string.find(name, "attach", 1, true) ~= nil
				or string.find(name, "collider", 1, true) ~= nil
				or string.find(name, "muzzle", 1, true) ~= nil
				or string.find(name, "origin", 1, true) ~= nil
				or string.find(name, "holder", 1, true) ~= nil
				or string.find(name, "marker", 1, true) ~= nil
				or string.find(name, "sight", 1, true) ~= nil
				or string.find(name, "aim", 1, true) ~= nil
				or string.find(name, "grip", 1, true) ~= nil
				or string.find(name, "eject", 1, true) ~= nil
				or string.find(name, "flash", 1, true) ~= nil
			then
				return true
			end
			if part:IsA("Part") and not part:FindFirstChildWhichIsA("SpecialMesh") then
				return true
			end
			if skipOrig ~= true then
				local orig = part:GetAttribute("__sonata_orig_trans") or part.Transparency
				if orig >= 0.95 then
					return true
				end
			end
			return false
		end

		local function isCharmOrHookInstance(inst: Instance, model: Model): boolean
			local cur: Instance? = inst
			while cur and cur ~= (model :: any) do
				local n = string.lower(cur.Name)
				if string.find(n, "charm", 1, true) ~= nil
					or string.find(n, "hook", 1, true) ~= nil
					or string.find(n, "ring", 1, true) ~= nil
					or string.sub(n, 1, 1) == "_"
				then
					return true
				end
				if cur.Parent == (model :: any) and cur:IsA("Model") and cur.Name ~= "ItemVisual" and not isArmInstance(cur, model) then
					return true
				end
				cur = cur.Parent
			end
			return false
		end

		local function isPureWeaponPart(d: BasePart, model: Model): boolean
			if not d:IsA("BasePart") then
				return false
			end
			if isArmInstance(d, model) then
				return false
			end
			if isCharmOrHookInstance(d, model) then
				return false
			end
			if isIgnoredPart(d, model) then
				return false
			end
			local orig = d:GetAttribute("__sonata_orig_trans") or d.Transparency
			if orig >= 0.95 then
				return false
			end
			local iv = model:FindFirstChild("ItemVisual", true)
			if iv and not d:IsDescendantOf(iv) then
				return false
			end
			return true
		end

		local function materialEnum(name: any): EnumItem?
			if type(name) ~= "string" then
				return nil
			end
			local mat = (Enum.Material :: any)[name]
			if typeof(mat) == "EnumItem" then
				return mat
			end
			return nil
		end

		local function applyPartMaterial(part: BasePart, matName: string, colorOn: boolean, color: Color3, opacity: number?)
			local mat = materialEnum(matName)
			if not mat then
				return
			end
			for _, child in part:GetChildren() do
				if child:IsA("SurfaceAppearance") or child:IsA("Texture") or child:IsA("Decal") then
					pcall(function()
						child:Destroy()
					end)
				elseif child:IsA("SpecialMesh") then
					pcall(function()
						child.TextureId = ""
					end)
				end
			end
			if part:IsA("MeshPart") then
				pcall(function()
					part.TextureID = ""
				end)
			end
			part.Material = mat
			if colorOn and typeof(color) == "Color3" then
				part.Color = color
			end
			if type(opacity) == "number" and part.Transparency < 0.95 then
				local vis = math.clamp(opacity, 0, 1)
				if vis > 0.001 then
					pcall(function()
						part.Transparency = math.min(1 - vis, 0.92)
					end)
				end
			end
			pcall(function()
				(part :: any).MaterialVariant = ""
			end)
		end

		local wireframeMeshCache: { [string]: { { Vector3 } } | false } = {}
		local wireframeMeshLoading: { [string]: boolean } = {}
		local AssetService = game:GetService("AssetService")

		local function getMeshWireframeLines(meshId: string): { { Vector3 } }?
			if type(meshId) ~= "string" or meshId == "" then
				return nil
			end
			local cached = wireframeMeshCache[meshId]
			if cached ~= nil then
				return if cached == false then nil else cached
			end
			if wireframeMeshLoading[meshId] then
				return nil
			end
			wireframeMeshLoading[meshId] = true
			task.spawn(function()
				local ok, em = pcall(function()
					return (AssetService :: any):CreateEditableMeshAsync(meshId)
				end)
				wireframeMeshLoading[meshId] = false
				if not ok or not em then
					wireframeMeshCache[meshId] = false
					return
				end
				local edges = {}
				local addedEdges = {}
				local okFaces, faces = pcall(function()
					return em:GetFaces()
				end)
				if not okFaces or type(faces) ~= "table" then
					pcall(function() em:Destroy() end)
					wireframeMeshCache[meshId] = false
					return
				end
				for _, fId in faces do
					local okV, verts = pcall(function() return em:GetFaceVertices(fId) end)
					if okV and type(verts) == "table" then
						local nv = #verts
						for i = 1, nv do
							local v1 = verts[i]
							local v2 = verts[(i % nv) + 1]
							local edgeKey = (v1 < v2) and (v1 .. "_" .. v2) or (v2 .. "_" .. v1)
							if not addedEdges[edgeKey] then
								addedEdges[edgeKey] = true
								local okP1, p1 = pcall(function() return em:GetPosition(v1) end)
								local okP2, p2 = pcall(function() return em:GetPosition(v2) end)
								if okP1 and okP2 and typeof(p1) == "Vector3" and typeof(p2) == "Vector3" then
									table.insert(edges, { p1, p2 })
								end
							end
						end
					end
				end
				pcall(function()
					em:Destroy()
				end)
				wireframeMeshCache[meshId] = edges
				if DrawingBridge.restyleViewModel then
					DrawingBridge.restyleViewModel()
				end
			end)
			return nil
		end

		local function addBoxWireframeLines(w: WireframeHandleAdornment, size: Vector3)
			local hx, hy, hz = size.X * 0.5, size.Y * 0.5, size.Z * 0.5
			local c = {
				Vector3.new(-hx, -hy, -hz), Vector3.new(hx, -hy, -hz),
				Vector3.new(hx, -hy, hz), Vector3.new(-hx, -hy, hz),
				Vector3.new(-hx, hy, -hz), Vector3.new(hx, hy, -hz),
				Vector3.new(hx, hy, hz), Vector3.new(-hx, hy, hz),
			}
			w:AddLine(c[1], c[2]); w:AddLine(c[2], c[3]); w:AddLine(c[3], c[4]); w:AddLine(c[4], c[1])
			w:AddLine(c[5], c[6]); w:AddLine(c[6], c[7]); w:AddLine(c[7], c[8]); w:AddLine(c[8], c[5])
			w:AddLine(c[1], c[5]); w:AddLine(c[2], c[6]); w:AddLine(c[3], c[7]); w:AddLine(c[4], c[8])
		end

		local customAssetCache: { [string]: Instance } = {}
		local assetLoading: { [string]: boolean } = {}

		local function parseAssetId(str: any): string?
			if type(str) ~= "string" or str == "" then
				return nil
			end
			return string.match(str, "(%d+)")
		end

		local function clearCustomAssetCache()
			table.clear(customAssetCache)
			table.clear(assetLoading)
			local lp = Players.LocalPlayer
			local char = lp and lp.Character
			if char then
				local old = char:FindFirstChild("__sonata_custom_char")
				if old then
					old:Destroy()
				end
			end
			local vm = getEquippedViewModel()
			if type(vm) == "table" and typeof(vm.Model) == "Instance" and vm.Model:IsA("Model") then
				for _, name in { "__sonata_custom_model", "__sonata_custom_hand_l", "__sonata_custom_hand_r" } do
					local old = vm.Model:FindFirstChild(name, true)
					if old then
						old:Destroy()
					end
				end
			end
		end
		DrawingBridge.clearCustomAssetCache = clearCustomAssetCache

		local function loadCustomAssetAsync(id: string)
			if assetLoading[id] or customAssetCache[id] ~= nil then
				return
			end
			assetLoading[id] = true
			task.spawn(function()
				local ok, res = pcall(function()
					return game:GetObjects("rbxassetid://" .. id)
				end)
				assetLoading[id] = false
				if ok and type(res) == "table" and #res > 0 then
					local root = res[1]
					if root then
						customAssetCache[id] = root
					end
				end
			end)
		end

		local function getCustomAssetModel(assetId: string): Instance?
			local id = parseAssetId(assetId)
			if not id then
				return nil
			end
			local cached = customAssetCache[id]
			if cached then
				local ok, cl = pcall(function()
					return cached:Clone()
				end)
				if ok and cl then
					return cl
				end
				return nil
			end
			loadCustomAssetAsync(id)
			return nil
		end

		local function prepareCustomAsset(inst: Instance, scale: number)
			local s = math.clamp(scale, 0.05, 10)
			for _, d in inst:GetDescendants() do
				if d:IsA("Humanoid") or d:IsA("Script") or d:IsA("LocalScript") or d:IsA("Animator") or d:IsA("AnimationController") or d:IsA("JointInstance") then
					pcall(function() d:Destroy() end)
				end
			end
			if inst:IsA("Humanoid") or inst:IsA("JointInstance") then
				pcall(function() inst:Destroy() end)
				return
			end

			local primary: BasePart? = nil
			if inst:IsA("Model") then
				primary = inst.PrimaryPart or inst:FindFirstChild("HumanoidRootPart") or inst:FindFirstChild("Handle") or inst:FindFirstChildWhichIsA("BasePart", true)
				if primary then
					inst.PrimaryPart = primary
				end
				pcall(function()
					inst:ScaleTo(s)
				end)
			elseif inst:IsA("BasePart") then
				primary = inst
				inst.Size = inst.Size * s
			end

			if primary then
				primary.CanCollide = false
				primary.CanTouch = false
				primary.CanQuery = false
				primary.CastShadow = false
				primary.Massless = true
				primary.Anchored = false
			end

			for _, d in inst:GetDescendants() do
				if d:IsA("BasePart") then
					d.CanCollide = false
					d.CanTouch = false
					d.CanQuery = false
					d.CastShadow = false
					d.Massless = true
					d.Anchored = false
					if primary and d ~= primary then
						local w = d:FindFirstChild("__sonata_internal_weld") or Instance.new("Weld")
						w.Name = "__sonata_internal_weld"
						w.Part0 = primary
						w.Part1 = d
						w.C0 = primary.CFrame:ToObjectSpace(d.CFrame)
						w.C1 = CFrame.identity
						w.Parent = d
					end
				end
			end
		end

		local function updateCustomViewModel(vmModel: Model)
			if vmModel:GetAttribute("__sonata_slots_off") == true then
				return
			end
			for _, slotName in { "__sonata_custom_model", "__sonata_custom_hand_l", "__sonata_custom_hand_r" } do
				local old = vmModel:FindFirstChild(slotName, true)
				if old then
					old:Destroy()
				end
			end
			vmModel:SetAttribute("__sonata_slots_off", true)
		end

		local lastCharFirstPerson: boolean? = nil
		local function updateCustomCharacter()
			local cfg = ClientFx
			local lp = Players.LocalPlayer
			local char = lp and lp.Character
			if not char then
				lastCharFirstPerson = nil
				return
			end
			local wantChar = cfg.customModel == true and cfg.customModelReplaceChar == true and type(cfg.customModelCharAsset) == "string" and parseAssetId(cfg.customModelCharAsset) ~= nil
			local current = char:FindFirstChild("__sonata_custom_char")
			if not wantChar then
				if current then
					current:Destroy()
				end
				lastCharFirstPerson = nil
				return
			end
			local hrp = char:FindFirstChild("HumanoidRootPart")
			if not hrp then
				return
			end
			local desiredId = parseAssetId(cfg.customModelCharAsset)
			if not desiredId then
				if current then
					current:Destroy()
				end
				return
			end
			local currentId = current and current:GetAttribute("AssetId")
			local currentScale = current and current:GetAttribute("Scale")
			local targetScale = cfg.customCharScale or 1
			if current and (currentId ~= desiredId or currentScale ~= targetScale) then
				current:Destroy()
				current = nil
				lastCharFirstPerson = nil
			end
			if not current then
				local loaded = getCustomAssetModel(desiredId)
				if loaded then
					loaded.Name = "__sonata_custom_char"
					loaded:SetAttribute("AssetId", desiredId)
					loaded:SetAttribute("Scale", targetScale)
					prepareCustomAsset(loaded, targetScale)
					loaded.Parent = char
					current = loaded
					lastCharFirstPerson = nil
				end
			end
			if current then
				local primary = if current:IsA("Model") then (current.PrimaryPart or current:FindFirstChildWhichIsA("BasePart", true)) else (current:IsA("BasePart") and current or nil)
				if primary then
					local spinAngle = if cfg.characterSpin == true then math.rad((os.clock() * (cfg.characterSpinSpeed or 2) * 60) % 360) else 0
					local offsetCF = CFrame.new(cfg.customCharX or 0, cfg.customCharY or -1.5, cfg.customCharZ or 0)
						* CFrame.Angles(math.rad(cfg.customCharPitch or 0), math.rad(cfg.customCharYaw or -90) + spinAngle, math.rad(cfg.customCharRoll or 0))

					local weld = primary:FindFirstChild("__sonata_char_weld")
					if not (weld and weld:IsA("Weld") and weld.Part0 == hrp and weld.Part1 == primary) then
						if weld then weld:Destroy() end
						weld = Instance.new("Weld")
						weld.Name = "__sonata_char_weld"
						weld.Part0 = hrp
						weld.Part1 = primary
						weld.Parent = primary
					end
					weld.C0 = offsetCF
					weld.C1 = CFrame.identity
				end

				local cam = workspace.CurrentCamera
				local dist = if cam then (cam.CFrame.Position - hrp.Position).Magnitude else 10
				local isFirstPerson = if lastCharFirstPerson == true then dist < 4.5 elseif lastCharFirstPerson == false then dist < 2.2 else dist < 3
				local label = if type(cfg.playerModelLabel) == "string" and cfg.playerModelLabel ~= "" then cfg.playerModelLabel else "model"
				local anchor = if current:IsA("Model") then (current.PrimaryPart or current:FindFirstChildWhichIsA("BasePart", true)) else current
				local tag = if anchor then anchor:FindFirstChild("__sonata_label") else nil
				if anchor and not tag then
					local gui = Instance.new("BillboardGui")
					gui.Name = "__sonata_label"
					gui.AlwaysOnTop = true
					gui.Size = UDim2.fromOffset(200, 32)
					gui.StudsOffset = Vector3.new(0, 3.4, 0)
					gui.LightInfluence = 0
					gui.Parent = anchor
					local text = Instance.new("TextLabel")
					text.Name = "T"
					text.BackgroundTransparency = 1
					text.Size = UDim2.fromScale(1, 1)
					text.Font = Enum.Font.GothamMedium
					text.TextSize = 16
					text.TextColor3 = Color3.fromRGB(255, 255, 255)
					text.TextStrokeTransparency = 0.35
					text.Parent = gui
					tag = gui
				end
				local text = tag and tag:FindFirstChild("T")
				if text and text:IsA("TextLabel") and text.Text ~= label then
					text.Text = label
				end
				current:SetAttribute("Label", label)
				if isFirstPerson ~= lastCharFirstPerson then
					lastCharFirstPerson = isFirstPerson
					local ltm = if isFirstPerson then 1 else 0
					for _, part in current:GetDescendants() do
						if part:IsA("BasePart") then
							part.LocalTransparencyModifier = ltm
						elseif part:IsA("Decal") then
							part.Transparency = ltm
						end
					end
					if current:IsA("BasePart") then
						current.LocalTransparencyModifier = ltm
					end
				end
			end
		end

		local lastStyledModel: Model? = nil
		local lastStyleSig = ""
		local lastStyleAt = 0
		local function colorSig(c: any): string
			local col = coerceColor3(c, Color3.fromRGB(255, 255, 255))
			return string.format("%d,%d,%d", math.floor(col.R * 255 + 0.5), math.floor(col.G * 255 + 0.5), math.floor(col.B * 255 + 0.5))
		end

		local function wireColorOf(cfg: any, arm: boolean): Color3
			local src = if arm then cfg.armWireColor else cfg.weaponWireColor
			return coerceColor3(src, Color3.fromRGB(255, 255, 255))
		end

		local function colorsClose(a: Color3, b: Color3): boolean
			return math.abs(a.R - b.R) < 0.004 and math.abs(a.G - b.G) < 0.004 and math.abs(a.B - b.B) < 0.004
		end

		local function paintExistingWires(model: Model)
			local cfg = ClientFx
			local thick = if type(cfg.weaponWireThickness) == "number" then math.clamp(cfg.weaponWireThickness, 0.5, 4) else 1
			local rebuilt = false
			for _, d in model:GetDescendants() do
				if d:IsA("WireframeHandleAdornment") and d.Name == "__sonata_wire" then
					local part = d.Parent
					local arm = typeof(part) == "Instance" and part:IsA("BasePart") and isArmInstance(part, model)
					local col = wireColorOf(cfg, arm == true)
					stampAdornmentColor(d, col)
					d.Thickness = thick
					d.Visible = true
					local now = coerceColor3((d :: any).Color3, Color3.fromRGB(13, 105, 172))
					if not colorsClose(now, col) then
						pcall(function()
							d:Destroy()
						end)
						rebuilt = true
					end
				end
			end
			if rebuilt then
				lastStyleSig = ""
			end
		end

		local function clientFxStyleSignature(): string
			local cfg = ClientFx
			local rem = cfg.removalsEnabled == true
			return string.format(
				"%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s",
				cfg.weaponMaterialOn and "1" or "0",
				cfg.materialOn and "1" or "0",
				tostring(cfg.weaponMaterial or cfg.material or ""),
				cfg.weaponColorOn and tostring(cfg.weaponColor) or "0",
				cfg.armMaterialOn and tostring(cfg.armMaterial or "") or "0",
				cfg.armColorOn and tostring(cfg.armColor) or "0",
				cfg.weaponWireframe and (tostring(cfg.weaponWireThickness or 1) .. colorSig(cfg.weaponWireColor)) or "0",
				cfg.armWireframe and ("1" .. colorSig(cfg.armWireColor)) or "0",
				cfg.wireframeOnly and "1" or "0",
				rem and (cfg.removeArms and "1" or "0") or "0",
				rem and (cfg.removeWeapon and "1" or "0") or "0",
				rem and (cfg.removeDecals and "1" or "0") or "0",
				rem and (cfg.removeClothes and "1" or "0") or "0",
				cfg.weaponLight and (tostring(cfg.weaponLightBrightness or 3) .. tostring(cfg.weaponLightColor or "")) or "0",
				cfg.customModel and (cfg.customModelReplaceWeapon and "1" or "0") or "0",
				cfg.customModel and (cfg.customModelHideGun and "1" or "0") or "0",
				cfg.customModel and (cfg.customModelHideArms and "1" or "0") or "0",
				cfg.customModel and (cfg.customModelReplaceLeftHand and "1" or "0") or "0",
				cfg.customModel and (cfg.customModelReplaceRightHand and "1" or "0") or "0",
				cfg.gunScaleOn and (tostring(cfg.gunScale) .. tostring(cfg.gunScaleX) .. tostring(cfg.gunScaleY) .. tostring(cfg.gunScaleZ)) or "0"
			)
		end

		local function weaponHideWanted(cfg: any): boolean
			if cfg.weaponWireframe == true and cfg.wireframeOnly == true then
				return true
			end
			if cfg.removalsEnabled == true and cfg.removeWeapon == true then
				return true
			end
			if cfg.customModel == true and (cfg.customModelHideGun == true or cfg.customModelReplaceWeapon == true) then
				return true
			end
			return false
		end

		local function armHideWanted(cfg: any, part: BasePart): boolean
			if cfg.removalsEnabled == true and cfg.removeArms == true then
				return true
			end
			if cfg.customModel ~= true then
				return false
			end
			if cfg.customModelHideArms == true then
				return true
			end
			local n = string.lower(part.Name)
			local pn = if part.Parent then string.lower(part.Parent.Name) else ""
			local isLeft = string.find(n, "left", 1, true) ~= nil or string.find(pn, "left", 1, true) ~= nil
			local isRight = string.find(n, "right", 1, true) ~= nil or string.find(pn, "right", 1, true) ~= nil
			if cfg.customModelReplaceLeftHand == true and isLeft then
				return true
			end
			if cfg.customModelReplaceRightHand == true and isRight then
				return true
			end
			return false
		end

		local function rememberOrigTrans(part: BasePart): number
			local existing = part:GetAttribute("__sonata_orig_trans")
			if type(existing) == "number" then
				return existing
			end
			local t = part.Transparency
			if type(t) == "number" and t < 0.95 then
				part:SetAttribute("__sonata_orig_trans", t)
				return t
			end
			return if type(t) == "number" then t else 1
		end

		local function revealPart(part: BasePart, origTrans: number?)
			if part:GetAttribute("__sonata_hid_gun") ~= true then
				return
			end
			local restore = origTrans
			if type(restore) ~= "number" then
				restore = part:GetAttribute("__sonata_orig_trans")
			end
			if type(restore) ~= "number" or restore >= 0.95 then
				restore = 0
			end
			pcall(function()
				part.Transparency = restore
				part.LocalTransparencyModifier = 0
			end)
			part:SetAttribute("__sonata_hid_gun", nil)
		end

		local lastEnsureAt = 0
		local lastEnsureModel: Model? = nil
		local lastEnsureHide = false
		local gunWasHid = false
		local function ensureGunVisible(model: Model)
			local cfg = ClientFx
			local hideGun = weaponHideWanted(cfg)
			local now = os.clock()
			if hideGun then
				lastEnsureHide = true
				lastEnsureModel = model
				gunWasHid = true
				return
			end
			local force = lastEnsureHide == true or gunWasHid == true or lastEnsureModel ~= model
			if not force and now - lastEnsureAt < 0.45 then
				return
			end
			lastEnsureAt = now
			lastEnsureModel = model
			lastEnsureHide = false
			for _, d in model:GetDescendants() do
				if not d:IsA("BasePart") then
					continue
				end
				if d.Name == "__sonata_custom_model"
					or d.Name == "__sonata_custom_hand_l"
					or d.Name == "__sonata_custom_hand_r"
					or d:FindFirstAncestor("__sonata_custom_model")
					or d:FindFirstAncestor("__sonata_custom_hand_l")
					or d:FindFirstAncestor("__sonata_custom_hand_r")
				then
					continue
				end
				if d:IsA("Part") and not d:FindFirstChildWhichIsA("SpecialMesh") then
					if d:GetAttribute("__sonata_hid_gun") ~= true then
						local orig = d:GetAttribute("__sonata_orig_trans")
						if type(orig) ~= "number" or orig >= 0.95 then
							if d.Transparency < 0.95 then
								pcall(function()
									d.Transparency = if type(orig) == "number" then orig else 1
								end)
							end
						end
					end
					continue
				end
				if isIgnoredPart(d, model) or isCharmOrHookInstance(d, model) then
					continue
				end
				local arm = isArmInstance(d, model)
				if arm and armHideWanted(cfg, d) then
					continue
				end
				if not arm and hideGun then
					continue
				end
				if d:GetAttribute("__sonata_hid_gun") == true then
					revealPart(d, d:GetAttribute("__sonata_orig_trans"))
					continue
				end
				local orig = d:GetAttribute("__sonata_orig_trans")
				if type(orig) == "number" and orig < 0.95 and d.Transparency >= 0.95 then
					pcall(function()
						d.Transparency = orig
						d.LocalTransparencyModifier = 0
					end)
				end
			end
			gunWasHid = false
		end

		local function styleViewModel(model: Model)
			local cfg = ClientFx
			local weaponOn = cfg.weaponMaterialOn == true or cfg.materialOn == true
			local armOn = cfg.armMaterialOn == true
			local weaponMat = if type(cfg.weaponMaterial) == "string" then cfg.weaponMaterial else cfg.material
			local armMat = if type(cfg.armMaterial) == "string" then cfg.armMaterial else "SmoothPlastic"
			local rem = cfg.removalsEnabled == true

			local anyEffectOn = weaponOn or armOn or (rem and (cfg.removeDecals or cfg.removeClothes or cfg.removeArms or cfg.removeWeapon or cfg.removeCharacter))
				or cfg.weaponColorOn or cfg.armColorOn
				or cfg.weaponLight or cfg.weaponWireframe or cfg.armWireframe or cfg.wireframeOnly
				or cfg.customModel or cfg.customModelReplaceWeapon
				or cfg.customModelReplaceLeftHand or cfg.customModelReplaceRightHand or cfg.customModelReplaceChar
				or (cfg.customModel and (cfg.customModelHideArms or cfg.customModelHideGun or cfg.customModelHideChar))
				or cfg.gunScaleOn

			if not anyEffectOn then
				for _, d in model:GetDescendants() do
					local unwWire = d:FindFirstChild("__sonata_wire")
					if unwWire then
						unwWire:Destroy()
					end
					if d:IsA("BasePart") then
						local orig = d:GetAttribute("__sonata_orig_trans")
						if type(orig) == "number" and orig < 0.95 then
							pcall(function()
								d.Transparency = orig
								d.LocalTransparencyModifier = 0
							end)
						end
						d:SetAttribute("__sonata_hid_gun", nil)
						local origSz = d:GetAttribute("__sonata_orig_size")
						if origSz ~= nil then
							d.Size = origSz
						end
						for _, child in d:GetChildren() do
							if child:IsA("SpecialMesh") then
								local origScale = child:GetAttribute("__sonata_orig_scale")
								if origScale ~= nil then
									child.Scale = origScale
								end
							end
						end
					end
				end
				local existingLight = model:FindFirstChild("__sonata_vm_light", true)
				if existingLight then
					existingLight:Destroy()
				end
				return
			end

			for _, d in model:GetDescendants() do
				if rem and cfg.removeDecals and (d:IsA("Decal") or d:IsA("Texture") or d:IsA("SurfaceAppearance")) then
					if not (weaponOn or armOn) then
						pcall(function()
							if d:IsA("Decal") or d:IsA("Texture") then
								d.Transparency = 1
							else
								d:Destroy()
							end
						end)
					else
						pcall(function()
							d:Destroy()
						end)
					end
				end
				if rem and cfg.removeClothes and (d:IsA("Shirt") or d:IsA("Pants") or d:IsA("ShirtGraphic") or d:IsA("Clothing") or d:IsA("CharacterMesh")) then
					pcall(function()
						d:Destroy()
					end)
				end
				if d:IsA("BasePart") then
					if d.Name == "__sonata_custom_model" or d.Name == "__sonata_custom_hand_l" or d.Name == "__sonata_custom_hand_r" or d.Name == "__sonata_custom_char"
						or d:FindFirstAncestor("__sonata_custom_model")
						or d:FindFirstAncestor("__sonata_custom_hand_l")
						or d:FindFirstAncestor("__sonata_custom_hand_r")
						or d:FindFirstAncestor("__sonata_custom_char")
					then
						continue
					end

					local origTrans = rememberOrigTrans(d)

					local unwantedWire = d:FindFirstChild("__sonata_wire")
					if origTrans >= 0.95 or isIgnoredPart(d, model) or isCharmOrHookInstance(d, model) then
						d.Transparency = origTrans
						if unwantedWire then
							unwantedWire:Destroy()
						end
						continue
					end

					local arm = isArmInstance(d, model)
					local isGunPart = not arm and isPureWeaponPart(d, model)
					local isArmPart = arm

					local wantWire = (isGunPart and cfg.weaponWireframe == true) or (isArmPart and cfg.armWireframe == true)
					if wantWire and origTrans < 0.95 then
						local wireCol = wireColorOf(cfg, isArmPart)
						local wireThick = if type(cfg.weaponWireThickness) == "number" then math.clamp(cfg.weaponWireThickness, 0.5, 4) else 1
						local lines: { { Vector3 } }? = nil
						local scale = Vector3.new(1, 1, 1)
						if d:IsA("MeshPart") and d.MeshId ~= "" then
							local ms = (d :: any).MeshSize
							scale = if (ms and ms.X > 0 and ms.Y > 0 and ms.Z > 0)
								then Vector3.new(d.Size.X / ms.X, d.Size.Y / ms.Y, d.Size.Z / ms.Z)
								else Vector3.new(1, 1, 1)
							lines = getMeshWireframeLines(d.MeshId)
						elseif d:IsA("Part") then
							local sm = d:FindFirstChildWhichIsA("SpecialMesh")
							if sm and sm.MeshId ~= "" then
								lines = getMeshWireframeLines(sm.MeshId)
								scale = sm.Scale
							end
						end

						if lines and #lines > 0 then
							local reuse = unwantedWire and unwantedWire:IsA("WireframeHandleAdornment") and unwantedWire
							if reuse then
								local curCol = coerceColor3((reuse :: any).Color3, Color3.fromRGB(13, 105, 172))
								if not colorsClose(curCol, wireCol) then
									reuse:Destroy()
									reuse = nil
									unwantedWire = nil
								end
							end
							local w = reuse or Instance.new("WireframeHandleAdornment")
							if w ~= unwantedWire then
								if unwantedWire and unwantedWire ~= w then
									unwantedWire:Destroy()
								end
								w.Name = "__sonata_wire"
								w.Adornee = d
								w.AlwaysOnTop = false
								w.ZIndex = 1
								stampAdornmentColor(w, wireCol)
								for _, edge in lines do
									w:AddLine(edge[1] * scale, edge[2] * scale)
								end
								w.Parent = d
							end
							stampAdornmentColor(w, wireCol)
							w.Thickness = wireThick
							w.Visible = true
						elseif unwantedWire then
							unwantedWire:Destroy()
						end
					elseif unwantedWire then
						unwantedWire:Destroy()
					end

					if arm then
						local origSz = d:GetAttribute("__sonata_orig_size")
						if origSz ~= nil then
							d.Size = origSz
						end
						local hideArm = armHideWanted(cfg, d)

						if hideArm then
							d:SetAttribute("__sonata_hid_gun", true)
							d.Transparency = 1
						elseif armOn then
							applyPartMaterial(d, armMat, cfg.armColorOn == true, cfg.armColor, cfg.armOpacity)
						elseif cfg.armColorOn == true and typeof(cfg.armColor) == "Color3" then
							for _, child in d:GetChildren() do
								if child:IsA("SurfaceAppearance") or child:IsA("Texture") or child:IsA("Decal") then
									pcall(function()
										child:Destroy()
									end)
								elseif child:IsA("SpecialMesh") then
									pcall(function()
										child.TextureId = ""
									end)
								end
							end
							if d:IsA("MeshPart") then
								pcall(function()
									d.TextureID = ""
								end)
							end
							d.Color = cfg.armColor
							if type(cfg.armOpacity) == "number" and origTrans < 0.95 then
								local vis = math.clamp(cfg.armOpacity, 0, 1)
								d.Transparency = if vis > 0.001 then math.min(1 - vis, 0.92) else origTrans
							else
								d.Transparency = origTrans
							end
							d:SetAttribute("__sonata_hid_gun", nil)
						else
							revealPart(d, origTrans)
						end
						if not hideArm and d.Transparency >= 0.95 then
							revealPart(d, origTrans)
						end
					else
						local origSize = d:GetAttribute("__sonata_orig_size")
						if origSize == nil then
							origSize = d.Size
							d:SetAttribute("__sonata_orig_size", origSize)
						end
						if cfg.gunScaleOn then
							local s = math.clamp(cfg.gunScale or 1, 0.05, 10)
							local sx = math.clamp(cfg.gunScaleX or 1, 0.1, 5) * s
							local sy = math.clamp(cfg.gunScaleY or 1, 0.1, 5) * s
							local sz = math.clamp(cfg.gunScaleZ or 1, 0.1, 5) * s
							d.Size = Vector3.new(origSize.X * sx, origSize.Y * sy, origSize.Z * sz)
						elseif origSize then
							d.Size = origSize
						end
						for _, child in d:GetChildren() do
							if child:IsA("SpecialMesh") then
								local origMeshScale = child:GetAttribute("__sonata_orig_scale")
								if origMeshScale == nil then
									origMeshScale = child.Scale
									child:SetAttribute("__sonata_orig_scale", origMeshScale)
								end
								if cfg.gunScaleOn then
									local s = math.clamp(cfg.gunScale or 1, 0.05, 10)
									local sx = math.clamp(cfg.gunScaleX or 1, 0.1, 5) * s
									local sy = math.clamp(cfg.gunScaleY or 1, 0.1, 5) * s
									local sz = math.clamp(cfg.gunScaleZ or 1, 0.1, 5) * s
									child.Scale = Vector3.new(origMeshScale.X * sx, origMeshScale.Y * sy, origMeshScale.Z * sz)
								elseif origMeshScale then
									child.Scale = origMeshScale
								end
							end
						end
						local shouldHideWeapon = weaponHideWanted(cfg)

						if shouldHideWeapon then
							d:SetAttribute("__sonata_hid_gun", true)
							d.Transparency = 1
						elseif weaponOn then
							applyPartMaterial(d, weaponMat, cfg.weaponColorOn == true, cfg.weaponColor, cfg.weaponOpacity)
						elseif cfg.weaponColorOn == true and typeof(cfg.weaponColor) == "Color3" then
							for _, child in d:GetChildren() do
								if child:IsA("SurfaceAppearance") or child:IsA("Texture") or child:IsA("Decal") then
									pcall(function()
										child:Destroy()
									end)
								elseif child:IsA("SpecialMesh") then
									pcall(function()
										child.TextureId = ""
									end)
								end
							end
							if d:IsA("MeshPart") then
								pcall(function()
									d.TextureID = ""
								end)
							end
							d.Color = cfg.weaponColor
							if type(cfg.weaponOpacity) == "number" and origTrans < 0.95 then
								local vis = math.clamp(cfg.weaponOpacity, 0, 1)
								d.Transparency = if vis > 0.001 then math.min(1 - vis, 0.92) else origTrans
							else
								d.Transparency = origTrans
							end
							d:SetAttribute("__sonata_hid_gun", nil)
							pcall(function()
								d.LocalTransparencyModifier = 0
							end)
						else
							revealPart(d, origTrans)
						end
						if not shouldHideWeapon and d.Transparency >= 0.95 then
							revealPart(d, origTrans)
						end
					end
				end
			end
			local lightHolder = model:FindFirstChild("Camera", true) or model:FindFirstChild("HumanoidRootPart", true) or model:FindFirstChildWhichIsA("BasePart", true)
			if lightHolder then
				local existingLight = lightHolder:FindFirstChild("__sonata_vm_light")
				if cfg.weaponLight == true then
					local light = existingLight or Instance.new("PointLight")
					light.Name = "__sonata_vm_light"
					light.Shadows = false
					light.Brightness = cfg.weaponLightBrightness or 3
					light.Range = cfg.weaponLightRange or 15
					light.Color = if typeof(cfg.weaponLightColor) == "Color3" then cfg.weaponLightColor else Color3.fromRGB(255, 255, 255)
					light.Enabled = true
					light.Parent = lightHolder
				elseif existingLight then
					existingLight:Destroy()
				end
			end
		end

		local function maybeStyleViewModel(model: Model?)
			if typeof(model) ~= "Instance" or not model:IsA("Model") then
				return
			end
			local sig = clientFxStyleSignature()
			if model == lastStyledModel and sig == lastStyleSig then
				return
			end
			lastStyledModel = model
			lastStyleSig = sig
			styleViewModel(model)
			paintExistingWires(model)
		end

		DrawingBridge.restyleViewModel = function()
			lastStyleSig = ""
			local vm = getEquippedViewModel()
			if type(vm) == "table" and typeof(vm.Model) == "Instance" and vm.Model:IsA("Model") then
				maybeStyleViewModel(vm.Model)
			end
		end
		DrawingBridge.recolorClientFx = function()
			ClientFx.tracerColor = currentTracerColor()
			ClientFx.weaponWireColor = coerceColor3(ClientFx.weaponWireColor, Color3.fromRGB(255, 255, 255))
			ClientFx.armWireColor = coerceColor3(ClientFx.armWireColor, Color3.fromRGB(255, 255, 255))
			for _, t in liveTracers do
				if t.beam then
					stampEffectColor(t.beam, currentTracerColor())
				end
			end
			pcall(tintWorldTracers)
			local vm = getEquippedViewModel()
			if type(vm) == "table" and typeof(vm.Model) == "Instance" and vm.Model:IsA("Model") then
				paintExistingWires(vm.Model)
			end
		end

		local function userViewOffset(): CFrame
			local pitch = ClientFx.pitch or 0
			local yaw = ClientFx.yaw
			local roll = ClientFx.roll
			if ClientFx.animate then
				local t = os.clock()
				yaw += math.sin(t * ClientFx.yawSpeed) * ClientFx.yawRange
				roll += math.sin(t * ClientFx.rollSpeed + 1.2) * ClientFx.rollRange
			end
			local fovOffset = if ClientFx.fovOffset then ClientFx.fovOffset * -0.05 else 0
			return CFrame.new(ClientFx.x, ClientFx.y, ClientFx.z + fovOffset)
				* CFrame.Angles(math.rad(pitch), math.rad(yaw), math.rad(roll))
		end

		pcall(function()
			local lp = Players.LocalPlayer
			if not lp then
				return
			end
			local viewclass = require(lp.PlayerScripts.Modules.ClientReplicatedClasses.ClientFighter.ClientItem.ClientViewModel)
			if type(viewclass) ~= "table" or type(viewclass.SetCFrame) ~= "function" then
				return
			end
			if viewclass.__sonataSetCFrame then
				return
			end
			local oldSet = viewclass.SetCFrame
			viewclass.SetCFrame = function(self: any, cf: any, ...: any)
				if ClientFx.viewmodel and typeof(cf) == "CFrame" then
					cf = cf * userViewOffset()
				end
				return oldSet(self, cf, ...)
			end
			viewclass.__sonataSetCFrame = true
			table.insert(ears, {
				Disconnect = function()
					viewclass.SetCFrame = oldSet
					viewclass.__sonataSetCFrame = nil
				end,
			} :: any)
		end)

		local setCFrameHooked = false
		pcall(function()
			local lp = Players.LocalPlayer
			local viewclass = require(lp.PlayerScripts.Modules.ClientReplicatedClasses.ClientFighter.ClientItem.ClientViewModel)
			setCFrameHooked = viewclass.__sonataSetCFrame == true
		end)

		local validBodyParts: { [string]: boolean } = {
			["head"] = true,
			["torso"] = true,
			["uppertorso"] = true,
			["lowertorso"] = true,
			["left arm"] = true,
			["leftarm"] = true,
			["leftupperarm"] = true,
			["leftlowerarm"] = true,
			["lefthand"] = true,
			["right arm"] = true,
			["rightarm"] = true,
			["rightupperarm"] = true,
			["rightlowerarm"] = true,
			["righthand"] = true,
			["left leg"] = true,
			["leftleg"] = true,
			["leftupperleg"] = true,
			["leftlowerleg"] = true,
			["leftfoot"] = true,
			["right leg"] = true,
			["rightleg"] = true,
			["rightupperleg"] = true,
			["rightlowerleg"] = true,
			["rightfoot"] = true,
		}

		local lastCharModel: Model? = nil
		local lastCharHide: boolean? = nil
		local lastCharWasFP: boolean? = nil
		local function updateCharacterRemoval()
			local lp = Players.LocalPlayer
			local char = lp and lp.Character
			if not char then
				lastCharModel = nil
				lastCharHide = nil
				lastCharWasFP = nil
				return
			end
			local hrp = char:FindFirstChild("HumanoidRootPart")
			local cam = workspace.CurrentCamera
			local dist = if hrp and cam then (cam.CFrame.Position - hrp.Position).Magnitude else 10
			local isFirstPerson = if lastCharWasFP == true then dist < 4.5 elseif lastCharWasFP == false then dist < 2.2 else dist < 3
			local wantChar = ClientFx.customModel == true and ClientFx.customModelReplaceChar == true and type(ClientFx.customModelCharAsset) == "string" and parseAssetId(ClientFx.customModelCharAsset) ~= nil
			local hide = ClientFx.removeCharacter == true or ClientFx.customModelHideChar == true or wantChar
			if char == lastCharModel and hide == lastCharHide and isFirstPerson == lastCharWasFP then
				return
			end
			lastCharModel = char
			lastCharHide = hide
			lastCharWasFP = isFirstPerson
			local customChar = char:FindFirstChild("__sonata_custom_char")
			for _, p in char:GetDescendants() do
				if customChar and (p == customChar or p:IsDescendantOf(customChar)) then
					continue
				end
				if p:IsA("BasePart") then
					local pName = string.lower(p.Name)
					local isBodyPart = validBodyParts[pName] == true
					local isAccessoryHandle = p.Name == "Handle" and p.Parent and p.Parent:IsA("Accessory")

					if hide or isFirstPerson then
						p.LocalTransparencyModifier = 1
						if hide then
							p.Transparency = 1
						end
					else
						p.LocalTransparencyModifier = 0
						if isBodyPart or isAccessoryHandle then
							local orig = p:GetAttribute("__sonata_char_orig_trans")
							p.Transparency = orig or 0
						else
							p.Transparency = 1
						end
					end
				elseif p:IsA("Decal") then
					p.Transparency = if (hide or isFirstPerson) then 1 else 0
				elseif p:IsA("BillboardGui") or p:IsA("SurfaceGui") or p:IsA("ParticleEmitter") or p:IsA("Beam") or p:IsA("Trail") then
					p.Enabled = not (hide or isFirstPerson)
				end
			end
		end

		pcall(function()
			RunService:UnbindFromRenderStep("__sonata_viewmodel")
		end)
		local vmLatch = true
		RunService:BindToRenderStep("__sonata_viewmodel", Enum.RenderPriority.Camera.Value + 1, function()
			local cfg = ClientFx
			local playerOn = cfg.customModel == true or cfg.removeCharacter == true or cfg.removalsEnabled == true
			local vmOn = playerOn or cfg.viewmodel == true or cfg.weaponMaterialOn == true or cfg.armMaterialOn == true
				or cfg.weaponColorOn == true or cfg.armColorOn == true or cfg.weaponLight == true
				or cfg.weaponWireframe == true or cfg.armWireframe == true or cfg.gunScaleOn == true
			if not playerOn and not vmOn then
				if vmLatch then
					vmLatch = false
					updateCharacterRemoval()
					updateCustomCharacter()
				end
			else
				vmLatch = true
				if playerOn then
					updateCharacterRemoval()
					if cfg.customModel == true then
						updateCustomCharacter()
					end
				end
			end
			local vm = getEquippedViewModel()
			if type(vm) ~= "table" then
				return
			end
			if vmOn then
				if not setCFrameHooked then
					if ClientFx.viewmodel then
						local base = CFrame.identity
						if type(vm.Info) == "table" and typeof(vm.Info.RootPartOffset) == "CFrame" then
							base = vm.Info.RootPartOffset
						end
						local combined = base * userViewOffset()
						vm._root_part_offset_override = combined
						vm._root_part_offset_override_inverse = combined:Inverse()
					elseif vm._root_part_offset_override ~= nil then
						vm._root_part_offset_override = nil
						vm._root_part_offset_override_inverse = nil
					end
				end
				if typeof(vm.Model) == "Instance" and vm.Model:IsA("Model") then
					updateCustomViewModel(vm.Model)
					maybeStyleViewModel(vm.Model)
				end
			end
			if typeof(vm.Model) == "Instance" and vm.Model:IsA("Model") then
				ensureGunVisible(vm.Model)
			end
		end)
		table.insert(ears, {
			Disconnect = function()
				pcall(function()
					RunService:UnbindFromRenderStep("__sonata_viewmodel")
				end)
				pcall(function()
					local lp = Players.LocalPlayer
					local char = lp and lp.Character
					if char then
						local old = char:FindFirstChild("__sonata_custom_char")
						if old then
							old:Destroy()
						end
						for _, p in char:GetDescendants() do
							if p:IsA("BasePart") then
								p.LocalTransparencyModifier = 0
							elseif p:IsA("Decal") then
								p.Transparency = 0
							end
						end
					end
				end)
			end,
		} :: any)
	end
	installClientFxRuntime()
	end
	installWorldRuntime()
	end

	local rebuildConfigList: (() -> ())? = nil
	local selectedConfig: string? = nil

	do
	local function installConfigsRuntime()
	local function ensureConfigFolder()
		if hasFsApi("isfolder") then
			if not fsIsfolder(CONFIG_FOLDER) and hasFsApi("makefolder") then
				pcall(fsMakefolder, CONFIG_FOLDER)
			end
		elseif hasFsApi("makefolder") then
			pcall(fsMakefolder, CONFIG_FOLDER)
		end
	end

	local function sanitizeConfigName(name: string): string
		local cleaned = string.gsub(name, "[^%w%-_ ]", "")
		cleaned = string.gsub(cleaned, "^%s+", "")
		cleaned = string.gsub(cleaned, "%s+$", "")
		cleaned = string.gsub(cleaned, "%s+", "_")
		if cleaned == "" then
			return "config"
		end
		return cleaned
	end

	local function configPath(name: string): string
		return CONFIG_FOLDER .. "/" .. sanitizeConfigName(name) .. ".json"
	end

	local AUTOLOAD_PATH = CONFIG_FOLDER .. "/autoload.json"
	local Autoload = {
		enabled = false,
		silent = false,
		name = "",
	}

	local function readAutoloadMeta()
		if not hasFsApi("readfile") then
			return
		end
		local ok, raw = pcall(fsReadfile, AUTOLOAD_PATH)
		if not ok or type(raw) ~= "string" or raw == "" then
			return
		end
		local decodeOk, data = pcall(function()
			return HttpService:JSONDecode(raw)
		end)
		if not decodeOk or type(data) ~= "table" then
			return
		end
		if type(data.enabled) == "boolean" then
			Autoload.enabled = data.enabled
		end
		if type(data.silent) == "boolean" then
			Autoload.silent = data.silent
		end
		if type(data.name) == "string" then
			Autoload.name = sanitizeConfigName(data.name)
			if Autoload.name == "config" and data.name == "" then
				Autoload.name = ""
			end
		end
	end

	local function writeAutoloadMeta(): boolean
		ensureConfigFolder()
		if not hasFsApi("writefile") then
			return false
		end
		local payload = {
			enabled = Autoload.enabled == true,
			silent = Autoload.silent == true,
			name = if type(Autoload.name) == "string" then Autoload.name else "",
		}
		local ok, encoded = pcall(function()
			return HttpService:JSONEncode(payload)
		end)
		if not ok or type(encoded) ~= "string" then
			return false
		end
		local writeOk = pcall(fsWritefile, AUTOLOAD_PATH, encoded)
		return writeOk == true
	end

	local function autoloadLabelText(): string
		local name = Autoload.name
		if type(name) ~= "string" or name == "" then
			return "none"
		end
		return name
	end

	readAutoloadMeta()

	pcall(function()
		for _, name in { "clearqueueonteleport", "clear_queue_on_teleport", "clearqueueteleport" } do
			local fn = execApi(name)
			if typeof(fn) == "function" then
				pcall(fn)
				break
			end
		end
	end)

