	local function restoreClientFx(data: any)
		if type(data) ~= "table" then
			return
		end
		local fx = DrawingBridge.ClientFx
		if type(fx) ~= "table" then
			return
		end
		local function bool(key: string)
			if type(data[key]) == "boolean" then
				fx[key] = data[key]
			end
		end
		local function num(key: string)
			if type(data[key]) == "number" then
				fx[key] = data[key]
			end
		end
		local function str(key: string)
			if type(data[key]) == "string" then
				fx[key] = data[key]
			end
		end
		bool("hitSound"); str("hitSoundName"); num("hitVolume"); num("hitPitch"); bool("muteGameHit")
		bool("killSound"); str("killSoundName"); num("killVolume"); num("killPitch")
		bool("shootSound"); str("shootSoundName"); num("shootVolume"); num("shootPitch"); bool("muteGameShoot")
		if type(data.gunSounds) == "boolean" and data.shootSound == nil then
			fx.shootSound = data.gunSounds
			if data.gunSounds == true and data.muteGameShoot == nil then
				fx.muteGameShoot = true
			end
		end
		if type(data.volume) == "number" and data.shootVolume == nil then
			fx.shootVolume = data.volume
		end
		if type(data.pitch) == "number" and data.shootPitch == nil then
			fx.shootPitch = data.pitch
		end
		bool("tracers"); bool("tracerReplace")
		num("tracerWidth"); num("tracerLifetime"); num("tracerBrightness")
		fx.tracerColor = tableToColor(data.tracerColor, fx.tracerColor)
		bool("ambience"); str("ambienceTrack"); num("ambienceVolume"); num("ambiencePitch"); num("ambienceEcho")
		bool("viewmodel"); bool("animate"); num("x"); num("y"); num("z"); num("pitch"); num("yaw"); num("roll"); num("fovOffset")
		num("yawRange"); num("yawSpeed"); num("rollRange"); num("rollSpeed")
		bool("weaponLight"); num("weaponLightBrightness"); num("weaponLightRange")
		fx.weaponLightColor = tableToColor(data.weaponLightColor, fx.weaponLightColor)
		bool("weaponWireframe"); bool("wireframeOnly"); num("weaponWireThickness"); bool("armWireframe")
		bool("gunScaleOn"); num("gunScale"); num("gunScaleX"); num("gunScaleY"); num("gunScaleZ")
		bool("removeArms"); bool("removeWeapon"); bool("removeCharacter"); bool("removalsEnabled")

		bool("customModel"); str("customSlot"); str("customModelAsset"); str("customModelTarget")
		bool("customModelReplaceWeapon"); str("customModelWeaponAsset"); num("customModelScale")
		num("customModelX"); num("customModelY"); num("customModelZ")
