		num("customLeftHandPitch"); num("customLeftHandYaw"); num("customLeftHandRoll")

		bool("customModelReplaceRightHand"); str("customModelRightHandAsset")
		num("customRightHandScale"); num("customRightHandX"); num("customRightHandY"); num("customRightHandZ")
		num("customRightHandPitch"); num("customRightHandYaw"); num("customRightHandRoll")

		bool("customModelReplaceChar"); str("customModelCharAsset"); str("playerModelName"); str("playerModelLabel")
