	local MENU_SETTING_FLAGS = {
		"ui_theme",
		"ui_accent",
		"togglebind",
		"disablemenumovement",
		"mod_detector",
		"menu_dpi",
		"menu_width",
		"menu_height",
		"keybind_indicator",
		"keybind_indicator_x",
