	local function exportUiSettings(): any
		local lib: any = DrawingBridge.library or drawingLibrary
		local accent = (lib and lib.theme and lib.theme.Accent) or Color3.fromRGB(235, 163, 255)
		local settings: any = {
			accent = colorToTable(accent),
		}
		if type(lib) == "table" then
			if type(lib.currentTheme) == "string" and lib.currentTheme ~= "" then
				settings.ui_theme = lib.currentTheme
			end
			if type(lib.options) == "table" then
				for _, flag in MENU_SETTING_FLAGS do
					local option = lib.options[flag]
					if option then
						if option.class == "toggle" then
							settings[flag] = option.state and 1 or 0
						elseif option.class == "slider" then
							settings[flag] = option.value
						elseif option.class == "bind" then
							settings[flag] = option.bind and option.bind.Name or "none"
						elseif option.class == "color" then
							settings[flag] = {
								option.color.R,
								option.color.G,
								option.color.B,
								option.trans or 0,
							}
						elseif option.class == "list" then
							settings[flag] = option.selected
						elseif option.class == "box" then
							settings[flag] = option.input
						end
					end
				end
			end
			if type(settings.ui_theme) ~= "string" and type(lib.currentTheme) == "string" then
				settings.ui_theme = lib.currentTheme
			end
		end
		return settings
	end

	local function restoreUiSettings(data: any)
		if type(data) ~= "table" then
			return
		end
		local lib: any = DrawingBridge.library or drawingLibrary
		if type(lib) ~= "table" then
			return
		end
		local themeName = data.ui_theme
		if type(themeName) == "string" and themeName ~= "" and type(lib.SelectTheme) == "function" then
			pcall(function()
				lib:SelectTheme(themeName)
			end)
			local themeOpt = lib.options and lib.options.ui_theme
			if themeOpt and type(themeOpt.Select) == "function" then
				pcall(function()
					themeOpt:Select(lib.currentTheme or themeName, true)
				end)
			end
		end
		local accent = tableToColor(data.accent, lib.theme and lib.theme.Accent or Color3.fromRGB(235, 163, 255))
		if type(data.ui_accent) == "table" and type(data.ui_accent[1]) == "number" then
			local a = data.ui_accent
			if (a[1] or 0) <= 1 and (a[2] or 0) <= 1 and (a[3] or 0) <= 1 then
				accent = Color3.new(a[1], a[2] or 0, a[3] or 0)
			else
				accent = Color3.fromRGB(a[1], a[2] or 0, a[3] or 0)
			end
		end
		if lib.theme then
			lib.theme.Accent = accent
		end
		if type(lib.UpdateThemeColors) == "function" then
			pcall(function()
				lib:UpdateThemeColors()
			end)
		elseif type(lib.SetTheme) == "function" then
			pcall(function()
				lib:SetTheme(lib.theme)
			end)
		end
		local accentOpt = lib.options and lib.options.ui_accent
		if accentOpt and type(accentOpt.SetColor) == "function" then
			pcall(function()
				accentOpt:SetColor(accent, true)
			end)
		end
		for _, flag in MENU_SETTING_FLAGS do
			if flag ~= "ui_accent" and flag ~= "ui_theme" then
				local value = data[flag]
				local option = lib.options and lib.options[flag]
				if value ~= nil and option then
					pcall(function()
						if option.class == "toggle" then
							option:SetState(value == 1 or value == true)
						elseif option.class == "slider" and type(value) == "number" then
							option:SetValue(value)
						elseif option.class == "bind" and type(value) == "string" then
							local key = (Enum.KeyCode :: any)[value] or (Enum.UserInputType :: any)[value]
							if key then
								option:SetBind(key)
							end
						elseif option.class == "list" then
							option:Select(value)
						elseif option.class == "box" and type(value) == "string" then
							option:SetInput(value)
						end
					end)
				end
			end
		end
	end

	local function buildConfigPayload(): any
		local skins, wraps, charms, finishers = Cosmetics:export()
		local payload = {
			version = 4,
			name = "sonata",
			savedAt = os.time(),
			skins = skins,
			wraps = wraps,
			charms = charms,
			finishers = finishers,
			esp = if exportEsp then exportEsp() else nil,
			combat = if exportCombat then exportCombat() else nil,
			world = if exportWorldQol then exportWorldQol() else nil,
			client = exportClientFx(),
			spoof = exportSpoof(),
			autoQueue = exportAutoQueue(),
			ui = exportUiSettings(),
		}
		local ok, encoded = pcall(function()
			return HttpService:JSONEncode(payload)
		end)
		if ok and type(encoded) == "string" then
			local decodeOk, clone = pcall(function()
				return HttpService:JSONDecode(encoded)
			end)
			if decodeOk and type(clone) == "table" then
				return clone
			end
		end
		return payload
	end

	local function listConfigs(): { { name: string, savedAt: number? } }
		ensureConfigFolder()
		local names = {}
		if not hasFsApi("listfiles") then
			return names
		end
		local files = fsListfiles(CONFIG_FOLDER)
		for _, path in files do
			if type(path) == "string" then
				local fileName = string.match(path, "([^/\\]+)$") or path
				local stem = string.match(fileName, "^(.*)%.json$")
				if stem and stem ~= "autoload" then
					local savedAt: number? = nil
					if hasFsApi("readfile") then
						local ok, raw = pcall(fsReadfile, configPath(stem))
						if ok and type(raw) == "string" then
							local decodeOk, data = pcall(function()
								return HttpService:JSONDecode(raw)
							end)
							if decodeOk and type(data) == "table" and type(data.savedAt) == "number" then
								savedAt = data.savedAt
							end
						end
					end
					table.insert(names, { name = stem, savedAt = savedAt })
				end
			end
		end
		table.sort(names, function(a, b)
			return a.name < b.name
		end)
		return names
	end

	local loadedConfigName: string? = nil

	local function saveConfig(name: string, opts: any?): (boolean, string)
		if not hasFsApi("writefile") then
			return false, "writefile unavailable"
		end
		ensureConfigFolder()
		local forceNew = type(opts) == "table" and opts.create == true
		local requested = sanitizeConfigName(name)
		local clean = requested
		if forceNew then
			if clean == "" then
				clean = "config"
			end
			if hasFsApi("isfile") or hasFsApi("readfile") then
				local base = clean
				local n = 1
				while true do
					local path = configPath(clean)
					local exists = false
					local isfileFn: any = execApi("isfile")
					if typeof(isfileFn) == "function" then
						local okFile, found = pcall(isfileFn :: (string) -> boolean, path)
						exists = okFile and found == true
					elseif hasFsApi("readfile") then
						local okRead, raw = pcall(fsReadfile, path)
						exists = okRead and type(raw) == "string"
					end
					if not exists then
						break
					end
					n += 1
					clean = base .. "_" .. tostring(n)
				end
			end
		elseif loadedConfigName and loadedConfigName ~= "" then
			if requested == "" or requested == loadedConfigName then
				clean = loadedConfigName
			else
				clean = requested
			end
		elseif clean == "" then
			clean = "config"
		end
		local payload = buildConfigPayload()
		payload.name = clean
		payload.savedAt = os.time()
		local ok, encoded = pcall(function()
			return HttpService:JSONEncode(payload)
		end)
		if not ok or type(encoded) ~= "string" then
			return false, "encode failed"
		end
		local path = configPath(clean)
		local writeOk, writeErr = pcall(fsWritefile, path, encoded)
		if not writeOk then
			return false, tostring(writeErr)
		end
		if hasFsApi("readfile") then
			local readOk, raw = pcall(fsReadfile, path)
			if not readOk or type(raw) ~= "string" then
				return false, "write verify failed"
			end
			local decodeOk, again = pcall(function()
				return HttpService:JSONDecode(raw)
			end)
			if not (decodeOk and type(again) == "table") then
				return false, "write verify failed"
			end
		end
		loadedConfigName = clean
		return true, clean
	end

	local function createConfig(name: string): (boolean, string)
		return saveConfig(name, { create = true })
	end

	local function readConfigFile(name: string): (boolean, string, any?)
		if not hasFsApi("readfile") then
			return false, "readfile unavailable", nil
		end
		local clean = sanitizeConfigName(name)
		local ok, raw = pcall(fsReadfile, configPath(clean))
		if not ok or type(raw) ~= "string" then
			return false, "missing config", nil
		end
		local decodeOk, data = pcall(function()
			return HttpService:JSONDecode(raw)
		end)
		if not decodeOk or type(data) ~= "table" then
			return false, "invalid json", nil
		end
		return true, clean, data
	end

	local function applyConfigData(data: any, clean: string)
		pcall(function()
			Cosmetics:restore(data)
		end)
		if restoreEsp then
			pcall(restoreEsp, data.esp)
		end
		if restoreCombat then
			pcall(restoreCombat, data.combat)
		end
		if restoreWorldQol then
			pcall(restoreWorldQol, data.world)
		end
		pcall(restoreClientFx, data.client)
		pcall(restoreSpoof, data.spoof)
		pcall(restoreAutoQueue, data.autoQueue)
		pcall(restoreUiSettings, data.ui)
		loadedConfigName = clean
		selectedConfig = clean
	end

	local function paintAfterConfigLoad(data: any)
		if rebuildConfigList then
			pcall(rebuildConfigList)
		end
		if refreshCombatUi then
			pcall(refreshCombatUi)
		end
		if DrawingBridge.syncAmbience then
			pcall(DrawingBridge.syncAmbience)
		end
		if DrawingBridge.requestSync then
			pcall(DrawingBridge.requestSync)
		end
		if type(data) == "table" and type(data.ui) == "table" then
			pcall(restoreUiSettings, data.ui)
		end
		if type(data) == "table" and type(data.spoof) == "table" then
			pcall(restoreSpoof, data.spoof)
		end
		if type(data) == "table" and type(data.autoQueue) == "table" then
			pcall(restoreAutoQueue, data.autoQueue)
		end
		if type(data) == "table" and type(data.client) == "table" then
			pcall(restoreClientFx, data.client)
			if DrawingBridge.syncAmbience then
				pcall(DrawingBridge.syncAmbience)
			end
		end
		if DrawingBridge.requestSync then
			pcall(DrawingBridge.requestSync)
		end
	end

	local function loadConfig(name: string, opts: any?): (boolean, string)
		local ok, cleanOrErr, data = readConfigFile(name)
		if not ok or type(data) ~= "table" then
			return false, cleanOrErr
		end
		local clean = cleanOrErr
		local sync = type(opts) == "table" and opts.sync == true
		if sync then
			applyConfigData(data, clean)
			paintAfterConfigLoad(data)
		else
			task.defer(function()
				applyConfigData(data, clean)
				task.defer(function()
					paintAfterConfigLoad(data)
				end)
			end)
		end
		return true, clean
	end

	local function tryAutoloadConfig(): boolean
		readAutoloadMeta()
		if not Autoload.enabled then
			return false
		end
		local name = Autoload.name
		if type(name) ~= "string" or name == "" then
			return false
		end
		local ok = select(1, loadConfig(name, { sync = true }))
		return ok == true
	end
	DrawingBridge.tryAutoloadConfig = tryAutoloadConfig
	DrawingBridge.Autoload = Autoload

	local function deleteConfig(name: string): boolean
		if not hasFsApi("delfile") then
			return false
		end
		return fsDelfile(configPath(sanitizeConfigName(name)))
	end

	do
		local LUA_DIR = "luas"
		local luaPaths: { [string]: string } = {}
		local luaNames: { string } = {}

		local function luaNotify(message: string)
			local lib: any = DrawingBridge.library
			if lib then
				pcall(function()
					lib:SendNotification(message, 3.5)
				end)
			end
		end

		local function shortError(err: any): string
			local text = string.gsub(tostring(err), "^[^:]*:%d+: ", "")
			if #text > 60 then
				text = string.sub(text, 1, 57) .. "..."
			end
			return text
		end

		local function ensureLuaDir(): boolean
			if fsIsfolder(LUA_DIR) then
				return true
			end
			return (pcall(fsMakefolder, LUA_DIR))
		end

		local function refreshLuaNames()
			table.clear(luaPaths)
			table.clear(luaNames)
			if not ensureLuaDir() then
				return
			end
			for _, path in fsListfiles(LUA_DIR) do
				local base = string.match(tostring(path), "([^/\\]+)$") or tostring(path)
				local stem = string.match(base, "^(.+)%.lua$") or string.match(base, "^(.+)%.txt$")
				if stem and not luaPaths[stem] then
					luaPaths[stem] = LUA_DIR .. "/" .. base
					table.insert(luaNames, stem)
				end
			end
			table.sort(luaNames, function(a: string, b: string): boolean
				return string.lower(a) < string.lower(b)
			end)
		end

		local function runLua(name: string, src: string)
			local compile = execApi("loadstring")
			if typeof(compile) ~= "function" then
				luaNotify("loadstring unavailable")
				return
			end
			local ok, fn, err = pcall(compile, src, "=" .. name)
			if not ok or typeof(fn) ~= "function" then
				luaNotify("syntax error · " .. shortError(if ok then err else fn))
				return
			end
			luaNotify("loaded · " .. name)
			task.spawn(function()
				local okRun, runErr = pcall(fn)
				if not okRun then
					luaNotify(name .. " · " .. shortError(runErr))
				end
			end)
		end

		local picked = ""

		local function readPicked(): (string?, string?)
			if picked == "" or not luaPaths[picked] then
				return nil, "no script selected"
			end
			local ok, src = pcall(fsReadfile, luaPaths[picked])
			if not ok or type(src) ~= "string" then
				return nil, "missing · " .. picked
			end
			return src, nil
		end

		DrawingBridge.builders.lua = function(kit: any)
			local tab = kit.tab("extras")
			tab:AddSubTabs({ "lua", "servers" })
			local scripts = tab:AddSection("luas", 1)
			scripts.subTab = "lua"
			refreshLuaNames()
			picked = luaNames[1] or ""
			local listCtl: any = nil
			listCtl = kit.fullList(scripts, "script", function()
				if #luaNames == 0 then
					return { "none" }
				end
				return luaNames
			end, function()
				return if picked ~= "" then picked else "none"
			end, function(value: string)
				if value ~= "none" and luaPaths[value] then
					picked = value
				end
			end)
			kit.buttons(scripts, {
				{
					text = "load",
					callback = function()
						local src, err = readPicked()
						if not src then
							luaNotify(err or "no script selected")
							refreshLuaNames()
							pcall(listCtl.render)
							return
						end
						runLua(picked, src)
					end,
				},
				{
					text = "refresh",
					callback = function()
						refreshLuaNames()
						if picked == "" or not luaPaths[picked] then
							picked = luaNames[1] or ""
						end
						pcall(listCtl.render)
					end,
				},
				{
					text = "delete",
					confirm = true,
					callback = function()
						if picked == "" or not luaPaths[picked] then
							luaNotify("no script selected")
							return
						end
						local name = picked
						pcall(fsDelfile, luaPaths[name])
						refreshLuaNames()
						picked = luaNames[1] or ""
						pcall(listCtl.render)
						luaNotify("deleted · " .. name)
					end,
				},
			})

			local serverRows: { any } = {}
			local serverByLabel: { [string]: any } = {}
			local pickedServer = ""
			local pastedId = ""
			local fetching = false

			local function serverNote(message: string)
				local lib: any = DrawingBridge.library
				if lib then
					pcall(function()
						lib:SendNotification(message, 3.5)
					end)
				end
			end

			local function readClipboard(): string
				local fn = execApi("getclipboard") or execApi("get_clipboard")
				if typeof(fn) ~= "function" then
					local syn = execApi("syn")
					if type(syn) == "table" then
						fn = syn.getclipboard or syn.get_clipboard
					end
				end
				if typeof(fn) ~= "function" then
					return ""
				end
				local ok, text = pcall(fn)
				if ok and type(text) == "string" then
					return text
				end
				return ""
			end

			local function writeClipboard(text: string): boolean
				local fn = execApi("setclipboard") or execApi("set_clipboard")
				if typeof(fn) ~= "function" then
					local syn = execApi("syn")
					if type(syn) == "table" then
						fn = syn.setclipboard or syn.set_clipboard
					end
				end
				if typeof(fn) ~= "function" then
					return false
				end
				return pcall(fn, text)
			end

			local function jobFromText(text: string): string?
				if type(text) ~= "string" then
					return nil
				end
				local id = string.match(text, "[%x]+%-[%x]+%-[%x]+%-[%x]+%-[%x]+")
				if type(id) == "string" and #id >= 32 then
					return id
				end
				local trimmed = string.gsub(text, "%s+", "")
				if #trimmed >= 16 then
					return trimmed
				end
				return nil
			end

			local function joinJob(jobId: string)
				if jobId == "" then
					serverNote("no server id")
					return
				end
				if jobId == game.JobId then
					serverNote("already in this server")
					return
				end
				local teleport = getService("TeleportService")
				local ok = pcall(function()
					teleport:TeleportToPlaceInstance(game.PlaceId, jobId, Players.LocalPlayer)
				end)
				if ok then
					serverNote("joining server")
				else
					serverNote("join failed")
				end
			end

			local function fetchPublicServers(): { any }
				local rows = {}
				local used: { [string]: boolean } = {}
				local cursor = ""
				local mine = game.JobId
				for _ = 1, 3 do
					local suffix = ""
					if cursor ~= "" then
						local encoded = cursor
						pcall(function()
							encoded = HttpService:UrlEncode(cursor)
						end)
						suffix = "&cursor=" .. encoded
					end
					local url = string.format("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Desc&limit=100%s", game.PlaceId, suffix)
					local ok, body = pcall(function()
						return game:HttpGet(url)
					end)
					if not ok or type(body) ~= "string" then
						break
					end
					local okDecode, page = pcall(function()
						return HttpService:JSONDecode(body)
					end)
					if not okDecode or type(page) ~= "table" or type(page.data) ~= "table" then
						break
					end
					for _, entry in page.data do
						local id = if type(entry) == "table" then entry.id else nil
						if type(id) == "string" and id ~= "" and id ~= mine and not used[id] then
							used[id] = true
							local playing = tonumber(entry.playing) or 0
							local maxp = tonumber(entry.maxPlayers) or 0
							local ping = tonumber(entry.ping)
							local pingText = if ping then string.format(" · %dms", math.floor(ping + 0.5)) else ""
							local base = string.format("%d/%d%s", playing, maxp, pingText)
							local label = base
							local n = 2
							while used["label:" .. label] do
								label = base .. " · " .. tostring(n)
								n += 1
							end
							used["label:" .. label] = true
							table.insert(rows, { id = id, playing = playing, label = label })
						end
					end
					cursor = if type(page.nextPageCursor) == "string" then page.nextPageCursor else ""
					if cursor == "" then
						break
					end
				end
				table.sort(rows, function(a, b)
					return a.playing > b.playing
				end)
				return rows
			end

			local listCtlServers: any = nil
			local function showServers(rows: { any })
				table.clear(serverRows)
				table.clear(serverByLabel)
				for _, row in rows do
					table.insert(serverRows, row)
					serverByLabel[row.label] = row
				end
				if not serverByLabel[pickedServer] then
					pickedServer = if serverRows[1] then serverRows[1].label else ""
				end
				if listCtlServers then
					pcall(listCtlServers.render)
				end
			end

			local function refreshServers()
				if fetching then
					return
				end
				fetching = true
				serverNote("loading servers")
				task.spawn(function()
					local ok, rows = pcall(fetchPublicServers)
					fetching = false
					if not ok or type(rows) ~= "table" then
						serverNote("server list failed")
						return
					end
					showServers(rows)
					serverNote(string.format("servers · %d", #rows))
				end)
			end

			local function randomJob(high: boolean): string?
				if #serverRows == 0 then
					return nil
				end
				local sorted = table.clone(serverRows)
				table.sort(sorted, function(a, b)
					if high then
						return a.playing > b.playing
					end
					return a.playing < b.playing
				end)
				local count = math.clamp(math.ceil(#sorted * 0.25), 1, #sorted)
				return sorted[math.random(1, count)].id
			end

			local browser = tab:AddSection("servers", 1)
			browser.subTab = "servers"
			listCtlServers = kit.fullList(browser, "server", function()
				if #serverRows == 0 then
					return { "none" }
				end
				local names = {}
				for _, row in serverRows do
					table.insert(names, row.label)
				end
				return names
			end, function()
				return if pickedServer ~= "" then pickedServer else "none"
			end, function(value: string)
				if value ~= "none" and serverByLabel[value] then
					pickedServer = value
				end
			end)
			kit.buttons(browser, {
				{
					text = "refresh",
					callback = refreshServers,
				},
				{
					text = "join",
					callback = function()
						local row = serverByLabel[pickedServer]
						if not row then
							serverNote("no server selected")
							return
						end
						joinJob(row.id)
					end,
				},
			})
			kit.buttons(browser, {
				{
					text = "random high",
					callback = function()
						local id = randomJob(true)
						if not id then
							serverNote("no servers")
							return
						end
						joinJob(id)
					end,
				},
				{
					text = "random low",
					callback = function()
						local id = randomJob(false)
						if not id then
							serverNote("no servers")
							return
						end
						joinJob(id)
					end,
				},
			})

			local share = tab:AddSection("share", 2)
			share.subTab = "servers"
			local idLine = kit.text(share, "server id")
			local function paintShare()
				local id = game.JobId
				local shown = if id ~= "" then id else "unavailable"
				pcall(function()
					idLine:SetText("id · " .. shown)
				end)
			end
			paintShare()
			local idBox = kit.box(share, "server id", function()
				return pastedId
			end, function(value: string)
				pastedId = value
			end)
			kit.buttons(share, {
				{
					text = "copy id",
					callback = function()
						local id = game.JobId
						if id == "" then
							serverNote("no server id")
							return
						end
						pastedId = id
						pcall(function()
							idBox:SetInput(id, true)
						end)
						if writeClipboard(id) then
							serverNote("copied server id")
						else
							serverNote("copy failed")
						end
					end,
				},
				{
					text = "join copied",
					callback = function()
						local id = jobFromText(pastedId) or jobFromText(readClipboard())
						if not id then
							serverNote("clipboard has no server id")
							return
						end
						pastedId = id
						pcall(function()
							idBox:SetInput(id, true)
						end)
						joinJob(id)
					end,
				},
			})
			task.defer(refreshServers)
		end
	end

	do
		local GroupService = getService("GroupService")
		local STAFF_WORDS = { "mod", "admin", "staff", "dev", "owner", "founder", "manager", "support", "contractor" }
		local detector: any = {
			groupId = nil,
			staffRank = 200,
			staff = {},
			friends = {},
			ranks = {},
			rolesReady = false,
			loading = false,
			kicked = false,
			duelCtrl = nil,
		}

		local function detectorOn(): boolean
			local lib: any = DrawingBridge.library
			return SESSION.alive and type(lib) == "table" and type(lib.flags) == "table" and lib.flags.mod_detector == true
		end

		local function playerKey(player: any): number?
			if typeof(player) ~= "Instance" then
				return nil
			end
			local ok, id = pcall(function()
				return player.UserId
			end)
			if ok and type(id) == "number" then
				return id
			end
			return nil
		end

		local function getJson(url: string): any
			local ok, body = pcall(function()
				return game:HttpGet(url)
			end)
			if not ok or type(body) ~= "string" then
				return nil
			end
			local okDecode, data = pcall(function()
				return HttpService:JSONDecode(body)
			end)
			return if okDecode then data else nil
		end

		local function isStaffRole(name: string): boolean
			local lower = string.lower(name)
			for _, word in STAFF_WORDS do
				if string.find(lower, word, 1, true) then
					return true
				end
			end
			return false
		end

		local function loadRoleMembers(gid: number, roleId: number)
			local cursor = ""
			for _ = 1, 10 do
				local suffix = if cursor ~= "" then "&cursor=" .. cursor else ""
				local page = getJson(string.format("https://groups.roblox.com/v1/groups/%d/roles/%d/users?limit=100&sortOrder=Asc%s", gid, roleId, suffix))
				if type(page) ~= "table" or type(page.data) ~= "table" then
					return
				end
				for _, user in page.data do
					local id = tonumber(user.userId)
					if id then
						detector.staff[id] = tostring(user.username or user.displayName or id)
					end
				end
				cursor = page.nextPageCursor
				if type(cursor) ~= "string" or cursor == "" then
					return
				end
			end
		end

		local function loadStaff()
			if detector.rolesReady or detector.loading then
				return
			end
			detector.loading = true
			if game.CreatorType == Enum.CreatorType.Group then
				detector.groupId = game.CreatorId
			end
			local gid = detector.groupId
			if gid then
				local payload = getJson(string.format("https://groups.roblox.com/v1/groups/%d/roles", gid))
				local roles = if type(payload) == "table" then payload.roles else nil
				if type(roles) ~= "table" then
					local ok, info = pcall(GroupService.GetGroupInfoAsync, GroupService, gid)
					roles = if ok and type(info) == "table" then info.Roles else nil
				end
				local lowest = math.huge
				for _, role in (if type(roles) == "table" then roles else {}) do
					local name = tostring(role.name or role.Name or "")
					local rank = tonumber(role.rank or role.Rank) or 0
					if rank > 1 and isStaffRole(name) then
						lowest = math.min(lowest, rank)
						local roleId = tonumber(role.id)
						if roleId then
							loadRoleMembers(gid, roleId)
						end
					end
				end
				if lowest < math.huge then
					detector.staffRank = lowest
				end
			end
			detector.rolesReady = true
			detector.loading = false
		end

		local function rankOf(player: Player): number
			local id = playerKey(player)
			if not id then
				return 0
			end
			local cached = detector.ranks[id]
			if cached then
				return cached
			end
			local rank = 0
			local attr = player:GetAttribute("GroupRank")
			if type(attr) == "number" then
				rank = attr
			elseif detector.groupId then
				local ok, value = pcall((player :: any).GetRankInGroup, player, detector.groupId)
				if ok and type(value) == "number" then
					rank = value
				end
			end
			detector.ranks[id] = rank
			return rank
		end

		local function isModerator(player: Player): boolean
			local id = playerKey(player)
			return (id ~= nil and detector.staff[id] ~= nil)
				or rankOf(player) >= detector.staffRank
				or player:GetAttribute("IsRobloxEmployee") == true
		end

		local function friendOfMod(player: Player): string?
			if next(detector.staff) == nil then
				return nil
			end
			local id = playerKey(player)
			if not id then
				return nil
			end
			local set = detector.friends[id]
			if set == nil then
				set = {}
				local data = getJson(string.format("https://friends.roblox.com/v1/users/%d/friends", id))
				if type(data) == "table" and type(data.data) == "table" then
					for _, friend in data.data do
						local friendId = tonumber(friend.id)
						if friendId then
							set[friendId] = true
						end
					end
				end
				detector.friends[id] = set
			end
			for friendId in set do
				local name = detector.staff[friendId]
				if name then
					return name
				end
			end
			return nil
		end

		local function inMyMatch(player: Player): boolean
			local lp = Players.LocalPlayer
			if not detector.duelCtrl then
				pcall(function()
					detector.duelCtrl = require(lp.PlayerScripts.Controllers.DuelController)
				end)
			end
			local ctrl = detector.duelCtrl
			if type(ctrl) ~= "table" or type(ctrl.GetDuel) ~= "function" then
				return false
			end
			local okMine, mine = pcall(ctrl.GetDuel, ctrl, lp)
			if not okMine or mine == nil then
				return false
			end
			local okTheirs, theirs = pcall(ctrl.GetDuel, ctrl, player)
			return okTheirs and theirs == mine
		end

		local function kickFor(player: Player, modName: string, viaFriend: boolean)
			if detector.kicked then
				return
			end
			detector.kicked = true
			local where = if inMyMatch(player) then "was in your match" else "was in the lobby"
			local reason = if viaFriend
				then string.format("friend of moderator %s (@%s) %s", modName, player.Name, where)
				else string.format("moderator %s (@%s) %s", player.DisplayName, player.Name, where)
			pcall(function()
				Players.LocalPlayer:Kick("[sonata] mod detector: " .. reason)
			end)
		end

		local function scanServer()
			if not detectorOn() or detector.kicked then
				return
			end
			loadStaff()
			local lp = Players.LocalPlayer
			local others = {}
			for _, player in Players:GetPlayers() do
				if player ~= lp then
					table.insert(others, player)
				end
			end
			for _, player in others do
				if not detectorOn() then
					return
				end
				if isModerator(player) then
					kickFor(player, player.Name, false)
					return
				end
			end
			for _, player in others do
				if not detectorOn() then
					return
				end
				local modName = friendOfMod(player)
				if modName then
					kickFor(player, modName, true)
					return
				end
			end
		end

		local scanning = false
		local function requestScan()
			if scanning then
				return
			end
			scanning = true
			task.spawn(function()
				pcall(scanServer)
				scanning = false
			end)
		end

		table.insert(ears, Players.PlayerAdded:Connect(function()
			task.delay(1, function()
				if detectorOn() then
					requestScan()
				end
			end)
		end))
		table.insert(ears, Players.PlayerRemoving:Connect(function(player)
			local id = playerKey(player)
			if not id then
				return
			end
			detector.ranks[id] = nil
			detector.friends[id] = nil
		end))
		task.spawn(function()
			while SESSION.alive do
				if detectorOn() then
					requestScan()
				end
				task.wait(4)
			end
		end)
	end

	DrawingBridge.builders.configs = function(kit: any)
		local settingsTab = DrawingBridge.settingsTab
		if not settingsTab then
			warn("settings tab is on vacation")
			return
		end
		local credits = settingsTab:AddSection("credits", 1, 999)
		credits.span = 2
		pcall(function()
			credits:AddText({ text = "ui/esp - skrill" })
			credits:AddText({ text = "manipulation/silent aim logic - koikyoto" })
			credits:AddText({ text = "main core loop/ragebot logic - xhafo" })
		end)
		pcall(function()
			settingsTab:UpdateSections()
		end)

		local section = settingsTab:AddSection("configs", 2)
		local nameText = loadedConfigName or selectedConfig or "default"
		local nameBox: any = nil
		local list: any = nil

		local function notify(message: string, _good: boolean?)
			local lib: any = DrawingBridge.library
			if lib then
				pcall(function()
					lib:SendNotification(message, 3.5)
				end)
			end
		end

		local function refreshConfigs()
			if not list then
				return
			end
			local names: { [string]: boolean } = {}
			list:ClearValues()
			for _, entry in listConfigs() do
				list:AddValue(entry.name)
				names[entry.name] = true
			end
			if selectedConfig and not names[selectedConfig] then
				selectedConfig = nil
			end
			if not selectedConfig and loadedConfigName and names[loadedConfigName] then
				selectedConfig = loadedConfigName
			end
			if selectedConfig then
				list:Select(selectedConfig, true)
			end
			if loadedConfigName and nameBox then
				nameText = loadedConfigName
				nameBox:SetInput(nameText, true)
			end
		end

		nameBox = kit.box(section, "Config name", function()
			return nameText
		end, function(value: string)
			nameText = value
		end)

		list = section:AddList({
			text = "Saved configs",
			values = {},
			selected = selectedConfig or loadedConfigName or "none",
			callback = function(value: any)
				if type(value) == "table" then
					value = value[1]
				end
				if type(value) == "string" then
					selectedConfig = value
					nameText = value
					if nameBox then
						nameBox:SetInput(value, true)
					end
				end
			end,
		})

		kit.buttons(section, {
			{
				text = "Create",
				callback = function()
					local target = sanitizeConfigName(nameText)
					local ok, result = createConfig(target)
					if ok then
						selectedConfig = result
						nameText = result
						if nameBox then
							nameBox:SetInput(result, true)
						end
						refreshConfigs()
						notify("created · " .. result)
					else
						notify("create failed · " .. tostring(result))
					end
				end,
			},
			{
				text = "Save",
				callback = function()
					local target = sanitizeConfigName(nameText)
					local ok, result = saveConfig(target)
					if ok then
						selectedConfig = result
						nameText = result
						refreshConfigs()
						notify("saved · " .. result)
					else
						notify("save failed · " .. tostring(result))
					end
				end,
			},
		})
		kit.buttons(section, {
			{
				text = "Load",
				callback = function()
					local target = selectedConfig or nameText
					local ok, result = loadConfig(target)
					if ok then
						notify("loaded · " .. result)
					else
						notify("load failed · " .. tostring(result))
					end
				end,
			},
			{
				text = "Delete",
				confirm = true,
				callback = function()
					local target = selectedConfig or nameText
					if deleteConfig(target) then
						if loadedConfigName == sanitizeConfigName(target) then
							loadedConfigName = nil
						end
						selectedConfig = nil
						refreshConfigs()
						notify("deleted · " .. tostring(sanitizeConfigName(target)))
					else
						notify("delete failed")
					end
				end,
			},
		})
		kit.buttons(section, {
			{
				text = "Refresh",
				callback = function()
					refreshConfigs()
				end,
			},
		})

		kit.separator(section, "autoload")
		local autoloadStatus = kit.text(section, autoloadLabelText())
		local function refreshAutoloadUi()
			if autoloadStatus and type(autoloadStatus.SetText) == "function" then
				pcall(function()
					autoloadStatus:SetText(autoloadLabelText())
				end)
			end
		end
		local function touchAutoload()
			writeAutoloadMeta()
			refreshAutoloadUi()
			if DrawingBridge.requestSync then
				pcall(DrawingBridge.requestSync)
			end
		end
		kit.flag(section, "autoload", Autoload, "enabled", nil, function(on: boolean)
			if on == true then
				local target = loadedConfigName or selectedConfig or sanitizeConfigName(nameText)
				if type(target) == "string" and target ~= "" and (Autoload.name == nil or Autoload.name == "") then
					Autoload.name = sanitizeConfigName(target)
				end
			end
			touchAutoload()
		end)
		kit.flag(section, "silent load", Autoload, "silent", nil, function()
			touchAutoload()
		end)
		kit.buttons(section, {
			{
				text = "set as autoload",
				callback = function()
					local target = loadedConfigName or selectedConfig or sanitizeConfigName(nameText)
					if type(target) ~= "string" or target == "" then
						notify("autoload · no config selected")
						return
					end
					local clean = sanitizeConfigName(target)
					local exists = false
					local path = configPath(clean)
					local isfileFn: any = execApi("isfile")
					if typeof(isfileFn) == "function" then
						local okFile, found = pcall(isfileFn :: (string) -> boolean, path)
						exists = okFile and found == true
					elseif hasFsApi("readfile") then
						local okRead, raw = pcall(fsReadfile, path)
						exists = okRead and type(raw) == "string"
					end
					if not exists then
						notify("autoload · config missing · save it first")
						return
					end
					Autoload.name = clean
					Autoload.enabled = true
					touchAutoload()
					notify("autoload · " .. clean)
				end,
			},
			{
				text = "remove autoload",
				callback = function()
					Autoload.enabled = false
					Autoload.name = ""
					touchAutoload()
					notify("autoload cleared")
				end,
			},
		})

		rebuildConfigList = function()
			refreshConfigs()
			refreshAutoloadUi()
		end
		refreshConfigs()
		refreshAutoloadUi()
	end

	end
	installConfigsRuntime()
	end

	do
	local open = true

	local function currentOpen(): boolean
		local lib: any = drawingLibrary
		if drawingActive and lib then
			return lib.open == true
		end
		return open
	end

	local function setOpen(nextOpen: boolean)
		open = nextOpen
		local lib: any = drawingLibrary
		if drawingActive and lib then
			pcall(function()
				lib:SetOpen(nextOpen)
			end)
		end
	end

	table.insert(ears, UserInputService.InputBegan:Connect(function(input: InputObject)
		if input.KeyCode == Enum.KeyCode.RightShift then
			setOpen(not currentOpen())
		end
	end))

	local function fullUnload()
		if not SESSION.alive then
			return
		end
		pcall(function()
			Cosmetics:clearAll()
		end)
		local states = { DrawingBridge.ClientFx, DrawingBridge.Esp, DrawingBridge.UtilEsp, DrawingBridge.Qol }
		for _, state in DrawingBridge.featureStates or {} do
			table.insert(states, state)
		end
		for _, state in states do
			if type(state) == "table" then
				for key, value in state do
					if value == true then
						state[key] = false
					end
				end
			end
		end
		for _, name in { "shutdownRagebot", "revertSpoof", "revertWorld", "nudgeExploits", "syncAmbience" } do
			local fn = DrawingBridge[name]
			if type(fn) == "function" then
				pcall(fn)
			end
		end
		for _ = 1, 3 do
			RunService.Heartbeat:Wait()
		end
		SESSION.alive = false
		for _, connection in ears do
			pcall(function()
				connection:Disconnect()
			end)
		end
		table.clear(ears)
		for _, gui in SESSION.guis do
			pcall(function()
				gui:Destroy()
			end)
		end
		table.clear(SESSION.guis)
		for _, path in { { SoundService, "sonata_fx_sounds" }, { SoundService, "sonata_ambience" }, { Workspace, "sonata_tracers" }, { Workspace, "sonata_weather" } } do
			local inst = (path[1] :: Instance):FindFirstChild(path[2])
			if inst then
				pcall(function()
					inst:Destroy()
				end)
			end
		end
		local env = fsGetgenv()
		if type(env) == "table" then
			local stale = {}
			for key in env do
				if type(key) == "string" and string.sub(key, 1, 8) == "__sonata" then
					table.insert(stale, key)
				end
			end
			for _, key in stale do
				env[key] = nil
			end
			env.Sonata = nil
		end
	end

	local window: Window
	window = {
		visible = function(_self: Window): boolean
			return currentOpen()
		end,
		setVisible = function(_self: Window, nextOpen: boolean)
			setOpen(nextOpen)
		end,
		toggle = function(_self: Window)
			setOpen(not currentOpen())
		end,
		destroy = function(_self: Window)
			local lib: any = drawingLibrary
			if drawingActive and lib then
				drawingActive = false
				pcall(function()
					lib:Unload()
				end)
			end
			fullUnload()
		end,
	}

	local function installDrawingMenu()
		local library: any = drawingLibrary
		if not library then
			return
		end

		DrawingBridge.library = library
		local okInit, _initErr = pcall(function()
			library:init()
		end)
		if not okInit then
			warn("bro is this kewl ass ui gonna load?")
			drawingActive = false
			return
		end
		if type(library.NewWindow) ~= "function" then
			warn("ui forgot how windows work")
			drawingActive = false
			return
		end
		local okWindow, windowOrErr = pcall(function()
			return library.NewWindow({
				title = spec.title,
				size = UDim2.new(0, 600, 0, 499),
				position = UDim2.new(0, 250, 0, 120),
			})
		end)
		if not okWindow or type(windowOrErr) ~= "table" then
			warn("menu said nah and left")
			drawingActive = false
			return
		end
		DrawingBridge.menu = windowOrErr

		for _, name in { "legit", "rage", "move", "visuals", "world", "items", "misc", "extras" } do
			pcall(DKit.tab, name)
		end
		local activeBuilders = if _G.AtomwareLiteMode == true then { "combat", "esp", "world", "configs" } else { "combat", "esp", "world", "cosmetics", "lua", "configs" }
		for _, key in activeBuilders do
			local builder = DrawingBridge.builders[key]
			if builder then
				local okBuild, _buildErr = pcall(builder, DKit)
				if not okBuild then
					warn(key .. " section faceplanted: " .. tostring(_buildErr))
				end
			end
		end

		pcall(function()
			DrawingBridge.menu:UpdateTabs()
		end)

		local okSettings, _settingsErr = pcall(function()
			DrawingBridge.settingsTab = library:CreateSettingsTab(DrawingBridge.menu)
			local startTheme = library.currentTheme or "Default"
			if type(library.SelectTheme) == "function" then
				library:SelectTheme(startTheme)
			elseif library.themes and library.themes[1] then
				library:SetTheme(library.themes[1].theme)
			end
			local themeOpt = library.options and library.options.ui_theme
			if themeOpt and type(themeOpt.Select) == "function" then
				themeOpt:Select(library.currentTheme or "Default", true)
			end
		end)
		if not okSettings then
			warn("settings tab tripped")
		end
		do
			local builder = DrawingBridge.builders.configs
			if builder then
				local okBuild, _buildErr = pcall(builder, DKit)
				if not okBuild then
					warn("configs section faceplanted")
				end
			end
		end

		pcall(function()
			library.unloaded:Connect(function()
				drawingActive = false
				open = false
				task.spawn(fullUnload)
			end)
		end)

		drawingActive = true
		open = library.open == true

		pcall(function()
			local loaded = false
			if DrawingBridge.tryAutoloadConfig then
				loaded = DrawingBridge.tryAutoloadConfig() == true
			end
			local meta = DrawingBridge.Autoload
			local silent = type(meta) == "table" and meta.enabled == true and meta.silent == true
			if silent then
				pcall(function()
					library:SetOpen(false)
				end)
				open = false
			elseif loaded then
				open = library.open == true
			end
		end)

		local env = fsGetgenv()
		if env then
			local sonata = env.Sonata
			if type(sonata) == "table" then
				sonata.library = library
				sonata.menu = DrawingBridge.menu
				sonata.bridge = DrawingBridge
			end
			env.__sonata_unload = fullUnload
		end
	end

	local okInstall, _installErr = pcall(installDrawingMenu)
	if not okInstall then
		warn("the whole ui fell down the stairs")
	end

	return window
	end
end

do
	local env = fsGetgenv()
	if env then
		env.Sonata = {
			cosmetics = Cosmetics,
			library = nil,
			menu = nil,
			bridge = nil,
		}
	end
end

Window({ title = "sonata" })

--//==================================================
--// ATOMWARE RIVALS - UNIVERSAL UI EVENT ADAPTER
--// Supports PC UI (main_ui.lua), Mobile UI (mobile_ui.lua),
--// and Mobile Lite UI (mobile_lite_ui.lua)
--//==================================================
do
	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")
	local Lighting = game:GetService("Lighting")
	local LocalPlayer = Players.LocalPlayer

	local bridge: any = DrawingBridge
	local Silent: any = bridge and bridge.Silent
	local Aim: any = bridge and bridge.Aim
	local Trigger: any = bridge and bridge.Trigger
	local Movement: any = bridge and bridge.Movement
	local Exploits: any = bridge and bridge.Exploits
	local Esp: any = bridge and bridge.Esp

	-- Hitbox Expander Runtime Loop
	_G.__HitboxExpanderEnabled = false
	_G.__HitboxSize = 8
	_G.__HitboxTargetPart = "Head"
	_G.__HitboxTransparency = 0.5
	local originalSizes = {}

	RunService.Heartbeat:Connect(function()
		if not _G.__HitboxExpanderEnabled then return end
		local targetPartName = _G.__HitboxTargetPart or "Head"
		local size = _G.__HitboxSize or 8
		local trans = _G.__HitboxTransparency or 0.5
		for _, player in ipairs(Players:GetPlayers()) do
			if player ~= LocalPlayer and player.Character then
				local part = player.Character:FindFirstChild(targetPartName)
				if part and part:IsA("BasePart") then
					if not originalSizes[part] then
						originalSizes[part] = part.Size
					end
					part.Size = Vector3.new(size, size, size)
					part.Transparency = trans
					part.CanCollide = false
				end
			end
		end
	end)

	local function resetHitboxes()
		for part, size in pairs(originalSizes) do
			if part and part.Parent then
				pcall(function()
					part.Size = size
					part.Transparency = 0
				end)
			end
		end
		table.clear(originalSizes)
	end

	-- Connect UI Events across all PC & Mobile UI Frameworks
	if _G.OnToggle then
		-- =========================================================
		-- COMBAT: SILENT AIM
		-- =========================================================
		_G.OnToggle("Enable Silent Aim", function(v)
			if Silent then Silent.enabled = (v == true) end
		end)
		_G.OnToggle("Show Silent FOV Circle", function(v)
			if Silent then Silent.drawFov = (v == true) end
		end)
		_G.OnToggle("Silent Team Check", function(v)
			if Silent then Silent.teamCheck = (v == true) end
		end)
		_G.OnToggle("Silent Wall Check", function(v)
			if Silent then Silent.visibleCheck = (v == true) end
		end)
		_G.OnSlider("Silent Aim Hit Chance", function(v)
			if Silent then Silent.accuracy = tonumber(v) or 100 end
		end)
		_G.OnSlider("Silent Aim FOV", function(v)
			if Silent then Silent.fov = tonumber(v) or 120 end
		end)
		_G.OnDropdown("Silent Target Part", function(v)
			if Silent then
				if v == "Head" or v == "Torso" then
					Silent.hitPart = v
				elseif v == "Closest" then
					Silent.hitPart = "Head"
				end
			end
		end)
		if _G.OnColorPicker then
			_G.OnColorPicker("Silent FOV Color", function(c3)
				if Silent then Silent.fovColor1 = c3 end
			end)
		end

		-- =========================================================
		-- COMBAT: AIMBOT
		-- =========================================================
		_G.OnToggle("Enable Aimbot", function(v)
			if Aim then Aim.enabled = (v == true) end
		end)
		_G.OnToggle("Show Aimbot FOV Circle", function(v)
			if Aim then Aim.drawFov = (v == true) end
		end)
		_G.OnToggle("Aimbot Team Check", function(v)
			if Aim then Aim.teamCheck = (v == true) end
		end)
		_G.OnToggle("Aimbot Wall Check", function(v)
			if Aim then Aim.visibleCheck = (v == true) end
		end)
		_G.OnSlider("Aimbot Smoothness", function(v)
			if Aim then Aim.smooth = tonumber(v) or 4 end
		end)
		_G.OnSlider("Aimbot FOV", function(v)
			if Aim then Aim.fov = tonumber(v) or 140 end
		end)
		_G.OnDropdown("Aimbot Mode", function(v)
			if Aim then
				if v == "Always On" or v == "Always" then
					Aim.keyName = "None"
				else
					Aim.keyName = v
				end
			end
		end)
		_G.OnDropdown("Aimbot Target Part", function(v)
			if Aim then
				Aim.hitboxes = {
					Head = (v == "Head" or v == "Closest"),
					Torso = (v == "Torso"),
					UpperTorso = (v == "Torso"),
					LowerTorso = (v == "Torso"),
					HumanoidRootPart = false,
				}
			end
		end)
		if _G.OnKeybind then
			_G.OnKeybind("Aimbot Key", function(k)
				if Aim then Aim.keyName = tostring(k) end
			end)
		end
		if _G.OnColorPicker then
			_G.OnColorPicker("Aimbot FOV Color", function(c3)
				if Aim then Aim.fovColor1 = c3 end
			end)
		end

		-- =========================================================
		-- COMBAT: TRIGGERBOT
		-- =========================================================
		_G.OnToggle("Enable Triggerbot", function(v)
			if Trigger then Trigger.enabled = (v == true) end
		end)
		_G.OnSlider("Triggerbot Delay", function(v)
			if Trigger then Trigger.delay = (tonumber(v) or 50) / 1000 end
		end)
		_G.OnToggle("Triggerbot Team Check", function(v)
			if Trigger then Trigger.teamCheck = (v == true) end
		end)
		_G.OnToggle("Triggerbot Headshot Only", function(v)
			if Trigger then Trigger.headOnly = (v == true) end
		end)

		-- =========================================================
		-- COMBAT: HITBOX EXPANDER
		-- =========================================================
		_G.OnToggle("Enable Hitbox Expander", function(v)
			_G.__HitboxExpanderEnabled = (v == true)
			if not v then resetHitboxes() end
		end)
		_G.OnSlider("Hitbox Size", function(v)
			_G.__HitboxSize = tonumber(v) or 8
		end)
		_G.OnSlider("Hitbox Transparency", function(v)
			_G.__HitboxTransparency = (tonumber(v) or 50) / 100
		end)
		_G.OnDropdown("Hitbox Target", function(v)
			_G.__HitboxTargetPart = v or "Head"
		end)
		_G.OnDropdown("Hitbox Part", function(v)
			_G.__HitboxTargetPart = v or "Head"
		end)

		-- =========================================================
		-- VISUALS: ESP
		-- =========================================================
		_G.OnToggle("Enable ESP", function(v)
			if Esp then Esp.master = (v == true) end
		end)
		_G.OnToggle("Box ESP", function(v)
			if Esp then Esp.box = (v == true) end
		end)
		_G.OnToggle("Box Fill", function(v)
			if Esp then Esp.boxFill = (v == true) end
		end)
		_G.OnToggle("Health Bar", function(v)
			if Esp then Esp.health = (v == true) end
		end)
		_G.OnToggle("Name ESP", function(v)
			if Esp then Esp.names = (v == true) end
		end)
		_G.OnToggle("Distance ESP", function(v)
			if Esp then Esp.distance = (v == true) end
		end)
		_G.OnToggle("Weapon ESP", function(v)
			if Esp then Esp.weapon = (v == true) end
		end)
		_G.OnToggle("Skeleton ESP", function(v)
			if Esp then Esp.skeleton = (v == true) end
		end)
		_G.OnToggle("Snaplines", function(v)
			if Esp then Esp.snaplines = (v == true) end
		end)
		_G.OnToggle("Chams / Highlights", function(v)
			if Esp then Esp.chams = (v == true) end
		end)
		_G.OnToggle("Team Check", function(v)
			if Esp then Esp.enemyOnly = (v == true) end
		end)
		_G.OnSlider("Max ESP Distance", function(v)
			if Esp then Esp.maxDistance = tonumber(v) or 1000 end
		end)
		if _G.OnColorPicker then
			_G.OnColorPicker("Box Color", function(c3) if Esp then Esp.boxColor = c3 end end)
			_G.OnColorPicker("Box Fill Color", function(c3) if Esp then Esp.boxFillColor = c3 end end)
			_G.OnColorPicker("Skeleton Color", function(c3) if Esp then Esp.skeletonColor = c3 end end)
			_G.OnColorPicker("Snapline Color", function(c3) if Esp then Esp.snaplinesColor = c3 end end)
			_G.OnColorPicker("Text Color", function(c3)
				if Esp then
					Esp.namesColor = c3
					Esp.distanceColor = c3
					Esp.weaponColor = c3
				end
			end)
		end

		-- =========================================================
		-- WORLD & LIGHTING
		-- =========================================================
		_G.OnToggle("Fullbright", function(v)
			if v then
				Lighting.Brightness = 2
				Lighting.ClockTime = 14
				Lighting.GlobalShadows = false
				Lighting.OutdoorAmbient = Color3.fromRGB(128, 128, 128)
			end
		end)
		_G.OnSlider("Brightness", function(v)
			Lighting.Brightness = tonumber(v) or 2
		end)
		_G.OnToggle("Remove Shadows", function(v)
			Lighting.GlobalShadows = not v
		end)
		_G.OnToggle("Clear Atmosphere / Fog", function(v)
			if v then
				Lighting.FogEnd = 100000
				for _, child in ipairs(Lighting:GetChildren()) do
					if child:IsA("Atmosphere") or child:IsA("BloomEffect") or child:IsA("ColorCorrectionEffect") then
						child.Enabled = false
					end
				end
			end
		end)
		_G.OnSlider("World Time of Day", function(v)
			Lighting.ClockTime = tonumber(v) or 14
		end)
		_G.OnToggle("Custom Camera FOV", function(v)
			_G.__CustomFovEnabled = (v == true)
			if not v and workspace.CurrentCamera then
				workspace.CurrentCamera.FieldOfView = 70
			end
		end)
		_G.OnSlider("Camera FOV", function(v)
			_G.__CustomFovVal = tonumber(v) or 90
			if _G.__CustomFovEnabled and workspace.CurrentCamera then
				workspace.CurrentCamera.FieldOfView = _G.__CustomFovVal
			end
		end)

		-- =========================================================
		-- PLAYER & MOVEMENT
		-- =========================================================
		_G.OnToggle("Speed Multiplier", function(v)
			if Movement then Movement.speed = (v == true) end
		end)
		_G.OnSlider("WalkSpeed", function(v)
			if Movement then Movement.walkMulti = math.clamp((tonumber(v) or 24) / 16, 0.5, 8) end
		end)
		_G.OnToggle("Infinite Jump", function(v)
			if Movement then Movement.infJump = (v == true) end
		end)
		_G.OnToggle("Bunny Hop", function(v)
			if Movement then Movement.bhop = (v == true) end
		end)
		_G.OnToggle("Fly", function(v)
			if Movement then Movement.fly = (v == true) end
		end)
		_G.OnSlider("Fly Speed", function(v)
			if Movement then Movement.flySpeed = tonumber(v) or 50 end
		end)
		_G.OnToggle("Noclip", function(v)
			if Movement then Movement.noclip = (v == true) end
		end)
	end
end

_G.AtomwareFeaturesLoaded = true
print("[Atomware Rivals] Authoritative Features Backend Loaded Successfully (PC, Mobile, and Lite Compatible)!")
